#!/bin/bash
# WebMonitor install/deploy script for Rocky Linux (LAMP stack).
#
# Run as root on the target server:
#   bash rocky-install.sh
#
# What this does:
#   1. Installs httpd + mod_ssl, MariaDB, PHP (+ php-fpm, php-mysqlnd,
#      php-snmp) and net-snmp-utils if not already present.
#   2. Creates the "webmonitor" database and a dedicated DB user with a
#      freshly generated random password (never hardcoded).
#   3. Writes the application files to /var/www/html/webmonitor and applies
#      database migrations (cli/migrate.php).
#   4. Creates an "admin" login with a generated password if no logins
#      exist yet (shown at the end).
#   5. Sets ownership/SELinux context, adds an Apache <Directory> block
#      enabling the app's .htaccess (HTTPS redirect, denies config/cli/
#      includes/migrations), and sets up HTTPS with a self-signed
#      certificate (kept across re-runs). Opens http/https in firewalld if
#      it is active.
#   6. Installs a systemd timer that checks hosts and evaluates alerts every
#      minute (webmonitor-cron.timer), then self-tests the deployed app.
#
# Reachability checks (both the periodic host monitor and the network scan
# feature) use plain TCP connects, not raw ICMP ping — so unlike an earlier
# version of this script, there is no SELinux/capability work needed to let
# PHP check hosts, and no ping-related policy module gets installed.
#
# If MariaDB's root account already has a password set (existing LAMP
# install), re-run as:
#   MYSQL_ROOT_PASS='yourpass' bash rocky-install.sh
#
set -euo pipefail

APP_DIR="/var/www/html/webmonitor"
DB_NAME="webmonitor"
DB_USER="webmonitor"
DB_PASS="$(openssl rand -hex 24)"
MYSQL_ROOT_PASS="${MYSQL_ROOT_PASS:-}"

if [ "$(id -u)" -ne 0 ]; then
    echo "Run this as root." >&2
    exit 1
fi

mysql_root() {
    if [ -n "$MYSQL_ROOT_PASS" ]; then
        mysql -u root -p"$MYSQL_ROOT_PASS" "$@"
    else
        mysql -u root "$@"
    fi
}

echo "==> [1/6] Installing packages (httpd, mod_ssl, mariadb-server, php, php-fpm, php-mysqlnd, php-snmp, net-snmp-utils, nmap)"
dnf install -y httpd mod_ssl openssl mariadb-server php php-cli php-fpm php-mysqlnd php-snmp \
    net-snmp-utils policycoreutils-python-utils nmap >/dev/null

echo "==> [2/6] Enabling services"
systemctl enable --now mariadb >/dev/null
systemctl enable --now php-fpm >/dev/null
systemctl enable --now httpd >/dev/null

echo "==> [3/6] Creating database and application user"
if ! mysql_root -e "SELECT 1;" >/dev/null 2>&1; then
    echo "ERROR: cannot connect to MariaDB as root." >&2
    echo "If root already has a password, re-run as: MYSQL_ROOT_PASS='yourpass' bash $0" >&2
    exit 1
fi

mysql_root <<SQL
CREATE DATABASE IF NOT EXISTS ${DB_NAME} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS '${DB_USER}'@'localhost' IDENTIFIED BY '${DB_PASS}';
ALTER USER '${DB_USER}'@'localhost' IDENTIFIED BY '${DB_PASS}';
GRANT ALL PRIVILEGES ON ${DB_NAME}.* TO '${DB_USER}'@'localhost';
FLUSH PRIVILEGES;
SQL

echo "==> [4/6] Writing application files to ${APP_DIR}"
mkdir -p "$APP_DIR"

mkdir -p "$(dirname "$APP_DIR/.htaccess")"
cat > "$APP_DIR/.htaccess" <<'WEBMON_FILE_EOF'
<FilesMatch "^(config\.php|config\.example\.php)$">
    Require all denied
</FilesMatch>

# Serve WebMonitor over HTTPS only (logins and session cookies must not
# travel in plain text). Scoped to this directory; other sites on the
# server are unaffected. 302 rather than 301 so browsers don't cache it.
<IfModule mod_rewrite.c>
    RewriteEngine On
    RewriteCond %{HTTPS} !=on
    RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [R=302,L]
</IfModule>

# Make browsers revalidate app files on each load so updates show up
# immediately (cheap 304s when nothing changed).
<IfModule mod_headers.c>
    <FilesMatch "\.(html|css|js|php)$">
        Header set Cache-Control "no-cache"
    </FilesMatch>
</IfModule>
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/config.php")"
cat > "$APP_DIR/config.php" <<'WEBMON_FILE_EOF'
<?php
// Database connection. Copy this file to config.php and set DB_PASS;
// rocky-install.sh does this automatically with a generated password.
define('DB_HOST', '127.0.0.1');
define('DB_NAME', 'webmonitor');
define('DB_USER', 'webmonitor');
define('DB_PASS', '__WEBMON_DB_PASS__');

// Minimum seconds between checks for a given host (used by the lazy
// check-on-poll trigger in api/hosts.php).
define('CHECK_INTERVAL_SEC', 10);

// How long to wait for a host to respond before marking it down.
define('CHECK_TIMEOUT_SEC', 5);

// Number of most recent check results kept per host for the graph.
define('HISTORY_LIMIT', 60);

// Server TLS certificate. Agents are given its public-key fingerprint so
// they can trust this server's self-signed certificate.
define('TLS_CERT_FILE', '/etc/pki/tls/certs/webmonitor.crt');

// Timezone for times shown in alerts. Defaults to the server's system
// timezone; uncomment to override.
// define('TIMEZONE', 'America/New_York');
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/favicon.ico")"
