mkdir -p "$(dirname "$APP_DIR/agent/install.ps1")"
cat > "$APP_DIR/agent/install.ps1" <<'WEBMON_FILE_EOF'
<#
.SYNOPSIS
    Installs (or removes) the WebMonitor agent on Windows.

.DESCRIPTION
    Normally run via the one-liner shown in the dashboard (Details -> Agent
    -> Install agent -> Windows), pasted into an elevated Windows PowerShell.
    That one-liner only trusts the WebMonitor server's certificate (by its
    SHA-256 fingerprint) before downloading this script.

    Installs to "C:\Program Files\WebMonitor Agent", keeps its token in
    C:\ProgramData\WebMonitorAgent (SYSTEM and Administrators only) and runs
    as the "WebMonitor Agent" scheduled task under SYSTEM.

    Uninstall: run the same one-liner with -Uninstall (shown in the
    dashboard when you remove the agent).
#>
param(
    [string]$Server,
    [string]$Token,
    [string]$CertHash,
    [switch]$RemoveZabbix,
    [switch]$RemoveCheckmk,
    [switch]$Uninstall
)

$ErrorActionPreference = 'Stop'
$InstallDir = Join-Path $env:ProgramFiles 'WebMonitor Agent'
$DataDir = Join-Path $env:ProgramData 'WebMonitorAgent'
$AgentFile = Join-Path $InstallDir 'webmonitor-agent.ps1'
$TaskName = 'WebMonitor Agent'
$Ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'

function Step([string]$m) { Write-Host "==> $m" -ForegroundColor Cyan }

function Stop-Agent {
    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
        Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
        Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
    }
    # The agent loop may outlive its task instance; stop it explicitly.
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" |
        Where-Object { $_.CommandLine -like '*webmonitor-agent.ps1*' } |
        ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
}

# Stops/disables the services and uninstalls matching MSI products.
function Remove-MonitoringAgent([string]$Label, [string[]]$ServiceNames, [string[]]$DisplayNames) {
    Step "Removing the $Label agent"
    $found = $false
    foreach ($svc in @(Get-Service -Name $ServiceNames -ErrorAction SilentlyContinue)) {
        Stop-Service -Name $svc.Name -Force -ErrorAction SilentlyContinue
        Set-Service -Name $svc.Name -StartupType Disabled
        Write-Host "    stopped and disabled service '$($svc.Name)'"
        $found = $true
    }
    $keys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
              'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
    $apps = @(Get-ItemProperty -Path $keys -ErrorAction SilentlyContinue | Where-Object {
        $app = $_
        $app.PSObject.Properties['DisplayName'] -and @($DisplayNames | Where-Object { $app.DisplayName -like $_ }).Count
    })
    foreach ($app in $apps) {
        $found = $true
        if ($app.PSChildName -match '^\{[0-9A-Fa-f-]+\}$') {
            $p = Start-Process -FilePath msiexec.exe -ArgumentList "/x $($app.PSChildName) /qn /norestart" -Wait -PassThru
            if ($p.ExitCode -eq 0 -or $p.ExitCode -eq 3010) {
                Write-Host "    uninstalled '$($app.DisplayName)'"
            } else {
                Write-Warning "    msiexec returned $($p.ExitCode) uninstalling '$($app.DisplayName)'; its service stays disabled"
            }
        } else {
            Write-Warning "    '$($app.DisplayName)' wasn't installed with an MSI; its service is disabled but the files remain"
        }
    }
    if (-not $found) { Write-Host "    no $Label agent found" }
}

function Install-Agent {
    if (-not $Server -or -not $Token -or -not $CertHash) {
        throw 'Usage: install.ps1 -Server URL -Token TOKEN -CertHash SHA256 [-RemoveZabbix] [-RemoveCheckmk]'
    }
    $Server = $Server.TrimEnd('/')

    Step 'Checking PowerShell'
    if ($PSVersionTable.PSVersion.Major -lt 5) {
        throw "Windows PowerShell 5.1 is required (found $($PSVersionTable.PSVersion))."
    }
    Write-Host "    PowerShell $($PSVersionTable.PSVersion)"

    Stop-Agent

    Step "Downloading the agent from $Server"
    New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
    New-Item -ItemType Directory -Force -Path $DataDir | Out-Null
    # Only SYSTEM and Administrators may read the agent's token.
    & icacls.exe $DataDir /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "icacls failed on $DataDir" }

    # The one-liner already restricted TLS to this server's certificate.
    $code = (New-Object Net.WebClient).DownloadString("$Server/agent/webmonitor-agent.ps1")
    $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseInput($code, [ref]$null, [ref]$errors)
    if ($errors -and $errors.Count) { throw "Downloaded agent failed to parse: $($errors[0].Message)" }
    Set-Content -Path $AgentFile -Value $code -Encoding UTF8

    # Remove other agents before ours starts, so its first inventory is accurate.
    if ($RemoveZabbix) { Remove-MonitoringAgent 'Zabbix' @('Zabbix Agent', 'Zabbix Agent 2') @('Zabbix Agent*') }
    if ($RemoveCheckmk) { Remove-MonitoringAgent 'Checkmk' @('CheckMkService') @('Check*MK Agent*', 'Checkmk Agent*') }

    Step 'Enrolling with the server'
    & $Ps -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $AgentFile -Enroll -Server $Server -Token $Token -CertHash $CertHash
    if ($LASTEXITCODE -ne 0) { throw 'Enrollment failed (see above).' }

    Step 'Creating the scheduled task'
    $action = New-ScheduledTaskAction -Execute $Ps -Argument ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "{0}"' -f $AgentFile)
    # Start at boot, and re-check every minute: if the agent isn't running
    # (crashed, or its daily restart), this starts it; otherwise it's ignored.
    $triggers = @(
        (New-ScheduledTaskTrigger -AtStartup),
        (New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 1))
    )
    $principal = New-ScheduledTaskPrincipal -UserId 'NT AUTHORITY\SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Seconds 0) `
        -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -Hidden
    Register-ScheduledTask -TaskName $TaskName -Description "Reports to WebMonitor at $Server" `
        -Action $action -Trigger $triggers -Principal $principal -Settings $settings | Out-Null
    Start-ScheduledTask -TaskName $TaskName

    Start-Sleep -Seconds 8
    $log = Join-Path $DataDir 'agent.log'
    $running = @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" |
        Where-Object { $_.CommandLine -like '*webmonitor-agent.ps1*' -and $_.CommandLine -notlike '*-Enroll*' }).Count -gt 0
    if ($running) {
        Step 'Done. The agent is running; data appears in the dashboard within a minute.'
        Write-Host "    Log: $log"
    } else {
        Write-Warning 'The agent does not appear to be running. Last log lines:'
        if (Test-Path $log) { Get-Content $log -Tail 15 }
        throw 'Agent failed to start.'
    }
}

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator)
try {
    if (-not $isAdmin) { throw 'Run this in an elevated PowerShell (Run as Administrator).' }
    if ($Uninstall) {
        Step 'Removing the WebMonitor agent'
        Stop-Agent
        Remove-Item -Recurse -Force -Path $InstallDir, $DataDir -ErrorAction SilentlyContinue
        Write-Host '    Removed. (Remove the host''s agent in the dashboard too.)'
    } else {
        Install-Agent
    }
} catch {
    Write-Host "!! $($_.Exception.Message)" -ForegroundColor Red
} finally {
    # Don't leave this session trusting only the WebMonitor certificate.
    [Net.ServicePointManager]::ServerCertificateValidationCallback = $null
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/agent/install.sh")"
cat > "$APP_DIR/agent/install.sh" <<'WEBMON_FILE_EOF'
#!/bin/bash
# Installs (or removes) the WebMonitor agent on a Linux host.
#
# Normally run via the command shown in the dashboard (Details -> Agent ->
# Install agent), which looks like:
#   curl -fsSk --pinnedpubkey 'sha256//...' https://SERVER/webmonitor/agent/install.sh \
#     | sudo bash -s -- --server https://SERVER/webmonitor --token TOKEN --pin 'sha256//...' [--remove-zabbix]
#
# curl's -k is safe here only because --pinnedpubkey makes curl refuse any
# server whose key doesn't match this WebMonitor server's certificate.
#
# Uninstall:
#   sudo bash install.sh --uninstall
set -euo pipefail

# Everything is inside main() so bash has read the whole script before any
# of it runs; with `curl | bash`, a command reading stdin could otherwise
# swallow the rest of the script.
main() {

INSTALL_DIR=/usr/local/lib/webmonitor-agent
CONF_DIR=/etc/webmonitor-agent
UNIT=/etc/systemd/system/webmonitor-agent.service

SERVER="" TOKEN="" PIN="" REMOVE_ZABBIX=0 REMOVE_CHECKMK=0 UNINSTALL=0
while [ $# -gt 0 ]; do
    case "$1" in
        --server) SERVER="${2%/}"; shift 2 ;;
        --token) TOKEN="$2"; shift 2 ;;
        --pin) PIN="$2"; shift 2 ;;
        --remove-zabbix) REMOVE_ZABBIX=1; shift ;;
        --remove-checkmk) REMOVE_CHECKMK=1; shift ;;
        --uninstall) UNINSTALL=1; shift ;;
        *) echo "Unknown option: $1" >&2; exit 1 ;;
    esac
done

if [ "$(id -u)" -ne 0 ]; then
    echo "Run as root (sudo)." >&2
    exit 1
fi
if ! command -v systemctl >/dev/null 2>&1; then
    echo "systemd is required." >&2
    exit 1
fi

if [ "$UNINSTALL" = 1 ]; then
    systemctl disable --now webmonitor-agent 2>/dev/null || true
    rm -f "$UNIT"
    systemctl daemon-reload
    rm -rf "$INSTALL_DIR" "$CONF_DIR"
    echo "WebMonitor agent removed. (Remove the host's agent in the dashboard too.)"
    exit 0
fi

if [ -z "$SERVER" ] || [ -z "$TOKEN" ] || [ -z "$PIN" ]; then
    echo "Usage: install.sh --server URL --token TOKEN --pin 'sha256//...' [--remove-zabbix] [--remove-checkmk]" >&2
    exit 1
fi

fetch() {  # fetch URL DEST — only from the pinned server
    curl -fsSk --pinnedpubkey "$PIN" --retry 2 -o "$2" "$1"
}

echo "==> Checking for Python 3"
if ! command -v python3 >/dev/null 2>&1; then
    if command -v apt-get >/dev/null 2>&1; then
        apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq python3 >/dev/null
    elif command -v dnf >/dev/null 2>&1; then
        dnf install -y -q python3 >/dev/null
    else
        echo "Python 3 is required and no supported package manager was found." >&2
        exit 1
    fi
fi
python3 --version

echo "==> Downloading the agent from $SERVER"
mkdir -p "$INSTALL_DIR"
install -d -m 700 "$CONF_DIR"
fetch "$SERVER/agent/webmonitor-agent.py" "$INSTALL_DIR/webmonitor-agent.py.new"
python3 -m py_compile "$INSTALL_DIR/webmonitor-agent.py.new"
mv "$INSTALL_DIR/webmonitor-agent.py.new" "$INSTALL_DIR/webmonitor-agent.py"
chmod 755 "$INSTALL_DIR/webmonitor-agent.py"
rm -rf "$INSTALL_DIR/__pycache__"
# The agent trusts exactly this certificate for all later connections.
fetch "$SERVER/api/agent.php?action=cert" "$CONF_DIR/server.crt"
chmod 644 "$CONF_DIR/server.crt"

echo "==> Enrolling with the server"
python3 "$INSTALL_DIR/webmonitor-agent.py" --enroll "$TOKEN" --server "$SERVER"

# remove_monitoring_agent LABEL CONFIG_NOTE "UNITS" "DEB_PACKAGES" "RPM_PACKAGES"
# Stops/disables the units and removes whichever packages are installed.
# Packages are removed, not purged, so their config stays on disk.
remove_monitoring_agent() {
    local label="$1" note="$2" units="$3" debs="$4" rpms="$5" found=0 pkgs="" u p
    echo "==> Removing the $label agent"
    for u in $units; do
        case "$u" in *.*) ;; *) u="$u.service" ;; esac
        if systemctl list-unit-files "$u" 2>/dev/null | grep -q "^$u"; then
            systemctl disable --now "$u" >/dev/null 2>&1 || true
            echo "    stopped and disabled $u"
            found=1
        fi
    done
    if command -v dpkg-query >/dev/null 2>&1; then
        for p in $debs; do
            dpkg-query -W -f '${db:Status-Abbrev}' "$p" 2>/dev/null | grep -q '^ii' && pkgs="$pkgs $p"
        done
        [ -n "$pkgs" ] && DEBIAN_FRONTEND=noninteractive apt-get remove -y -qq $pkgs >/dev/null
    elif command -v rpm >/dev/null 2>&1; then
        for p in $rpms; do
            rpm -q "$p" >/dev/null 2>&1 && pkgs="$pkgs $p"
        done
        [ -n "$pkgs" ] && dnf remove -y -q $pkgs >/dev/null
    fi
    if [ -n "$pkgs" ]; then
        echo "    removed packages:$pkgs ($note)"
    elif [ "$found" = 0 ]; then
        echo "    no $label agent found"
    fi
    return 0
}

# Remove other agents before ours starts, so its first inventory is accurate.
if [ "$REMOVE_ZABBIX" = 1 ]; then
    remove_monitoring_agent Zabbix "config in /etc/zabbix kept" \
        "zabbix-agent zabbix-agent2" \
        "zabbix-agent zabbix-agent2 zabbix-agent2-plugin-mongodb zabbix-agent2-plugin-postgresql zabbix-agent2-plugin-mssql" \
        "zabbix-agent zabbix-agent2"
fi
if [ "$REMOVE_CHECKMK" = 1 ]; then
    remove_monitoring_agent Checkmk "config in /etc/check_mk kept" \
        "check-mk-agent.socket check-mk-agent-async cmk-agent-ctl-daemon" \
        "check-mk-agent" "check-mk-agent"
fi

echo "==> Installing the systemd service"
cat > "$UNIT" <<EOF
[Unit]
Description=WebMonitor agent
Documentation=$SERVER
After=network-online.target
Wants=network-online.target

[Service]
ExecStart=/usr/bin/env python3 $INSTALL_DIR/webmonitor-agent.py
Restart=always
RestartSec=30
# Runs as root: it reads hardware info and package state and installs
# updates from the dashboard (package scripts may write anywhere, so no
# filesystem sandboxing beyond a private /tmp).
PrivateTmp=true
Nice=10

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable webmonitor-agent >/dev/null 2>&1
systemctl restart webmonitor-agent

sleep 3
if systemctl is-active --quiet webmonitor-agent; then
    echo "==> Done. The agent is running; data appears in the dashboard within a minute."
    echo "    Logs: journalctl -u webmonitor-agent -f"
else
    echo "!! The agent service is not running:" >&2
    journalctl -u webmonitor-agent -n 20 --no-pager >&2 || true
    exit 1
fi
}

main "$@"
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/agent/webmonitor-agent.ps1")"
cat > "$APP_DIR/agent/webmonitor-agent.ps1" <<'WEBMON_FILE_EOF'
<#
.SYNOPSIS
    WebMonitor agent for Windows.

.DESCRIPTION
    Reports to the WebMonitor server over HTTPS (outbound only, nothing
    listens on this host), using the same report format as the Linux agent:
      - metrics every minute: CPU, memory, page file, disks, network, uptime
      - inventory every hour: OS, hardware, installed programs, pending
        Windows Updates, reboot-pending, failed services, antivirus state

    Written for the built-in Windows PowerShell 5.1. Installed and enrolled
    by install.ps1 and run by the "WebMonitor Agent" scheduled task as SYSTEM.

    webmonitor-agent.ps1 -Enroll -Server URL -Token TOKEN -CertHash HASH   (installer)
    webmonitor-agent.ps1                                                  (scheduled task)
    webmonitor-agent.ps1 -Print metrics|inventory                         (show a report)

    It also runs jobs from the dashboard (check for / install Windows Updates,
    reboot, upgrade the agent). Only those job types exist and each is
    implemented here, so the server can never make the agent run arbitrary
    commands. Each job runs in a child process (-RunJob) so the main loop
    keeps reporting while Windows Update works.
#>
param(
    [switch]$Enroll,
    [string]$Server,
    [string]$Token,
    [string]$CertHash,
    [ValidateSet('', 'metrics', 'inventory')]
    [string]$Print = '',
    # Internal: run one job (started by the main loop in a child process).
    [string]$RunJob = ''
)

$ErrorActionPreference = 'Stop'
$Version = '0.5.0'
$DataDir = Join-Path $env:ProgramData 'WebMonitorAgent'
$ConfFile = Join-Path $DataDir 'agent.json'
$LogFile = Join-Path $DataDir 'agent.log'
$DefaultIntervals = @{ metrics = 60; inventory = 3600 }
# Recycle the process daily; the scheduled task restarts it within a minute.
$MaxRuntimeHours = 24
$JobDir = Join-Path $DataDir 'jobs'
$JobPollSec = 20
$JobFlushSec = 10

# ------------------------------------------------------------- transport

# HTTPS client that trusts exactly one certificate (by SHA-256 of its DER
# bytes) for each request, instead of changing process-wide TLS settings.
if (-not ('WebMonHttp' -as [type])) {
    Add-Type -IgnoreWarnings -TypeDefinition @'
using System;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Net.Security;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;

public class WebMonResult {
    public int Status;
    public string Body;
}

public static class WebMonHttp {
    public static string Sha256Hex(byte[] data) {
        using (SHA256 sha = SHA256.Create()) {
            return BitConverter.ToString(sha.ComputeHash(data)).Replace("-", "");
        }
    }

    public static WebMonResult Send(string method, string url, string json, string headerName,
                                    string headerValue, string certHash) {
        HttpWebRequest req = (HttpWebRequest)WebRequest.Create(url);
        req.Method = method;
        req.Timeout = 60000;
        req.ReadWriteTimeout = 60000;
        req.UserAgent = "webmonitor-agent-windows";
        req.ServerCertificateValidationCallback = delegate(object sender, X509Certificate cert,
                X509Chain chain, SslPolicyErrors errors) {
            return cert != null && string.Equals(Sha256Hex(cert.GetRawCertData()), certHash,
                                                 StringComparison.OrdinalIgnoreCase);
        };
        if (!string.IsNullOrEmpty(headerName)) req.Headers[headerName] = headerValue;

        if (!string.IsNullOrEmpty(json)) {  // PowerShell passes $null as ""
            byte[] body = Encoding.UTF8.GetBytes(json);
            if (body.Length > 2048) {
                MemoryStream ms = new MemoryStream();
                using (GZipStream gz = new GZipStream(ms, CompressionMode.Compress)) {
                    gz.Write(body, 0, body.Length);
                }
                body = ms.ToArray();
                req.Headers["Content-Encoding"] = "gzip";
            }
            req.ContentType = "application/json";
            req.ContentLength = body.Length;
            using (Stream st = req.GetRequestStream()) {
                st.Write(body, 0, body.Length);
            }
        }

        HttpWebResponse resp;
        try {
            resp = (HttpWebResponse)req.GetResponse();
        } catch (WebException ex) {
            resp = ex.Response as HttpWebResponse;
            if (resp == null) throw;
        }
        using (resp) {
            using (StreamReader reader = new StreamReader(resp.GetResponseStream(), Encoding.UTF8)) {
                WebMonResult result = new WebMonResult();
                result.Status = (int)resp.StatusCode;
                result.Body = reader.ReadToEnd();
                return result;
            }
        }
    }
}
'@
}

# TLS 1.2 isn't enabled by default for .NET Framework on older systems.
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor 3072

function Write-Log([string]$Level, [string]$Message) {
    $line = '{0} {1} {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $Message
    try {
        if ((Test-Path $LogFile) -and (Get-Item $LogFile).Length -gt 1MB) {
            Move-Item -Force $LogFile "$LogFile.1"
        }
        Add-Content -Path $LogFile -Value $line -Encoding UTF8
    } catch { }
    if ($Print -or $Enroll) { Write-Host $line }
}

function Send-Report([string]$Action, $Payload, [string]$HeaderName, [string]$HeaderValue, $Conf) {
    $json = $Payload | ConvertTo-Json -Depth 8 -Compress
    $url = '{0}/api/agent.php?action={1}' -f $Conf.server, $Action
    $r = [WebMonHttp]::Send('POST', $url, $json, $HeaderName, $HeaderValue, $Conf.cert_hash)
    $body = $null
    if ($r.Body) {
        try { $body = $r.Body | ConvertFrom-Json } catch { $body = $null }
    }
    return @{ Status = $r.Status; Body = $body }
}

# --------------------------------------------------------------- metrics

$script:PrevCpu = $null
$script:PrevNet = $null
$script:PrevTime = $null

function Get-CpuRaw {
    $p = Get-CimInstance -ClassName Win32_PerfRawData_PerfOS_Processor -Filter "Name='_Total'"
    # PercentProcessorTime here is the inverse (idle) 100ns timer.
    return @([double]$p.PercentProcessorTime, [double]$p.Timestamp_Sys100NS)
}

function Get-NetRaw {
    $h = @{}
    foreach ($s in @(Get-NetAdapterStatistics -ErrorAction SilentlyContinue)) {
        $h[$s.Name] = @([double]$s.ReceivedBytes, [double]$s.SentBytes)
    }
    return $h
}

function Get-Metrics {
    $now = Get-Date
    $cpu = Get-CpuRaw
    $net = Get-NetRaw
    if ($null -eq $script:PrevCpu) {
        # First sample: take a short baseline so CPU% and rates mean something.
        $script:PrevCpu = $cpu; $script:PrevNet = $net; $script:PrevTime = $now
        Start-Sleep -Seconds 1
        $now = Get-Date; $cpu = Get-CpuRaw; $net = Get-NetRaw
    }

    $cpuPct = $null
    $dTs = $cpu[1] - $script:PrevCpu[1]
    if ($dTs -gt 0) {
        $pct = 100.0 * (1.0 - ($cpu[0] - $script:PrevCpu[0]) / $dTs)
        $cpuPct = [math]::Round([math]::Max(0.0, [math]::Min(100.0, $pct)), 1)
    }
    $elapsed = [math]::Max(($now - $script:PrevTime).TotalSeconds, 0.001)

    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $memTotal = [double]$os.TotalVisibleMemorySize * 1024
    $memFree = [double]$os.FreePhysicalMemory * 1024
    $swapTotal = 0.0; $swapUsed = 0.0
    foreach ($pf in @(Get-CimInstance -ClassName Win32_PageFileUsage -ErrorAction SilentlyContinue)) {
        $swapTotal += [double]$pf.AllocatedBaseSize * 1MB
        $swapUsed += [double]$pf.CurrentUsage * 1MB
    }

    $disks = @()
    foreach ($d in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType=3')) {
        if (-not $d.Size) { continue }
        $size = [double]$d.Size; $free = [double]$d.FreeSpace
        $disks += [ordered]@{
            mount = $d.DeviceID
            device = $(if ($d.VolumeName) { $d.VolumeName } else { $d.DeviceID })
            fstype = $d.FileSystem
            size = $size
            used = $size - $free
            available = $free
            used_pct = [math]::Round(100.0 * ($size - $free) / $size, 1)
        }
    }

    $addrs = @{}
    foreach ($ip in @(Get-NetIPAddress -ErrorAction SilentlyContinue)) {
        if ($ip.IPAddress -like 'fe80*' -or $ip.IPAddress -like '169.254.*' -or
            $ip.IPAddress -eq '127.0.0.1' -or $ip.IPAddress -eq '::1') { continue }
        if (-not $addrs.ContainsKey($ip.InterfaceAlias)) { $addrs[$ip.InterfaceAlias] = @() }
        $addrs[$ip.InterfaceAlias] += ('{0}/{1}' -f $ip.IPAddress, $ip.PrefixLength)
    }
    $network = @()
    foreach ($a in @(Get-NetAdapter -ErrorAction SilentlyContinue | Sort-Object Name)) {
        $ifAddrs = @(); if ($addrs.ContainsKey($a.Name)) { $ifAddrs = @($addrs[$a.Name]) }
        if ($a.Status -ne 'Up' -and $ifAddrs.Count -eq 0) { continue }
        $rx = $null; $tx = $null; $rxRate = $null; $txRate = $null
        if ($net.ContainsKey($a.Name)) {
            $rx = $net[$a.Name][0]; $tx = $net[$a.Name][1]
            if ($script:PrevNet.ContainsKey($a.Name)) {
                $rxRate = [math]::Round([math]::Max(0, $rx - $script:PrevNet[$a.Name][0]) / $elapsed)
                $txRate = [math]::Round([math]::Max(0, $tx - $script:PrevNet[$a.Name][1]) / $elapsed)
            }
        }
        $speed = $null
        if ($a.ReceiveLinkSpeed -gt 0) { $speed = [int64]($a.ReceiveLinkSpeed / 1000000) }
        $network += [ordered]@{
            name = $a.Name
            addrs = $ifAddrs
            mac = $(if ($a.MacAddress) { $a.MacAddress.Replace('-', ':').ToLower() } else { $null })
            up = ($a.Status -eq 'Up')
            speed_mbps = $speed
            rx_bytes = $rx; tx_bytes = $tx
            rx_rate = $rxRate; tx_rate = $txRate
        }
    }

    $script:PrevCpu = $cpu; $script:PrevNet = $net; $script:PrevTime = $now

    return [ordered]@{
        cpu_pct = $cpuPct
        cpu_count = [Environment]::ProcessorCount
        load = $null   # Windows has no load average
        memory = [ordered]@{
            total = $memTotal
            used = $memTotal - $memFree
            available = $memFree
            swap_total = $swapTotal
            swap_used = $swapUsed
        }
        uptime_sec = [int64]($now - $os.LastBootUpTime).TotalSeconds
        processes = @(Get-Process).Count
        disks = $disks
        network = $network
    }
}

# ------------------------------------------------------------- inventory

function Get-InstalledPrograms {
    $seen = @{}
    $list = New-Object System.Collections.Generic.List[object]
    $keys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
              'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
    foreach ($p in @(Get-ItemProperty -Path $keys -ErrorAction SilentlyContinue)) {
        $name = $p.PSObject.Properties['DisplayName']
        if (-not $name -or -not $name.Value) { continue }
        if ($p.PSObject.Properties['SystemComponent'] -and $p.SystemComponent -eq 1) { continue }
        $ver = ''
        if ($p.PSObject.Properties['DisplayVersion'] -and $p.DisplayVersion) { $ver = [string]$p.DisplayVersion }
        $key = '{0}|{1}' -f $name.Value, $ver
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        $list.Add(@([string]$name.Value, $ver))
    }
    return , $list.ToArray()
}

# Windows Update search runs in a child job so a stuck search can't hang
# the agent. It reads the results of Windows' own last scan (Online =
# false) rather than contacting Windows Update every hour.
function Get-PendingUpdates {
    $job = Start-Job -ScriptBlock {
        $session = New-Object -ComObject Microsoft.Update.Session
        $searcher = $session.CreateUpdateSearcher()
        $criteria = "IsInstalled=0 and IsHidden=0 and Type='Software'"
        try {
            $searcher.Online = $false
            $result = $searcher.Search($criteria)
        } catch {
            $searcher.Online = $true
            $result = $searcher.Search($criteria)
        }
        foreach ($u in $result.Updates) {
            $cats = @($u.Categories | ForEach-Object { $_.Name })
            [pscustomobject]@{
                name = [string]$u.Title
                kb = (@($u.KBArticleIDs) | ForEach-Object { "KB$_" }) -join ', '
                security = (($cats -contains 'Security Updates') -or [bool]$u.MsrcSeverity)
            }
        }
    }
    try {
        if (-not (Wait-Job $job -Timeout 600)) {
            Stop-Job $job
            return [ordered]@{ manager = 'windows-update'; error = 'Windows Update search timed out'; packages = $null }
        }
        $items = @(Receive-Job $job -ErrorAction Stop)
        $pkgs = @()
        foreach ($i in $items) {
            $pkgs += [ordered]@{
                name = $i.name; current = $null
                new = $(if ($i.kb) { $i.kb } else { $null })
                security = [bool]$i.security
            }
        }
        return [ordered]@{ manager = 'windows-update'; packages = $pkgs }
    } catch {
        return [ordered]@{ manager = 'windows-update'; error = "Windows Update search failed: $($_.Exception.Message)"; packages = $null }
    } finally {
        Remove-Job $job -Force -ErrorAction SilentlyContinue
    }
}

function Test-RebootPending {
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { return $true }
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { return $true }
    try {
        return [bool](New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired
    } catch {
        return $false
    }
}

# Antivirus: every product registered with Windows Security Center (desktop
# Windows), plus Microsoft Defender's own status (also on Windows Server,
# which has no Security Center). enabled/up_to_date/realtime are $null when
# unknown.
function Get-Antivirus {
    $products = New-Object System.Collections.Generic.List[object]
    $errors = @()
    try {
        foreach ($p in @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)) {
            # productState: byte 2 = scanner on (0x10/0x11), byte 3 = signatures (0x00 up to date, 0x10 out of date).
            $hex = '{0:x6}' -f [int]$p.productState
            $products.Add([ordered]@{
                    name = [string]$p.displayName
                    enabled = @('10', '11') -contains $hex.Substring(2, 2)
                    up_to_date = $hex.Substring(4, 2) -eq '00'
                    realtime = $null; signature_age_days = $null; last_scan = $null; source = 'security-center'
                })
        }
    } catch {
        # Not on Windows Server; Defender below still answers there.
    }
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        $scan = @($mp.QuickScanEndTime, $mp.FullScanEndTime | Where-Object { $_ }) | Sort-Object -Descending | Select-Object -First 1
        $passive = $mp.PSObject.Properties['AMRunningMode'] -and $mp.AMRunningMode -match 'Passive|EDR'
        $defender = [ordered]@{
            name = 'Microsoft Defender Antivirus'
            enabled = [bool]($mp.AMServiceEnabled -and $mp.AntivirusEnabled -and -not $passive)
            up_to_date = ([int]$mp.AntivirusSignatureAge -le 3)
            realtime = [bool]$mp.RealTimeProtectionEnabled
            signature_age_days = [int]$mp.AntivirusSignatureAge
            last_scan = $(if ($scan) { [int64](($scan.ToUniversalTime() - [datetime]'1970-01-01').TotalSeconds) } else { $null })
            tamper_protected = $(if ($mp.PSObject.Properties['IsTamperProtected']) { [bool]$mp.IsTamperProtected } else { $null })
            passive = [bool]$passive
            source = 'defender'
        }
        # Defender's own report is more detailed than Security Center's line for it.
        $existing = @($products | Where-Object { $_.name -match 'Defender' })
        foreach ($e in $existing) { [void]$products.Remove($e) }
        $products.Add($defender)
    } catch {
        if ($products.Count -eq 0) { $errors += "Defender status unavailable: $($_.Exception.Message)" }
    }
    $result = [ordered]@{ products = $products.ToArray() }
    if ($errors) { $result.error = $errors -join '; ' }
    return $result
}

# Services the server asked us to watch (from its report replies). Their state
# goes out with every metrics report; only these can be restarted by a job.
$script:Watched = @()
$ServiceNamePattern = '^[A-Za-z0-9@._:\-+ ]{1,120}$'

function ConvertTo-Epoch([datetime]$t) {
    return [int64](($t.ToUniversalTime() - [datetime]'1970-01-01').TotalSeconds)
}

# Every service, for the dashboard's "watch a service" picker.
function Get-AllServices {
    $list = @(Get-CimInstance -ClassName Win32_Service | Sort-Object DisplayName | ForEach-Object {
        [ordered]@{ name = $_.Name; display = $_.DisplayName; state = $_.State.ToLower(); start_type = $_.StartMode }
    })
    return , $list
}

# State of each watched service: running/stopped/..., start mode, PID and when its process started.
function Get-WatchedServices([string[]]$Names) {
    $out = New-Object System.Collections.ArrayList
    foreach ($n in $Names) {
        if ($n -notmatch $ServiceNamePattern) { continue }
        $svc = Get-CimInstance -ClassName Win32_Service -Filter ("Name='{0}'" -f $n.Replace("'", "''")) -ErrorAction SilentlyContinue
        if (-not $svc) { [void]$out.Add([ordered]@{ name = $n; missing = $true }); continue }
        $since = $null
        if ($svc.ProcessId -gt 0) {
            $p = Get-Process -Id $svc.ProcessId -ErrorAction SilentlyContinue
            if ($p -and $p.StartTime) { $since = ConvertTo-Epoch $p.StartTime }
        }
        $pid_ = $null
        if ($svc.ProcessId -gt 0) { $pid_ = [int]$svc.ProcessId }
        [void]$out.Add([ordered]@{
            name = $svc.Name; display = $svc.DisplayName; state = $svc.State.ToLower()
            start_type = $svc.StartMode; since = $since; pid = $pid_; restarts = $null
        })
    }
    return , $out.ToArray()
}

function Get-FailedServices {
    # Automatic services that stopped with an error. 1077 = never started
    # (trigger-start services that simply haven't been needed).
    $failed = @(Get-CimInstance -ClassName Win32_Service -Filter "StartMode='Auto' AND State='Stopped'" |
        Where-Object { $_.ExitCode -ne 0 -and $_.ExitCode -ne 1077 } |
        ForEach-Object { $_.Name })
    return , $failed
}

# Whether the previous boot ended cleanly: Windows logs Kernel-Power 41,
# EventLog 6008 (unexpected shutdown) or a BugCheck 1001 at the start of
# the boot that follows a crash, hang or power loss.
function Get-LastBootInfo([datetime]$BootTime) {
    $events = @()
    try {
        $events = @(Get-WinEvent -ErrorAction Stop -FilterHashtable @{
                LogName = 'System'; Id = 41, 6008, 1001; StartTime = $BootTime.AddMinutes(-5) } |
            Where-Object { $_.Id -ne 1001 -or $_.ProviderName -eq 'Microsoft-Windows-WER-SystemErrorReporting' })
    } catch {
        if ($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') {
            return [ordered]@{ previous_shutdown_clean = $null; error = $_.Exception.Message }
        }
    }
    $list = @($events | ForEach-Object { '{0} {1} {2}' -f $_.Id, $_.ProviderName, $_.TimeCreated.ToString('s') })
    return [ordered]@{ previous_shutdown_clean = ($events.Count -eq 0); crash_events = $list }
}

function Get-Inventory {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $cs = Get-CimInstance -ClassName Win32_ComputerSystem
    $bios = Get-CimInstance -ClassName Win32_BIOS
    $cpu = @(Get-CimInstance -ClassName Win32_Processor)[0]
    $cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    $displayVersion = $null
    if ($cv -and $cv.PSObject.Properties['DisplayVersion']) { $displayVersion = $cv.DisplayVersion }

    $model = '{0} {1}' -f $cs.Manufacturer, $cs.Model
    $virt = 'none'
    if ($model -match 'Virtual Machine|Hyper-V') { $virt = 'microsoft' }
    elseif ($model -match 'VMware') { $virt = 'vmware' }
    elseif ($model -match 'QEMU|KVM|Standard PC') { $virt = 'kvm' }
    elseif ($model -match 'VirtualBox') { $virt = 'oracle' }
    elseif ($model -match 'Xen') { $virt = 'xen' }

    $hostname = $env:COMPUTERNAME
    if ($cs.PartOfDomain) { $hostname = '{0}.{1}' -f $env:COMPUTERNAME, $cs.Domain }

    $pretty = $os.Caption
    if ($displayVersion) { $pretty = '{0} {1}' -f $pretty, $displayVersion }
    $pretty = '{0} (build {1})' -f $pretty, $os.BuildNumber

    return [ordered]@{
        hostname = $hostname
        os = [ordered]@{
            pretty_name = $pretty
            id = 'windows'
            id_like = $null
            version_id = $os.Version
            version_codename = $displayVersion
        }
        kernel = $os.Version
        arch = $os.OSArchitecture
        boot_time = [int64](($os.LastBootUpTime.ToUniversalTime() - [datetime]'1970-01-01').TotalSeconds)
        hardware = [ordered]@{
            vendor = $cs.Manufacturer
            model = $cs.Model
            serial = $bios.SerialNumber
            bios = $bios.SMBIOSBIOSVersion
            cpu_model = $(if ($cpu) { $cpu.Name.Trim() } else { $null })
            cpu_count = [Environment]::ProcessorCount
            memory_total = [double]$cs.TotalPhysicalMemory
            virtualization = $virt
        }
        packages = Get-InstalledPrograms
        updates = Get-PendingUpdates
        reboot_required = Test-RebootPending
        failed_services = Get-FailedServices
        services = Get-AllServices
        antivirus = Get-Antivirus
        last_boot = Get-LastBootInfo $os.LastBootUpTime
        agent = [ordered]@{ version = $Version; powershell = $PSVersionTable.PSVersion.ToString() }
    }
}

# ------------------------------------------------------------------ main

function Invoke-Enroll {
    if (-not $Server -or -not $Token -or -not $CertHash) {
        throw '-Enroll needs -Server, -Token and -CertHash'
    }
    $conf = @{ server = $Server.TrimEnd('/'); cert_hash = $CertHash.ToUpper() }
    $payload = [ordered]@{ hostname = $env:COMPUTERNAME; version = $Version }
    $r = Send-Report 'enroll' $payload 'X-Enroll-Token' $Token $conf
    if ($r.Status -ne 200 -or -not $r.Body -or -not $r.Body.agent_token) {
        $msg = 'unexpected response'
        if ($r.Body -and $r.Body.error) { $msg = $r.Body.error }
        throw "Enrollment failed ($($r.Status)): $msg"
    }
    $conf.agent_token = $r.Body.agent_token
    $conf.host_id = $r.Body.host_id
    if (-not (Test-Path $DataDir)) { New-Item -ItemType Directory -Path $DataDir | Out-Null }
    ($conf | ConvertTo-Json -Compress) | Set-Content -Path $ConfFile -Encoding ASCII
    Write-Host "Enrolled with $($conf.server) as host #$($conf.host_id)."
}

# ------------------------------------------------------------------ jobs

function New-UpdateSession {
    $session = New-Object -ComObject Microsoft.Update.Session
    $session.ClientApplicationID = 'WebMonitor'
    return $session
}

function Test-SecurityUpdate($u) {
    $cats = @($u.Categories | ForEach-Object { $_.Name })
    return (($cats -contains 'Security Updates') -or [bool]$u.MsrcSeverity)
}

# Child-process side: runs the job described in $Path (JSON), logging to
# <id>.log and writing the outcome to <id>.result.json.
function Invoke-Job([string]$Path) {
    $job = Get-Content -Raw -Path $Path | ConvertFrom-Json
    $log = Join-Path $JobDir ('{0}.log' -f $job.id)
    $resultFile = Join-Path $JobDir ('{0}.result.json' -f $job.id)
    $result = [ordered]@{ status = 'succeeded'; exit_code = 0; summary = $null; reboot = $false; restart_agent = $false }
    function Out-JobLog([string]$m) { Add-Content -Path $log -Value $m -Encoding UTF8 }

    try {
        switch ($job.type) {
            'refresh' {
                Out-JobLog 'Asking Windows Update for the latest list of updates...'
                $searcher = (New-UpdateSession).CreateUpdateSearcher()
                $searcher.Online = $true
                $r = $searcher.Search("IsInstalled=0 and IsHidden=0 and Type='Software'")
                $sec = @($r.Updates | Where-Object { Test-SecurityUpdate $_ }).Count
                foreach ($u in $r.Updates) { Out-JobLog ('  available: ' + $u.Title) }
                $result.summary = '{0} updates available ({1} security)' -f $r.Updates.Count, $sec
            }
            'updates' {
                $securityOnly = [bool]$job.params.security_only
                $session = New-UpdateSession
                $searcher = $session.CreateUpdateSearcher()
                $searcher.Online = $true
                Out-JobLog 'Searching for updates...'
                $found = $searcher.Search("IsInstalled=0 and IsHidden=0 and Type='Software'")
                $coll = New-Object -ComObject Microsoft.Update.UpdateColl
                foreach ($u in $found.Updates) {
                    if ($securityOnly -and -not (Test-SecurityUpdate $u)) { continue }
                    if ($u.InstallationBehavior.CanRequestUserInput) {
                        Out-JobLog ('  skipped (needs user input): ' + $u.Title)
                        continue
                    }
                    if (-not $u.EulaAccepted) { $u.AcceptEula() }
                    [void]$coll.Add($u)
                    Out-JobLog ('  selected: ' + $u.Title)
                }
                if ($coll.Count -eq 0) {
                    Out-JobLog 'Nothing to install.'
                    $result.summary = $(if ($securityOnly) { 'no security updates were pending' } else { 'no updates were pending' })
                } else {
                    Out-JobLog ('Downloading {0} update(s)...' -f $coll.Count)
                    $dl = $session.CreateUpdateDownloader()
                    $dl.Updates = $coll
                    [void]$dl.Download()
                    Out-JobLog 'Installing...'
                    $inst = $session.CreateUpdateInstaller()
                    $inst.Updates = $coll
                    $ir = $inst.Install()
                    $codes = @{ 0 = 'not started'; 1 = 'in progress'; 2 = 'succeeded'; 3 = 'succeeded with errors'; 4 = 'failed'; 5 = 'aborted' }
                    $failed = 0
                    for ($i = 0; $i -lt $coll.Count; $i++) {
                        $rc = $ir.GetUpdateResult($i).ResultCode
                        if ($rc -ge 4) { $failed++ }
                        Out-JobLog ('  {0}: {1}' -f $codes[[int]$rc], $coll.Item($i).Title)
                    }
                    $result.exit_code = [int]$ir.ResultCode
                    if ($failed -gt 0) {
                        $result.status = 'failed'
                        $result.summary = '{0} of {1} updates failed' -f $failed, $coll.Count
                    } else {
                        $result.summary = '{0} updates installed' -f $coll.Count
                    }
                }
                $needsReboot = Test-RebootPending
                $result.summary += $(if ($needsReboot) { '; reboot required' } else { '; reboot not needed' })
                if ($needsReboot -and [bool]$job.params.reboot) {
                    $result.reboot = $true
                    $result.summary += ' - rebooting now'
                }
            }
            'reboot' {
                Out-JobLog 'Rebooting in 1 minute.'
                $result.reboot = $true
                $result.summary = 'rebooting'
            }
            'agent_upgrade' {
                $conf = Get-Content -Raw -Path $ConfFile | ConvertFrom-Json
                $r = [WebMonHttp]::Send('GET', ($conf.server + '/agent/webmonitor-agent.ps1'), $null, $null, $null, $conf.cert_hash)
                if ($r.Status -ne 200) { throw "download failed (HTTP $($r.Status))" }
                if ($r.Body -notmatch "(?m)^\`$Version = '([^']+)'") { throw "downloaded file doesn't look like the agent" }
                $newVersion = $Matches[1]
                $errors = $null
                [void][System.Management.Automation.Language.Parser]::ParseInput($r.Body, [ref]$null, [ref]$errors)
                if ($errors -and $errors.Count) { throw "downloaded agent failed to parse: $($errors[0].Message)" }
                $me = $PSCommandPath
                Set-Content -Path "$me.new" -Value $r.Body -Encoding UTF8
                Move-Item -Force "$me.new" $me
                Out-JobLog "Installed agent $newVersion (was $Version); restarting."
                $result.summary = "upgraded $Version -> $newVersion"
                $result.restart_agent = $true
            }
            'service_restart' {
                $name = [string]$job.params.service
                if ($name -notmatch $ServiceNamePattern) { throw "not a valid service name: '$name'" }
                if (@($job.watched) -notcontains $name) { throw "$name is not on this host's watched list; only watched services can be restarted" }
                Out-JobLog "Restarting $name..."
                Restart-Service -Name $name -Force -ErrorAction Stop
                $svc = $null
                for ($i = 0; $i -lt 15; $i++) {
                    Start-Sleep -Seconds 2
                    $svc = Get-Service -Name $name -ErrorAction Stop
                    if ($svc.Status -eq 'Running') { break }
                }
                Out-JobLog ("{0}: {1}" -f $name, $svc.Status)
                if ($svc.Status -ne 'Running') { throw "$name restarted but is $($svc.Status)" }
                $result.summary = "restarted $name; it is running"
            }
            default { throw "this agent ($Version) doesn't know job type '$($job.type)'" }
        }
    } catch {
        Out-JobLog ('ERROR: ' + $_.Exception.Message)
        $result.status = 'failed'
        if (-not $result.exit_code) { $result.exit_code = 1 }
        $result.summary = $_.Exception.Message
    }
    ($result | ConvertTo-Json -Compress) | Set-Content -Path $resultFile -Encoding ASCII
}

# Main-loop side: reads what the child has logged since $Offset.
function Read-JobLog([string]$Path, [ref]$Offset) {
    if (-not (Test-Path $Path)) { return '' }
    $fs = [System.IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite')
    try {
        if ($fs.Length -le $Offset.Value) { return '' }
        [void]$fs.Seek($Offset.Value, 'Begin')
        $buf = New-Object byte[] ($fs.Length - $Offset.Value)
        $n = $fs.Read($buf, 0, $buf.Length)
        $Offset.Value += $n
        return [System.Text.Encoding]::UTF8.GetString($buf, 0, $n).TrimStart([char]0xFEFF)
    } finally {
        $fs.Dispose()
    }
}

function Invoke-Loop {
    # One running copy at a time (the task's repeat trigger is a safety net).
    $mutex = New-Object System.Threading.Mutex($false, 'Global\WebMonitorAgent')
    try {
        $owned = $mutex.WaitOne(0)
    } catch {
        $owned = $true  # abandoned by a crashed copy; we own it now
    }
    if (-not $owned) { return }

    $conf = Get-Content -Raw -Path $ConfFile | ConvertFrom-Json
    $intervals = @{ metrics = $DefaultIntervals.metrics; inventory = $DefaultIntervals.inventory }
    $nextDue = @{ inventory = [datetime]::MinValue; metrics = [datetime]::MinValue; jobs = (Get-Date).AddSeconds(5) }
    $failures = 0
    $started = Get-Date
    $job = $null   # running job: @{ id; proc; log; offset; pending; lastFlush }
    if (-not (Test-Path $JobDir)) { New-Item -ItemType Directory -Path $JobDir | Out-Null }
    Write-Log 'INFO' "WebMonitor agent $Version (PowerShell $($PSVersionTable.PSVersion)) reporting to $($conf.server)"

    while ($job -or ((Get-Date) - $started).TotalHours -lt $MaxRuntimeHours) {
        # --- jobs: stream output of a running one, or ask for the next
        if ($job) {
            $offset = $job.offset
            $job.pending += Read-JobLog $job.log ([ref]$offset)
            $job.offset = $offset
            $finished = $job.proc.HasExited
            if ($finished -or ((Get-Date) - $job.lastFlush).TotalSeconds -ge $JobFlushSec) {
                $update = [ordered]@{ id = $job.id; status = 'running'; output = $job.pending }
                $res = $null
                if ($finished) {
                    $resultFile = Join-Path $JobDir ('{0}.result.json' -f $job.id)
                    if (Test-Path $resultFile) { $res = Get-Content -Raw $resultFile | ConvertFrom-Json }
                    if (-not $res) { $res = [pscustomobject]@{ status = 'failed'; exit_code = $job.proc.ExitCode; summary = 'job process ended without a result'; reboot = $false; restart_agent = $false } }
                    $update.status = $res.status; $update.exit_code = $res.exit_code
                    $update.summary = $res.summary; $update.rebooting = [bool]$res.reboot
                }
                try {
                    $r = Send-Report 'job_update' $update 'X-Agent-Token' $conf.agent_token $conf
                    if ($r.Status -eq 200 -or $r.Status -eq 409) { $job.pending = '' }
                } catch { Write-Log 'WARN' "job $($job.id): update failed: $($_.Exception.Message)" }
                $job.lastFlush = Get-Date
                if ($finished -and $job.pending -eq '') {
                    Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path $JobDir ('{0}.*' -f $job.id))
                    Write-Log 'INFO' "job $($job.id) finished: $($res.status) - $($res.summary)"
                    $job = $null
                    $nextDue.inventory = Get-Date   # report the new state right away
                    $nextDue.metrics = Get-Date
                    if ($res.reboot) {
                        & shutdown.exe /r /t 60 /c ('WebMonitor: rebooting (job {0})' -f $update.id) | Out-Null
                    }
                    if ($res.restart_agent) {
                        Write-Log 'INFO' 'Restarting into the upgraded agent'
                        break   # the scheduled task starts the new version within a minute
                    }
                }
            }
        } elseif ((Get-Date) -ge $nextDue.jobs) {
            $nextDue.jobs = (Get-Date).AddSeconds($JobPollSec)
            try {
                $r = Send-Report 'jobs' ([ordered]@{ version = $Version }) 'X-Agent-Token' $conf.agent_token $conf
                if ($r.Status -eq 200 -and $r.Body -and $r.Body.job) {
                    $j = $r.Body.job
                    # The job runs in its own process: give it the watched list (service restarts check it).
                    $j | Add-Member -NotePropertyName watched -NotePropertyValue @($script:Watched) -Force
                    $jobFile = Join-Path $JobDir ('{0}.json' -f $j.id)
                    ($j | ConvertTo-Json -Depth 4 -Compress) | Set-Content -Path $jobFile -Encoding ASCII
                    $Ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
                    $proc = Start-Process -FilePath $Ps -PassThru -WindowStyle Hidden -ArgumentList @(
                        '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass',
                        '-File', ('"{0}"' -f $PSCommandPath), '-RunJob', ('"{0}"' -f $jobFile))
                    $job = @{ id = $j.id; proc = $proc; log = (Join-Path $JobDir ('{0}.log' -f $j.id));
                              offset = [int64]0; pending = ''; lastFlush = Get-Date }
                    Write-Log 'INFO' "Started job $($j.id) ($($j.type))"
                }
            } catch { Write-Log 'WARN' "job poll failed: $($_.Exception.Message)" }
        }

        foreach ($kind in @('inventory', 'metrics')) {
            if ((Get-Date) -lt $nextDue[$kind]) { continue }
            $status = $null; $body = $null; $err = $null
            try {
                if ($kind -eq 'inventory') { $data = Get-Inventory } else { $data = Get-Metrics }
                if ($kind -eq 'metrics' -and $script:Watched.Count -gt 0) { $data.services = Get-WatchedServices $script:Watched }
                $payload = [ordered]@{ kind = $kind; version = $Version; data = $data }
                $r = Send-Report 'report' $payload 'X-Agent-Token' $conf.agent_token $conf
                $status = $r.Status; $body = $r.Body
            } catch {
                $err = $_.Exception.Message
            }

            if ($status -eq 200) {
                $failures = 0
                if ($body -and $body.intervals) {
                    foreach ($k in @('metrics', 'inventory')) {
                        $v = $body.intervals.$k
                        if ($v -is [int] -and $v -ge 10) { $intervals[$k] = $v }
                    }
                }
                if ($body -and $body.PSObject.Properties['watch_services']) {
                    $new = @($body.watch_services | Where-Object { $_ -is [string] -and $_ -match $ServiceNamePattern } | Select-Object -First 200)
                    if (($new -join '|') -ne ($script:Watched -join '|')) {
                        $script:Watched = $new
                        $nextDue.metrics = Get-Date   # report the newly watched services right away
                    }
                }
                $nextDue[$kind] = (Get-Date).AddSeconds($intervals[$kind])
            } elseif ($status -eq 401) {
                $msg = $(if ($body) { $body.error } else { '' })
                Write-Log 'ERROR' "Server rejected this agent's token: $msg"
                $nextDue[$kind] = (Get-Date).AddMinutes(10)
            } else {
                $failures++
                $retry = [math]::Min(300, 15 * [math]::Pow(2, [math]::Min($failures, 5)))
                $msg = $err
                if (-not $msg -and $body) { $msg = $body.error }
                Write-Log 'WARN' "$kind report failed ($status): $msg - retrying in ${retry}s"
                $nextDue[$kind] = (Get-Date).AddSeconds($retry)
            }
        }
        $soonest = $nextDue.inventory
        if ($nextDue.metrics -lt $soonest) { $soonest = $nextDue.metrics }
        if (-not $job -and $nextDue.jobs -lt $soonest) { $soonest = $nextDue.jobs }
        $wait = ($soonest - (Get-Date)).TotalSeconds
        if ($job) { $wait = [math]::Min($wait, 5) }
        Start-Sleep -Seconds ([math]::Max(1, [math]::Ceiling($wait)))
    }
    Write-Log 'INFO' 'Restarting (daily recycle or agent upgrade)'
    $mutex.ReleaseMutex()
}

if ($Print) {
    if ($Print -eq 'inventory') { $data = Get-Inventory } else { $data = Get-Metrics }
    $data | ConvertTo-Json -Depth 8
} elseif ($Enroll) {
    Invoke-Enroll
} elseif ($RunJob) {
    Invoke-Job $RunJob
} else {
    try {
        Invoke-Loop
    } catch {
        Write-Log 'ERROR' "Agent stopped: $($_.Exception.Message)"
        exit 1
    }
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/agent/webmonitor-agent.py")"
cat > "$APP_DIR/agent/webmonitor-agent.py" <<'WEBMON_FILE_EOF'
#!/usr/bin/env python3
"""WebMonitor agent for Linux.

Reports to the WebMonitor server over HTTPS (outbound only, nothing listens
on this host):
  - metrics every minute: CPU, load, memory, disks, network, uptime
  - inventory every hour: OS, kernel, hardware, packages, pending updates,
    reboot-required, failed services, antivirus state
  - workloads every 5 minutes: Proxmox VE guests (VMs and LXC containers)
    and Docker/Podman containers, so the dashboard can show what runs where

Python 3 standard library only. Installed and enrolled by install.sh:
  webmonitor-agent.py --enroll TOKEN --server URL   (one time, by installer)
  webmonitor-agent.py                                (run by systemd)
  webmonitor-agent.py --print metrics|inventory      (show what would be sent)

It also runs jobs from the dashboard (check for / install updates, reboot,
upgrade the agent). Only those job types exist; each is implemented here,
so the server can never make the agent run arbitrary commands.
"""
import argparse
import gzip
import json
import logging
import os
import platform
import re
import shutil
import signal
import socket
import ssl
import subprocess
import sys
import tempfile
import threading
import time
import urllib.error
import urllib.request

VERSION = "0.6.0"
CONF_DIR = "/etc/webmonitor-agent"
CONF_FILE = os.path.join(CONF_DIR, "agent.conf")
CA_FILE = os.path.join(CONF_DIR, "server.crt")
STATE_FILE = "/var/lib/webmonitor-agent/state.json"

DEFAULT_INTERVALS = {"metrics": 60, "inventory": 3600, "workloads": 300}
CMD_TIMEOUT = 180

# Filesystems worth reporting. Network filesystems are skipped on purpose:
# statvfs() on a hung NFS/CIFS mount can block the agent indefinitely.
LOCAL_FS = {"ext2", "ext3", "ext4", "xfs", "btrfs", "zfs", "vfat", "exfat",
            "ntfs", "ntfs3", "f2fs", "jfs", "reiserfs", "fuseblk", "bcachefs"}
SKIP_MOUNT_PREFIXES = ("/snap/", "/var/lib/docker/", "/var/lib/containers/",
                       "/run/", "/proc", "/sys", "/dev")
# Container bridges: internal to the host, always hidden.
CONTAINER_IFACE = re.compile(r"^(docker\d+|br-[0-9a-f]{12}|podman\d+|cni-podman\d+)$")
# Virtual interfaces that are noise unless they carry an address.
VIRTUAL_IFACE_PREFIXES = ("veth", "tap", "fwbr", "fwpr", "fwln", "docker",
                          "br-", "virbr", "vnet", "cali", "flannel", "cni")

log = logging.getLogger("webmonitor-agent")


# ---------------------------------------------------------------- helpers

def read(path, default=None):
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return default


def run(cmd, timeout=CMD_TIMEOUT):
    """Runs a command; returns (exit_code, stdout). Never raises."""
    if not shutil.which(cmd[0]):
        return None, ""
    env = dict(os.environ, LC_ALL="C", LANG="C")
    try:
        p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                           timeout=timeout, env=env, check=False)
        return p.returncode, p.stdout.decode("utf-8", "replace")
    except (OSError, subprocess.SubprocessError) as e:
        log.warning("%s failed: %s", cmd[0], e)
        return None, ""


# ---------------------------------------------------------------- metrics

class MetricsCollector:
    """Keeps the previous CPU/network sample so rates can be computed."""

    def __init__(self):
        self.prev_cpu = None
        self.prev_net = None
        self.prev_time = None

    @staticmethod
    def _cpu_times():
        parts = (read("/proc/stat", "").splitlines() or [""])[0].split()
        if not parts or parts[0] != "cpu":
            return None
        vals = [int(v) for v in parts[1:9]]  # user nice system idle iowait irq softirq steal
        idle = vals[3] + vals[4]
        return sum(vals), idle

    @staticmethod
    def _net_counters():
        counters = {}
        for line in (read("/proc/net/dev", "").splitlines())[2:]:
            name, _, rest = line.partition(":")
            fields = rest.split()
            if len(fields) >= 9:
                counters[name.strip()] = (int(fields[0]), int(fields[8]))  # rx, tx bytes
        return counters

    def collect(self):
        now = time.monotonic()
        cpu = self._cpu_times()
        net = self._net_counters()
        if self.prev_cpu is None:
            # First sample: take a short baseline so CPU% is meaningful.
            self.prev_cpu, self.prev_net, self.prev_time = cpu, net, now
            time.sleep(1)
            now, cpu, net = time.monotonic(), self._cpu_times(), self._net_counters()

        cpu_pct = None
        if cpu and self.prev_cpu:
            dt, di = cpu[0] - self.prev_cpu[0], cpu[1] - self.prev_cpu[1]
            if dt > 0:
                cpu_pct = round(max(0.0, min(100.0, 100.0 * (dt - di) / dt)), 1)

        elapsed = max(now - self.prev_time, 0.001)
        rates = {}
        for name, (rx, tx) in net.items():
            if name in self.prev_net:
                prx, ptx = self.prev_net[name]
                rates[name] = (max(0, rx - prx) / elapsed, max(0, tx - ptx) / elapsed)
        self.prev_cpu, self.prev_net, self.prev_time = cpu, net, now

        return {
            "cpu_pct": cpu_pct,
            "cpu_count": os.cpu_count(),
            "load": [round(x, 2) for x in os.getloadavg()],
            "memory": memory(),
            "uptime_sec": uptime_sec(),
            "processes": sum(1 for d in os.listdir("/proc") if d.isdigit()),
            "disks": disks(),
            "network": network(net, rates),
        }


def memory():
    info = {}
    for line in read("/proc/meminfo", "").splitlines():
        key, _, val = line.partition(":")
        parts = val.split()
        if parts:
            info[key] = int(parts[0]) * 1024
    total = info.get("MemTotal", 0)
    avail = info.get("MemAvailable", info.get("MemFree", 0))
    swap_total = info.get("SwapTotal", 0)
    return {
        "total": total,
        "used": max(0, total - avail),
        "available": avail,
        "swap_total": swap_total,
        "swap_used": max(0, swap_total - info.get("SwapFree", 0)),
    }


def uptime_sec():
    try:
        return int(float(read("/proc/uptime", "0").split()[0]))
    except (ValueError, IndexError):
        return None


def disks():
    out, seen = [], set()
    for line in read("/proc/mounts", "").splitlines():
        parts = line.split()
        if len(parts) < 3:
            continue
        dev, mnt, fstype = parts[0], parts[1].replace("\\040", " "), parts[2]
        if fstype not in LOCAL_FS or dev in seen or mnt.startswith(SKIP_MOUNT_PREFIXES):
            continue
        seen.add(dev)
        try:
            st = os.statvfs(mnt)
        except OSError:
            continue
        size = st.f_blocks * st.f_frsize
        if size == 0:
            continue
        used = (st.f_blocks - st.f_bfree) * st.f_frsize
        avail = st.f_bavail * st.f_frsize
        out.append({
            "mount": mnt, "device": dev, "fstype": fstype,
            "size": size, "used": used, "available": avail,
            # Same formula as df: space reserved for root doesn't count.
            "used_pct": round(100.0 * used / (used + avail), 1) if used + avail else None,
        })
        if len(out) >= 40:
            break
    return out


def addresses():
    """{iface: {"mac": str, "addrs": [cidr, ...]}} via `ip -j addr`."""
    code, out = run(["ip", "-j", "addr", "show"], timeout=10)
    result = {}
    if code != 0:
        return result
    try:
        for link in json.loads(out):
            addrs = [f"{a['local']}/{a['prefixlen']}" for a in link.get("addr_info", [])
                     if a.get("scope") == "global" and "local" in a]
            result[link["ifname"]] = {"mac": link.get("address"), "addrs": addrs,
                                      "up": "UP" in link.get("flags", [])}
    except (ValueError, KeyError, TypeError):
        pass
    return result


def network(counters, rates):
    addrs = addresses()
    out = []
    for name, (rx, tx) in sorted(counters.items()):
        if name == "lo" or CONTAINER_IFACE.match(name):
            continue
        info = addrs.get(name, {})
        physical = os.path.exists(f"/sys/class/net/{name}/device")
        if not info.get("addrs") and not physical and name.startswith(VIRTUAL_IFACE_PREFIXES):
            continue
        speed = read(f"/sys/class/net/{name}/speed", "").strip()
        rx_rate, tx_rate = rates.get(name, (None, None))
        out.append({
            "name": name,
            "addrs": info.get("addrs", []),
            "mac": info.get("mac"),
            "up": info.get("up"),
            "speed_mbps": int(speed) if speed.lstrip("-").isdigit() and int(speed) > 0 else None,
            "rx_bytes": rx, "tx_bytes": tx,
            "rx_rate": round(rx_rate) if rx_rate is not None else None,
            "tx_rate": round(tx_rate) if tx_rate is not None else None,
        })
    return out[:30]


# ------------------------------------------------------- boot tracking

class BootTracker:
    """Tells whether the previous boot ended cleanly.

    The agent records "stopped cleanly" when systemd stops it (as it does on
    every normal shutdown or reboot). If the machine comes back up and that
    record is missing, the previous boot ended in a crash, hang or power
    loss. Works without a persistent journal.
    """

    def __init__(self):
        self.boot_id = (read("/proc/sys/kernel/random/boot_id", "") or "").strip()
        prev = {}
        try:
            with open(STATE_FILE, encoding="utf-8") as f:
                prev = json.load(f)
        except (OSError, ValueError):
            pass
        if prev.get("boot_id") and prev["boot_id"] != self.boot_id:
            self.previous_shutdown_clean = bool(prev.get("clean_stop"))
        elif prev.get("boot_id") == self.boot_id:
            # Agent restarted within the same boot: keep what we found at boot.
            self.previous_shutdown_clean = prev.get("previous_shutdown_clean")
        else:
            self.previous_shutdown_clean = None  # first run after install
        self._save(clean_stop=False)

    def _save(self, clean_stop):
        try:
            os.makedirs(os.path.dirname(STATE_FILE), mode=0o700, exist_ok=True)
            tmp = STATE_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"boot_id": self.boot_id, "clean_stop": clean_stop,
                           "previous_shutdown_clean": self.previous_shutdown_clean}, f)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, STATE_FILE)
        except OSError as e:
            log.warning("cannot write %s: %s", STATE_FILE, e)

    def mark_clean_stop(self):
        self._save(clean_stop=True)


BOOT = None  # set in run_forever()


# -------------------------------------------------------------- inventory

def os_release():
    info = {}
    for line in read("/etc/os-release", "").splitlines():
        key, _, val = line.partition("=")
        if key:
            info[key.lower()] = val.strip().strip('"')
    return {k: info.get(k) for k in ("pretty_name", "id", "id_like", "version_id", "version_codename")}


def hardware():
    dmi = lambda name: (read(f"/sys/class/dmi/id/{name}", "") or "").strip() or None
    model = None
    for line in read("/proc/cpuinfo", "").splitlines():
        if line.lower().startswith(("model name", "hardware", "cpu model")):
            model = line.split(":", 1)[1].strip()
            break
    code, virt = run(["systemd-detect-virt"], timeout=10)
    return {
        "vendor": dmi("sys_vendor"),
        "model": dmi("product_name"),
        "serial": dmi("product_serial"),
        "bios": dmi("bios_version"),
        "cpu_model": model,
        "cpu_count": os.cpu_count(),
        "memory_total": memory()["total"],
        "virtualization": virt.strip() if code == 0 else "none",
    }


def package_manager():
    if shutil.which("apt-get") and shutil.which("dpkg-query"):
        return "apt"
    if shutil.which("dnf"):
        return "dnf"
    if shutil.which("yum"):
        return "yum"
    return None


def packages(pm):
    if pm == "apt":
        _, out = run(["dpkg-query", "-W", "-f", "${db:Status-Abbrev}\t${Package}\t${Version}\n"])
        pkgs = []
        for line in out.splitlines():
            status, _, rest = line.partition("\t")
            name, _, ver = rest.partition("\t")
            if status.startswith("ii"):
                pkgs.append([name, ver])
        return pkgs
    if pm in ("dnf", "yum"):
        _, out = run(["rpm", "-qa", "--qf", "%{NAME}\t%{EPOCHNUM}:%{VERSION}-%{RELEASE}.%{ARCH}\n"])
        return [line.split("\t", 1) for line in out.splitlines() if "\t" in line]
    return []


APT_INST = re.compile(r"^Inst (\S+) (?:\[(\S+)\] )?\((\S+) (.*?)\)")


def updates(pm):
    """Pending updates from the package manager's existing cache.

    Doesn't refresh package lists itself (apt-daily / dnf-makecache timers
    do that), so this stays fast and doesn't hit mirrors every hour.
    """
    pkgs = []
    if pm == "apt":
        code, out = run(["apt-get", "-s", "-o", "Debug::NoLocking=1", "dist-upgrade"])
        if code != 0:
            return {"manager": pm, "error": "apt-get simulation failed", "packages": None}
        for line in out.splitlines():
            m = APT_INST.match(line)
            if m:
                name, current, new, origin = m.groups()
                pkgs.append({"name": name, "current": current, "new": new,
                             "security": "security" in origin.lower()})
    elif pm in ("dnf", "yum"):
        code, out = run([pm, "-q", "-C", "check-update"])
        if code not in (0, 100):
            return {"manager": pm, "error": f"{pm} check-update failed", "packages": None}
        security = set()
        _, sec_out = run([pm, "-q", "-C", "updateinfo", "list", "--security"])
        for line in sec_out.splitlines():
            parts = line.split()
            if len(parts) >= 3:
                # name-version-release.arch -> name
                security.add(parts[-1].rsplit("-", 2)[0])
        for line in out.splitlines():
            if line.startswith("Obsoleting"):
                break  # what follows are replacements, not upgrades
            parts = line.split()
            if len(parts) == 3 and not line.startswith(" "):
                name = parts[0].rsplit(".", 1)[0]
                pkgs.append({"name": name, "current": None, "new": parts[1],
                             "security": name in security})
    else:
        return {"manager": None, "packages": None}
    return {"manager": pm, "packages": pkgs}


def newer_kernel_installed():
    """True if a kernel newer than the running one is in /boot.

    Catches cases the distro flag misses (Proxmox doesn't create
    /var/run/reboot-required after kernel updates).
    """
    running = f"/boot/vmlinuz-{platform.release()}"
    if not os.path.exists(running):
        return None
    try:
        kernels = [os.path.join("/boot", f) for f in os.listdir("/boot") if f.startswith("vmlinuz-")]
        newest = max(kernels, key=os.path.getmtime)
        return os.path.getmtime(newest) > os.path.getmtime(running) + 60
    except (OSError, ValueError):
        return None


def reboot_required(pm):
    if os.path.exists("/var/run/reboot-required"):
        return True
    if pm in ("dnf", "yum") and shutil.which("needs-restarting"):
        code, _ = run(["needs-restarting", "-r"], timeout=60)
        if code in (0, 1):
            return code == 1
    return newer_kernel_installed()


# Services the server asked us to watch (from its report replies); their state
# goes out with every metrics report, and only these can be restarted by a job.
WATCHED = []
SERVICE_NAME = re.compile(r"^[A-Za-z0-9@._:\-+]{1,120}$")


def list_services():
    """Every loaded systemd service, for the dashboard's "watch a service" picker."""
    code, out = run(["systemctl", "list-units", "--type=service", "--all", "--no-legend", "--plain", "--no-pager"], timeout=20)
    if code is None:
        return None
    result = []
    for line in out.splitlines():
        parts = line.split(None, 4)
        if len(parts) >= 4 and parts[0].endswith(".service") and parts[1] != "not-found":
            result.append({"name": parts[0], "state": parts[2], "sub": parts[3],
                           "display": parts[4] if len(parts) > 4 else None})
    return result


def watched_services(names):
    """State of each watched unit: active state, sub-state, since (epoch s), restart count, PID."""
    names = [n for n in names if SERVICE_NAME.match(n)]
    if not names or not shutil.which("systemctl"):
        return []
    code, out = run(["systemctl", "show", "--no-pager", "--property=Id,LoadState,ActiveState,SubState,"
                     "Description,ActiveEnterTimestampMonotonic,InactiveEnterTimestampMonotonic,NRestarts,MainPID,UnitFileState"]
                    + names, timeout=20)
    if code is None:
        return []
    up = uptime_sec() or 0
    boot = time.time() - up
    result = []
    for name, block in zip(names, out.strip().split("\n\n")):
        p = dict(line.split("=", 1) for line in block.splitlines() if "=" in line)
        if p.get("LoadState") in (None, "not-found"):
            result.append({"name": name, "missing": True})
            continue
        active = p.get("ActiveState")
        mono = p.get("ActiveEnterTimestampMonotonic" if active == "active" else "InactiveEnterTimestampMonotonic", "0")
        since = int(boot + int(mono) / 1e6) if mono.isdigit() and int(mono) > 0 else None
        result.append({
            "name": name, "display": p.get("Description"), "state": active, "sub": p.get("SubState"),
            "since": since, "restarts": int(p["NRestarts"]) if p.get("NRestarts", "").isdigit() else None,
            "pid": int(p["MainPID"]) if p.get("MainPID", "0").isdigit() and p.get("MainPID") != "0" else None,
            "start_type": p.get("UnitFileState") or None,
        })
    return result


def failed_services():
    code, out = run(["systemctl", "list-units", "--type=service", "--state=failed",
                     "--no-legend", "--plain", "--no-pager"], timeout=20)
    if code is None:
        return None
    return [line.split()[0] for line in out.splitlines() if line.strip()]


# Antivirus products recognised on Linux: systemd units that mean it's
# installed (the first that exists) and running (any active).
LINUX_AV = [
    ("ClamAV", ["clamav-daemon.service", "clamd@scan.service", "clamd.service"]),
    ("Microsoft Defender for Endpoint", ["mdatp.service"]),
    ("CrowdStrike Falcon", ["falcon-sensor.service"]),
    ("Sophos Protection", ["sophos-spl.service"]),
    ("ESET Endpoint Antivirus", ["eea.service", "esets.service"]),
    ("SentinelOne", ["sentinelone.service"]),
]
CLAMAV_DB_DIRS = ["/var/lib/clamav"]


def unit_state(unit):
    """'active', 'inactive', 'failed', ... or None when the unit doesn't exist."""
    code, out = run(["systemctl", "show", unit, "--property=LoadState,ActiveState", "--no-pager"], timeout=10)
    if code is None:
        return None
    props = dict(line.split("=", 1) for line in out.splitlines() if "=" in line)
    if props.get("LoadState") in (None, "not-found"):
        return None
    return props.get("ActiveState")


def clamav_signature_age_days():
    newest = None
    for d in CLAMAV_DB_DIRS:
        for name in ("daily.cld", "daily.cvd"):
            try:
                m = os.stat(os.path.join(d, name)).st_mtime
            except OSError:
                continue
            newest = m if newest is None else max(newest, m)
    return None if newest is None else int((time.time() - newest) // 86400)


def antivirus():
    """Installed antivirus products: enabled = its service runs; up_to_date where known."""
    if not shutil.which("systemctl"):
        return {"products": [], "error": "systemctl not available"}
    products = []
    for name, units in LINUX_AV:
        states = [s for s in (unit_state(u) for u in units) if s is not None]
        if not states:
            continue
        p = {"name": name, "enabled": "active" in states, "up_to_date": None, "realtime": None,
             "signature_age_days": None, "last_scan": None, "source": "systemd"}
        if name == "ClamAV":
            age = clamav_signature_age_days()
            p["signature_age_days"] = age
            p["up_to_date"] = None if age is None else age <= 3
            # clamd only scans on demand unless on-access scanning (clamonacc) runs too.
            p["realtime"] = unit_state("clamav-clamonacc.service") == "active" or unit_state("clamonacc.service") == "active"
        elif name == "Microsoft Defender for Endpoint":
            code, out = run(["mdatp", "health", "--field", "real_time_protection_enabled"], timeout=20)
            if code == 0 and out.strip() in ("true", "false"):
                p["realtime"] = out.strip() == "true"
            code, out = run(["mdatp", "health", "--field", "definitions_status"], timeout=20)
            if code == 0 and out.strip():
                p["up_to_date"] = "up_to_date" in out.replace('"', "").replace("-", "_").lower()
        products.append(p)
    return {"products": products}


def collect_inventory():
    pm = package_manager()
    up = uptime_sec()
    return {
        "hostname": socket.gethostname(),
        "os": os_release(),
        "kernel": platform.release(),
        "arch": platform.machine(),
        "boot_time": int(time.time() - up) if up is not None else None,
        "hardware": hardware(),
        "packages": packages(pm),
        "updates": updates(pm),
        "reboot_required": reboot_required(pm),
        "failed_services": failed_services(),
        "services": list_services(),
        "antivirus": antivirus(),
        "last_boot": {"previous_shutdown_clean": BOOT.previous_shutdown_clean if BOOT else None},
        "agent": {"version": VERSION, "python": platform.python_version()},
    }


# ------------------------------------------------------------- transport

class Client:
    def __init__(self, server, token=None):
        self.server = server.rstrip("/")
        self.token = token
        self.ctx = ssl.create_default_context(cafile=CA_FILE)

    def post(self, action, payload, headers=None):
        body = json.dumps(payload, separators=(",", ":")).encode()
        hdrs = {"Content-Type": "application/json", "User-Agent": f"webmonitor-agent/{VERSION}"}
        if len(body) > 2048:
            body = gzip.compress(body)
            hdrs["Content-Encoding"] = "gzip"
        if self.token:
            hdrs["X-Agent-Token"] = self.token
        hdrs.update(headers or {})
        req = urllib.request.Request(f"{self.server}/api/agent.php?action={action}",
                                     data=body, headers=hdrs, method="POST")
        try:
            with urllib.request.urlopen(req, context=self.ctx, timeout=60) as resp:
                return resp.status, json.loads(resp.read() or b"{}")
        except urllib.error.HTTPError as e:
            try:
                detail = json.loads(e.read() or b"{}")
            except ValueError:
                detail = {}
            return e.code, detail

    def get(self, path):
        """GET a file from the server (same pinned TLS); returns bytes."""
        req = urllib.request.Request(f"{self.server}/{path.lstrip('/')}",
                                     headers={"User-Agent": f"webmonitor-agent/{VERSION}"})
        with urllib.request.urlopen(req, context=self.ctx, timeout=120) as resp:
            return resp.read()


def load_conf():
    with open(CONF_FILE, encoding="utf-8") as f:
        return json.load(f)


def save_conf(conf):
    os.makedirs(CONF_DIR, mode=0o700, exist_ok=True)
    tmp = CONF_FILE + ".tmp"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        json.dump(conf, f)
    os.replace(tmp, CONF_FILE)


def enroll(server, enroll_token):
    client = Client(server)
    status, resp = client.post("enroll", {"hostname": socket.gethostname(), "version": VERSION},
                               headers={"X-Enroll-Token": enroll_token})
    if status != 200 or "agent_token" not in resp:
        print(f"Enrollment failed ({status}): {resp.get('error', 'unexpected response')}", file=sys.stderr)
        return 1
    save_conf({"server": server.rstrip("/"), "agent_token": resp["agent_token"], "host_id": resp.get("host_id")})
    print(f"Enrolled with {server} as host #{resp.get('host_id')}.")
    return 0


# ------------------------------------------------------------- workloads

MAC_RE = re.compile(r"([0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5})")


def run_json(cmd, timeout=20):
    code, out = run(cmd, timeout=timeout)
    if code != 0 or not out.strip():
        return None
    try:
        return json.loads(out)
    except ValueError:
        return None


def arp_table():
    """{mac: ip} for IPv4 neighbours this host has seen."""
    table = {}
    for n in run_json(["ip", "-j", "neigh", "show"], timeout=10) or []:
        mac, ip = (n.get("lladdr") or "").lower(), n.get("dst") or ""
        if mac and "." in ip:
            table[mac] = ip
    return table


def proxmox_guests():
    """VMs and LXC containers on this Proxmox VE node, or None if not one."""
    if not shutil.which("pvesh"):
        return None
    node = socket.gethostname().split(".")[0]
    resources = run_json(["pvesh", "get", "/cluster/resources", "--type", "vm", "--output-format", "json"], timeout=30)
    if resources is None:
        return {"error": "pvesh /cluster/resources failed", "guests": []}
    arp = arp_table()
    guests = []
    for r in resources:
        if r.get("node") != node or r.get("template"):
            continue
        kind, vmid = r.get("type"), r.get("vmid")
        if kind not in ("qemu", "lxc") or vmid is None:
            continue
        base = f"/nodes/{node}/{kind}/{vmid}"
        config = run_json(["pvesh", "get", base + "/config", "--output-format", "json"], timeout=15) or {}
        macs, ips = [], []
        for key, val in config.items():
            if not re.fullmatch(r"net\d+", key) or not isinstance(val, str):
                continue
            m = MAC_RE.search(val)
            if m:
                macs.append(m.group(1).lower())
            ipm = re.search(r"(?:^|,)ip=([0-9.]+)/", val)   # LXC static address
            if ipm:
                ips.append(ipm.group(1))
        if r.get("status") == "running":
            if kind == "qemu" and str(config.get("agent", "0")).split(",")[0] in ("1", "enabled=1"):
                data = run_json(["pvesh", "get", base + "/agent/network-get-interfaces", "--output-format", "json"], timeout=8)
                for iface in (data or {}).get("result", []) if isinstance(data, dict) else []:
                    for a in iface.get("ip-addresses", []):
                        if a.get("ip-address-type") == "ipv4" and not a.get("ip-address", "").startswith("127."):
                            ips.append(a["ip-address"])
            elif kind == "lxc":
                for iface in run_json(["pvesh", "get", base + "/interfaces", "--output-format", "json"], timeout=8) or []:
                    inet = (iface.get("inet") or "").split("/")[0]
                    if inet and not inet.startswith("127."):
                        ips.append(inet)
        ips += [arp[m] for m in macs if m in arp]
        guests.append({
            "vmid": vmid, "type": kind, "name": r.get("name") or config.get("hostname") or f"{kind}-{vmid}",
            "status": r.get("status"), "macs": sorted(set(macs)), "ips": sorted(set(ips)),
            "cpus": r.get("maxcpu"), "memory": r.get("maxmem"),
        })
    code, ver = run(["pveversion"], timeout=10)
    return {"node": node, "version": ver.strip().split("/")[1] if code == 0 and "/" in ver else None,
            "guests": sorted(guests, key=lambda g: g["vmid"])}


def parse_labels(raw):
    if isinstance(raw, dict):
        return raw
    out = {}
    for part in (raw or "").split(","):
        k, _, v = part.partition("=")
        if k:
            out[k.strip()] = v.strip()
    return out


def containers():
    """Docker (or Podman) containers on this host, or None if neither runs here."""
    for tool in ("docker", "podman"):
        if not shutil.which(tool):
            continue
        code, out = run([tool, "ps", "-a", "--no-trunc", "--format", "{{json .}}"], timeout=20)
        if code != 0:
            continue   # e.g. daemon not running; try the other tool
        items = []
        for line in out.splitlines():
            try:
                c = json.loads(line)
            except ValueError:
                continue
            names = c.get("Names")
            name = (names[0] if isinstance(names, list) and names else names or "").lstrip("/")
            labels = parse_labels(c.get("Labels"))
            status = c.get("Status") or ""
            health = "healthy" if "(healthy)" in status else "unhealthy" if "(unhealthy)" in status \
                else "starting" if "health: starting" in status else None
            ports = c.get("Ports")
            if isinstance(ports, list):   # podman
                ports = ", ".join(f"{p.get('host_port')}->{p.get('container_port')}/{p.get('protocol', 'tcp')}"
                                  for p in ports if p.get("host_port"))
            items.append({
                "id": (c.get("ID") or c.get("Id") or "")[:12],
                "name": name,
                "image": c.get("Image"),
                "state": (c.get("State") or "").lower(),
                "status": status,
                "health": health,
                "ports": ports or "",
                "project": labels.get("com.docker.compose.project") or labels.get("io.podman.compose.project"),
            })
        if items or tool == "docker":
            return {"engine": tool, "containers": sorted(items, key=lambda x: (x["project"] or "~", x["name"]))}
    return None


def collect_workloads():
    return {"proxmox": proxmox_guests(), "containers": containers()}


# ------------------------------------------------------------------ jobs

JOB_POLL_SEC = 20
JOB_FLUSH_SEC = 10
JOB_MAX_SEC = 3 * 3600
# Non-interactive package installs that keep existing config files and wait
# for another apt (e.g. unattended-upgrades) instead of failing.
APT_ENV = {"DEBIAN_FRONTEND": "noninteractive", "NEEDRESTART_MODE": "a", "APT_LISTCHANGES_FRONTEND": "none"}
APT_OPTS = ["-o", "Dpkg::Options::=--force-confdef", "-o", "Dpkg::Options::=--force-confold",
            "-o", "DPkg::Lock::Timeout=600"]


class JobFailed(Exception):
    pass


class JobRunner(threading.Thread):
    """Runs one job in the background, streaming output to the server."""

    def __init__(self, client, job):
        super().__init__(daemon=True)
        self.client = client
        self.job = job
        self.buf = []
        self.lock = threading.Lock()
        self.done = threading.Event()
        self.reboot = False
        self.restart_agent = False

    def emit(self, text):
        with self.lock:
            self.buf.append(text if text.endswith("\n") else text + "\n")

    def send(self, status, **extra):
        with self.lock:
            chunk, self.buf = "".join(self.buf), []
        payload = {"id": self.job["id"], "status": status, "output": chunk, **extra}
        try:
            code, _ = self.client.post("job_update", payload)
        except (OSError, ssl.SSLError, ValueError) as e:
            code = None
            log.warning("job %s: update failed: %s", self.job["id"], e)
        if code not in (200, 409):
            with self.lock:  # keep the output for the next attempt
                self.buf.insert(0, chunk)
        return code

    def run_cmd(self, cmd, env=None):
        """Runs a command, streaming its output; returns the exit code."""
        self.emit("$ " + " ".join(cmd))
        full_env = dict(os.environ, LC_ALL="C", LANG="C", **(env or {}))
        try:
            p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                 stdin=subprocess.DEVNULL, env=full_env, text=True, errors="replace")
        except OSError as e:
            raise JobFailed(f"cannot run {cmd[0]}: {e}")
        deadline = time.monotonic() + JOB_MAX_SEC
        for line in p.stdout:
            self.emit(line.rstrip("\n"))
            if time.monotonic() > deadline:
                p.kill()
                raise JobFailed(f"{cmd[0]} took longer than {JOB_MAX_SEC // 3600} hours")
        return p.wait()

    def run(self):
        flusher = threading.Thread(target=self._flush_loop, daemon=True)
        flusher.start()
        status, exit_code, summary = "succeeded", 0, None
        try:
            handler = JOB_HANDLERS.get(self.job["type"])
            if handler is None:
                raise JobFailed(f"this agent ({VERSION}) doesn't know job type {self.job['type']!r}")
            summary = handler(self, self.job.get("params") or {})
        except JobFailed as e:
            status, exit_code, summary = "failed", 1, str(e)
            self.emit("ERROR: " + str(e))
        except Exception as e:  # report anything unexpected rather than dying silently
            status, exit_code, summary = "failed", 1, f"agent error: {e}"
            self.emit("ERROR: " + repr(e))
        self.done.set()
        for attempt in range(6):  # make sure the final status gets through
            if self.send(status, exit_code=exit_code, summary=summary, rebooting=self.reboot) in (200, 409):
                break
            time.sleep(10 * (attempt + 1))
        if self.reboot:
            log.info("job %s: rebooting in 1 minute", self.job["id"])
            subprocess.run(["shutdown", "-r", "+1", "WebMonitor: rebooting (job %s)" % self.job["id"]], check=False)

    def _flush_loop(self):
        while not self.done.wait(JOB_FLUSH_SEC):
            self.send("running")


def job_refresh(job, params):
    pm = package_manager()
    if pm == "apt":
        code = job.run_cmd(["apt-get", "update"] + APT_OPTS, APT_ENV)
    elif pm in ("dnf", "yum"):
        code = job.run_cmd([pm, "-y", "makecache", "--refresh"])
    else:
        raise JobFailed("no supported package manager (apt or dnf) found")
    if code != 0:
        raise JobFailed(f"refreshing package lists failed (exit {code})")
    pkgs = updates(pm).get("packages") or []
    sec = sum(1 for p in pkgs if p["security"])
    return f"{len(pkgs)} updates available ({sec} security)"


def job_updates(job, params):
    pm = package_manager()
    security_only = bool(params.get("security_only"))
    if pm == "apt":
        if job.run_cmd(["apt-get", "update"] + APT_OPTS, APT_ENV) != 0:
            raise JobFailed("apt-get update failed")
        if security_only:
            # Debian/Ubuntu have no "security only" switch; upgrade exactly
            # the packages that come from the security archive.
            names = sorted({p["name"] for p in (updates(pm).get("packages") or []) if p["security"]})
            if not names:
                job.emit("No security updates to install.")
                return finish_updates(job, pm, params, "no security updates were pending")
            code = job.run_cmd(["apt-get", "-y", "install", "--only-upgrade"] + APT_OPTS + names, APT_ENV)
        else:
            code = job.run_cmd(["apt-get", "-y", "dist-upgrade"] + APT_OPTS, APT_ENV)
    elif pm in ("dnf", "yum"):
        cmd = [pm, "-y", "upgrade", "--refresh"] + (["--security"] if security_only else [])
        code = job.run_cmd(cmd)
    else:
        raise JobFailed("no supported package manager (apt or dnf) found")
    if code != 0:
        raise JobFailed(f"the package manager exited with code {code}")
    return finish_updates(job, pm, params, "updates installed")


def finish_updates(job, pm, params, what):
    left = updates(pm).get("packages") or []
    needs_reboot = bool(reboot_required(pm))
    msg = f"{what}; {len(left)} still pending; reboot {'required' if needs_reboot else 'not needed'}"
    if needs_reboot and params.get("reboot"):
        job.reboot = True
        msg += " — rebooting now"
    return msg


def job_reboot(job, params):
    job.emit("Rebooting in 1 minute.")
    job.reboot = True
    return "rebooting"


def job_agent_upgrade(job, params):
    me = os.path.realpath(__file__)
    try:
        code = job.client.get("agent/webmonitor-agent.py")
    except (OSError, ssl.SSLError) as e:
        raise JobFailed(f"download failed: {e}")
    m = re.search(rb'^VERSION = "([^"]+)"', code, re.M)
    if not m:
        raise JobFailed("downloaded file doesn't look like the agent")
    new_version = m.group(1).decode()
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(me), suffix=".py")
    with os.fdopen(fd, "wb") as f:
        f.write(code)
    try:
        compile(code, tmp, "exec")  # refuse to install something that won't run
    except SyntaxError as e:
        os.unlink(tmp)
        raise JobFailed(f"downloaded agent has a syntax error: {e}")
    os.chmod(tmp, 0o755)
    os.replace(tmp, me)
    job.emit(f"Installed agent {new_version} (was {VERSION}); restarting.")
    job.restart_agent = True
    return f"upgraded {VERSION} -> {new_version}"


def job_service_restart(job, params):
    name = str(params.get("service") or "")
    if not SERVICE_NAME.match(name):
        raise JobFailed(f"not a valid service name: {name!r}")
    if name not in WATCHED:
        raise JobFailed(f"{name} is not on this host's watched list; only watched services can be restarted")
    if job.run_cmd(["systemctl", "restart", name]) != 0:
        job.run_cmd(["systemctl", "status", "--no-pager", "--lines=20", name])
        raise JobFailed(f"systemctl restart {name} failed")
    time.sleep(3)
    state = (watched_services([name]) or [{}])[0]
    job.emit(f"{name}: {state.get('state')} ({state.get('sub')})")
    if state.get("state") != "active":
        raise JobFailed(f"{name} restarted but is {state.get('state')} ({state.get('sub')})")
    return f"restarted {name}; it is running"


JOB_HANDLERS = {
    "service_restart": job_service_restart,
    "refresh": job_refresh,
    "updates": job_updates,
    "reboot": job_reboot,
    "agent_upgrade": job_agent_upgrade,
}


def run_forever():
    global BOOT
    BOOT = BootTracker()

    def stop(signum, _frame):
        BOOT.mark_clean_stop()
        log.info("Stopping (signal %s)", signum)
        sys.exit(0)
    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)

    conf = load_conf()
    client = Client(conf["server"], conf["agent_token"])
    intervals = dict(DEFAULT_INTERVALS)
    collector = MetricsCollector()
    next_due = {"inventory": 0.0, "metrics": 0.0, "workloads": 10.0, "jobs": 5.0}
    failures = 0
    job = None
    log.info("WebMonitor agent %s reporting to %s", VERSION, conf["server"])

    while True:
        now = time.monotonic()
        if job is not None and not job.is_alive():
            if job.restart_agent:
                log.info("Restarting into the upgraded agent")
                os.execv(sys.executable, [sys.executable, os.path.realpath(__file__)])
            job = None
            next_due["inventory"] = 0.0  # report the new state right away
            next_due["metrics"] = 0.0
        if job is None and now >= next_due["jobs"]:
            next_due["jobs"] = now + JOB_POLL_SEC
            try:
                status, resp = client.post("jobs", {"version": VERSION})
                if status == 200 and resp.get("job"):
                    log.info("Starting job %s (%s)", resp["job"]["id"], resp["job"]["type"])
                    job = JobRunner(client, resp["job"])
                    job.start()
            except (OSError, ssl.SSLError, ValueError) as e:
                log.warning("job poll failed: %s", e)

        for kind in ("inventory", "workloads", "metrics"):
            if now < next_due[kind]:
                continue
            try:
                data = (collect_inventory() if kind == "inventory"
                        else collect_workloads() if kind == "workloads" else collector.collect())
                if kind == "metrics" and WATCHED:
                    data["services"] = watched_services(WATCHED)
                status, resp = client.post("report", {"kind": kind, "version": VERSION, "data": data})
            except (OSError, ssl.SSLError, ValueError) as e:
                status, resp = None, {"error": str(e)}

            if status == 200:
                failures = 0
                intervals.update({k: int(v) for k, v in resp.get("intervals", {}).items()
                                  if k in intervals and isinstance(v, int) and v >= 10})
                watch = resp.get("watch_services")
                if isinstance(watch, list):
                    new = [n for n in watch if isinstance(n, str) and SERVICE_NAME.match(n)][:200]
                    if new != WATCHED:
                        WATCHED[:] = new
                        next_due["metrics"] = 0.0  # report the newly watched services right away
                next_due[kind] = time.monotonic() + intervals[kind]
            elif status == 401:
                # Removed or re-installed from the dashboard; don't hammer.
                log.error("Server rejected this agent's token: %s", resp.get("error"))
                next_due[kind] = time.monotonic() + 600
            else:
                failures += 1
                retry = min(300, 15 * 2 ** min(failures, 5))
                log.warning("%s report failed (%s): %s — retrying in %ss",
                            kind, status, resp.get("error"), retry)
                next_due[kind] = time.monotonic() + retry
        due = [t for k, t in next_due.items() if k != "jobs" or job is None]
        time.sleep(max(1.0, min(min(due) - time.monotonic(), 5.0 if job else 3600)))


def main():
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    p = argparse.ArgumentParser(description="WebMonitor agent")
    p.add_argument("--enroll", metavar="TOKEN", help="one-time enrollment token")
    p.add_argument("--server", help="WebMonitor URL, e.g. https://192.168.1.10/webmonitor")
    p.add_argument("--print", choices=["metrics", "inventory", "workloads"], help="print a report and exit")
    p.add_argument("--version", action="version", version=VERSION)
    args = p.parse_args()

    if args.print:
        data = (collect_inventory() if args.print == "inventory"
                else collect_workloads() if args.print == "workloads" else MetricsCollector().collect())
        json.dump(data, sys.stdout, indent=2)
        print()
        return 0
    if args.enroll:
        if not args.server:
            p.error("--enroll needs --server")
        return enroll(args.server, args.enroll)
    run_forever()
    return 0


if __name__ == "__main__":
    sys.exit(main())
