cat > "$APP_DIR/api/scan-queue.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/../includes/devicescan.php';
require_once __DIR__ . '/../includes/discovery.php';
require_once __DIR__ . '/../includes/auth.php';
header('Content-Type: application/json');
require_api_auth_admin_writes();

$pdo = db();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $input = json_decode(file_get_contents('php://input'), true) ?? [];
    $subnet = (string) ($input['subnet'] ?? '');
    if (!preg_match('#^\d{1,3}\.\d{1,3}\.\d{1,3}\.0/24$#', $subnet)
        || !filter_var(substr($subnet, 0, -3), FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
        http_response_code(400);
        echo json_encode(['error' => 'not a /24 subnet']);
        exit;
    }
    $now = (int) round(microtime(true) * 1000);
    $stmt = $pdo->prepare('UPDATE subnet_scans SET requested_at = GREATEST(COALESCE(requested_at, 0) + 1, ?), priority_at = ? WHERE subnet = ?');
    $stmt->execute([$now, next_scan_priority(), $subnet]);
    if (!$stmt->rowCount()) {
        http_response_code(404);
        echo json_encode(['error' => 'subnet scan settings not found']);
        exit;
    }
    echo json_encode(['ok' => true]);
    exit;
}
if ($_SERVER['REQUEST_METHOD'] !== 'GET') {
    http_response_code(405);
    echo json_encode(['error' => 'method not allowed']);
    exit;
}

$active = active_scans();
$deviceRequests = $pdo->query('SELECT ip, mac, requested_at, priority_at FROM device_scans
                               WHERE requested_at IS NOT NULL ORDER BY priority_at DESC, requested_at, dkey')->fetchAll();
$subnets = subnet_scan_rows();
$result = ['active' => $active, 'requested' => count($deviceRequests) + count(array_filter($subnets, fn($r) => $r['requested_at'] !== null))];
if (!empty($_GET['details'])) {
    $result['devices'] = array_map(fn($r) => ['ip' => $r['ip'], 'mac' => $r['mac'], 'requestedAt' => (int) $r['requested_at'],
                                              'priority' => $r['priority_at'] !== null], $deviceRequests);
    $result['dueDevices'] = array_map(fn($r) => ['ip' => $r[2], 'mac' => $r[1], 'name' => $r[3], 'scannedAt' => $r[0] ?: null], due_device_scans());
    $names = subnet_names();
    $result['subnets'] = [];
    foreach ($subnets as $subnet => $r) {
        if (!$r['enabled'] && $r['requested_at'] === null) continue;
        $result['subnets'][] = [
            'subnet' => $subnet, 'name' => $names[$subnet] ?? null,
            'requestedAt' => $r['requested_at'] !== null ? (int) $r['requested_at'] : null,
            'priority' => $r['priority_at'] !== null ? (int) $r['priority_at'] : null,
            'dueAt' => $r['enabled'] ? ($r['last_scan_at'] ? (int) $r['last_scan_at'] + (int) $r['every_min'] * 60000 : 0) : null,
        ];
    }
    usort($result['subnets'], fn($a, $b) => ($b['priority'] ?? 0) <=> ($a['priority'] ?? 0) ?: ($a['dueAt'] ?? PHP_INT_MAX) <=> ($b['dueAt'] ?? PHP_INT_MAX));
}
echo json_encode($result);
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/api/scan.php")"
cat > "$APP_DIR/api/scan.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/../includes/scanner.php';
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/scanqueue.php';
header('Content-Type: application/json');
require_api_auth('admin');

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode(['error' => 'method not allowed']);
    exit;
}

set_time_limit(120);

$input = json_decode(file_get_contents('php://input'), true) ?? [];
$networksRaw = trim((string) ($input['networks'] ?? ''));
$doSnmp = !empty($input['snmp']);
$community = trim((string) ($input['community'] ?? 'public'));
if ($community === '') $community = 'public';
$community = substr($community, 0, 64);

if ($networksRaw === '') {
    http_response_code(400);
    echo json_encode(['error' => 'networks is required, e.g. 192.168.1.0/24']);
    exit;
}

try {
    $ips = parse_networks($networksRaw);
} catch (InvalidArgumentException $e) {
    http_response_code(400);
    echo json_encode(['error' => $e->getMessage()]);
    exit;
}

if (!$ips) {
    http_response_code(400);
    echo json_encode(['error' => 'no addresses to scan']);
    exit;
}

$lock = 'webmonitor_adhoc_' . bin2hex(random_bytes(12));
$pdo = db();
$stmt = $pdo->prepare('SELECT GET_LOCK(?, 0)');
$stmt->execute([$lock]);
if (!(int) $stmt->fetchColumn()) {
    http_response_code(503);
    echo json_encode(['error' => 'could not start scan']);
    exit;
}
try {
scan_activity_start($lock, 'subnet', mb_substr($networksRaw, 0, 255));
$sweepResults = network_sweep($ips, NETCHECK_PORTS, 1.5);

$existing = [];
foreach (db()->query('SELECT id, ip_address FROM hosts') as $row) {
    $existing[$row['ip_address']] = (int) $row['id'];
}

$snmpAvailable = snmp_available();
$snmpActive = $doSnmp && $snmpAvailable;

$results = [];
foreach ($ips as $ip) {
    $sweep = $sweepResults[$ip];
    if (!$sweep['up']) continue;

    $snmp = $snmpActive ? snmp_probe($ip, $community, 1.0) : null;
    $classification = classify_device($sweep['port'], $sweep['open'], $snmp);

    $results[] = [
        'ip' => $ip,
        'port' => $sweep['port'],
        'open' => $sweep['open'],
        'ms' => $sweep['ms'],
        'snmp' => $snmp,
        'os' => $classification['os'],
        'device' => $classification['device'],
        'label' => $classification['label'],
        'confidence' => $classification['confidence'],
        'monitored' => isset($existing[$ip]),
        'hostId' => $existing[$ip] ?? null,
    ];
}

} finally {
    scan_activity_end($lock);
    $stmt = $pdo->prepare('SELECT RELEASE_LOCK(?)');
    $stmt->execute([$lock]);
}
echo json_encode([
    'scanned' => count($ips),
    'active' => count($results),
    'snmpRequested' => $doSnmp,
    'snmpAvailable' => $snmpAvailable,
    'results' => $results,
]);
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/api/schedules.php")"
cat > "$APP_DIR/api/schedules.php" <<'WEBMON_FILE_EOF'
<?php
// Update schedules (Updates view).
//   GET                         -> {schedules, conflicts, timezone}       (any user)
//   POST   ?preview=1   {id?, ...} -> conflicts this schedule would have   (admins)
//   POST                {...}   -> create                                  (admins)
//   PATCH  ?id=N        {...}   -> update (any subset, e.g. {enabled})     (admins)
//   DELETE ?id=N                -> delete                                  (admins)
//   POST   ?id=N&run=1          -> run now                                 (admins)
require_once __DIR__ . '/../includes/schedules.php';
require_once __DIR__ . '/../includes/auth.php';
header('Content-Type: application/json');
$me = require_api_auth_admin_writes();

function fail(int $code, string $msg): void {
    http_response_code($code);
    echo json_encode(['error' => $msg]);
    exit;
}

/**
 * Marks the most recent occurrence as already handled, so creating or
 * editing a schedule never fires it immediately for a time just passed.
 */
function skip_past_occurrence(int $id): void {
    $stmt = db()->prepare('SELECT * FROM update_schedules WHERE id = ?');
    $stmt->execute([$id]);
    $s = $stmt->fetch();
    $occ = $s ? schedule_last_occurrence($s, new DateTimeImmutable()) : null;
    db()->prepare('UPDATE update_schedules SET last_run_key = ? WHERE id = ?')
        ->execute([$occ ? $occ->format('Y-m-d H:i') : null, $id]);
}

$pdo = db();
$method = $_SERVER['REQUEST_METHOD'];
$input = $method === 'GET' ? [] : (json_decode(file_get_contents('php://input'), true) ?? []);
$id = (int) ($_GET['id'] ?? 0);

$serverIp = (string) ($_SERVER['SERVER_ADDR'] ?? '');

if ($method === 'GET') {
    $rows = $pdo->query('SELECT * FROM update_schedules ORDER BY at_time, name')->fetchAll();
    echo json_encode([
        'schedules' => array_map(fn($r) => schedule_row($r) + ['resolvedHostIds' => schedule_host_ids($r)], $rows),
        'conflicts' => schedule_conflicts($rows, $serverIp),
        'timezone' => date_default_timezone_get(),
    ]);
    exit;
}

// Conflicts the schedule in the form would have if saved (nothing is saved).
if ($method === 'POST' && !empty($_GET['preview'])) {
    try {
        $f = schedule_fields($input);
    } catch (InvalidArgumentException $e) {
        echo json_encode(['conflicts' => [], 'invalid' => $e->getMessage()]);
        exit;
    }
    $candidateId = (int) ($input['id'] ?? 0);
    $rows = array_values(array_filter($pdo->query('SELECT * FROM update_schedules')->fetchAll(),
        fn($r) => (int) $r['id'] !== $candidateId));
    $rows[] = $f + ['id' => $candidateId, 'enabled' => 1, 'created_by' => null];
    $mine = array_values(array_filter(schedule_conflicts($rows, $serverIp),
        fn($c) => in_array($candidateId, $c['scheduleIds'], true)));
    echo json_encode(['conflicts' => $mine]);
    exit;
}

if ($method === 'POST' && !$id) {
    try {
        $f = schedule_fields($input);
    } catch (InvalidArgumentException $e) {
        fail(400, $e->getMessage());
    }
    $pdo->prepare('INSERT INTO update_schedules (name, enabled, job_type, params, days, at_time, targets, host_ids, created_by, created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
        ->execute([$f['name'], $f['enabled'], $f['job_type'], $f['params'], $f['days'], $f['at_time'],
                   $f['targets'], $f['host_ids'], $me['id'], now_ms()]);
    $newId = (int) $pdo->lastInsertId();
    skip_past_occurrence($newId);
    http_response_code(201);
    echo json_encode(['id' => $newId]);
    exit;
}

$stmt = $pdo->prepare('SELECT * FROM update_schedules WHERE id = ?');
$stmt->execute([$id]);
$sched = $stmt->fetch();
if (!$sched) fail(404, 'Schedule not found.');

if ($method === 'POST' && !empty($_GET['run'])) {
    echo json_encode(run_schedule($sched, true));
    exit;
}

if ($method === 'PATCH') {
    $current = schedule_row($sched);
    try {
        $f = schedule_fields(array_merge([
            'name' => $current['name'], 'jobType' => $current['jobType'], 'params' => $current['params'],
            'days' => $current['days'], 'atTime' => $current['atTime'], 'targets' => $current['targets'],
            'hostIds' => $current['hostIds'], 'enabled' => $current['enabled'],
        ], $input));
    } catch (InvalidArgumentException $e) {
        fail(400, $e->getMessage());
    }
    $pdo->prepare('UPDATE update_schedules SET name = ?, enabled = ?, job_type = ?, params = ?, days = ?, at_time = ?,
                   targets = ?, host_ids = ? WHERE id = ?')
        ->execute([$f['name'], $f['enabled'], $f['job_type'], $f['params'], $f['days'], $f['at_time'],
                   $f['targets'], $f['host_ids'], $id]);
    skip_past_occurrence($id);
    echo json_encode(['ok' => true]);
    exit;
}

if ($method === 'DELETE') {
    $pdo->prepare('DELETE FROM update_schedules WHERE id = ?')->execute([$id]);
    http_response_code(204);
    exit;
}

fail(405, 'method not allowed');
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/api/services.php")"
cat > "$APP_DIR/api/services.php" <<'WEBMON_FILE_EOF'
<?php
// Service monitoring (Services tab).
//   GET                          -> {services: [...]}
//   GET ?host=ID                 -> {services: [...]} for one host
//   GET ?available=HOSTID        -> services the host's agent can watch (picker)
//   POST {kind, hostId, name, target, options, interval, alert}   -> add; admins
//   PUT ?id=ID {...}             -> change; admins
//   DELETE ?id=ID                -> remove; admins
//   POST ?id=ID&action=check     -> check now (network checks); admins
//   POST ?id=ID&action=restart   -> restart a watched agent service (agent job); admins
require_once __DIR__ . '/../includes/services.php';
require_once __DIR__ . '/../includes/jobs.php';
require_once __DIR__ . '/../includes/auth.php';
header('Content-Type: application/json');
$user = require_api_auth_admin_writes();
session_write_close();

function fail(int $code, string $msg): void {
    http_response_code($code);
    echo json_encode(['error' => $msg]);
    exit;
}

function load_service(int $id): array {
    $st = db()->prepare('SELECT * FROM services WHERE id = ?');
    $st->execute([$id]);
    $s = $st->fetch();
    if (!$s) fail(404, 'That check no longer exists.');
    return $s;
}

$method = $_SERVER['REQUEST_METHOD'];
$id = (int) ($_GET['id'] ?? 0);

if ($method === 'GET') {
    if (isset($_GET['available'])) {
        $a = agent_available_services((int) $_GET['available']);
        if (!$a) fail(404, 'That host has no agent.');
        echo json_encode($a);
        exit;
    }
    echo json_encode(['services' => service_list(isset($_GET['host']) ? (int) $_GET['host'] : null)]);
    exit;
}

$input = json_decode(file_get_contents('php://input'), true) ?? [];
$pdo = db();

if ($method === 'POST' && $id && ($_GET['action'] ?? '') === 'check') {
    $s = load_service($id);
    if ($s['kind'] === 'agent') fail(400, 'Agent services are reported by the agent every minute.');
    run_service_checks([$s]);
    echo json_encode(['services' => service_list()]);
    exit;
}

if ($method === 'POST' && $id && ($_GET['action'] ?? '') === 'restart') {
    $s = load_service($id);
    if ($s['kind'] !== 'agent') fail(400, 'Only agent services can be restarted.');
    $a = agent_available_services((int) $s['host_id']);
    $min = $a ? SERVICE_RESTART_MIN_AGENT[$a['platform']] : null;
    if (!$a || !$a['version'] || version_compare($a['version'], $min, '<')) {
        fail(400, "Restarting needs agent $min or newer. Upgrade it from the Updates tab first.");
    }
    $r = create_jobs([(int) $s['host_id']], 'service_restart', ['service' => $s['target']], isset($user['id']) ? (int) $user['id'] : null);
    if (!$r['created']) fail(409, $r['skipped'][0]['reason'] ?? 'Could not queue the restart.');
    echo json_encode(['ok' => true, 'jobId' => $r['created'][0]]);
    exit;
}

if ($method === 'POST') {
    [$row, $err] = service_validate($input);
    if ($err) fail(400, $err);
    $pdo->prepare('INSERT INTO services (host_id, kind, name, target, options, interval_sec, enabled, alert, created_by, created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
        ->execute([$row['host_id'], $row['kind'], $row['name'], $row['target'], json_encode($row['options']), $row['interval_sec'],
                   (int) $row['enabled'], (int) $row['alert'], isset($user['id']) ? (int) $user['id'] : null, now_ms()]);
    $newId = (int) $pdo->lastInsertId();
    if ($row['kind'] !== 'agent') run_service_checks([load_service($newId)]);   // show a result right away
    echo json_encode(['id' => $newId, 'services' => service_list()]);
    exit;
}

if ($method === 'PUT' && $id) {
    $s = load_service($id);
    unset($input['kind']);   // the type of a check doesn't change; add a new one instead
    [$row, $err] = service_validate($input, $s);
    if ($err) fail(400, $err);
    $changed = $row['target'] !== $s['target'] || json_encode($row['options']) !== json_encode(service_options($s['options']));
    $pdo->prepare('UPDATE services SET host_id = ?, name = ?, target = ?, options = ?, interval_sec = ?, enabled = ?, alert = ?'
                  . ($changed ? ", status = 'pending', fail_count = 0, message = NULL, cert_expires_at = NULL" : '') . ' WHERE id = ?')
        ->execute([$row['host_id'], $row['name'], $row['target'], json_encode($row['options']), $row['interval_sec'],
                   (int) $row['enabled'], (int) $row['alert'], $id]);
    if ($changed && $row['enabled'] && $row['kind'] !== 'agent') run_service_checks([load_service($id)]);
    echo json_encode(['services' => service_list()]);
    exit;
}

if ($method === 'DELETE' && $id) {
    $pdo->prepare('DELETE FROM services WHERE id = ?')->execute([$id]);
    echo json_encode(['services' => service_list()]);
    exit;
}

fail(405, 'method not allowed');
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/api/subnets.php")"
cat > "$APP_DIR/api/subnets.php" <<'WEBMON_FILE_EOF'
<?php
// Subnet settings. Names are shown with the address ("Servers · 192.168.10.0/24");
// a subnet's gateway is shown in its heading instead of as a card; discovery
// scans the subnet on a schedule and adds/removes cards (includes/discovery.php).
//   GET                                     -> {names, gateways, scans, log}
//   PUT  {names, gateways, scans}           -> replace all (admins)
//        scans: {subnet: {enabled, everyMin, autoAdd, removeDays, removeScanOnly}}
//   POST ?scan=192.168.10.0/24                -> scan that subnet now (admins)
require_once __DIR__ . '/../includes/discovery.php';
require_once __DIR__ . '/../includes/auth.php';
header('Content-Type: application/json');
require_api_auth_admin_writes();

function fail(int $code, string $msg): void {
    http_response_code($code);
    echo json_encode(['error' => $msg]);
    exit;
}

$method = $_SERVER['REQUEST_METHOD'];
$isSubnet = fn($s) => (bool) preg_match('#^\d{1,3}\.\d{1,3}\.\d{1,3}\.0/24$#', (string) $s)
    && filter_var(substr((string) $s, 0, -3), FILTER_VALIDATE_IP, FILTER_FLAG_IPV4);

function subnets_state(): array {
    $log = db()->query('SELECT ts, subnet, action, ip, name, detail FROM discovery_log ORDER BY id DESC LIMIT 40')->fetchAll();
    return [
        'names' => (object) subnet_names(),
        'gateways' => (object) subnet_gateways(),
        'scans' => (object) array_map('subnet_scan_public', subnet_scan_rows()),
        'log' => array_map(fn($l) => ['ts' => (int) $l['ts']] + $l, $log),
    ];
}

if ($method === 'GET') {
    echo json_encode(subnets_state());
    exit;
}

if ($method === 'POST' && isset($_GET['scan'])) {
    $subnet = (string) $_GET['scan'];
    if (!$isSubnet($subnet)) fail(400, 'not a /24 subnet');
    set_time_limit(180);
    $pdo = db();
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_discovery', 60)")->fetchColumn()) fail(409, 'another scan is running, try again shortly');
    try {
        $result = run_subnet_scans($subnet, true)[$subnet] ?? null;
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_discovery')");
    }
    echo json_encode(['result' => $result] + subnets_state());
    exit;
}
if ($method !== 'PUT') fail(405, 'method not allowed');

$input = json_decode(file_get_contents('php://input'), true) ?? [];

$names = [];
foreach ((array) ($input['names'] ?? []) as $subnet => $name) {
    if (!$isSubnet($subnet)) fail(400, "not a /24 subnet: $subnet");
    $name = trim(preg_replace('/\s+/', ' ', (string) $name));
    if ($name === '') continue;   // blank = no name
    if (mb_strlen($name) > 40) fail(400, 'names can be at most 40 characters');
    $names[$subnet] = $name;
}

$gateways = [];
foreach ((array) ($input['gateways'] ?? []) as $subnet => $ip) {
    if (!$isSubnet($subnet)) fail(400, "not a /24 subnet: $subnet");
    $ip = trim((string) $ip);
    if ($ip === '') continue;
    $prefix = substr($subnet, 0, -4);   // "192.168.10."
    if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) || !str_starts_with($ip, $prefix)) {
        fail(400, "gateway for $subnet must be an address in that subnet (e.g. {$prefix}1)");
    }
    $gateways[$subnet] = $ip;
}

$scans = [];
foreach ((array) ($input['scans'] ?? []) as $subnet => $s) {
    if (!$isSubnet($subnet)) fail(400, "not a /24 subnet: $subnet");
    $every = (int) ($s['everyMin'] ?? 60);
    if (!in_array($every, SCAN_EVERY_CHOICES, true)) fail(400, 'unsupported scan interval');
    $days = $s['removeDays'] ?? null;
    if ($days !== null && $days !== '') {
        if (!is_numeric($days) || (int) $days < 1 || (int) $days > 365) fail(400, "remove after must be 1-365 days ($subnet)");
        $days = (int) $days;
    } else {
        $days = null;
    }
    $scans[$subnet] = [!empty($s['enabled']) ? 1 : 0, $every, !empty($s['autoAdd']) ? 1 : 0, $days, ($s['removeScanOnly'] ?? true) ? 1 : 0, !empty($s['autoName']) ? 1 : 0];
}

$pdo = db();
$pdo->beginTransaction();
$save = $pdo->prepare('INSERT INTO settings (k, v) VALUES (?, ?) ON DUPLICATE KEY UPDATE v = VALUES(v)');
$save->execute(['subnet_names', json_encode($names)]);
$save->execute(['subnet_gateways', json_encode($gateways)]);
if (array_key_exists('scans', $input)) {
    $upsert = $pdo->prepare('INSERT INTO subnet_scans (subnet, enabled, every_min, auto_add, remove_after_days, remove_scan_only, auto_name)
                             VALUES (?, ?, ?, ?, ?, ?, ?)
                             ON DUPLICATE KEY UPDATE enabled = VALUES(enabled), every_min = VALUES(every_min), auto_add = VALUES(auto_add),
                               remove_after_days = VALUES(remove_after_days), remove_scan_only = VALUES(remove_scan_only), auto_name = VALUES(auto_name)');
    foreach ($scans as $subnet => $v) $upsert->execute(array_merge([$subnet], $v));
    // Subnets no longer listed: forget their settings (but not their scan history in the log).
    $keep = array_keys($scans);
    $pdo->prepare('DELETE FROM subnet_scans' . ($keep ? ' WHERE subnet NOT IN (' . implode(',', array_fill(0, count($keep), '?')) . ')' : ''))
        ->execute($keep);
}
$pdo->commit();
echo json_encode(subnets_state());
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/api/switch-config.php")"
cat > "$APP_DIR/api/switch-config.php" <<'WEBMON_FILE_EOF'
<?php
// Switch/router configuration backups (admins only: configs hold secrets).
//   GET    ?host=N                 -> {settings, versions, vendors, publicKey, schedules}
//   PUT    ?host=N  {vendor, port, username, auth, password?, enablePassword?, command?, schedule, legacySsh}
//                                   -> save settings (blank passwords keep the saved ones)
//   POST   ?host=N&backup=1        -> back up now (runs within a minute)
//   POST   ?host=N&forget_key=1    -> forget the device's SSH host key
//   GET    ?version=V              -> {version, content}; &download=1 -> the file
//   GET    ?version=V&diff=1       -> {version, previous, diff: [[op, line], ...]}
//   DELETE ?version=V              -> delete one version
require_once __DIR__ . '/../includes/configbackup.php';
require_once __DIR__ . '/../includes/auth.php';
header('Content-Type: application/json');
require_api_auth('admin');

function fail(int $code, string $msg): void {
    http_response_code($code);
    echo json_encode(['error' => $msg]);
    exit;
}

function version_row(array $v): array {
    return ['id' => (int) $v['id'], 'fetchedAt' => (int) $v['fetched_at'], 'source' => $v['source'],
            'bytes' => (int) $v['bytes'], 'changed' => (bool) $v['changed'], 'sha256' => $v['sha256']];
}

$pdo = db();
$method = $_SERVER['REQUEST_METHOD'];

// ---- one version ----
if (isset($_GET['version'])) {
    $stmt = $pdo->prepare('SELECT v.*, h.name, h.ip_address FROM switch_configs v JOIN hosts h ON h.id = v.host_id WHERE v.id = ?');
    $stmt->execute([(int) $_GET['version']]);
    $v = $stmt->fetch();
    if (!$v) fail(404, 'not found');
    if ($method === 'DELETE') {
        $pdo->prepare('DELETE FROM switch_configs WHERE id = ?')->execute([$v['id']]);
        http_response_code(204);
        exit;
    }
    if ($method !== 'GET') fail(405, 'method not allowed');
    if (!empty($_GET['download'])) {
        $name = preg_replace('/[^A-Za-z0-9._-]+/', '_', $v['name'] === $v['ip_address'] ? $v['ip_address'] : $v['name']);
        $file = $name . '_' . date('Y-m-d_His', intdiv((int) $v['fetched_at'], 1000)) . '.cfg';
        header('Content-Type: text/plain; charset=utf-8');
        header('Content-Disposition: attachment; filename="' . $file . '"');
        header('X-Content-Type-Options: nosniff');
        echo $v['content'];
        exit;
    }
    if (!empty($_GET['diff'])) {
        $prev = $pdo->prepare('SELECT * FROM switch_configs WHERE host_id = ? AND id < ? ORDER BY id DESC LIMIT 1');
        $prev->execute([$v['host_id'], $v['id']]);
        $p = $prev->fetch();
        echo json_encode(['version' => version_row($v), 'previous' => $p ? version_row($p) : null,
                          'diff' => $p ? config_diff($p['content'], $v['content']) : null]);
        exit;
    }
    echo json_encode(['version' => version_row($v), 'content' => $v['content']]);
    exit;
}

// ---- a device ----
$hostId = (int) ($_GET['host'] ?? 0);
$stmt = $pdo->prepare('SELECT * FROM hosts WHERE id = ?');
$stmt->execute([$hostId]);
$host = $stmt->fetch();
if (!$host) fail(404, 'host not found');
$cfgStmt = $pdo->prepare('SELECT * FROM config_backup_settings WHERE host_id = ?');
$cfgStmt->execute([$hostId]);
$cfg = $cfgStmt->fetch() ?: null;

if ($method === 'GET') {
    $versions = $pdo->prepare('SELECT id, fetched_at, source, bytes, changed, sha256 FROM switch_configs WHERE host_id = ? ORDER BY id DESC LIMIT 200');
    $versions->execute([$hostId]);
    echo json_encode([
        'settings' => $cfg ? [
            'vendor' => $cfg['vendor'], 'port' => (int) $cfg['port'], 'username' => $cfg['username'], 'auth' => $cfg['auth'],
            'hasPassword' => $cfg['secret_enc'] !== null, 'hasEnablePassword' => $cfg['enable_enc'] !== null,
            'command' => $cfg['command'], 'schedule' => $cfg['schedule'], 'legacySsh' => (bool) $cfg['legacy_ssh'],
            'requestedAt' => $cfg['requested_at'] ? (int) $cfg['requested_at'] : null,
            'lastAttemptAt' => $cfg['last_attempt_at'] ? (int) $cfg['last_attempt_at'] : null,
            'lastOkAt' => $cfg['last_ok_at'] ? (int) $cfg['last_ok_at'] : null,
            'lastError' => $cfg['last_error'],
        ] : null,
        'versions' => array_map('version_row', $versions->fetchAll()),
        'vendors' => array_map(fn($k, $v) => ['id' => $k, 'label' => $v['label'], 'needsCommand' => $k === 'generic',
                                               'enable' => !empty($v['enable'])], array_keys(CONFIG_VENDORS), CONFIG_VENDORS),
        'schedules' => array_keys(CONFIG_SCHEDULES),
        'publicKey' => ssh_public_key(),
    ]);
    exit;
}

if ($method === 'PUT') {
    $in = json_decode(file_get_contents('php://input'), true) ?? [];
    $vendor = (string) ($in['vendor'] ?? '');
    if (!isset(CONFIG_VENDORS[$vendor])) fail(400, 'choose the device type');
    $username = trim((string) ($in['username'] ?? ''));
    if ($username === '' || strlen($username) > 64 || !preg_match('/^[^\s@:]+$/', $username)) fail(400, 'enter a valid username');
    $port = (int) ($in['port'] ?? 22);
    if ($port < 1 || $port > 65535) fail(400, 'port must be 1-65535');
    $auth = ($in['auth'] ?? 'key') === 'password' ? 'password' : 'key';
    $schedule = (string) ($in['schedule'] ?? 'off');
    if (!isset(CONFIG_SCHEDULES[$schedule])) fail(400, 'unknown schedule');
    $command = $vendor === 'generic' ? trim((string) ($in['command'] ?? '')) : null;
    if ($vendor === 'generic' && ($command === '' || strlen($command) > 255)) fail(400, 'enter the command that prints the configuration');

    $secret = $cfg['secret_enc'] ?? null;
    if ($auth === 'password') {
        $pw = (string) ($in['password'] ?? '');
        if ($pw !== '') $secret = encrypt_secret($pw);
        if ($secret === null) fail(400, 'enter the password');
    } else {
        $secret = null;
    }
    $enable = $cfg['enable_enc'] ?? null;
    if (array_key_exists('enablePassword', $in)) {
        $ep = (string) $in['enablePassword'];
        if ($ep !== '') $enable = encrypt_secret($ep);
    }
    if (!empty($in['clearEnablePassword'])) $enable = null;

    $legacy = !empty($in['legacySsh']) ? 1 : 0;
    $pdo->prepare('INSERT INTO config_backup_settings (host_id, vendor, port, username, auth, secret_enc, enable_enc, command, schedule, legacy_ssh)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                   ON DUPLICATE KEY UPDATE vendor = VALUES(vendor), port = VALUES(port), username = VALUES(username), auth = VALUES(auth),
                     secret_enc = VALUES(secret_enc), enable_enc = VALUES(enable_enc), command = VALUES(command), schedule = VALUES(schedule),
                     legacy_ssh = VALUES(legacy_ssh)')
        ->execute([$hostId, $vendor, $port, $username, $auth, $secret, $enable, $command, $schedule, $legacy]);
    echo json_encode(['ok' => true]);
    exit;
}

if ($method === 'POST' && !empty($_GET['backup'])) {
    if (!$cfg) fail(400, 'set up the login first');
    $pdo->prepare('UPDATE config_backup_settings SET requested_at = ? WHERE host_id = ?')->execute([now_ms_cfg(), $hostId]);
    echo json_encode(['ok' => true]);
    exit;
}

if ($method === 'POST' && !empty($_GET['forget_key'])) {
    // known_hosts lives in /var/lib/webmonitor (not writable by the web server): the next backup does it.
    $pdo->prepare("INSERT INTO settings (k, v) VALUES ('ssh_forget_hosts', JSON_ARRAY(?))
                   ON DUPLICATE KEY UPDATE v = JSON_ARRAY_APPEND(v, '$', ?)")->execute([$host['ip_address'], $host['ip_address']]);
    echo json_encode(['ok' => true]);
    exit;
}

fail(405, 'method not allowed');
WEBMON_FILE_EOF

