    'tv' => '/\btvs?\b|media|stream/i', 'console' => '/gam/i',
];

// Card device type -> category.
const CARD_CATEGORY = ['server' => 'server', 'nas' => 'server', 'switch' => 'network', 'router' => 'network', 'ap' => 'network',
    'printer' => 'printer', 'camera' => 'camera', 'desktop' => 'computer', 'laptop' => 'computer', 'mobile' => 'phone', 'ups' => 'iot',
    'iot' => 'iot', 'console' => 'console', 'tv' => 'tv'];

/** Loads the IEEE OUI list into mac_vendors when it's missing or the file changed (background jobs). */
function ensure_mac_vendors(): void {
    $pdo = db();
    $mtime = @filemtime(OUI_FILE);
    if (!$mtime || (string) $pdo->query("SELECT v FROM settings WHERE k = 'oui_mtime'")->fetchColumn() === (string) $mtime) return;
    $fh = @fopen(OUI_FILE, 'r');
    if (!$fh) return;
    $rows = [];
    while (($line = fgets($fh)) !== false) {
        if (preg_match('/^([0-9A-F]{6})\s+\(base 16\)\s+(.+?)\s*$/', $line, $m)) $rows[$m[1]] = mb_substr($m[2], 0, 160);
    }
    fclose($fh);
    if (count($rows) < 1000) return;
    $pdo->beginTransaction();
    $pdo->exec('DELETE FROM mac_vendors');
    foreach (array_chunk($rows, 1000, true) as $chunk) {
        $pdo->prepare('INSERT INTO mac_vendors (prefix, vendor) VALUES ' . implode(',', array_fill(0, count($chunk), '(?, ?)')))
            ->execute(array_merge(...array_map(fn($p, $v) => [$p, $v], array_keys($chunk), $chunk)));
    }
    $pdo->prepare("INSERT INTO settings (k, v) VALUES ('oui_mtime', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")->execute([(string) $mtime]);
    $pdo->commit();
}

/** Locally administered MACs: phones' private Wi-Fi addresses (but not Docker 02:42 / QEMU 52:54). */
function is_random_mac(string $mac): bool {
    return (bool) (hexdec($mac[1]) & 2) && !str_starts_with($mac, '02:42') && !str_starts_with($mac, '52:54:00');
}

/** [mac => vendor] for many MACs at once. */
function mac_vendors(array $macs): array {
    $prefixes = [];
    foreach ($macs as $m) if ($m && !is_random_mac($m)) $prefixes[strtoupper(str_replace(':', '', substr($m, 0, 8)))][] = $m;
    if (!$prefixes) return [];
    $out = [];
    foreach (array_chunk(array_keys($prefixes), 500) as $chunk) {
        $q = db()->prepare('SELECT prefix, vendor FROM mac_vendors WHERE prefix IN (' . implode(',', array_fill(0, count($chunk), '?')) . ')');
        $q->execute($chunk);
        foreach ($q->fetchAll(PDO::FETCH_KEY_PAIR) as $p => $v) foreach ($prefixes[$p] as $m) $out[$m] = $v;
    }
    foreach ($macs as $m) {
        if ($m && str_starts_with($m, '52:54:00')) $out[$m] = 'QEMU/KVM virtual NIC';
        elseif ($m && str_starts_with($m, '02:42')) $out[$m] = 'Docker container';
    }
    return $out;
}

/**
 * [category, label, confidence] for one device. $d: name, vendor, os (Wi-Fi
 * fingerprint), mac, wireless (bool), subnetName, cardDevice.
 */
function identify_device(array $d): array {
    $name = trim((string) ($d['name'] ?? ''));
    $vendor = (string) ($d['vendor'] ?? '');
    $os = (string) ($d['os'] ?? '');
    if (!empty($d['cardDevice']) && isset(CARD_CATEGORY[$d['cardDevice']]) && $d['cardDevice'] !== 'server') {
        $labels = ['ap' => 'Access point', 'nas' => 'NAS', 'ups' => 'UPS', 'iot' => 'Smart-home device', 'console' => 'Game console', 'tv' => 'TV / streaming'];
        return [CARD_CATEGORY[$d['cardDevice']], $labels[$d['cardDevice']] ?? ucfirst($d['cardDevice']), 'high'];
    }
    if ($name !== '' && !filter_var($name, FILTER_VALIDATE_IP)) {
        foreach (DEVICE_NAME_RULES as [$re, $cat, $label]) if (preg_match($re, $name)) return [$cat, $label, 'high'];
    }
    // What the device said about itself when scanned (model, UPnP name, web page title).
    $said = trim((string) ($d['scanText'] ?? ''));
    if ($said !== '') {
        foreach (DEVICE_NAME_RULES as [$re, $cat, $label]) if (preg_match($re, $said)) return [$cat, $label, 'high'];
        if (preg_match('/speaker|google home|nest (mini|audio|hub)/i', $said)) return ['speaker', 'Smart speaker', 'high'];
        if (preg_match('/mainsail|fluidd|octoprint|klipper|moonraker|bambu|prusalink|creality/i', $said)) return ['printer', '3D printer', 'high'];
        if (preg_match('/print|epson|brother|laserjet/i', $said)) return ['printer', 'Printer', 'high'];
        if (preg_match('/\bnas\b|qnap|synology|ts-x\d|diskstation/i', $said)) return ['server', 'NAS', 'high'];
    }
    // What Home Assistant controls on it (its entities' domains).
    $kinds = (array) ($d['haKinds'] ?? []);
    foreach ([['camera', 'camera', 'Camera'], ['vacuum', 'appliance', 'Robot vacuum'], ['lawn_mower', 'appliance', 'Robot mower'],
              ['climate', 'iot', 'Thermostat / climate'], ['lock', 'iot', 'Smart lock'], ['alarm_control_panel', 'iot', 'Alarm panel'],
              ['cover', 'iot', 'Blind / garage door'], ['light', 'iot', 'Smart light'], ['fan', 'iot', 'Smart fan'],
              ['media_player', 'tv', 'Media player'], ['switch', 'iot', 'Smart plug / switch']] as [$k, $cat, $label]) {
        if (in_array($k, $kinds, true)) return [$cat, $label, 'high'];
    }
    // Services it advertises over mDNS (same subnet only).
    $svc = (array) ($d['scan']['services'] ?? []);
    foreach ([['_ipp', 'printer', 'Printer'], ['_printer', 'printer', 'Printer'], ['_qdiscover', 'server', 'NAS'], ['_adisk', 'server', 'NAS'],
              ['_rdlink', 'computer', 'Mac'], ['_sonos', 'speaker', 'Sonos'], ['_googlecast', 'speaker', 'Google Cast device'],
              ['_airplay', 'tv', 'AirPlay device (Apple TV or speaker)'], ['_companion-link', 'phone', 'Apple device'],
              ['_hap', 'iot', 'HomeKit device'], ['_esphomelib', 'iot', 'ESPHome device']] as [$s, $cat, $label]) {
        if (in_array($s, $svc, true)) return [$cat, $label, 'medium'];
    }
    // Services it offers.
    $ports = $d['scanPorts'] ?? [];
    if (in_array(5555, $ports, true) && array_intersect([8008, 8009], $ports)) return ['tv', 'Android TV / Google TV device', 'medium'];
    foreach ([[8060, 'tv', 'Roku'], [6668, 'iot', 'Tuya smart device'], [8008, 'speaker', 'Google Cast device'], [62078, 'phone', 'iPhone / iPad'],
              [9100, 'printer', 'Printer'], [631, 'printer', 'Printer'], [1400, 'speaker', 'Sonos'],
              [9999, 'iot', 'TP-Link Kasa'], [3001, 'tv', 'LG webOS TV'], [8001, 'tv', 'Samsung TV'], [1925, 'tv', 'Philips TV'],
              [3389, 'computer', 'Windows PC']] as [$port, $cat, $label]) {
        if (in_array($port, $ports, true)) return [$cat, $label, 'medium'];
    }
    if (in_array(55443, $ports, true) && preg_match('/Yeelight|Xiaomi|Qingdao/i', $vendor)) return ['iot', 'Yeelight', 'medium'];
    if ($vendor !== '') {
        if (preg_match('/Microsoft/i', $vendor) && preg_match('/gam/i', (string) ($d['subnetName'] ?? ''))) return ['console', 'Xbox', 'medium'];
        foreach (DEVICE_VENDOR_RULES as [$re, $cat, $label]) if (preg_match($re, $vendor)) return [$cat, $label, 'medium'];
    }
    if ($os !== '' && $os !== 'NOFP') {
        if (preg_match('/iphone|ipad|android|windows mobile|ios/i', $os)) return ['phone', $os, 'medium'];
        if (preg_match('/roku/i', $os)) return ['tv', 'Roku', 'high'];
        if (preg_match('/^win|mac ?os|chrome ?os/i', $os)) return ['computer', $os, 'medium'];
    }
    if ($vendor !== '') {
        // Makers of both TVs/streamers and other things, on a network kept for TVs: a TV or streamer.
        if (preg_match('/\btvs?\b|media|stream/i', (string) ($d['subnetName'] ?? '')) && preg_match('/Amazon|Google|Samsung|LG |Sony|Hisense|TCL|Vizio|Apple/i', $vendor)) {
            $what = ['Amazon' => 'Fire TV', 'Google' => 'Chromecast / Google TV', 'Apple' => 'Apple TV'];
            foreach ($what as $re => $label) if (stripos($vendor, $re) !== false) return ['tv', $label, 'medium'];
            return ['tv', 'TV', 'medium'];
        }
        foreach (DEVICE_VENDOR_GENERIC as [$re, $cat, $label]) if (preg_match($re, $vendor)) return [$cat, $label, 'low'];
    }
    if (!empty($d['mac']) && is_random_mac($d['mac'])) {
        // Phones use a private address per Wi-Fi network; on a Wi-Fi subnet that's the likely answer.
        // On an IoT/TV/gaming subnet, the subnet says more (below); elsewhere it's likely a VM.
        $subnetName = (string) ($d['subnetName'] ?? '');
        if (!empty($d['wireless']) || preg_match('/wi-?fi|wireless|wlan|guest/i', $subnetName)) return ['phone', 'Phone / tablet (private Wi-Fi address)', 'low'];
        if (!preg_match('/iot|smart|\btvs?\b|media|stream|gam/i', $subnetName)) return ['server', 'VM or container (locally assigned MAC)', 'low'];
    }
    if (preg_match('/^linux$/i', $os)) return ['iot', 'Linux device', 'low'];
    $subnet = (string) ($d['subnetName'] ?? '');
    if (preg_match('/iot/i', $subnet)) return ['iot', 'Device on the IoT network', 'low'];
    if (preg_match('/gam/i', $subnet)) return ['console', 'Device on the gaming network', 'low'];
    if (preg_match('/\btvs?\b|media|stream/i', $subnet)) return ['tv', 'Device on the TV network', 'low'];
    // A card added as "server" (the default type) with nothing else to go on.
    if (!empty($d['cardDevice']) && isset(CARD_CATEGORY[$d['cardDevice']])) return [CARD_CATEGORY[$d['cardDevice']], $d['cardDevice'] === 'nas' ? 'NAS' : 'Server', 'medium'];
    return ['unknown', $vendor !== '' ? $vendor : 'Unknown', 'low'];
}

/**
 * Every device seen on the network, identified: from the topology (switch
 * ports, Wi-Fi clients by AP, Proxmox guests) plus monitored cards not seen
 * on any port.
 */
function device_inventory(): array {
    require_once __DIR__ . '/portmap.php';
    require_once __DIR__ . '/wireless.php';
    $topo = network_topology();
    $wifi = wireless_overview();
    $wifiByMac = [];
    foreach ($wifi['clients'] as $c) $wifiByMac[$c['mac']] = $c;
    $names = subnet_names();
    $cards = [];
    foreach (db()->query('SELECT id, name, ip_address, device, auto_named FROM hosts') as $h) $cards[(int) $h['id']] = $h;
    // A card named and typed by auto-naming says nothing new about the device: don't read it back.
    $autoNamed = array_flip(array_keys(array_filter($cards, fn($c) => (bool) $c['auto_named'])));

    $rows = [];
    $byIp = [];   // ip -> row key, so a VM listed by its host and seen on a port is one row
    $add = function (array $r) use (&$rows, &$byIp) {
        $key = $r['mac'] ?: ('ip:' . $r['ip']);
        // Same address as an earlier row: the same device if one of the two has no MAC (e.g. a VM
        // listed by its Proxmox host); two different MACs on one IP are two devices (a conflict).
        if ($r['ip'] && isset($byIp[$r['ip']]) && (!$r['mac'] || !($rows[$byIp[$r['ip']]]['mac'] ?? null))) $key = $byIp[$r['ip']];
        if (isset($rows[$key])) {
            foreach ($r as $k => $v) if (($rows[$key][$k] ?? null) === null && $v !== null) $rows[$key][$k] = $v;
            return;
        }
        $rows[$key] = $r;
        if ($r['ip']) $byIp[$r['ip']] = $key;
    };
    foreach ((array) $topo['nodes'] as $n) {
        $add(['mac' => $n['mac'] ?? null, 'ip' => $n['ip'], 'name' => $n['name'], 'hostId' => $n['id'], 'wireless' => false,
              'where' => ['kind' => 'network'], 'vlan' => null, 'cardDevice' => $n['device'], 'os' => null]);
        foreach ($n['ports'] as $p) {
            foreach ($p['devices'] as $d) {
                $w = $wifiByMac[$d['mac']] ?? null;
                $isWifi = $n['device'] === 'ap';
                $cardName = isset($d['host']['name']) && $d['host']['name'] !== ($d['host']['ip'] ?? null) && !isset($autoNamed[$d['host']['id']]) ? $d['host']['name'] : null;
                $add(['mac' => $d['mac'], 'ip' => $d['ip'] ?? ($d['host']['ip'] ?? null), 'name' => $cardName ?? ($w['name'] ?? null) ?? (isset($d['host']['id']) && isset($autoNamed[$d['host']['id']]) ? null : ($d['name'] ?? null)),
                      'hostId' => $d['host']['id'] ?? null, 'wireless' => $isWifi,
                      'where' => $isWifi ? ['kind' => 'wifi', 'ap' => $n['name'], 'apId' => $n['id'], 'ssid' => $p['port'], 'band' => $d['band'] ?? null]
                                         : ['kind' => 'wired', 'switch' => $n['name'], 'switchId' => $n['id'], 'port' => $p['port']],
                      'vlan' => $d['vlan'] ?? null, 'cardDevice' => isset($d['host']['id']) && !isset($autoNamed[$d['host']['id']]) ? ($cards[$d['host']['id']]['device'] ?? null) : null,
                      'os' => $w['os'] ?? null, 'note' => $d['note'] ?? null]);
                foreach ($d['guests'] ?? [] as $g) {
                    $add(['mac' => null, 'ip' => $g['ip'], 'name' => $g['name'], 'hostId' => $g['hostId'], 'wireless' => false,
                          'where' => ['kind' => 'vm', 'hypervisor' => $d['host']['name'] ?? '', 'hypervisorId' => $d['host']['id'] ?? null,
                                      'vmid' => $g['vmid'], 'type' => $g['type']],
                          'vlan' => null, 'cardDevice' => 'server', 'os' => null, 'forceCategory' => ['server', $g['type'] === 'lxc' ? 'LXC container' : 'Virtual machine']]);
                }
                foreach ($d['wifiClients'] ?? [] as $c) {
                    $w2 = $wifiByMac[$c['mac']] ?? null;
                    $wname = $c['hostId'] && isset($autoNamed[$c['hostId']]) ? ($wifiByMac[$c['mac']]['name'] ?? null) : $c['name'];
                    $add(['mac' => $c['mac'], 'ip' => $c['ip'], 'name' => $wname, 'hostId' => $c['hostId'], 'wireless' => true,
                          'where' => ['kind' => 'wifi', 'ap' => $d['host']['name'] ?? $d['ap']['name'], 'apId' => $d['host']['id'] ?? null, 'ssid' => $c['ssid'], 'band' => $c['band']],
                          'vlan' => null, 'cardDevice' => null, 'os' => $w2['os'] ?? null]);
                }
            }
        }
    }
    foreach ($topo['unplaced'] as $u) {
        $auto = isset($autoNamed[$u['id']]);
        $add(['mac' => null, 'ip' => $u['ip'], 'name' => $auto ? null : $u['name'], 'hostId' => $u['id'], 'wireless' => false,
              'where' => ['kind' => 'unplaced'], 'vlan' => null, 'cardDevice' => $auto ? null : $u['device'], 'os' => null]);
    }

    // Devices known only by address (cards not seen on any port): the MAC that the switches' ARP
    // tables, or else the DHCP server, give that address. Not a MAC another row already has.
    require_once __DIR__ . '/dhcpleases.php';
    $ipMac = dhcp_lease_macs();
    foreach (known_mac_ips() as $mac => $ip) $ipMac[$ip] = $mac;
    $usedMacs = array_flip(array_filter(array_column($rows, 'mac')));
    foreach ($rows as &$r) {
        $mac = !$r['mac'] && $r['ip'] ? ($ipMac[$r['ip']] ?? null) : null;
        if (!$mac || isset($usedMacs[$mac])) continue;
        $r['mac'] = $mac;
        $usedMacs[$mac] = true;
        if ($w = $wifiByMac[$mac] ?? null) {
            $r['wireless'] = true;
            $r['name'] ??= $w['name'] ?? null;
            $r['os'] ??= $w['os'] ?? null;
        }
    }
    unset($r);

    $vendors = mac_vendors(array_filter(array_column($rows, 'mac')));
    require_once __DIR__ . '/devicescan.php';
    $scans = device_scan_summaries();
    $scanPorts = [];
    foreach (db()->query('SELECT dkey, data FROM device_scans WHERE data IS NOT NULL') as $sr) {
        $scanPorts[$sr['dkey']] = array_column(json_decode($sr['data'], true)['ports'] ?? [], 'port');
    }
    require_once __DIR__ . '/homeassistant.php';
    [$haByMac, $haByIp, $haByName, $haAll] = ha_device_index();
    $scanKey = function (array $r) use ($scans): string {
        $key = device_scan_key($r['mac'], $r['ip']);
        return !isset($scans[$key]) && $r['ip'] && isset($scans['ip:' . $r['ip']]) ? 'ip:' . $r['ip'] : $key;   // scanned from its card (by IP)
    };
    // Home Assistant's record of each device: by MAC, then IP, then an exact (unique) name...
    $haFor = $haUsed = [];
    foreach ($rows as $k => $r) {
        $scan = $scans[$scanKey($r)] ?? null;
        $ha = ($r['mac'] ? $haByMac[$r['mac']] ?? null : null) ?? ($r['ip'] ? $haByIp[$r['ip']] ?? null : null)
            ?? $haByName[mb_strtolower((string) ($scan['name'] ?? ''))] ?? $haByName[mb_strtolower((string) ($r['name'] ?? ''))] ?? null;
        if ($ha) { $haFor[$k] = $ha; $haUsed[$ha['_i']] = true; }
    }
    // ...then a maker that only one device has on each side (HA's one Resideo thermostat is the one
    // Resideo device on the network). One name twice under a maker is one device in two integrations.
    $haBrand = $rowBrand = [];
    foreach ($haAll as $d) {
        if (!isset($haUsed[$d['_i']]) && ($b = short_brand($d['maker'] ?? null))) $haBrand[$b][mb_strtolower($d['name'])][] = $d;
    }
    foreach ($rows as $k => $r) {
        if (isset($haFor[$k])) continue;
        $scan = $scans[$scanKey($r)] ?? null;
        if ($b = short_brand($scan['maker'] ?? null) ?? short_brand($r['mac'] ? ($vendors[$r['mac']] ?? null) : null)) $rowBrand[$b][] = $k;
    }
    foreach ($haBrand as $b => $byName) {
        if (count($byName) !== 1 || count($rowBrand[$b] ?? []) !== 1 || in_array($b, HA_MAKER_MATCH_SKIP, true)) continue;
        $group = reset($byName);
        usort($group, fn($x, $y) => count($y) <=> count($x));   // the integration that says the most (has a model)
        $haFor[$rowBrand[$b][0]] = $group[0] + ['byMaker' => true];
        foreach ($group as $d) $haUsed[$d['_i']] = true;
    }
    // In Home Assistant but not found on the network (cloud-linked devices): listed on their own.
    $haOnly = [];
    foreach ($haAll as $d) {
        if (isset($haUsed[$d['_i']])) continue;
        $haOnly[] = array_intersect_key($d, array_flip(['name', 'maker', 'model', 'area', 'kinds']));
    }
    $out = [];
    foreach ($rows as $k => $r) {
        $key = $scanKey($r);
        $scan = $scans[$key] ?? null;
        $r['scan'] = $scan;
        $r['scanText'] = $scan ? implode(' ', array_filter([$scan['maker'] ?? null, $scan['model'] ?? null, $scan['name'] ?? null, $scan['webTitle'] ?? null])) : '';
        $r['scanPorts'] = $scanPorts[$key] ?? [];
        if (empty($r['name']) && !empty($scan['name'])) $r['name'] = $scan['name'];
        $ha = $haFor[$k] ?? null;
        $r['ha'] = $ha ? array_intersect_key($ha, array_flip(['name', 'maker', 'model', 'firmware', 'area', 'byMaker'])) : null;
        $r['haKinds'] = $ha['kinds'] ?? [];
        if ($ha) {
            // The name you gave it in Home Assistant, unless a person named its card here.
            $card = $r['hostId'] ? ($cards[$r['hostId']] ?? null) : null;
            $cardNamed = $card && !$card['auto_named'] && $card['name'] !== $card['ip_address'];
            if (!$cardNamed) $r['name'] = $ha['name'];
            $r['scanText'] = trim($r['scanText'] . ' ' . implode(' ', array_filter([$ha['maker'] ?? null, $ha['model'] ?? null, $ha['name']])));
        }
        $r['vendor'] = $r['mac'] ? ($vendors[$r['mac']] ?? null) : null;
        $r['randomMac'] = $r['mac'] ? is_random_mac($r['mac']) : false;
        $subnet = $r['ip'] ? preg_replace('/\.\d+$/', '.0/24', $r['ip']) : null;
        $r['subnet'] = $subnet;
        $r['subnetName'] = $subnet ? ($names[$subnet] ?? null) : null;
        if (!empty($r['name']) && filter_var($r['name'], FILTER_VALIDATE_IP)) $r['name'] = null;
        [$r['category'], $r['label'], $r['confidence']] = $r['forceCategory'] ?? null
            ? [...$r['forceCategory'], 'high'] : identify_device($r);
        // The exact model when the device told us ("Roku Premiere 3920CA").
        if (!empty($scan['model']) && $r['category'] !== 'server' || (!empty($scan['model']) && $r['label'] === 'NAS')) {
            $maker = (string) ($scan['maker'] ?? '');
            $r['label'] = $maker !== '' && stripos($scan['model'], $maker) === false ? "$maker {$scan['model']}" : $scan['model'];
        } elseif (!empty($ha['model']) && $r['category'] !== 'server' && empty($r['forceCategory'])) {
            $maker = (string) ($ha['maker'] ?? '');
            $r['label'] = mb_substr($maker !== '' && stripos($ha['model'], $maker) === false ? "$maker {$ha['model']}" : $ha['model'], 0, 80);
        }
        unset($r['forceCategory'], $r['scanText'], $r['scanPorts'], $r['haKinds']);
        $r['netWarning'] = wrong_network_note($r, $names);
        $out[] = $r;
    }
    usort($out, fn($a, $b) => [array_search($a['category'], array_keys(DEVICE_CATEGORIES)), ip2long($a['ip'] ?? '255.255.255.255')]
                           <=> [array_search($b['category'], array_keys(DEVICE_CATEGORIES)), ip2long($b['ip'] ?? '255.255.255.255')]);
    return ['devices' => $out, 'haOnly' => $haOnly, 'categories' => DEVICE_CATEGORIES, 'generatedAt' => (int) round(microtime(true) * 1000)];
}

// ---- Useful names ----

// Hostnames that say nothing about the device.
const GENERIC_NAME = '/^(wlan\d*|lwip\d*|esp[_-]?[0-9a-f]{4,}|android-[0-9a-f]{6,}|amazon-[0-9a-f]{6,}|blink[ -]?device|blink dhcp|device|unknown|localhost|espressif|[0-9a-f]{12}|samsung|lg|google)$/i';

// Chip/platform makers inside many brands' gadgets: one of each on both sides proves nothing.
const HA_MAKER_MATCH_SKIP = ['ESP', 'Murata', 'Tuya', 'Amazon', 'Google', 'Apple', 'Samsung', 'Microsoft', 'TP-Link'];

// Short brand from a maker name (MAC prefix or what the device said).
const BRANDS = [
    '/Blink/i' => 'Blink', '/Ring/i' => 'Ring', '/Nest/i' => 'Nest', '/Google/i' => 'Google', '/Amazon/i' => 'Amazon', '/Espressif/i' => 'ESP',
    '/Tuya/i' => 'Tuya', '/Samsung|Seongji/i' => 'Samsung', '/LG /i' => 'LG', '/Midea/i' => 'Midea', '/Roku/i' => 'Roku', '/Sonos/i' => 'Sonos',
    '/Apple/i' => 'Apple', '/Philips|Signify/i' => 'Philips Hue', '/ecobee/i' => 'ecobee', '/Wyze/i' => 'Wyze', '/TP-LINK/i' => 'TP-Link',
    '/Zengge/i' => 'Magic Home', '/Shelly/i' => 'Shelly', '/iRobot/i' => 'iRobot', '/Sony/i' => 'Sony', '/Microsoft/i' => 'Microsoft',
    '/Resideo|Honeywell/i' => 'Resideo', '/Ecovacs/i' => 'Ecovacs', '/^LGE$/i' => 'LG',
    '/Nintendo/i' => 'Nintendo', '/Epson/i' => 'Epson', '/Dish/i' => 'Dish', '/Belkin/i' => 'Wemo', '/Murata/i' => 'Murata',
];
const KIND_WORDS = ['console' => 'console', 'tv' => 'TV', 'speaker' => 'speaker', 'camera' => 'camera', 'iot' => 'smart device',
    'appliance' => 'appliance', 'phone' => 'phone', 'computer' => 'computer', 'printer' => 'printer', 'voip' => 'phone', 'network' => 'network device',
    'server' => 'server', 'unknown' => 'device'];
// Words that are what a thing is, not whose it is ("Console" isn't a first name).
const NOT_A_FIRST_NAME = '/^(phone|computer|speaker|camera|printer|laptop|console|tv|desktop|server|tablet|device|router|switch|plug|bulb|light|doorbell)$/i';

function short_brand(?string $maker): ?string {
    if (!$maker) return null;
    foreach (BRANDS as $re => $b) if (preg_match($re, $maker)) return $b;
    return null;
}

/** A readable name from a hostname: "Nest-Hello-56ba" -> "Nest Hello", "Samsung-Washer" -> "Samsung Washer". */
function tidy_hostname(?string $n): ?string {
    $n = trim((string) $n);
    if ($n === '' || filter_var($n, FILTER_VALIDATE_IP) || preg_match(GENERIC_NAME, $n)) return null;
    $n = preg_replace('/[-_ ][0-9a-f]{4,}$/i', '', $n);                // trailing serial/MAC fragment
    $n = preg_replace('/(?<=[a-z])[-_ ]s[-_ ]/i', "'s ", $n);           // "Geraldine-s-S21" -> "Geraldine's S21"
    $n = preg_replace('/^([A-Za-z]+?)s[-_ ](?=home|pod|tv|ipad|iphone|phone|laptop|mac)/i', "$1's ", $n);   // "Sams-Home-Pod" -> "Sam's Home Pod"
    $n = preg_replace('/[-_]+/', ' ', $n);
    $n = preg_replace('/\s+/', ' ', trim($n));
    if ($n === '' || preg_match(GENERIC_NAME, $n) || strlen($n) < 3) return null;
    return mb_substr(mb_strtoupper(mb_substr($n, 0, 1)) . mb_substr($n, 1), 0, 50);
}

/** Best name for a device (inventory row): its own name, else brand + kind ("Blink camera"). */
function useful_device_name(array $d): string {
    $scan = $d['scan'] ?? [];
    if (!empty($d['ha']['name'])) return mb_substr($d['ha']['name'], 0, 50);   // the name you gave it in Home Assistant
    $own = tidy_hostname($scan['name'] ?? null) ?? tidy_hostname($d['name'] ?? null);
    // Just a first name ("Aaron-"): say whose what it is ("Aaron's Roku").
    if ($own && !str_contains($own, ' ') && preg_match('/^[A-Z][a-z]{2,}$/', $own) && !preg_match(NOT_A_FIRST_NAME, $own)) {
        $what = short_brand($scan['maker'] ?? null) ?? short_brand($d['vendor'] ?? null) ?? (KIND_WORDS[$d['category']] ?? null);
        if ($what && $d['category'] !== 'unknown') return "$own's $what";
    }
    if ($own) return $own;
    // The hostname's brand beats the network card's maker ("Blink-Device" on an Amazon chip is a Blink).
    $brand = short_brand($d['name'] ?? null) ?? short_brand($scan['maker'] ?? null) ?? short_brand($d['vendor'] ?? null) ?? short_brand($d['label'] ?? null);
    if (!empty($scan['model'])) return mb_substr($brand && stripos($scan['model'], $brand) === false ? "$brand {$scan['model']}" : $scan['model'], 0, 50);
    $kind = KIND_WORDS[$d['category']] ?? 'device';
    $vendor = (string) ($d['vendor'] ?? '');
    if (preg_match('/doorbell|hello/i', (string) ($d['name'] ?? ''))) $kind = 'doorbell';
    if (preg_match('/^Amazon Echo/', $d['label'] ?? '')) [$brand, $kind] = ['Amazon', 'Echo'];
    if (preg_match('/Zengge/i', $vendor) || preg_match('/LED light/i', $d['label'] ?? '')) $kind = 'LED controller';
    if (preg_match('/Air-?Condition/i', $vendor)) $kind = 'air conditioner';
    if (($d['label'] ?? '') === '3D printer') return '3D printer';
    if (($d['label'] ?? '') === 'Android TV / Google TV device') return 'Android TV box';
    if (in_array($d['label'] ?? '', ['Fire TV', 'Apple TV'], true)) return $d['label'];
    if (($d['label'] ?? '') === 'Chromecast / Google TV') return 'Chromecast';
    return $brand ? "$brand $kind" : ucfirst($kind);
}

/** Card type for a device category. */
/** Nothing real known about the device: no name, nothing from a scan, no telling identification. */
function nothing_known(array $d): bool {
    $vague = $d['category'] === 'unknown' || ($d['category'] === 'server' && $d['label'] === 'Server');   // unknown: the label is just the chip's maker
    return $vague && empty($d['name']) && empty($d['scan']['name']) && empty($d['scan']['model']) && empty($d['scan']['webTitle']);
}

function card_type_for(string $category): string {
    return ['console' => 'console', 'tv' => 'tv', 'camera' => 'camera', 'phone' => 'mobile', 'printer' => 'printer', 'computer' => 'desktop',
            'network' => 'switch', 'server' => 'server'][$category] ?? 'iot';
}

/**
 * Subnets with "Name and type cards" on: cards named only by their address (or named
 * by this before, until a person renames them) get a useful name and type. Same names
 * in one subnet get the address's last number (".12"). Runs from cli/poll-snmp.php.
 */
function auto_name_cards(): void {
    $pdo = db();
    $subnets = $pdo->query('SELECT subnet FROM subnet_scans WHERE auto_name = 1')->fetchAll(PDO::FETCH_COLUMN);
    if (!$subnets) return;
    require_once __DIR__ . '/checker.php';
    $inventory = [];
    foreach (device_inventory()['devices'] as $d) if ($d['ip'] && $d['hostId']) $inventory[(int) $d['hostId']] = $d;
    foreach ($subnets as $subnet) {
        $prefix = substr($subnet, 0, -4);
        $q = $pdo->prepare('SELECT id, name, ip_address, device, auto_named FROM hosts WHERE ip_address LIKE ?');
        $q->execute([$prefix . '%']);
        $cards = $q->fetchAll();
        $planned = [];
        foreach ($cards as $c) {
            if (!$c['auto_named'] && $c['name'] !== $c['ip_address']) continue;   // a person named it
            $d = $inventory[(int) $c['id']] ?? null;
            if (!$d) continue;
            if ($c['auto_named'] && nothing_known($d)) {
                $pdo->prepare("UPDATE hosts SET name = ip_address, device = 'server', auto_named = 0 WHERE id = ?")->execute([$c['id']]);
                continue;
            }
            // Nothing known beyond the card's default "server" type: no name is better than a made-up one.
            if (nothing_known($d)) continue;
            $planned[(int) $c['id']] = ['name' => useful_device_name($d), 'type' => $c['device'] === 'server' || $c['auto_named'] ? card_type_for($d['category']) : $c['device'],
                                       'ip' => $c['ip_address'], 'old' => $c['name']];
        }
        // Names used more than once in the subnet (also by cards named by hand) get ".<last number>".
        $count = array_count_values(array_map('strtolower', array_merge(array_column($planned, 'name'),
            array_map(fn($c) => $c['name'], array_filter($cards, fn($c) => !isset($planned[(int) $c['id']]))))));
        foreach ($planned as $id => $p) {
            $name = $count[strtolower($p['name'])] > 1 ? $p['name'] . ' .' . substr(strrchr($p['ip'], '.'), 1) : $p['name'];
            if ($name === $p['old'] && $p['type'] === null) continue;
            $pdo->prepare('UPDATE hosts SET name = ?, device = ?, auto_named = 1 WHERE id = ?')->execute([mb_substr($name, 0, 60), $p['type'], $id]);
        }
    }
}

/**
 * "Smart-home device on Wifi — belongs on IoT": a device whose kind has a network of
 * its own (by subnet name) but that's on a different one. Null when fine or unknown.
 */
function wrong_network_note(array $d, array $subnetNames): ?string {
    $re = EXPECTED_NETWORK[$d['category']] ?? null;
    if (!$re || empty($d['ip']) || ($d['where']['kind'] ?? '') === 'vm' || $d['confidence'] === 'low') return null;
    $homes = array_filter($subnetNames, fn($n) => preg_match($re, $n));
    if (!$homes || isset($homes[$d['subnet']])) return null;
    $here = $d['subnetName'] ?: $d['subnet'];
    $kind = strtolower(DEVICE_CATEGORIES[$d['category']][1]);
    return "$kind on the $here network — belongs on " . implode(' / ', array_unique($homes));
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/devicescan.php")"
cat > "$APP_DIR/includes/devicescan.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/scanner.php';   // snmp_probe()
require_once __DIR__ . '/scanqueue.php';

/**
 * Deep device scan, Fing-style: asks a device directly what it is.
 *   - TCP ports (common services and smart-home/TV/console ports), with
 *     web page titles and server banners;
 *   - UPnP/SSDP description (friendly name, maker, model, serial);
 *   - brand info pages: Roku, Google Cast, Shelly, Tasmota, Philips Hue;
 *   - NetBIOS name (Windows, NAS), SNMP sysDescr (printers, gear).
 * Takes a few seconds; runs in the background (cron for "Scan now",
 * poll-snmp.php for a daily refresh of every device).
 */

const SCAN_PORTS = [
    21 => 'FTP', 22 => 'SSH', 23 => 'Telnet', 53 => 'DNS', 80 => 'Web', 81 => 'Web', 139 => 'NetBIOS', 443 => 'Web (HTTPS)', 445 => 'File sharing (SMB)',
    515 => 'Printer (LPD)', 548 => 'AFP (Apple file sharing)', 554 => 'Video stream (RTSP)', 631 => 'Printer (IPP)', 1400 => 'Sonos',
    1883 => 'MQTT', 1925 => 'Philips TV', 3000 => 'Web app', 3001 => 'LG webOS TV', 3389 => 'Remote Desktop', 3689 => 'iTunes / DAAP',
    4343 => 'Aruba Instant', 5000 => 'Web (UPnP / Synology)', 5001 => 'Web (Synology HTTPS)', 5555 => 'Android debug (ADB)', 5900 => 'VNC',
    6466 => 'Android TV remote', 6467 => 'Android TV remote', 6668 => 'Tuya', 7000 => 'AirPlay', 7100 => 'AirPlay', 8000 => 'Web',
    8001 => 'Samsung TV', 8002 => 'Samsung TV', 8008 => 'Google Cast', 8009 => 'Google Cast', 8060 => 'Roku', 8080 => 'Web', 8081 => 'Web',
    8443 => 'Web (HTTPS)', 8888 => 'Web', 9000 => 'Web / Cast', 9100 => 'Printer (raw)', 9999 => 'TP-Link Kasa', 32400 => 'Plex',
    49152 => 'UPnP', 49153 => 'UPnP', 55443 => 'Yeelight', 62078 => 'Apple device sync',
];
// Card types whose Details show the scanned device info (and get scanned when set).
const DEVICE_SCAN_TYPES = ['iot', 'console', 'tv', 'camera'];
const SCAN_WEB_PORTS = [80, 81, 443, 3000, 5000, 5001, 8000, 8080, 8081, 8443, 8888, 4343];
const SCAN_TLS_PORTS = [443, 5001, 8443, 4343];

/** Open TCP ports, all tried at once (one shared timeout). */
function scan_tcp_ports(string $ip, array $ports, float $timeout = 1.5): array {
    $socks = [];
    foreach ($ports as $p) {
        $s = @stream_socket_client("tcp://$ip:$p", $errno, $err, $timeout, STREAM_CLIENT_ASYNC_CONNECT | STREAM_CLIENT_CONNECT);
        if ($s) { stream_set_blocking($s, false); $socks[$p] = $s; }
    }
    $open = [];
    $deadline = microtime(true) + $timeout;
    while ($socks && microtime(true) < $deadline) {
        $w = array_values($socks);
        $r = $e = null;
        if (@stream_select($r, $w, $e, 0, 200000) === false) break;
        foreach ($w as $s) {
            $p = array_search($s, $socks, true);
            if (@stream_socket_get_name($s, true) !== false) $open[] = $p;   // connected
            fclose($s);
            unset($socks[$p]);
        }
    }
    foreach ($socks as $s) fclose($s);
    sort($open);
    return $open;
}

/** Small HTTP GET: [status, headers, body] or null. */
function scan_http(string $url, int $timeout = 3): ?array {
    $ch = curl_init($url);
    $headers = [];
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 2,
        CURLOPT_CONNECTTIMEOUT => 2, CURLOPT_TIMEOUT => $timeout, CURLOPT_SSL_VERIFYPEER => false, CURLOPT_SSL_VERIFYHOST => 0,
        CURLOPT_USERAGENT => 'WebMonitor device scan', CURLOPT_RANGE => '0-65535',
        CURLOPT_HEADERFUNCTION => function ($c, $h) use (&$headers) {
            if (str_contains($h, ':')) { [$k, $v] = explode(':', $h, 2); $headers[strtolower(trim($k))] = trim($v); }
            return strlen($h);
        },
    ]);
    $body = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    if ($body === false || !$code) return null;
    return [$code, $headers, substr((string) $body, 0, 65536)];
}

/** UPnP: unicast M-SEARCH, then the device description of the first answer. */
function scan_ssdp(string $ip): ?array {
    $s = @stream_socket_client("udp://$ip:1900", $errno, $err, 1);
    if (!$s) return null;
    fwrite($s, "M-SEARCH * HTTP/1.1\r\nHOST: $ip:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 1\r\nST: upnp:rootdevice\r\n\r\n");
    stream_set_timeout($s, 2);
    $reply = (string) fread($s, 4096);
    fclose($s);
    if (!preg_match('/^location:\s*(\S+)/mi', $reply, $m)) return null;
    $out = ['location' => $m[1], 'server' => preg_match('/^server:\s*(.+)$/mi', $reply, $sv) ? trim($sv[1]) : null];
    $r = scan_http($m[1]);
    if ($r && $r[0] < 400 && ($x = @simplexml_load_string($r[2]))) {
        $x->registerXPathNamespace('u', 'urn:schemas-upnp-org:device-1-0');
        $dev = $x->xpath('//u:device')[0] ?? $x->device ?? null;
        if ($dev) {
            foreach (['friendlyName', 'manufacturer', 'modelName', 'modelNumber', 'modelDescription', 'serialNumber', 'deviceType'] as $k) {
                $v = trim((string) ($dev->$k ?? ''));
                if ($v !== '') $out[$k] = mb_substr($v, 0, 120);
            }
        }
    }
    return $out;
}

/** NetBIOS node status (UDP 137): the machine's name and workgroup. */
function scan_netbios(string $ip): ?array {
    $s = @stream_socket_client("udp://$ip:137", $errno, $err, 1);
    if (!$s) return null;
    $name = "\x20" . 'CK' . str_repeat('A', 30) . "\x00";   // "*" padded, first-level encoded
    fwrite($s, pack('nnnnnn', random_int(1, 65535), 0, 1, 0, 0, 0) . $name . pack('nn', 0x21, 1));
    stream_set_timeout($s, 1);
    $r = (string) fread($s, 2048);
    fclose($s);
    if (strlen($r) < 57) return null;
    $count = ord($r[56]);
    $names = [];
    for ($i = 0; $i < $count && 57 + $i * 18 + 18 <= strlen($r); $i++) {
        $entry = substr($r, 57 + $i * 18, 18);
        $nm = rtrim(substr($entry, 0, 15));
        $type = ord($entry[15]);
        $group = (ord($entry[16]) & 0x80) !== 0;
        if ($nm !== '' && ctype_print($nm)) $names[] = ['name' => $nm, 'type' => $type, 'group' => $group];
    }
    $host = array_values(array_filter($names, fn($n) => !$n['group'] && $n['type'] === 0x00))[0]['name'] ?? null;
    $wg = array_values(array_filter($names, fn($n) => $n['group'] && $n['type'] === 0x00))[0]['name'] ?? null;
    return $host || $wg ? ['name' => $host, 'workgroup' => $wg] : null;
}

/** A DNS name in wire format. */
function dns_wire_name(string $name): string {
    $out = '';
    foreach (explode('.', rtrim($name, '.')) as $label) $out .= chr(strlen($label)) . $label;
    return $out . "\0";
}

/** Reads a (possibly compressed) DNS name at $off; moves $off past it. */
function dns_read_name(string $p, int &$off): string {
    $labels = [];
    $pos = $off;
    $jumped = false;
    for ($hops = 0; $pos < strlen($p) && $hops < 20;) {
        $len = ord($p[$pos]);
        if ($len === 0) { $pos++; break; }
        if (($len & 0xC0) === 0xC0) {
            if ($pos + 1 >= strlen($p)) break;
            if (!$jumped) $off = $pos + 2;
            $jumped = true;
            $pos = (($len & 0x3F) << 8) | ord($p[$pos + 1]);
            $hops++;
            continue;
        }
        $labels[] = substr($p, $pos + 1, $len);
        $pos += $len + 1;
    }
    if (!$jumped) $off = $pos;
    return implode('.', $labels);
}

/** One unicast mDNS question (RFC 6762 "legacy unicast"): [[type, name, value], ...]. */
function mdns_query(string $ip, string $qname, int $qtype): array {
    $s = @stream_socket_client("udp://$ip:5353", $errno, $err, 1);
    if (!$s) return [];
    fwrite($s, pack('nnnnnn', random_int(1, 65535), 0, 1, 0, 0, 0) . dns_wire_name($qname) . pack('nn', $qtype, 1));
    stream_set_timeout($s, 1);
    $r = (string) fread($s, 9000);
    fclose($s);
    if (strlen($r) < 12) return [];
    $h = unpack('nid/nflags/nqd/nan/nns/nar', $r);
    $off = 12;
    for ($i = 0; $i < $h['qd']; $i++) { dns_read_name($r, $off); $off += 4; }
    $out = [];
    for ($i = 0; $i < $h['an'] + $h['ns'] + $h['ar'] && $off + 10 <= strlen($r); $i++) {
        $name = dns_read_name($r, $off);
        $t = unpack('ntype/nclass/Nttl/nlen', substr($r, $off, 10));
        $off += 10;
        $start = $off;
        $data = substr($r, $off, $t['len']);
        $off += $t['len'];
        if ($t['type'] === 12) {
            $o = $start;
            $out[] = ['PTR', $name, dns_read_name($r, $o)];
        } elseif ($t['type'] === 16) {
            $txt = [];
            for ($j = 0; $j < strlen($data);) { $l = ord($data[$j]); $txt[] = substr($data, $j + 1, $l); $j += $l + 1; }
            $out[] = ['TXT', $name, $txt];
        }
    }
    return $out;
}

/**
 * mDNS / Bonjour: the device's .local name, the services it advertises and, for
 * Apple gear, its model. Only answered on the same subnet as this server.
 */
function scan_mdns(string $ip): ?array {
    $reverse = implode('.', array_reverse(explode('.', $ip))) . '.in-addr.arpa';
    $out = [];
    foreach (mdns_query($ip, $reverse, 12) as [$type, , $value]) {
        if ($type === 'PTR' && str_ends_with($value, '.local')) { $out['hostname'] = mb_substr(substr($value, 0, -6), 0, 80); break; }
    }
    if (!$out) return null;   // not answering mDNS: don't ask twice more
    $services = [];
    foreach (mdns_query($ip, '_services._dns-sd._udp.local', 12) as [$type, , $value]) {
        if ($type === 'PTR' && preg_match('/^(_[a-z0-9-]+)\._(tcp|udp)\.local$/i', $value, $m)) $services[] = strtolower($m[1]);
    }
    if ($services) $out['services'] = array_values(array_unique($services));
    foreach (mdns_query($ip, $out['hostname'] . '._device-info._tcp.local', 16) as [$type, , $txt]) {
        foreach ($type === 'TXT' ? $txt : [] as $kv) if (str_starts_with($kv, 'model=')) $out['model'] = mb_substr(substr($kv, 6), 0, 60);
    }
    return $out;
}

/** Brand info pages that say exactly what the device is. */
function scan_brand_apis(string $ip, array $open): array {
    $out = [];
    if (in_array(8060, $open, true) && ($r = scan_http("http://$ip:8060/query/device-info")) && ($x = @simplexml_load_string($r[2]))) {
        $out['roku'] = array_filter(['name' => (string) $x->{'user-device-name'} ?: (string) $x->{'friendly-device-name'},
            'model' => trim((string) $x->{'model-name'} . ' ' . (string) $x->{'model-number'}), 'serial' => (string) $x->{'serial-number'},
            'firmware' => (string) $x->{'software-version'}, 'maker' => (string) $x->{'vendor-name'} ?: 'Roku']);
    }
    if (in_array(8008, $open, true) && ($r = scan_http("http://$ip:8008/setup/eureka_info?params=name,device_info,build_info")) && ($j = json_decode($r[2], true))) {
        $out['cast'] = array_filter(['name' => $j['name'] ?? null, 'model' => $j['device_info']['model_name'] ?? null,
            'maker' => $j['device_info']['manufacturer'] ?? null, 'firmware' => $j['build_info']['cast_build_revision'] ?? null]);
    }
    if (in_array(80, $open, true)) {
        if (($r = scan_http("http://$ip/shelly", 2)) && ($j = json_decode($r[2], true)) && (isset($j['type']) || isset($j['model']))) {
            $out['shelly'] = array_filter(['model' => $j['model'] ?? $j['type'] ?? null, 'name' => $j['name'] ?? null,
                'firmware' => $j['fw'] ?? $j['ver'] ?? null, 'maker' => 'Shelly']);
        } elseif (($r = scan_http("http://$ip/cm?cmnd=Status%200", 2)) && ($j = json_decode($r[2], true)) && isset($j['StatusFWR'])) {
            $out['tasmota'] = array_filter(['name' => $j['Status']['DeviceName'] ?? $j['Status']['FriendlyName'][0] ?? null,
                'model' => 'Tasmota ' . ($j['StatusFWR']['Hardware'] ?? ''), 'firmware' => $j['StatusFWR']['Version'] ?? null, 'maker' => 'Tasmota']);
        } elseif (($r = scan_http("http://$ip/api/config", 2)) && ($j = json_decode($r[2], true)) && isset($j['bridgeid'])) {
            $out['hue'] = array_filter(['name' => $j['name'] ?? null, 'model' => 'Hue bridge ' . ($j['modelid'] ?? ''),
                'firmware' => $j['swversion'] ?? null, 'maker' => 'Philips Hue']);
        }
    }
    return $out;
}

/** Title and server banner of a web page. */
function scan_web(string $ip, int $port): ?array {
    $scheme = in_array($port, SCAN_TLS_PORTS, true) ? 'https' : 'http';
    $r = scan_http("$scheme://$ip:$port/", 3);
    if (!$r) return null;
    $title = preg_match('/<title[^>]*>(.*?)<\/title>/is', $r[2], $m) ? trim(html_entity_decode(strip_tags($m[1]), ENT_QUOTES)) : null;
    return array_filter(['status' => $r[0], 'title' => $title ? mb_substr(preg_replace('/\s+/', ' ', $title), 0, 100) : null,
        'server' => isset($r[1]['server']) ? mb_substr($r[1]['server'], 0, 100) : null]);
}

function scan_ssh_banner(string $ip): ?string {
    $s = @stream_socket_client("tcp://$ip:22", $errno, $err, 2);
    if (!$s) return null;
    stream_set_timeout($s, 2);
    $line = trim((string) fgets($s, 256));
    fclose($s);
    return str_starts_with($line, 'SSH-') ? mb_substr($line, 0, 100) : null;
}

/** SNMP communities to try on scanned devices: the ones set on host cards (most used first), then "public". */
function scan_snmp_communities(): array {
    static $list = null;
    if ($list === null) {
        $list = db()->query("SELECT community FROM hosts WHERE community <> '' GROUP BY community ORDER BY COUNT(*) DESC LIMIT 4")->fetchAll(PDO::FETCH_COLUMN);
        $list = array_values(array_unique(array_merge($list, ['public'])));
    }
    return $list;
}

/** Scans one device; returns the result stored in device_scans.data. */
function scan_device(string $ip): array {
    $t = microtime(true);
    $open = scan_tcp_ports($ip, array_keys(SCAN_PORTS));
    $out = ['ip' => $ip, 'ports' => array_map(fn($p) => ['port' => $p, 'service' => SCAN_PORTS[$p] ?? null], $open)];
    $web = [];
    foreach (array_intersect($open, SCAN_WEB_PORTS) as $p) if ($w = scan_web($ip, $p)) $web[$p] = $w;
    if ($web) $out['web'] = $web;
    if (in_array(22, $open, true) && ($b = scan_ssh_banner($ip))) $out['ssh'] = $b;
    if ($u = scan_ssdp($ip)) $out['upnp'] = $u;
    if ($nb = scan_netbios($ip)) $out['netbios'] = $nb;
    if ($md = scan_mdns($ip)) $out['mdns'] = $md;
    if ($api = scan_brand_apis($ip, $open)) $out['brand'] = $api;
    foreach (scan_snmp_communities() as $community) {
        if ($snmp = snmp_probe($ip, $community, 0.8)) { $out['snmp'] = array_filter(['descr' => mb_substr((string) $snmp['sysDescr'], 0, 200), 'name' => $snmp['sysName']]); break; }
    }
    $out['summary'] = scan_summary($out);
    $out['ms'] = (int) round((microtime(true) - $t) * 1000);
    return $out;
}

/** The best name/maker/model/firmware from everything the device said. */
function scan_summary(array $s): array {
    $sum = [];
    foreach ($s['brand'] ?? [] as $b) foreach (['name', 'maker', 'model', 'serial', 'firmware'] as $k) if (!empty($b[$k])) $sum[$k] ??= $b[$k];
    $u = $s['upnp'] ?? [];
    $sum['name'] ??= $u['friendlyName'] ?? null;
    $sum['maker'] ??= $u['manufacturer'] ?? null;
    if (!isset($sum['model']) && !empty($u['modelName'])) $sum['model'] = trim($u['modelName'] . (!empty($u['modelNumber']) && !str_contains($u['modelName'], $u['modelNumber']) ? ' ' . $u['modelNumber'] : ''));
    $sum['serial'] ??= $u['serialNumber'] ?? null;
    $sum['name'] ??= $s['mdns']['hostname'] ?? $s['netbios']['name'] ?? $s['snmp']['name'] ?? null;
    if (!isset($sum['model']) && !empty($s['mdns']['model'])) $sum['model'] = $s['mdns']['model'];
    if (!empty($s['mdns']['services'])) $sum['services'] = $s['mdns']['services'];
    if (!isset($sum['model']) && !empty($s['snmp']['descr'])) $sum['model'] = mb_substr(strtok($s['snmp']['descr'], "\r\n"), 0, 80);
    if (!isset($sum['firmware']) && !empty($u['server']) && preg_match('/([A-Za-z]+)\/([\d.]+)/', $u['server'], $m)) $sum['firmware'] = "{$m[1]} {$m[2]}";
    foreach ($s['web'] ?? [] as $w) { if (!empty($w['title'])) { $sum['webTitle'] = $w['title']; break; } }
    return array_filter($sum, fn($v) => $v !== null && $v !== '');
}

function device_scan_key(?string $mac, ?string $ip): string {
    return $mac ?: "ip:$ip";
}

/** Asks for a scan of a device (runs within a minute). */
function request_device_scan(?string $mac, string $ip, bool $priority = true): void {
    $now = (int) round(microtime(true) * 1000);
    db()->prepare('INSERT INTO device_scans (dkey, ip, mac, requested_at, priority_at) VALUES (?, ?, ?, ?, ?)
                   ON DUPLICATE KEY UPDATE ip = VALUES(ip),
                     priority_at = IF(VALUES(priority_at) IS NULL, priority_at, VALUES(priority_at)),
                     requested_at = GREATEST(COALESCE(requested_at, 0) + 1, VALUES(requested_at))')
        ->execute([device_scan_key($mac, $ip), $ip, $mac, $now, $priority ? next_scan_priority() : null]);
}

function save_device_scan(?string $mac, string $ip, array $data, ?int $requestAt): void {
    db()->prepare('INSERT INTO device_scans (dkey, ip, mac, scanned_at, data) VALUES (?, ?, ?, ?, ?)
                   ON DUPLICATE KEY UPDATE ip = IF(requested_at <=> ?, VALUES(ip), ip), scanned_at = VALUES(scanned_at), data = VALUES(data),
                     priority_at = IF(requested_at <=> ?, NULL, priority_at),
                     requested_at = IF(requested_at <=> ?, NULL, requested_at)')
        ->execute([device_scan_key($mac, $ip), $ip, $mac, (int) round(microtime(true) * 1000), json_encode($data), $requestAt, $requestAt, $requestAt]);
    // A card known only by its address takes the name the device gave itself.
    if (!empty($data['summary']['name'])) {
        $card = db()->prepare('SELECT id FROM hosts WHERE ip_address = ?');
        $card->execute([$ip]);
        if ($id = $card->fetchColumn()) adopt_host_name((int) $id, $data['summary']['name']);
    }
}

/** "Scan now" requests (cli/cron.php, every minute; a few per run). */
function run_requested_scans(int $max = 4): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_device_scan', 0)")->fetchColumn()) return;
    try {
        for ($i = 0; $i < $max; $i++) {
            $r = $pdo->query('SELECT dkey, ip, mac, requested_at FROM device_scans WHERE requested_at IS NOT NULL
                              ORDER BY priority_at DESC, requested_at, dkey LIMIT 1')->fetch();
            if (!$r) break;
            scan_activity_start('webmonitor_device_scan', 'device', $r['ip']);
            try {
                save_device_scan($r['mac'], $r['ip'], scan_device($r['ip']), (int) $r['requested_at']);
            } finally {
                scan_activity_end('webmonitor_device_scan');
            }
        }
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_device_scan')");
    }
}

/** Devices eligible for the daily refresh, oldest scan first. */
function due_device_scans(): array {
    require_once __DIR__ . '/devices.php';
    require_once __DIR__ . '/checker.php';
    $known = [];
    foreach (db()->query('SELECT dkey, scanned_at, requested_at FROM device_scans') as $r) $known[$r['dkey']] = $r;
    $due = [];
    foreach (device_inventory()['devices'] as $d) {
        if (!$d['ip'] || in_array($d['where']['kind'] ?? '', ['network'], true)) continue;
        $key = device_scan_key($d['mac'], $d['ip']);
        $row = $known[$key] ?? null;
        $at = (int) ($row['scanned_at'] ?? 0);
        if ($at < (time() - 86400) * 1000 && empty($row['requested_at'])) $due[] = [$at, $d['mac'], $d['ip'], $d['name']];
    }
    sort($due);
    return $due;
}

/** Daily refresh: scans devices not scanned for a day (cli/poll-snmp.php, a few per run). */
function refresh_device_scans(int $max = 4): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_device_scan', 0)")->fetchColumn()) return;
    try {
        foreach (array_slice(due_device_scans(), 0, $max) as [, $mac, $ip]) {
            if ($pdo->query('SELECT 1 FROM device_scans WHERE requested_at IS NOT NULL LIMIT 1')->fetchColumn()) break;
            scan_activity_start('webmonitor_device_scan', 'device', $ip);
            try {
                save_device_scan($mac, $ip, scan_device($ip), null);
            } finally {
                scan_activity_end('webmonitor_device_scan');
            }
        }
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_device_scan')");
    }
}

/** [dkey => summary + scannedAt] for device identification. */
function device_scan_summaries(): array {
    $out = [];
    foreach (db()->query('SELECT dkey, ip, scanned_at, data FROM device_scans WHERE data IS NOT NULL') as $r) {
        $d = json_decode($r['data'], true);
        $out[$r['dkey']] = ($d['summary'] ?? []) + ['scannedAt' => (int) $r['scanned_at'], 'ports' => count($d['ports'] ?? [])];
    }
    return $out;
}

/** [ip => {model, maker, firmware, name}] of the newest scan per address, for the cards. */
function device_card_summaries(): array {
    $out = [];
    foreach (db()->query('SELECT ip, data FROM device_scans WHERE data IS NOT NULL AND ip IS NOT NULL ORDER BY scanned_at') as $r) {
        $s = json_decode($r['data'], true)['summary'] ?? [];
        if ($s) $out[$r['ip']] = array_intersect_key($s, array_flip(['model', 'maker', 'firmware', 'name']));
    }
    return $out;
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/dhcpleases.php")"
cat > "$APP_DIR/includes/dhcpleases.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/configbackup.php';

/**
 * DHCP leases from switches that are DHCP servers (Cisco IOS "ip dhcp pool"),
 * read over the SSH login set up for config backups. A lease ties an address
 * to a MAC even when the device isn't in any ARP table right now, so devices
 * known only by address get a maker (and private-address phones are seen as such).
 * Stored in settings 'dhcp_leases': {"at": ms, "leases": {ip: mac}}.
 */

const DHCP_LEASES_EVERY_SEC = 3600;

/** "show ip dhcp binding" -> [ip => mac]. Client IDs "01" + MAC only (others are DUIDs). */
function parse_cisco_dhcp_bindings(string $out): array {
    $leases = [];
    foreach (explode("\n", $out) as $line) {
        if (!preg_match('/^(\d{1,3}(?:\.\d{1,3}){3})\s+([0-9a-f.]+)\s/i', trim($line), $m)) continue;
        if (!filter_var($m[1], FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) continue;
        $hex = strtolower(str_replace('.', '', $m[2]));
        if (strlen($hex) === 14 && str_starts_with($hex, '01')) $hex = substr($hex, 2);   // client ID: type 01 (Ethernet) + MAC
        if (strlen($hex) === 12 && ctype_xdigit($hex)) $leases[$m[1]] = implode(':', str_split($hex, 2));
    }
    return $leases;
}

/** Hourly from cli/poll-snmp.php: devices whose backed-up config has DHCP pools. */
function refresh_dhcp_leases(bool $force = false): void {
    $pdo = db();
    $stored = json_decode((string) $pdo->query("SELECT v FROM settings WHERE k = 'dhcp_leases'")->fetchColumn(), true) ?: [];
    if (!$force && (int) ($stored['at'] ?? 0) > now_ms_cfg() - DHCP_LEASES_EVERY_SEC * 1000) return;
    $rows = $pdo->query("SELECT c.*, h.ip_address FROM config_backup_settings c JOIN hosts h ON h.id = c.host_id
                         WHERE c.vendor = 'cisco_ios' AND c.last_error IS NULL")->fetchAll();
    $latest = $pdo->prepare('SELECT content FROM switch_configs WHERE host_id = ? ORDER BY fetched_at DESC LIMIT 1');
    $leases = [];
    $ok = false;
    foreach ($rows as $r) {
        $latest->execute([$r['host_id']]);
        if (!preg_match('/^ip dhcp pool /m', (string) $latest->fetchColumn())) continue;   // not a DHCP server
        [$out, $err] = ssh_shell($r, $r['ip_address'], ['enable' => true, 'commands' => ['terminal length 0', 'show ip dhcp binding']]);
        if ($err || $out === null) {
            printf("%s DHCP leases from %s failed: %s\n", date('Y-m-d H:i:s'), $r['ip_address'], $err);
            continue;
        }
        $leases += parse_cisco_dhcp_bindings($out);
        $ok = true;
    }
    // Keep the last good table when every server failed; try again next hour either way.
    if (!$ok && $rows) $leases = $stored['leases'] ?? [];
    $pdo->prepare("INSERT INTO settings (k, v) VALUES ('dhcp_leases', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")
        ->execute([json_encode(['at' => now_ms_cfg(), 'leases' => $leases])]);
}

/** [ip => mac] from the last lease table. */
function dhcp_lease_macs(): array {
    $stored = json_decode((string) db()->query("SELECT v FROM settings WHERE k = 'dhcp_leases'")->fetchColumn(), true) ?: [];
    return is_array($stored['leases'] ?? null) ? $stored['leases'] : [];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/discovery.php")"
cat > "$APP_DIR/includes/discovery.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/scanner.php';
require_once __DIR__ . '/notify.php';
require_once __DIR__ . '/scanqueue.php';

/**
 * Subnet discovery (Settings -> Subnets). Per subnet:
 *   - scan every N minutes: sweep the /24, mark monitored hosts as seen,
 *     and add new devices (or just list them, when auto-add is off);
 *   - remove cards not seen for N days.
 * Hosts with an agent, the subnet's gateway and muted hosts are never
 * removed. "Seen" (hosts.last_seen_at) also comes from successful checks
 * (checker.php) and the server's ARP table (topology.php).
 *
 * Run by cli/poll-snmp.php every 5 minutes; "Scan now" runs one directly.
 */

const SCAN_EVERY_CHOICES = [15, 30, 60, 180, 360, 720, 1440];   // minutes
const DISCOVERY_MAX_ADDS = 15;          // per subnet per run (SNMP-probing new devices takes time)
const DISCOVERY_REMOVE_MAX_SHARE = 0.25; // more than this vanishing at once may be an outage (see looks_like_outage)
const DISCOVERY_OUTAGE_WINDOW_SEC = 6 * 3600;   // ...when they all went quiet within this window

function discovery_now_ms(): int {
    return (int) round(microtime(true) * 1000);
}

function subnet_scan_rows(): array {
    $rows = [];
    foreach (db()->query('SELECT * FROM subnet_scans') as $r) $rows[$r['subnet']] = $r;
    return $rows;
}

/** Public form of a subnet_scans row. */
function subnet_scan_public(array $r): array {
    return [
        'enabled' => (bool) $r['enabled'],
        'everyMin' => (int) $r['every_min'],
        'autoAdd' => (bool) $r['auto_add'],
        'removeDays' => $r['remove_after_days'] !== null ? (int) $r['remove_after_days'] : null,
        'removeScanOnly' => (bool) $r['remove_scan_only'],
        'autoName' => (bool) ($r['auto_name'] ?? false),
        'lastScanAt' => $r['last_scan_at'] !== null ? (int) $r['last_scan_at'] : null,
        'lastResult' => $r['last_result'] ? json_decode($r['last_result'], true) : null,
    ];
}

function log_discovery(string $subnet, string $action, string $ip, string $name, ?string $detail = null): void {
    db()->prepare('INSERT INTO discovery_log (ts, subnet, action, ip, name, detail) VALUES (?, ?, ?, ?, ?, ?)')
        ->execute([discovery_now_ms(), $subnet, $action, $ip, mb_substr($name, 0, 60), $detail !== null ? mb_substr($detail, 0, 255) : null]);
}

/** Marks hosts with these IPs as seen now. */
function mark_ips_seen(array $ips): void {
    if (!$ips) return;
    $ips = array_values(array_unique($ips));
    db()->prepare('UPDATE hosts SET last_seen_at = ? WHERE ip_address IN (' . implode(',', array_fill(0, count($ips), '?')) . ')')
        ->execute(array_merge([discovery_now_ms()], $ips));
}

/** The SNMP community most hosts in the subnet use (new devices get the same). */
function subnet_community(string $prefix): string {
    $stmt = db()->prepare("SELECT community FROM hosts WHERE ip_address LIKE ? AND community <> 'public'
                           GROUP BY community ORDER BY COUNT(*) DESC LIMIT 1");
    $stmt->execute([$prefix . '%']);
    return (string) ($stmt->fetchColumn() ?: 'public');
}

/**
 * Sweeps one subnet: marks hosts seen, adds new devices when auto-add is on.
 * Returns the result stored in subnet_scans.last_result.
 */
function scan_subnet(string $subnet, bool $autoAdd): array {
    $started = microtime(true);
    $pdo = db();
    $prefix = substr($subnet, 0, -4);   // "192.168.10."
    $ips = parse_networks($subnet);
    $sweep = network_sweep($ips, NETCHECK_PORTS, 1.5);
    $upIps = array_keys(array_filter($sweep, fn($r) => $r['up']));

    $known = [];
    $stmt = $pdo->prepare('SELECT ip_address FROM hosts WHERE ip_address LIKE ?');
    $stmt->execute([$prefix . '%']);
    foreach ($stmt->fetchAll(PDO::FETCH_COLUMN) as $ip) $known[$ip] = true;

    mark_ips_seen(array_values(array_filter($upIps, fn($ip) => isset($known[$ip]))));
    $new = array_values(array_filter($upIps, fn($ip) => !isset($known[$ip])));
    usort($new, fn($a, $b) => ip2long($a) <=> ip2long($b));

    $added = [];
    if ($autoAdd && $new) {
        $community = subnet_community($prefix);
        $snmpOk = snmp_available();
        $insert = $pdo->prepare("INSERT INTO hosts (name, ip_address, os, device, community, added_by, last_seen_at)
                                 VALUES (?, ?, ?, ?, ?, 'scan', ?)");
        foreach (array_slice($new, 0, DISCOVERY_MAX_ADDS) as $ip) {
            $snmp = $snmpOk ? snmp_probe($ip, $community, 1.0) : null;
            $class = classify_device($sweep[$ip]['port'], $sweep[$ip]['open'], $snmp);
            $name = substr(explode('.', trim((string) ($snmp['sysName'] ?? '')))[0], 0, 60);
            if ($name === '' || filter_var($name, FILTER_VALIDATE_IP)) $name = $ip;
            $insert->execute([$name, $ip, $class['os'], $class['device'], $community, discovery_now_ms()]);
            log_discovery($subnet, 'added', $ip, $name, $class['label']);
            $added[] = $name === $ip ? $ip : "$name ($ip)";
        }
    }

    return [
        'at' => discovery_now_ms(),
        'ms' => (int) round((microtime(true) - $started) * 1000),
        'scanned' => count($ips),
        'up' => count($upIps),
        'added' => $added,
        'new' => $autoAdd ? array_slice($new, DISCOVERY_MAX_ADDS) : $new,   // seen but not (yet) added
    ];
}

/**
 * Many hosts unseen at once: an outage when nothing on the subnet answers now, or
 * when they all went quiet together. Hosts that dropped off one by one over days
 * (devices that moved to a new DHCP address) are just gone.
 */
function looks_like_outage(array $lastSeenMs, int $seenInLastHour): bool {
    if ($seenInLastHour === 0) return true;
    $seen = array_filter($lastSeenMs);   // never seen: no time to compare
    return count($seen) >= 2 && max($seen) - min($seen) < DISCOVERY_OUTAGE_WINDOW_SEC * 1000;
}

/**
 * Removes cards in the subnet not seen for $days days. Never: hosts with
 * an agent, the subnet's gateway, muted hosts, or (when $scanOnly) hosts a
 * person added. Returns [removed labels, skipped reason or null].
 */
function remove_unseen(string $subnet, int $days, bool $scanOnly): array {
    $pdo = db();
    $prefix = substr($subnet, 0, -4);
    $cutoffMs = discovery_now_ms() - $days * 86400000;
    $gateway = subnet_gateways()[$subnet] ?? '';

    $total = $pdo->prepare('SELECT COUNT(*) FROM hosts WHERE ip_address LIKE ?');
    $total->execute([$prefix . '%']);
    $total = (int) $total->fetchColumn();

    $stmt = $pdo->prepare('SELECT h.id, h.name, h.ip_address, h.last_seen_at FROM hosts h
        LEFT JOIN agents a ON a.host_id = h.id
        WHERE h.ip_address LIKE ? AND a.host_id IS NULL AND h.ip_address <> ?
          AND (h.muted_until IS NULL OR h.muted_until < ?)
          AND COALESCE(h.last_seen_at, 0) < ? AND h.created_at < FROM_UNIXTIME(?)'
        . ($scanOnly ? " AND h.added_by = 'scan'" : ''));
    $stmt->execute([$prefix . '%', $gateway, discovery_now_ms(), $cutoffMs, intdiv($cutoffMs, 1000)]);
    $stale = $stmt->fetchAll();
    if (!$stale) return [[], null];

    if (count($stale) > max(2, (int) floor($total * DISCOVERY_REMOVE_MAX_SHARE))) {
        $recent = $pdo->prepare('SELECT COUNT(*) FROM hosts WHERE ip_address LIKE ? AND last_seen_at >= ?');
        $recent->execute([$prefix . '%', discovery_now_ms() - 3600000]);
        if (looks_like_outage(array_map(fn($h) => (int) $h['last_seen_at'], $stale), (int) $recent->fetchColumn())) {
            return [[], count($stale) . " of $total hosts not seen for $days days at once — looks like an outage, so nothing was removed"];
        }
    }

    $removed = [];
    foreach ($stale as $h) {
        delete_host((int) $h['id']);
        $ago = $h['last_seen_at'] ? (int) floor((discovery_now_ms() - (int) $h['last_seen_at']) / 86400000) : null;
        log_discovery($subnet, 'removed', $h['ip_address'], $h['name'], $ago !== null ? "not seen for $ago days" : 'never seen');
        $removed[] = $h['name'] === $h['ip_address'] ? $h['ip_address'] : "{$h['name']} ({$h['ip_address']})";
    }
    return [$removed, null];
}

/**
 * Runs due scans and removals. $only + $force: scan that subnet now
 * ("Scan now"). Returns [subnet => result].
 */
function run_subnet_scans(?string $only = null, bool $force = false): array {
    $pdo = db();
    $out = [];
    $rows = subnet_scan_rows();
    if ($only !== null && !isset($rows[$only])) {
        $rows[$only] = ['subnet' => $only, 'enabled' => 0, 'every_min' => 60, 'auto_add' => 0,
                        'remove_after_days' => null, 'remove_scan_only' => 1, 'last_scan_at' => null];
    }
    while ($rows) {
        if ($only === null) {
            $current = subnet_scan_rows();
            $rows = array_intersect_key($current, $rows);
            if (!$rows) break;
        }
        uasort($rows, fn($a, $b) => (int) ($b['priority_at'] ?? 0) <=> (int) ($a['priority_at'] ?? 0));
        $subnet = array_key_first($rows);
        $r = $rows[$subnet];
        unset($rows[$subnet]);
        if ($only !== null && $subnet !== $only) continue;
        $due = $r['enabled'] && (int) $r['last_scan_at'] + (int) $r['every_min'] * 60000 <= discovery_now_ms() + 30000;
        $result = null;
        $requestedAt = isset($r['requested_at']) ? (int) $r['requested_at'] : null;
        if ($force || $due || $requestedAt !== null) {
            scan_activity_start('webmonitor_discovery', 'subnet', $subnet);
            try {
                $result = scan_subnet($subnet, (bool) $r['auto_add']);
            } finally {
                scan_activity_end('webmonitor_discovery');
            }
        }
        $removed = [];
        $skipped = null;
        if ($r['remove_after_days']) {
            [$removed, $skipped] = remove_unseen($subnet, (int) $r['remove_after_days'], (bool) $r['remove_scan_only']);
            if ($skipped) {
                // Log once per day, not every 5 minutes.
                $last = $pdo->prepare("SELECT MAX(ts) FROM discovery_log WHERE subnet = ? AND action = 'skipped'");
                $last->execute([$subnet]);
                if ((int) $last->fetchColumn() < discovery_now_ms() - 86400000) log_discovery($subnet, 'skipped', '', '', $skipped);
            }
        }
        if ($result !== null) {
            $result['removed'] = $removed;
            $result['skipped'] = $skipped;
            $pdo->prepare('INSERT INTO subnet_scans (subnet, last_scan_at, last_result) VALUES (?, ?, ?)
                           ON DUPLICATE KEY UPDATE last_scan_at = VALUES(last_scan_at), last_result = VALUES(last_result),
                             priority_at = IF(requested_at <=> ?, NULL, priority_at),
                             requested_at = IF(requested_at <=> ?, NULL, requested_at)')
                ->execute([$subnet, $result['at'], json_encode($result), $requestedAt, $requestedAt]);
        }
        $added = $result['added'] ?? [];
        if ($added || $removed) {
            $label = ($n = subnet_names()[$subnet] ?? '') !== '' ? "$n ($subnet)" : $subnet;
            $lines = array_merge(array_map(fn($x) => "Added: $x", $added), array_map(fn($x) => "Removed (not seen for {$r['remove_after_days']} days): $x", $removed));
            notify_all("WebMonitor: changes on $label", implode("\n", $lines), 'info');
        }
        $out[$subnet] = ($result ?? []) + ['removed' => $removed, 'skipped' => $skipped];
    }
    return $out;
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/flows.php")"
cat > "$APP_DIR/includes/flows.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/history.php';

/**
 * Network traffic from NetFlow/IPFIX. cli/flow-collector.py (the
 * webmonitor-flow service) writes one summary per minute to FLOW_DIR;
 * cli/cron.php loads them every minute with ingest_flows(). Detail is kept
 * FLOW_KEEP_DAYS; each monitored host's traffic also goes into the history
 * graphs (flow_in / flow_out, bytes per second), kept for a year+.
 */

const FLOW_DIR = '/var/lib/webmonitor/flows';
const FLOW_KEEP_DAYS = 14;
const FLOW_CONV_KEEP_DAYS = 3;

// Service names for the usual ports ([proto][port]; 6 TCP, 17 UDP).
const FLOW_SERVICES = [
    6 => [111 => 'RPC (NFS)', 873 => 'rsync', 2049 => 'NFS', 20 => 'FTP data', 21 => 'FTP', 22 => 'SSH', 23 => 'Telnet', 25 => 'SMTP', 53 => 'DNS', 80 => 'HTTP', 110 => 'POP3', 143 => 'IMAP',
          443 => 'HTTPS', 445 => 'SMB', 465 => 'SMTPS', 587 => 'SMTP submission', 853 => 'DNS over TLS', 993 => 'IMAPS', 995 => 'POP3S',
          1194 => 'OpenVPN', 1883 => 'MQTT', 1935 => 'RTMP streaming', 2049 => 'NFS', 3074 => 'Xbox Live', 3306 => 'MySQL', 3389 => 'Remote Desktop',
          3478 => 'PlayStation / STUN', 3479 => 'PlayStation', 3480 => 'PlayStation', 5222 => 'XMPP chat', 5223 => 'Apple push', 5228 => 'Google Play',
          5900 => 'VNC', 8006 => 'Proxmox', 8080 => 'HTTP alt', 8443 => 'HTTPS alt', 8883 => 'MQTT TLS', 9100 => 'Printing', 27015 => 'Steam',
          32400 => 'Plex'],
    17 => [53 => 'DNS', 67 => 'DHCP', 68 => 'DHCP', 123 => 'NTP', 137 => 'NetBIOS', 161 => 'SNMP', 443 => 'QUIC (HTTP/3)', 500 => 'IPsec',
           514 => 'Syslog', 1194 => 'OpenVPN', 1900 => 'SSDP', 2055 => 'NetFlow', 3074 => 'Xbox Live', 3478 => 'STUN / PlayStation', 3479 => 'PlayStation',
           3480 => 'PlayStation', 3544 => 'Teredo (Xbox)', 4500 => 'IPsec NAT-T', 5353 => 'mDNS', 19302 => 'Google Meet / STUN',
           27015 => 'Steam', 41641 => 'Tailscale', 51820 => 'WireGuard'],
];
const FLOW_PROTOS = [1 => 'ICMP', 2 => 'IGMP', 6 => 'TCP', 17 => 'UDP', 47 => 'GRE', 50 => 'ESP', 58 => 'ICMPv6', 112 => 'VRRP'];

function flow_service_name(int $proto, int $port): string {
    if ($port === 0) return FLOW_PROTOS[$proto] ?? "IP proto $proto";
    if (isset(FLOW_SERVICES[$proto][$port])) return FLOW_SERVICES[$proto][$port];
    if ($port >= 27000 && $port <= 27100) return 'Steam games';
    if ($port >= 16384 && $port <= 32767 && $proto === 17) return 'Voice / video (RTP)';
    return (FLOW_PROTOS[$proto] ?? "proto $proto") . " $port";
}

/**
 * [$who, $names]: $who(ip) gives {ip, name, hostId, category, label} for a local address
 * (cards first, then what the device inventory knows); $names is [ip => {name, hostId}] of the cards.
 */
function flow_name_resolver(): array {
    $names = [];
    foreach (db()->query('SELECT id, name, ip_address FROM hosts') as $h) $names[$h['ip_address']] = ['name' => $h['name'] === $h['ip_address'] ? null : $h['name'], 'hostId' => (int) $h['id']];
    $inventory = [];
    try {
        require_once __DIR__ . '/devices.php';
        require_once __DIR__ . '/checker.php';
        foreach (device_inventory()['devices'] as $dv) if ($dv['ip']) $inventory[$dv['ip']] ??= $dv;
    } catch (Throwable $e) { /* names are a nicety */ }
    $who = function (string $ip) use ($names, $inventory) {
        $inv = $inventory[$ip] ?? null;
        return ['ip' => $ip, 'name' => $names[$ip]['name'] ?? $inv['name'] ?? null, 'hostId' => $names[$ip]['hostId'] ?? null,
                'category' => $inv['category'] ?? null, 'label' => $inv['label'] ?? null];
    };
    return [$who, $names];
}

/** Loads finished minute files from the collector. cli/cron.php, every minute. */
function ingest_flows(): void {
    if (!is_dir(FLOW_DIR)) return;
    $pdo = db();
    $status = @file_get_contents(FLOW_DIR . '/status.json');
    if ($status !== false) {
        $pdo->prepare("INSERT INTO settings (k, v) VALUES ('flow_status', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")->execute([$status]);
    }
    $files = glob(FLOW_DIR . '/[0-9]*.json') ?: [];
    sort($files);
    if (!$files) return;
    $hostIds = [];
    foreach ($pdo->query('SELECT id, ip_address FROM hosts') as $h) $hostIds[$h['ip_address']] = (int) $h['id'];
    $ifTables = (bool) $pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'flow_iface_conv'")->fetchColumn();

    foreach ($files as $file) {
        $d = json_decode((string) @file_get_contents($file), true);
        if (!is_array($d) || !isset($d['ts'])) { @unlink($file); continue; }
        $ts = (int) $d['ts'];
        $t = $d['totals'];
        $pdo->beginTransaction();
        $pdo->prepare('INSERT INTO flow_totals (ts, down_bytes, up_bytes, internal_bytes, flows) VALUES (?, ?, ?, ?, ?)
                       ON DUPLICATE KEY UPDATE down_bytes = down_bytes + VALUES(down_bytes), up_bytes = up_bytes + VALUES(up_bytes),
                         internal_bytes = internal_bytes + VALUES(internal_bytes), flows = flows + VALUES(flows)')
            ->execute([$ts, $t['down'], $t['up'], $t['internal'], $t['flows']]);
        foreach (array_chunk($d['hosts'], 300, true) as $chunk) {
            $vals = [];
            foreach ($chunk as $ip => $h) array_push($vals, $ts, $ip, $h[0], $h[1], $h[4] ?? 0, $h[5] ?? 0);
            $pdo->prepare('INSERT INTO flow_hosts (ts, ip, bytes_in, bytes_out, inet_in, inet_out) VALUES ' . implode(',', array_fill(0, count($chunk), '(?, ?, ?, ?, ?, ?)'))
                . ' ON DUPLICATE KEY UPDATE bytes_in = bytes_in + VALUES(bytes_in), bytes_out = bytes_out + VALUES(bytes_out),
                    inet_in = inet_in + VALUES(inet_in), inet_out = inet_out + VALUES(inet_out)')->execute($vals);
        }
        foreach (array_chunk($d['conv'], 300) as $chunk) {
            $pdo->prepare('INSERT INTO flow_conv (ts, local_ip, remote_ip, proto, port, bytes_in, bytes_out) VALUES '
                . implode(',', array_fill(0, count($chunk), '(?, ?, ?, ?, ?, ?, ?)')))
                ->execute(array_merge(...array_map(fn($c) => [$ts, ...$c], $chunk)));
        }
        foreach (array_chunk($d['services'], 300) as $chunk) {
            $pdo->prepare('INSERT INTO flow_services (ts, proto, port, bytes_in, bytes_out) VALUES ' . implode(',', array_fill(0, count($chunk), '(?, ?, ?, ?, ?)'))
                . ' ON DUPLICATE KEY UPDATE bytes_in = bytes_in + VALUES(bytes_in), bytes_out = bytes_out + VALUES(bytes_out)')
                ->execute(array_merge(...array_map(fn($s) => [$ts, ...$s], $chunk)));
        }
        if ($ifTables) {
            // Per exporter interface (newer collectors only).
            foreach (array_chunk($d['ifaces'] ?? [], 300) as $chunk) {
                $pdo->prepare('INSERT INTO flow_ifaces (ts, exporter, if_index, dir, bytes, packets, flows) VALUES ' . implode(',', array_fill(0, count($chunk), '(?, ?, ?, ?, ?, ?, ?)'))
                    . ' ON DUPLICATE KEY UPDATE bytes = bytes + VALUES(bytes), packets = packets + VALUES(packets), flows = flows + VALUES(flows)')
                    ->execute(array_merge(...array_map(fn($f) => [$ts, ...$f], $chunk)));
            }
            foreach (array_chunk($d['ifconv'] ?? [], 300) as $chunk) {
                $pdo->prepare('INSERT INTO flow_iface_conv (ts, exporter, if_index, src_ip, dst_ip, proto, port, bytes) VALUES '
                    . implode(',', array_fill(0, count($chunk), '(?, ?, ?, ?, ?, ?, ?, ?)')))
                    ->execute(array_merge(...array_map(fn($c) => [$ts, ...$c], $chunk)));
            }
        }
        $pdo->commit();
        // Monitored hosts: into their history graphs (bytes per second over the minute).
        foreach ($d['hosts'] as $ip => [$in, $out]) {
            if (isset($hostIds[$ip])) {
                record_points($hostIds[$ip], [['flow_in', '', 'bit/s', round($in / 60, 1)], ['flow_out', '', 'bit/s', round($out / 60, 1)]], $ts);
            }
        }
        @unlink($file);
    }
    $cut = time() - FLOW_KEEP_DAYS * 86400;
    if (date('i') === '07') {   // once an hour is plenty
        foreach (['flow_totals', 'flow_hosts', 'flow_services'] as $tbl) $pdo->prepare("DELETE FROM $tbl WHERE ts < ?")->execute([$cut]);
        $pdo->prepare('DELETE FROM flow_conv WHERE ts < ?')->execute([time() - FLOW_CONV_KEEP_DAYS * 86400]);
        if ($ifTables) {
            $pdo->prepare('DELETE FROM flow_ifaces WHERE ts < ?')->execute([$cut]);
            $pdo->prepare('DELETE FROM flow_iface_conv WHERE ts < ?')->execute([time() - FLOW_CONV_KEEP_DAYS * 86400]);
        }
    }
}

// Switches report a long transfer about every 60-90 s (the flow's active timeout plus cache scan
// drift), so short buckets alternate between full and empty; 5-minute buckets show the real rate.
const TRAFFIC_RANGES = ['15m' => [900, 60], '1h' => [3600, 300], '6h' => [21600, 300], '24h' => [86400, 900], '7d' => [604800, 3600]];

/** The Traffic report: totals over time, top devices, services and conversations. */
function traffic_report(string $range): array {
    [$span, $bucket] = TRAFFIC_RANGES[$range] ?? TRAFFIC_RANGES['1h'];
    $pdo = db();
    $from = intdiv(time() - $span, 60) * 60;
    $status = json_decode((string) $pdo->query("SELECT v FROM settings WHERE k = 'flow_status'")->fetchColumn(), true);

    $q = $pdo->prepare("SELECT ts - MOD(ts, $bucket) t, SUM(down_bytes) d, SUM(up_bytes) u, SUM(internal_bytes) i FROM flow_totals
                        WHERE ts >= ? GROUP BY t ORDER BY t");
    $q->execute([$from]);
    $series = array_map(fn($r) => [(int) $r['t'], round($r['d'] * 8 / $bucket), round($r['u'] * 8 / $bucket), round($r['i'] * 8 / $bucket)], $q->fetchAll());

    // "Now": the last five complete minutes averaged, for the same reason.
    $last2 = $pdo->query('SELECT ts, down_bytes, up_bytes, internal_bytes FROM flow_totals ORDER BY ts DESC LIMIT 5')->fetchAll();
    $now = $last2 && (int) $last2[0]['ts'] >= time() - 300
        ? ['ts' => (int) $last2[0]['ts'],
           'down' => round(array_sum(array_column($last2, 'down_bytes')) * 8 / (60 * count($last2))),
           'up' => round(array_sum(array_column($last2, 'up_bytes')) * 8 / (60 * count($last2))),
           'internal' => round(array_sum(array_column($last2, 'internal_bytes')) * 8 / (60 * count($last2)))]
        : null;

    [$who, $names] = flow_name_resolver();

    $q = $pdo->prepare('SELECT ip, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_hosts WHERE ts >= ? GROUP BY ip ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 30');
    $q->execute([$from]);
    $hosts = array_map(fn($r) => $who($r['ip']) + ['in' => (int) $r['i'], 'out' => (int) $r['o']], $q->fetchAll());

    $q = $pdo->prepare('SELECT proto, port, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_services WHERE ts >= ? GROUP BY proto, port ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 20');
    $q->execute([$from]);
    $services = array_map(fn($r) => ['proto' => (int) $r['proto'], 'port' => (int) $r['port'], 'name' => flow_service_name((int) $r['proto'], (int) $r['port']),
                                     'in' => (int) $r['i'], 'out' => (int) $r['o']], $q->fetchAll());

    $q = $pdo->prepare("SELECT local_ip, remote_ip, proto, port, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_conv WHERE ts >= ?
                        AND remote_ip NOT LIKE '224.%' AND remote_ip NOT LIKE '239.%' AND remote_ip <> '255.255.255.255'
                        GROUP BY local_ip, remote_ip, proto, port ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 25");
    $q->execute([max($from, time() - FLOW_CONV_KEEP_DAYS * 86400)]);
    $conv = array_map(fn($r) => ['local' => $who($r['local_ip']), 'remote' => $r['remote_ip'], 'remoteLocal' => (bool) preg_match('/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/', $r['remote_ip']),
                                 'remoteName' => $names[$r['remote_ip']]['name'] ?? null, 'service' => flow_service_name((int) $r['proto'], (int) $r['port']),
                                 'in' => (int) $r['i'], 'out' => (int) $r['o']], $q->fetchAll());

    $totals = $pdo->prepare('SELECT SUM(down_bytes) d, SUM(up_bytes) u, SUM(internal_bytes) i FROM flow_totals WHERE ts >= ?');
    $totals->execute([$from]);
    $sum = $totals->fetch();
    return [
        'range' => $range, 'bucket' => $bucket, 'from' => $from, 'series' => $series, 'now' => $now,
        'totals' => ['down' => (int) $sum['d'], 'up' => (int) $sum['u'], 'internal' => (int) $sum['i']],
        'hosts' => $hosts, 'services' => $services, 'conversations' => $conv,
        // The status file is copied in once a minute by cron, so allow a few minutes before calling it stopped.
        'collector' => $status ? ['running' => isset($status['at']) && $status['at'] >= time() - 240, 'lastPacket' => $status['lastPacket'] ?? null,
                                  'exporters' => array_keys($status['exporters'] ?? []), 'records' => $status['records'] ?? 0,
                                  'noTemplate' => $status['noTemplate'] ?? 0, 'port' => $status['port'] ?? 2055] : null,
        'serverIp' => $_SERVER['SERVER_ADDR'] ?? null,
    ];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/history.php")"
cat > "$APP_DIR/includes/history.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';

/**
 * History for graphs: per-minute points (8 days) rolled into hourly
 * avg/min/max (400 days). A series is (host, metric, subject), e.g.
 * (7, 'disk', '/'), (5, 'temp_disk', 'HDD3'), (11, 'net_rx', 'ens18').
 *
 * Writers: store_agent_metrics() (every agent report), record_ping_points()
 * and the NAS poll. cli/cron.php runs rollup_history() every minute (it only
 * does work once per hour).
 */

const HISTORY_RAW_DAYS = 8;
const HISTORY_HOURLY_DAYS = 400;
// Ranges the dashboard offers: [seconds, bucket seconds, source].
const HISTORY_RANGES = [
    '1h' => [3600, 60, 'raw'],
    '6h' => [6 * 3600, 60, 'raw'],
    '24h' => [86400, 300, 'raw'],
    '7d' => [7 * 86400, 1800, 'raw'],
    '30d' => [30 * 86400, 3 * 3600, 'hourly'],
    '90d' => [90 * 86400, 12 * 3600, 'hourly'],
    '1y' => [365 * 86400, 86400, 'hourly'],
];

/** Id of a series, created on first use (cached per request). */
function series_id(int $hostId, string $metric, string $subject, string $unit): int {
    static $cache = [];
    $subject = mb_substr($subject, 0, 120);
    $key = "$hostId|$metric|$subject";
    if (isset($cache[$key])) return $cache[$key];
    $pdo = db();
    $pdo->prepare('INSERT IGNORE INTO metric_series (host_id, metric, subject, unit) VALUES (?, ?, ?, ?)')
        ->execute([$hostId, $metric, $subject, $unit]);
    $stmt = $pdo->prepare('SELECT id FROM metric_series WHERE host_id = ? AND metric = ? AND subject = ?');
    $stmt->execute([$hostId, $metric, $subject]);
    return $cache[$key] = (int) $stmt->fetchColumn();
}

/**
 * Records points for one host at one time (rounded to the minute).
 * $points: [[metric, subject, unit, value], ...]; null values are skipped.
 */
function record_points(int $hostId, array $points, ?int $ts = null): void {
    $ts = intdiv($ts ?? time(), 60) * 60;
    $rows = [];
    foreach ($points as [$metric, $subject, $unit, $value]) {
        if ($value === null || !is_numeric($value) || !is_finite((float) $value)) continue;
        $rows[] = [series_id($hostId, $metric, (string) $subject, $unit), $ts, (float) $value];
    }
    if (!$rows) return;
    // INSERT IGNORE: a second report in the same minute keeps the first.
    db()->prepare('INSERT IGNORE INTO metric_points (series_id, ts, value) VALUES '
        . implode(',', array_fill(0, count($rows), '(?, ?, ?)')))
        ->execute(array_merge(...$rows));
}

/** Response time and availability of every host, from its latest check. Cron, every minute. */
function record_ping_points(): void {
    $cutoff = (int) round(microtime(true) * 1000) - 120000;
    $latest = db()->query("SELECT c.host_id, c.up, c.ms FROM checks c
        JOIN (SELECT host_id, MAX(ts) ts FROM checks GROUP BY host_id) m ON m.host_id = c.host_id AND m.ts = c.ts
        WHERE c.ts > $cutoff")->fetchAll();
    foreach ($latest as $c) {
        record_points((int) $c['host_id'], [
            ['up', '', '%', $c['up'] ? 100 : 0],
            ['ping_ms', '', 'ms', $c['up'] && $c['ms'] !== null ? (int) $c['ms'] : null],
        ]);
    }
}

/** Rolls finished hours into metric_hourly and purges old data. Cheap when there's nothing to do. */
function rollup_history(): void {
    $pdo = db();
    $done = (int) $pdo->query("SELECT v FROM settings WHERE k = 'history_rolled_until'")->fetchColumn();
    $thisHour = intdiv(time(), 3600) * 3600;
    if ($done >= $thisHour) return;
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_rollup', 0)")->fetchColumn()) return;
    try {
        $from = $done ?: (int) $pdo->query('SELECT COALESCE(MIN(ts), 0) FROM metric_points')->fetchColumn();
        $from = intdiv($from, 3600) * 3600;
        if ($from > 0 && $from < $thisHour) {
            $pdo->prepare('INSERT INTO metric_hourly (series_id, ts, avg_value, min_value, max_value, samples)
                           SELECT series_id, ts - MOD(ts, 3600), AVG(value), MIN(value), MAX(value), COUNT(*)
                           FROM metric_points WHERE ts >= ? AND ts < ?
                           GROUP BY series_id, ts - MOD(ts, 3600)
                           ON DUPLICATE KEY UPDATE avg_value = VALUES(avg_value), min_value = VALUES(min_value),
                             max_value = VALUES(max_value), samples = VALUES(samples)')
                ->execute([$from, $thisHour]);
        }
        $pdo->prepare("INSERT INTO settings (k, v) VALUES ('history_rolled_until', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")
            ->execute([(string) $thisHour]);
        $pdo->prepare('DELETE FROM metric_points WHERE ts < ?')->execute([time() - HISTORY_RAW_DAYS * 86400]);
        $pdo->prepare('DELETE FROM metric_hourly WHERE ts < ?')->execute([time() - HISTORY_HOURLY_DAYS * 86400]);
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_rollup')");
    }
}

/**
 * History of a host for a range: [[metric, subject, unit, points: [[ts, avg, min, max], ...]], ...].
 * Points are averaged into buckets so each line has a few hundred points at most.
 */
function query_history(int $hostId, string $range): array {
    [$span, $bucket, $source] = HISTORY_RANGES[$range] ?? HISTORY_RANGES['24h'];
    $pdo = db();
    // Per-port switch traffic has its own charts (Network tab, includes/netlive.php).
    $stmt = $pdo->prepare("SELECT id, metric, subject, unit FROM metric_series WHERE host_id = ? AND metric NOT IN ('port_in', 'port_out')");
    $stmt->execute([$hostId]);
    $series = [];
    foreach ($stmt->fetchAll() as $s) {
        $series[(int) $s['id']] = ['metric' => $s['metric'], 'subject' => $s['subject'], 'unit' => $s['unit'], 'points' => []];
    }
    if (!$series) return [];

    $from = time() - $span;
    $ids = implode(',', array_keys($series));
    $sql = $source === 'raw'
        ? "SELECT series_id, ts - MOD(ts, $bucket) AS t, AVG(value) a, MIN(value) mn, MAX(value) mx
           FROM metric_points WHERE series_id IN ($ids) AND ts >= ? GROUP BY series_id, t ORDER BY t"
        : "SELECT series_id, ts - MOD(ts, $bucket) AS t, SUM(avg_value * samples) / SUM(samples) a, MIN(min_value) mn, MAX(max_value) mx
           FROM metric_hourly WHERE series_id IN ($ids) AND ts >= ? GROUP BY series_id, t ORDER BY t";
    $q = $pdo->prepare($sql);
    $q->execute([$from]);
    foreach ($q->fetchAll(PDO::FETCH_NUM) as [$sid, $t, $a, $mn, $mx]) {
        $series[(int) $sid]['points'][] = [(int) $t, round((float) $a, 2), round((float) $mn, 2), round((float) $mx, 2)];
    }
    return array_values(array_filter($series, fn($s) => $s['points']));
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/homeassistant.php")"
cat > "$APP_DIR/includes/homeassistant.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/configbackup.php';   // encrypt_secret(), decrypt_secret()

/**
 * Home Assistant: what it knows about each device (the name you gave it, maker,
 * model, firmware, room, and what it does), read hourly over HA's WebSocket API
 * with a long-lived access token. Covers every brand HA is linked to (Tuya,
 * Google, Alexa, Hue, ...), so devices that answer no scan still get identified.
 *
 * settings 'homeassistant': {"url", "token_enc"}
 * settings 'ha_devices':    {"at", "error", "devices": [{name, maker, model, firmware, area, macs[], ips[], kinds[]}]}
 */

const HA_REFRESH_EVERY_SEC = 3600;
const HA_TIMEOUT_SEC = 20;
// Entity domains that say what a device is.
const HA_KIND_DOMAINS = ['camera', 'media_player', 'vacuum', 'climate', 'light', 'switch', 'fan', 'cover', 'lock', 'alarm_control_panel',
    'water_heater', 'humidifier', 'lawn_mower', 'remote', 'sensor', 'binary_sensor'];

function ha_config(): array {
    $c = json_decode((string) db()->query("SELECT v FROM settings WHERE k = 'homeassistant'")->fetchColumn(), true);
    return is_array($c) ? $c : [];
}

function ha_save_config(array $c): void {
    db()->prepare("INSERT INTO settings (k, v) VALUES ('homeassistant', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")->execute([json_encode($c)]);
}

/** "http://192.168.40.7:8123" (scheme, host, optional port; no path) or null. */
function ha_normalize_url(string $url): ?string {
    $url = rtrim(trim($url), '/');
    $p = parse_url($url);
    if (!$p || !in_array($p['scheme'] ?? '', ['http', 'https'], true) || empty($p['host'])) return null;
    if (isset($p['user']) || isset($p['pass']) || isset($p['query']) || isset($p['fragment']) || (($p['path'] ?? '') !== '')) return null;
    if (!preg_match('/^[A-Za-z0-9.\-]+$|^\[[0-9a-fA-F:]+\]$/', $p['host'])) return null;
    return $p['scheme'] . '://' . $p['host'] . (isset($p['port']) ? ':' . (int) $p['port'] : '');
}

/**
 * Minimal WebSocket client for HA: authenticates, sends each request (given an
 * id) and returns [id => result]. Throws RuntimeException with a readable message.
 */
function ha_ws_requests(string $url, string $token, array $requests): array {
    $p = parse_url($url);
    $tls = $p['scheme'] === 'https';
    $host = $p['host'];
    $port = (int) ($p['port'] ?? ($tls ? 443 : 80));
    $ctx = stream_context_create(['ssl' => ['verify_peer' => false, 'verify_peer_name' => false, 'SNI_enabled' => true, 'peer_name' => trim($host, '[]')]]);
    $s = @stream_socket_client(($tls ? 'ssl' : 'tcp') . "://$host:$port", $errno, $err, 5, STREAM_CLIENT_CONNECT, $ctx);
    if (!$s) throw new RuntimeException("cannot connect to $host:$port ($err)");
    $deadline = microtime(true) + HA_TIMEOUT_SEC;
    $buf = '';
    $read = function (int $n) use ($s, &$buf, $deadline): string {
        while (strlen($buf) < $n) {
            if (microtime(true) > $deadline) throw new RuntimeException('Home Assistant took too long to answer');
            stream_set_timeout($s, max(1, (int) ceil($deadline - microtime(true))));
            $chunk = fread($s, 65536);
            if ($chunk === false || ($chunk === '' && feof($s))) throw new RuntimeException('Home Assistant closed the connection');
            $buf .= $chunk;
        }
        $out = substr($buf, 0, $n);
        $buf = (string) substr($buf, $n);
        return $out;
    };
    $send = function (int $opcode, string $payload) use ($s): void {
        $len = strlen($payload);
        $head = chr(0x80 | $opcode) . ($len < 126 ? chr(0x80 | $len) : ($len < 65536 ? chr(0x80 | 126) . pack('n', $len) : chr(0x80 | 127) . pack('J', $len)));
        $mask = random_bytes(4);
        fwrite($s, $head . $mask . ($payload ^ str_repeat($mask, intdiv($len, 4) + 1)));
    };
    // One whole message (joins fragments, answers pings).
    $recv = function () use ($read, $send): array {
        $msg = '';
        while (true) {
            [$b0, $b1] = array_values(unpack('C2', $read(2)));
            $op = $b0 & 0x0F;
            $len = $b1 & 0x7F;
            if ($len === 126) $len = unpack('n', $read(2))[1];
            elseif ($len === 127) $len = unpack('J', $read(8))[1];
            if ($len > 50 * 1024 * 1024) throw new RuntimeException('Home Assistant sent an oversized message');
            $mask = ($b1 & 0x80) ? $read(4) : null;
            $data = $len ? $read($len) : '';
            if ($mask) $data ^= str_repeat($mask, intdiv($len, 4) + 1);
            if ($op === 0x8) throw new RuntimeException('Home Assistant closed the connection');
            if ($op === 0x9) { $send(0xA, $data); continue; }
            if ($op === 0xA) continue;
            $msg .= $data;
            if ($b0 & 0x80) break;
        }
        $j = json_decode($msg, true);
        if (!is_array($j)) throw new RuntimeException('Home Assistant sent something that is not JSON');
        return $j;
    };

    try {
        $key = base64_encode(random_bytes(16));
        $hostHeader = $host . ((!$tls && $port !== 80) || ($tls && $port !== 443) ? ":$port" : '');
        fwrite($s, "GET /api/websocket HTTP/1.1\r\nHost: $hostHeader\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
            . "Sec-WebSocket-Key: $key\r\nSec-WebSocket-Version: 13\r\nUser-Agent: WebMonitor\r\n\r\n");
        $raw = '';
        while (!str_contains($raw, "\r\n\r\n")) {
            $raw .= $read(1);
            if (strlen($raw) > 16384) throw new RuntimeException('not a Home Assistant WebSocket endpoint');
        }
        [$headers, $rest] = explode("\r\n\r\n", $raw, 2);
        $buf = $rest . $buf;
        if (!preg_match('#^HTTP/1\.[01] 101#', $headers)) {
            throw new RuntimeException('not a Home Assistant WebSocket endpoint (' . strtok($headers, "\r\n") . ')');
        }
        if (($recv()['type'] ?? '') !== 'auth_required') throw new RuntimeException('unexpected greeting from Home Assistant');
        $send(0x1, json_encode(['type' => 'auth', 'access_token' => $token]));
        $auth = $recv();
        if (($auth['type'] ?? '') !== 'auth_ok') throw new RuntimeException('Home Assistant refused the access token');
        foreach ($requests as $id => $req) $send(0x1, json_encode(['id' => $id] + $req));
        $results = [];
        while (count($results) < count($requests)) {
            $m = $recv();
            if (($m['type'] ?? '') !== 'result' || !isset($requests[$m['id'] ?? null])) continue;
            if (empty($m['success'])) throw new RuntimeException('Home Assistant: ' . ($m['error']['message'] ?? 'request failed'));
            $results[$m['id']] = $m['result'];
        }
        $send(0x8, '');
        return $results;
    } finally {
        fclose($s);
    }
}

/** HA's registries -> WebMonitor's device list. Pure (tested in deploy/test-device-identity.php). */
function ha_build_devices(array $devices, array $areas, array $entities, array $states): array {
    $areaName = array_column($areas, 'name', 'area_id');
    $stateBy = [];
    $stateVal = [];
    foreach ($states as $st) {
        $stateBy[$st['entity_id'] ?? ''] = $st['attributes'] ?? [];
        $stateVal[$st['entity_id'] ?? ''] = (string) ($st['state'] ?? '');
    }
    $kinds = $ips = $entityArea = [];
    foreach ($entities as $e) {
        $dev = $e['device_id'] ?? null;
        if (!$dev || !empty($e['disabled_by'])) continue;
        $domain = strtok((string) ($e['entity_id'] ?? ''), '.');
        if (in_array($domain, HA_KIND_DOMAINS, true)) $kinds[$dev][$domain] = true;
        foreach (['ip_address', 'ip', 'host', 'ipv4_address'] as $k) {
            $v = $stateBy[$e['entity_id']][$k] ?? null;
            if (is_string($v) && filter_var($v, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) $ips[$dev][$v] = true;
        }
        // A sensor whose state is the device's IP (e.g. "sensor.plug_ip").
        $val = $stateVal[$e['entity_id']] ?? '';
        if ($domain === 'sensor' && preg_match('/_ip(_address)?$/', (string) $e['entity_id']) && filter_var($val, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
            $ips[$dev][$val] = true;
        }
        if (!empty($e['area_id'])) $entityArea[$dev] ??= $e['area_id'];
    }
    $out = [];
    foreach ($devices as $d) {
        if (!empty($d['disabled_by']) || ($d['entry_type'] ?? null) === 'service') continue;
        $id = (string) ($d['id'] ?? '');
        $macs = [];
        foreach ((array) ($d['connections'] ?? []) as $c) {
            if (is_array($c) && ($c[0] ?? '') === 'mac' && ($m = normalize_mac((string) ($c[1] ?? '')))) $macs[] = $m;
        }
        $devIps = array_keys($ips[$id] ?? []);
        if (!empty($d['configuration_url']) && ($h = parse_url((string) $d['configuration_url'], PHP_URL_HOST)) && filter_var($h, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
            $devIps[] = $h;
        }
        $name = trim((string) ($d['name_by_user'] ?? '')) ?: trim((string) ($d['name'] ?? ''));
        if ($name === '') continue;
        $area = $d['area_id'] ?? $entityArea[$id] ?? null;
        $out[] = array_filter([
            'name' => mb_substr($name, 0, 80), 'userNamed' => !empty($d['name_by_user']),
            'maker' => $d['manufacturer'] ?? null, 'model' => $d['model'] ?? null, 'firmware' => $d['sw_version'] ?? null,
            'area' => $area ? ($areaName[$area] ?? null) : null,
            'macs' => array_values(array_unique($macs)), 'ips' => array_values(array_unique($devIps)),
            'kinds' => array_keys($kinds[$id] ?? []),
        ], fn($v) => $v !== null && $v !== '' && $v !== []);
    }
    return $out;
}

/** Hourly from cli/poll-snmp.php ($force: now, from Settings). Returns the error or null. */
function refresh_ha_devices(bool $force = false): ?string {
    require_once __DIR__ . '/portmap.php';   // normalize_mac()
    $cfg = ha_config();
    $token = decrypt_secret($cfg['token_enc'] ?? null);
    if (empty($cfg['url']) || $token === null) return null;
    $stored = ha_devices_stored();
    if (!$force && (int) ($stored['at'] ?? 0) > now_ms_cfg() - HA_REFRESH_EVERY_SEC * 1000) return $stored['error'] ?? null;
    $error = null;
    try {
        $r = ha_ws_requests($cfg['url'], $token, [
            1 => ['type' => 'config/device_registry/list'], 2 => ['type' => 'config/area_registry/list'],
            3 => ['type' => 'config/entity_registry/list'], 4 => ['type' => 'get_states'],
        ]);
        $devices = ha_build_devices((array) $r[1], (array) $r[2], (array) $r[3], (array) $r[4]);
    } catch (Throwable $e) {
        $error = $e->getMessage();
        $devices = $stored['devices'] ?? [];   // keep the last good list
    }
    db()->prepare("INSERT INTO settings (k, v) VALUES ('ha_devices', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")
        ->execute([json_encode(['at' => now_ms_cfg(), 'error' => $error, 'devices' => $devices])]);
    return $error;
}

function ha_devices_stored(): array {
    $d = json_decode((string) db()->query("SELECT v FROM settings WHERE k = 'ha_devices'")->fetchColumn(), true);
    return is_array($d) ? $d : [];
}

/** Lookups for device_inventory(): [byMac, byIp, byName (lower-case, unique names only), all]; each device has its index as _i. */
function ha_device_index(): array {
    $byMac = $byIp = $byName = $dupe = $all = [];
    foreach (ha_devices_stored()['devices'] ?? [] as $i => $d) {
        $d['_i'] = $i;
        $all[] = $d;
        foreach ($d['macs'] ?? [] as $m) $byMac[$m] = $d;
        foreach ($d['ips'] ?? [] as $ip) $byIp[$ip] = $d;
        $n = mb_strtolower($d['name']);
        if (isset($byName[$n])) $dupe[$n] = true;
        $byName[$n] = $d;
    }
    return [$byMac, $byIp, array_diff_key($byName, $dupe), $all];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/hostdetails.php")"
cat > "$APP_DIR/includes/hostdetails.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/nas.php';
require_once __DIR__ . '/history.php';

/**
 * Server details over SNMP v2c: system info (SNMPv2-MIB), resources
 * (HOST-RESOURCES-MIB, plus UCD-SNMP load average on net-snmp agents) and
 * IP-bearing interfaces (IF-MIB + IP-MIB). Every section is optional — many
 * agents only expose some of these, so missing data is simply left out.
 *
 * Uses the php-snmp extension's SNMP class (installed by rocky-install.sh).
 */

const OID_SYS_DESCR_0 = '.1.3.6.1.2.1.1.1.0';
const OID_SYS_OBJECT_ID_0 = '.1.3.6.1.2.1.1.2.0';
const OID_SYS_UPTIME_0 = '.1.3.6.1.2.1.1.3.0';       // agent uptime, timeticks
const OID_SYS_CONTACT_0 = '.1.3.6.1.2.1.1.4.0';
const OID_SYS_NAME_0 = '.1.3.6.1.2.1.1.5.0';
const OID_SYS_LOCATION_0 = '.1.3.6.1.2.1.1.6.0';

const OID_HR_SYSTEM_UPTIME_0 = '.1.3.6.1.2.1.25.1.1.0'; // OS uptime, timeticks
const OID_HR_NUM_USERS_0 = '.1.3.6.1.2.1.25.1.5.0';
const OID_HR_PROCESSES_0 = '.1.3.6.1.2.1.25.1.6.0';
const OID_HR_MEMORY_SIZE_0 = '.1.3.6.1.2.1.25.2.2.0';   // KB
const OID_HR_STORAGE_ENTRY = '.1.3.6.1.2.1.25.2.3.1';   // .col.index
const OID_HR_PROCESSOR_LOAD = '.1.3.6.1.2.1.25.3.3.1.2';
const OID_UCD_LOAD_AVG = '.1.3.6.1.4.1.2021.10.1.3';   // .1/.2/.3 = 1/5/15 min

const OID_IP_AD_ENT_IF_INDEX = '.1.3.6.1.2.1.4.20.1.2'; // indexed by IP
const OID_IP_AD_ENT_NETMASK = '.1.3.6.1.2.1.4.20.1.3';
const OID_IF_DESCR_COL = '.1.3.6.1.2.1.2.2.1.2';
const OID_IF_PHYS_ADDR_COL = '.1.3.6.1.2.1.2.2.1.6';
const OID_IF_OPER_STATUS_COL = '.1.3.6.1.2.1.2.2.1.8';
const OID_IF_NAME_COL = '.1.3.6.1.2.1.31.1.1.1.1';
const OID_IF_HIGH_SPEED_COL = '.1.3.6.1.2.1.31.1.1.1.15'; // Mbps

const OID_NET_SNMP_PREFIX = '.1.3.6.1.4.1.8072.';

// Cisco devices don't implement HOST-RESOURCES-MIB; these fill CPU/memory in.
const OID_CISCO_PREFIX = '.1.3.6.1.4.1.9.';
const OID_CISCO_CPU_1MIN = '.1.3.6.1.4.1.9.9.109.1.1.1.1.7';     // cpmCPUTotal1minRev, % per CPU
const OID_CISCO_MEM_POOL_NAME = '.1.3.6.1.4.1.9.9.48.1.1.1.2';   // ciscoMemoryPoolName
const OID_CISCO_MEM_POOL_USED = '.1.3.6.1.4.1.9.9.48.1.1.1.5';   // bytes
const OID_CISCO_MEM_POOL_FREE = '.1.3.6.1.4.1.9.9.48.1.1.1.6';   // bytes

// hrStorageType values worth showing; buffers/caches ("other") are skipped.
const HR_STORAGE_TYPES = [
    '.1.3.6.1.2.1.25.2.1.2' => 'ram',
    '.1.3.6.1.2.1.25.2.1.3' => 'virtual',
    '.1.3.6.1.2.1.25.2.1.4' => 'disk',
    '.1.3.6.1.2.1.25.2.1.10' => 'network',
];

function host_details_available(): bool {
    return class_exists('SNMP');
}

function snmp_session(string $ip, string $community, float $timeoutSec): SNMP {
    $s = new SNMP(SNMP::VERSION_2c, $ip, $community, (int) round($timeoutSec * 1_000_000), 1);
    $s->valueretrieval = SNMP_VALUE_PLAIN;
    $s->oid_output_format = SNMP_OID_OUTPUT_NUMERIC;
    $s->quick_print = true;
    $s->exceptions_enabled = 0;
    return $s;
}

/** GET several scalars; OIDs the agent doesn't have are simply absent. */
function snmp_get_many(SNMP $s, array $oids): array {
    $r = @$s->get($oids);
    if (!is_array($r)) return [];
    return array_map(fn($v) => is_string($v) ? trim($v, " \t\"") : $v, $r);
}

/** Walks a subtree, returning [suffix => value]; [] if unsupported. */
function snmp_walk_suffix(SNMP $s, string $oid): array {
    $r = @$s->walk($oid, true);
    if (!is_array($r)) return [];
    $out = [];
    foreach ($r as $k => $v) {
        if ($v === false || $v === null) continue;
        $out[(string) $k] = is_string($v) ? trim($v, " \t\"") : $v;
    }
    return $out;
}

function int_or_null($v): ?int {
    return is_numeric($v) ? (int) $v : null;
}

function str_or_null($v): ?string {
    return is_string($v) && $v !== '' ? $v : null;
}

function format_mac(string $raw): ?string {
    if ($raw === '') return null;
    // Plain retrieval returns the raw 6 bytes; some agents send hex text.
    $hex = strlen($raw) === 6 ? bin2hex($raw) : strtolower(preg_replace('/[^0-9a-fA-F]/', '', $raw));
    if (strlen($hex) !== 12 || $hex === '000000000000') return null;
    return implode(':', str_split($hex, 2));
}

/**
 * Collects server details over SNMP. Returns null if the host doesn't
 * answer SNMP at all (not enabled, wrong community, or firewalled).
 */
function collect_host_details(string $ip, string $community, float $timeoutSec = 1.5): ?array {
    $s = snmp_session($ip, $community, $timeoutSec);

    $sys = snmp_get_many($s, [
        OID_SYS_DESCR_0, OID_SYS_OBJECT_ID_0, OID_SYS_UPTIME_0,
        OID_SYS_CONTACT_0, OID_SYS_NAME_0, OID_SYS_LOCATION_0,
    ]);
    if (!$sys) return null;

    $hr = snmp_get_many($s, [
        OID_HR_SYSTEM_UPTIME_0, OID_HR_NUM_USERS_0, OID_HR_PROCESSES_0, OID_HR_MEMORY_SIZE_0,
        OID_UCD_LOAD_AVG . '.1', OID_UCD_LOAD_AVG . '.2', OID_UCD_LOAD_AVG . '.3',
    ]);

    // Prefer the OS uptime; sysUpTime is only how long the SNMP agent has run.
    $ticks = int_or_null($hr[OID_HR_SYSTEM_UPTIME_0] ?? null) ?? int_or_null($sys[OID_SYS_UPTIME_0] ?? null);

    $load = [];
    foreach (['.1', '.2', '.3'] as $i) {
        $v = $hr[OID_UCD_LOAD_AVG . $i] ?? null;
        if (is_numeric($v)) $load[] = (float) $v;
    }

    $cpu = array_values(array_filter(
        array_map('int_or_null', snmp_walk_suffix($s, OID_HR_PROCESSOR_LOAD)),
        fn($v) => $v !== null
    ));

    // QNAPs list every mount in hrStorage (slow, and their volumes come
    // from QNAP's own tables instead), so skip the generic storage walk.
    // Detect with the patient session: a slow answer mustn't make a QNAP
    // look like a generic host (and trigger the slow storage walk).
    $qs = snmp_session($ip, $community, QNAP_TIMEOUT_SEC);
    $isQnap = is_qnap($qs);
    $storage = $isQnap ? [] : collect_storage($s);
    $objectId = (string) ($sys[OID_SYS_OBJECT_ID_0] ?? '');
    if (str_starts_with($objectId, OID_CISCO_PREFIX)) {
        if (!$cpu) {
            $cpu = array_values(array_filter(
                array_map('int_or_null', snmp_walk_suffix($s, OID_CISCO_CPU_1MIN)),
                fn($v) => $v !== null
            ));
        }
        if (!$storage) $storage = collect_cisco_memory($s);
    }

    return [
        'system' => [
            'name' => str_or_null($sys[OID_SYS_NAME_0] ?? null),
            'descr' => str_or_null($sys[OID_SYS_DESCR_0] ?? null),
            'objectId' => str_or_null($sys[OID_SYS_OBJECT_ID_0] ?? null),
            'contact' => str_or_null($sys[OID_SYS_CONTACT_0] ?? null),
            'location' => str_or_null($sys[OID_SYS_LOCATION_0] ?? null),
            'uptimeSec' => $ticks !== null ? intdiv($ticks, 100) : null,
        ],
        'resources' => [
            'users' => int_or_null($hr[OID_HR_NUM_USERS_0] ?? null),
            'processes' => int_or_null($hr[OID_HR_PROCESSES_0] ?? null),
            'memoryKb' => int_or_null($hr[OID_HR_MEMORY_SIZE_0] ?? null),
            'cpuLoad' => $cpu,
            'loadAvg' => count($load) === 3 ? $load : null,
        ],
        'storage' => $storage,
        'network' => collect_network($s),
        'nas' => $isQnap ? collect_qnap($qs, $sys, $cpu) : null,
        'netSnmp' => str_starts_with($objectId, OID_NET_SNMP_PREFIX),
    ];
}

function collect_storage(SNMP $s): array {
    $rows = [];
    foreach (snmp_walk_suffix($s, OID_HR_STORAGE_ENTRY) as $suffix => $v) {
        [$col, $idx] = array_pad(explode('.', $suffix, 2), 2, null);
        if ($idx !== null) $rows[$idx][(int) $col] = $v;
    }

    $storage = [];
    foreach ($rows as $r) {
        // Columns: 2=type, 3=descr, 4=allocation units (bytes), 5=size, 6=used.
        $type = HR_STORAGE_TYPES['.' . ltrim((string) ($r[2] ?? ''), '.')] ?? null;
        $units = int_or_null($r[4] ?? null);
        $size = int_or_null($r[5] ?? null);
        if ($type === null || !$units || !$size) continue;
        $storage[] = [
            'descr' => (string) ($r[3] ?? ''),
            'type' => $type,
            'sizeBytes' => $size * $units,
            'usedBytes' => (int) (int_or_null($r[6] ?? null) ?? 0) * $units,
        ];
    }
    return $storage;
}

/** Cisco memory pools (e.g. "Processor", "I/O") as RAM-type storage rows. */
function collect_cisco_memory(SNMP $s): array {
    $names = snmp_walk_suffix($s, OID_CISCO_MEM_POOL_NAME);
    if (!$names) return [];
    $used = snmp_walk_suffix($s, OID_CISCO_MEM_POOL_USED);
    $free = snmp_walk_suffix($s, OID_CISCO_MEM_POOL_FREE);

    $pools = [];
    foreach ($names as $idx => $name) {
        $u = int_or_null($used[$idx] ?? null);
        $f = int_or_null($free[$idx] ?? null);
        if ($u === null || $f === null || $u + $f === 0) continue;
        $pools[] = ['descr' => "$name memory", 'type' => 'ram', 'sizeBytes' => $u + $f, 'usedBytes' => $u];
    }
    return $pools;
}

function collect_network(SNMP $s): array {
    $ipToIf = snmp_walk_suffix($s, OID_IP_AD_ENT_IF_INDEX);
    if (!$ipToIf) return [];
    $masks = snmp_walk_suffix($s, OID_IP_AD_ENT_NETMASK);

    $ifIndexes = array_values(array_unique(array_filter(array_map('int_or_null', $ipToIf))));
    $oids = [];
    foreach ($ifIndexes as $i) {
        array_push($oids,
            OID_IF_NAME_COL . ".$i", OID_IF_DESCR_COL . ".$i", OID_IF_OPER_STATUS_COL . ".$i",
            OID_IF_PHYS_ADDR_COL . ".$i", OID_IF_HIGH_SPEED_COL . ".$i");
    }
    $info = [];
    foreach (array_chunk($oids, 40) as $chunk) $info += snmp_get_many($s, $chunk);

    $network = [];
    foreach ($ipToIf as $ip => $ifIndex) {
        $ifIndex = (int) $ifIndex;
        if (!filter_var($ip, FILTER_VALIDATE_IP) || str_starts_with($ip, '127.')) continue;
        $status = (string) ($info[OID_IF_OPER_STATUS_COL . ".$ifIndex"] ?? '');
        $speed = int_or_null($info[OID_IF_HIGH_SPEED_COL . ".$ifIndex"] ?? null);
        $network[] = [
            'ifIndex' => $ifIndex,
            'name' => str_or_null($info[OID_IF_NAME_COL . ".$ifIndex"] ?? null)
                ?? str_or_null($info[OID_IF_DESCR_COL . ".$ifIndex"] ?? null)
                ?? "if$ifIndex",
            'ip' => $ip,
            'mask' => str_or_null($masks[$ip] ?? null),
            'mac' => format_mac((string) ($info[OID_IF_PHYS_ADDR_COL . ".$ifIndex"] ?? '')),
            'status' => $status === '1' ? 'up' : ($status === '2' ? 'down' : 'unknown'),
            'speedMbps' => $speed ?: null,
        ];
    }
    usort($network, fn($a, $b) => ip2long($a['ip']) <=> ip2long($b['ip']));
    return $network;
}

/** Returns ['details' => array, 'collectedAt' => ms] or null if never collected. */
function load_host_details(int $hostId): ?array {
    $stmt = db()->prepare('SELECT data, collected_at FROM host_details WHERE host_id = ?');
    $stmt->execute([$hostId]);
    $row = $stmt->fetch();
    if (!$row) return null;
    return ['details' => json_decode($row['data'], true), 'collectedAt' => (int) $row['collected_at']];
}

function save_host_details(int $hostId, array $details): int {
    $ts = (int) round(microtime(true) * 1000);
    db()->prepare(
        'INSERT INTO host_details (host_id, data, collected_at) VALUES (?, ?, ?)
         ON DUPLICATE KEY UPDATE data = VALUES(data), collected_at = VALUES(collected_at)'
    )->execute([$hostId, json_encode($details), $ts]);
    adopt_host_name($hostId, $details['system']['name'] ?? null);
    return $ts;
}

const SNMP_POLL_SEC = 240;   // polled by webmonitor-snmp.timer every 5 min

/**
 * Re-collects SNMP details for NAS hosts every SNMP_POLL_SEC, so their
 * health is monitored (and alerted on) without anyone opening Details.
 * Called by cron every minute.
 */
function poll_snmp_devices(): void {
    if (!host_details_available()) return;
    $pdo = db();
    $due = $pdo->prepare("SELECT h.* FROM hosts h LEFT JOIN host_details d ON d.host_id = h.id
                          WHERE h.device = 'nas' AND (d.collected_at IS NULL OR d.collected_at < ?)");
    $due->execute([(int) round(microtime(true) * 1000) - SNMP_POLL_SEC * 1000]);
    foreach ($due->fetchAll() as $h) {
        $details = collect_host_details($h['ip_address'], $h['community'] !== '' ? $h['community'] : 'public');
        // A failed poll keeps the previous details; alerts treat them as
        // stale (and leave NAS alerts unchanged) after 20 minutes.
        if ($details !== null) {
            save_host_details((int) $h['id'], $details);
            if (!empty($details['nas'])) record_points((int) $h['id'], nas_history_points($details['nas']));
        } else fwrite(STDERR, date('c') . " no SNMP response from {$h['name']} ({$h['ip_address']})\n");
    }
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/jobs.php")"
cat > "$APP_DIR/includes/jobs.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/agents.php';

/**
 * Jobs: actions that agents run on their hosts (Phase 3: updates).
 *
 * Only these types exist, and each agent implements them itself; the
 * server sends a type plus a couple of booleans, never commands.
 *   refresh        check for updates now (apt-get update / dnf makecache /
 *                  online Windows Update scan), then send a fresh inventory
 *   updates        install updates; params: security_only, reboot (if needed)
 *   reboot         reboot the host
 *   agent_upgrade  download the current agent from this server and restart
 *   service_restart restart one watched service; params: service (agents only
 *                  restart services they've been told to watch)
 *
 * Agents ask for work (POST api/agent.php?action=jobs) and stream progress
 * back (action=job_update). Hosts are muted while a job runs, and briefly
 * after a reboot, so planned work doesn't raise alerts.
 */

const JOB_TYPES = ['refresh', 'updates', 'reboot', 'agent_upgrade', 'service_restart'];
const JOB_MIN_AGENT_VERSION = '0.3.0';
const JOB_OUTPUT_MAX = 65536;            // keep the last 64 KB of output
const JOB_QUEUED_TTL_SEC = 24 * 3600;    // never picked up -> expired
const JOB_STALL_SEC = 60 * 60;           // running but silent -> failed
const JOB_REBOOT_MUTE_MIN = 20;

function job_params(string $type, array $in): array {
    if ($type === 'updates') {
        return ['security_only' => !empty($in['security_only']), 'reboot' => !empty($in['reboot'])];
    }
    if ($type === 'service_restart') {
        $name = (string) ($in['service'] ?? '');
        return preg_match('/^[A-Za-z0-9@._:\-+ ]{1,120}$/', $name) ? ['service' => $name] : [];
    }
    return [];
}

function job_label(string $type, array $params): string {
    switch ($type) {
        case 'refresh': return 'Check for updates';
        case 'reboot': return 'Reboot';
        case 'agent_upgrade': return 'Upgrade agent';
        case 'service_restart': return 'Restart ' . ($params['service'] ?? 'service');
        case 'updates':
            return (!empty($params['security_only']) ? 'Install security updates' : 'Install all updates')
                . (!empty($params['reboot']) ? ', reboot if needed' : '');
    }
    return $type;
}

function job_row(array $j, bool $withOutput = false): array {
    $params = json_decode((string) $j['params'], true) ?: [];
    $row = [
        'id' => (int) $j['id'],
        'hostId' => (int) $j['host_id'],
        'hostName' => $j['host_name'] ?? null,
        'hostIp' => $j['ip_address'] ?? null,
        'type' => $j['type'],
        'params' => $params,
        'label' => job_label($j['type'], $params),
        'status' => $j['status'],
        'createdBy' => $j['username'] ?? null,
        'scheduleName' => $j['schedule_name'] ?? null,
        'createdAt' => (int) $j['created_at'],
        'startedAt' => $j['started_at'] !== null ? (int) $j['started_at'] : null,
        'updatedAt' => $j['updated_at'] !== null ? (int) $j['updated_at'] : null,
        'finishedAt' => $j['finished_at'] !== null ? (int) $j['finished_at'] : null,
        'exitCode' => $j['exit_code'] !== null ? (int) $j['exit_code'] : null,
        'summary' => $j['summary'],
        'hasOutput' => ($j['output'] ?? '') !== '',
    ];
    if ($withOutput) $row['output'] = (string) $j['output'];
    return $row;
}

const JOB_SELECT = 'SELECT j.*, h.name AS host_name, h.ip_address, u.username, s.name AS schedule_name
                    FROM jobs j JOIN hosts h ON h.id = j.host_id LEFT JOIN users u ON u.id = j.created_by
                    LEFT JOIN update_schedules s ON s.id = j.schedule_id';

/**
 * Queues a job on each host. Returns ['created' => [jobId...],
 * 'skipped' => [['hostId', 'host', 'reason']...]]. Jobs started by a
 * schedule ($scheduleId) skip hosts a person has muted for maintenance.
 */
function create_jobs(array $hostIds, string $type, array $params, ?int $userId, ?int $scheduleId = null): array {
    $pdo = db();
    $created = [];
    $skipped = [];
    $params = job_params($type, $params);
    $agents = agent_summaries();
    foreach (array_unique(array_map('intval', $hostIds)) as $hid) {
        $stmt = $pdo->prepare('SELECT id, name, ip_address, muted_until, mute_reason FROM hosts WHERE id = ?');
        $stmt->execute([$hid]);
        $h = $stmt->fetch();
        if (!$h) continue;
        $label = $h['name'] === $h['ip_address'] ? $h['ip_address'] : $h['name'];
        if ($scheduleId !== null && (int) $h['muted_until'] > now_ms()
            && !str_starts_with((string) $h['mute_reason'], JOB_MUTE_PREFIX)) {
            $skipped[] = ['hostId' => $hid, 'host' => $label,
                          'reason' => 'muted for maintenance' . ($h['mute_reason'] ? " ({$h['mute_reason']})" : '')];
            continue;
        }
        $a = $agents[$hid] ?? null;
        if (!$a) {
            $skipped[] = ['hostId' => $hid, 'host' => $label, 'reason' => 'no agent installed'];
            continue;
        }
        if (!$a['version'] || version_compare($a['version'], JOB_MIN_AGENT_VERSION, '<')) {
            $skipped[] = ['hostId' => $hid, 'host' => $label,
                          'reason' => "agent {$a['version']} is too old for jobs — reinstall it once (Details → Agent → Reinstall)"];
            continue;
        }
        $busy = $pdo->prepare("SELECT id FROM jobs WHERE host_id = ? AND status IN ('queued', 'running') LIMIT 1");
        $busy->execute([$hid]);
        if ($busy->fetchColumn()) {
            $skipped[] = ['hostId' => $hid, 'host' => $label, 'reason' => 'another job is already queued or running'];
            continue;
        }
        $pdo->prepare('INSERT INTO jobs (host_id, type, params, created_by, schedule_id, created_at) VALUES (?, ?, ?, ?, ?, ?)')
            ->execute([$hid, $type, json_encode($params), $userId, $scheduleId, now_ms()]);
        $created[] = (int) $pdo->lastInsertId();
    }
    return ['created' => $created, 'skipped' => $skipped];
}

/** For an agent asking for work: the oldest queued job, now marked running. */
function next_job_for_host(int $hostId): ?array {
    $pdo = db();
    $pdo->beginTransaction();
    try {
        $stmt = $pdo->prepare("SELECT * FROM jobs WHERE host_id = ? AND status = 'queued' ORDER BY id LIMIT 1 FOR UPDATE");
        $stmt->execute([$hostId]);
        $job = $stmt->fetch();
        if (!$job) {
            $pdo->commit();
            return null;
        }
        $now = now_ms();
        $pdo->prepare("UPDATE jobs SET status = 'running', started_at = ?, updated_at = ? WHERE id = ?")
            ->execute([$now, $now, $job['id']]);
        $pdo->commit();
    } catch (Throwable $e) {
        $pdo->rollBack();
        throw $e;
    }
    $params = json_decode($job['params'], true) ?: [];
    if ($job['type'] === 'reboot' || $job['type'] === 'updates') {
        // Updates restart services; reboots take the host down. Mute until
        // the job finishes (extended after a reboot, see finish).
        job_mute($hostId, (int) $job['id'], $job['type'] === 'reboot' ? JOB_REBOOT_MUTE_MIN : 180,
                 job_label($job['type'], $params));
    }
    return ['id' => (int) $job['id'], 'type' => $job['type'], 'params' => $params];
}

/**
 * Progress from the agent. $status: running | succeeded | failed.
 * Output chunks are appended (the last JOB_OUTPUT_MAX bytes are kept).
 * $rebooting: the agent is about to reboot the host.
 */
function update_job(int $hostId, int $jobId, string $status, string $chunk, ?int $exitCode, ?string $summary, bool $rebooting): bool {
    $pdo = db();
    $stmt = $pdo->prepare("SELECT * FROM jobs WHERE id = ? AND host_id = ? AND status = 'running'");
    $stmt->execute([$jobId, $hostId]);
    $job = $stmt->fetch();
    if (!$job || !in_array($status, ['running', 'succeeded', 'failed'], true)) return false;

    $output = (string) $job['output'] . $chunk;
    if (strlen($output) > JOB_OUTPUT_MAX) $output = "[…earlier output trimmed…]\n" . substr($output, -JOB_OUTPUT_MAX);
    $now = now_ms();
    $final = $status !== 'running';
    $pdo->prepare('UPDATE jobs SET status = ?, output = ?, updated_at = ?, finished_at = ?, exit_code = COALESCE(?, exit_code),
                   summary = COALESCE(?, summary) WHERE id = ?')
        ->execute([$status, $output, $now, $final ? $now : null, $exitCode,
                   $summary !== null ? mb_substr($summary, 0, 500) : null, $jobId]);
    if ($final) job_unmute($hostId, $jobId, $rebooting || $job['type'] === 'reboot');
    return true;
}

const JOB_MUTE_PREFIX = 'Job #';

/** Mutes the host for a job, unless a person muted it for longer. */
function job_mute(int $hostId, int $jobId, int $minutes, string $label): void {
    $until = now_ms() + $minutes * 60000;
    db()->prepare('UPDATE hosts SET muted_until = ?, mute_reason = ?
                   WHERE id = ? AND (muted_until IS NULL OR muted_until < ? OR mute_reason LIKE ?)')
        ->execute([$until, mb_substr(JOB_MUTE_PREFIX . "$jobId: $label", 0, 120), $hostId, $until, JOB_MUTE_PREFIX . '%']);
}

/** Ends a job's mute; after a reboot keeps it a while so the host can come back. */
function job_unmute(int $hostId, int $jobId, bool $rebooting): void {
    db()->prepare('UPDATE hosts SET muted_until = ?, mute_reason = IF(? IS NULL, NULL, mute_reason)
                   WHERE id = ? AND mute_reason LIKE ?')
        ->execute([$rebooting ? now_ms() + JOB_REBOOT_MUTE_MIN * 60000 : null,
                   $rebooting ? 1 : null, $hostId, JOB_MUTE_PREFIX . $jobId . ':%']);
}

/** Expires never-collected jobs and fails jobs whose agent went silent. Run by cron. */
function job_housekeeping(): void {
    $pdo = db();
    $now = now_ms();
    $pdo->prepare("UPDATE jobs SET status = 'expired', finished_at = ?, summary = 'Not picked up by the agent within 24 hours'
                   WHERE status = 'queued' AND created_at < ?")
        ->execute([$now, $now - JOB_QUEUED_TTL_SEC * 1000]);
    $stale = $pdo->prepare("SELECT id, host_id FROM jobs WHERE status = 'running' AND COALESCE(updated_at, started_at) < ?");
    $stale->execute([$now - JOB_STALL_SEC * 1000]);
    foreach ($stale->fetchAll() as $j) {
        $pdo->prepare("UPDATE jobs SET status = 'failed', finished_at = ?,
                       summary = 'The agent stopped reporting progress for an hour' WHERE id = ?")
            ->execute([$now, $j['id']]);
        job_unmute((int) $j['host_id'], (int) $j['id'], false);
    }
    $pdo->prepare('DELETE FROM jobs WHERE finished_at IS NOT NULL AND finished_at < ?')->execute([$now - 180 * 86400000]);
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/nas.php")"
cat > "$APP_DIR/includes/nas.php" <<'WEBMON_FILE_EOF'
<?php
/**
 * QNAP NAS over SNMP (no agent: QTS has no systemd/Python and resets custom
 * services on reboot). Uses QNAP's NAS-MIB "Ex" tables (64-bit sizes,
 * numeric temperatures) and the newer QTS-MIB for model, serial, system
 * temperature and RAID levels.
 *
 * Enable SNMP on the NAS: Control Panel -> Network & File Services -> SNMP.
 */

const QNAP_MODEL = '.1.3.6.1.4.1.24681.1.4.1.1.1.1.1.2.1.3.1';   // answers fast: used to detect QNAPs
// QNAP's agent is slow on some tables (2+ s per request); give it time.
const QNAP_TIMEOUT_SEC = 5.0;
const QNAP_DISK_EX = '.1.3.6.1.4.1.24681.1.3.11.1';               // .col.idx
const QNAP_FAN_EX = '.1.3.6.1.4.1.24681.1.3.15.1';
const QNAP_VOLUME_EX = '.1.3.6.1.4.1.24681.1.3.17.1';
const QNAP_ENCLOSURE = '.1.3.6.1.4.1.24681.1.4.1.1.1.1.1.2.1';    // model, serial, name, temp
const QNAP_POOLS = '.1.3.6.1.4.1.24681.1.4.1.1.1.2.1.2.1';        // capacity, status, RAID level
const HR_STORAGE_DESCR = '.1.3.6.1.2.1.25.2.3.1.3';
const HR_STORAGE_UNITS = '.1.3.6.1.2.1.25.2.3.1.4';
const HR_STORAGE_SIZE = '.1.3.6.1.2.1.25.2.3.1.5';
const HR_STORAGE_USED = '.1.3.6.1.2.1.25.2.3.1.6';

// Alert thresholds for NAS hardware (°C).
const NAS_DISK_TEMP_WARN = 55;
const NAS_DISK_TEMP_CRIT = 60;
const NAS_SYSTEM_TEMP_WARN = 60;
const NAS_SYSTEM_TEMP_CRIT = 70;

/** [index => [col => value]] from a walk of TABLE.entry (suffixes "col.idx"). */
function snmp_table(SNMP $s, string $entryOid): array {
    $rows = [];
    foreach (snmp_walk_suffix($s, $entryOid) as $suffix => $v) {
        [$col, $idx] = array_pad(explode('.', (string) $suffix, 2), 2, null);
        if ($idx !== null) $rows[$idx][(int) $col] = $v;
    }
    ksort($rows, SORT_NATURAL);
    return $rows;
}

function is_qnap(SNMP $s): bool {
    return (bool) snmp_get_many($s, [QNAP_MODEL]);
}

/**
 * QNAP details. $s should use QNAP_TIMEOUT_SEC; $cpuLoad is the per-core
 * hrProcessorLoad list the generic collector already fetched.
 */
function collect_qnap(SNMP $s, array $sys, array $cpuLoad): array {
    $enc = snmp_table($s, QNAP_ENCLOSURE)['1'] ?? [];

    $disks = [];
    foreach (snmp_table($s, QNAP_DISK_EX) as $r) {
        // Columns: 2 name, 3 temp °C, 4 status (0 ready, -5 no disk), 5 model, 6 bytes, 7 SMART.
        $status = int_or_null($r[4] ?? null);
        if ($status === -5) continue;   // empty bay
        $disks[] = [
            'slot' => (string) ($r[2] ?? ''), 'model' => (string) ($r[5] ?? ''),
            'bytes' => int_or_null($r[6] ?? null), 'tempC' => int_or_null($r[3] ?? null) ?: null,
            'status' => $status, 'smart' => (string) ($r[7] ?? ''),
        ];
    }

    $fans = [];
    foreach (snmp_table($s, QNAP_FAN_EX) as $r) {
        $fans[] = ['name' => (string) ($r[2] ?? ''), 'rpm' => int_or_null($r[3] ?? null)];
    }

    $pools = [];
    foreach (snmp_table($s, QNAP_POOLS) as $r) {
        // Columns: 2 pool id, 3 capacity bytes, 5 status, 7 RAID level ("Single", "1", "5", ...).
        $level = (string) ($r[7] ?? '');
        $pools[] = [
            'id' => int_or_null($r[2] ?? null), 'bytes' => int_or_null($r[3] ?? null),
            'status' => (string) ($r[5] ?? ''),
            'level' => ctype_digit($level) ? "RAID $level" : $level,
        ];
    }

    $volumes = [];
    foreach (snmp_table($s, QNAP_VOLUME_EX) as $r) {
        // Columns: 2 "[Volume NAME, Pool N]", 3 filesystem, 4 total KB, 5 free KB, 6 status.
        $desc = (string) ($r[2] ?? '');
        preg_match('/Volume\s+([^,\]]+)(?:,\s*Pool\s+(\d+))?/', $desc, $m);
        $total = (int_or_null($r[4] ?? null) ?? 0) * 1024;
        $free = (int_or_null($r[5] ?? null) ?? 0) * 1024;
        $volumes[] = [
            'name' => trim($m[1] ?? $desc), 'pool' => isset($m[2]) ? (int) $m[2] : null,
            'fs' => (string) ($r[3] ?? ''), 'bytes' => $total, 'freeBytes' => $free,
            'usedPct' => $total ? round(100 * ($total - $free) / $total, 1) : null,
            'status' => rtrim((string) ($r[6] ?? ''), '.'),
        ];
    }

    // Memory: hrStorage lists every mount on a QNAP (dozens of rows, slow),
    // so read the names, then fetch just physical memory, buffers and cache.
    $want = [];
    foreach (snmp_walk_suffix($s, HR_STORAGE_DESCR) as $idx => $name) {
        $name = strtolower((string) $name);
        if (in_array($name, ['physical memory', 'memory buffers', 'cached memory'], true)) $want[$name] = (string) $idx;
        if (count($want) === 3 || str_starts_with($name, '/')) break;   // mounts come after the memory rows
    }
    $mem = null;
    if (isset($want['physical memory'])) {
        $oids = [];
        foreach ($want as $idx) array_push($oids, HR_STORAGE_UNITS . ".$idx", HR_STORAGE_SIZE . ".$idx", HR_STORAGE_USED . ".$idx");
        $v = snmp_get_many($s, $oids);
        $val = fn($base, $name) => (int) ($v[$base . '.' . $want[$name]] ?? 0) * (int) ($v[HR_STORAGE_UNITS . '.' . $want[$name]] ?? 0);
        $mem = ['total' => $val(HR_STORAGE_SIZE, 'physical memory'), 'used' => $val(HR_STORAGE_USED, 'physical memory')];
        foreach (['memory buffers', 'cached memory'] as $n) if (isset($want[$n])) $mem['used'] -= $val(HR_STORAGE_USED, $n);
        $mem['used'] = max(0, $mem['used']);
    }

    preg_match('/(\d+\.\d+\.\d+(?:\.\d+)?)\s*$/', (string) ($sys[OID_SYS_DESCR_0] ?? ''), $fw);
    return [
        'vendor' => 'QNAP',
        'model' => (string) ($enc[3] ?? ''),
        'serial' => (string) ($enc[4] ?? ''),
        'name' => (string) ($enc[6] ?? ''),
        'bays' => int_or_null($enc[5] ?? null),
        'firmware' => $fw[1] ?? null,
        'systemTempC' => int_or_null($enc[7] ?? null),
        'cpuPct' => $cpuLoad ? round(array_sum($cpuLoad) / count($cpuLoad), 1) : null,
        'memory' => $mem,
        'disks' => $disks,
        'fans' => $fans,
        'pools' => $pools,
        'volumes' => $volumes,
    ];
}

/**
 * Alert-worthy NAS conditions: [[type, subject, severity, message]...].
 * Volume space uses the regular disk thresholds ($warnPct/$critPct).
 */
function nas_problems(array $nas, string $label, int $warnPct, int $critPct): array {
    $out = [];
    foreach ($nas['volumes'] ?? [] as $v) {
        $pct = $v['usedPct'];
        $note = $v['status'] && $v['status'] !== 'Ready' ? " (QNAP status: {$v['status']})" : '';
        if ($pct !== null && $pct >= $warnPct) {
            $out[] = ['disk', "volume {$v['name']}", $pct >= $critPct ? 'critical' : 'warning',
                "$label: volume {$v['name']} is {$pct}% full, " . human_bytes((float) $v['freeBytes']) . " free$note"];
        } elseif ($v['status'] && !in_array($v['status'], ['Ready', 'Warning'], true)) {
            $out[] = ['nas_health', "volume {$v['name']}", 'critical', "$label: volume {$v['name']} status is {$v['status']}"];
        }
    }
    foreach ($nas['pools'] ?? [] as $p) {
        if ($p['status'] && $p['status'] !== 'Ready') {
            $out[] = ['nas_health', "pool {$p['id']}", 'critical', "$label: storage pool {$p['id']} ({$p['level']}) is {$p['status']}"];
        }
    }
    foreach ($nas['disks'] ?? [] as $d) {
        $smart = strtoupper($d['smart']);
        if (($smart !== '' && $smart !== 'GOOD' && $smart !== '--') || ($d['status'] !== null && $d['status'] !== 0)) {
            $out[] = ['nas_health', "disk {$d['slot']}", 'critical',
                "$label: {$d['slot']} ({$d['model']}) reports SMART {$d['smart']}, status {$d['status']} — check or replace the drive"];
        } elseif ($d['tempC'] !== null && $d['tempC'] >= NAS_DISK_TEMP_WARN) {
            $out[] = ['nas_health', "disk {$d['slot']} temperature", $d['tempC'] >= NAS_DISK_TEMP_CRIT ? 'critical' : 'warning',
                "$label: {$d['slot']} is running hot ({$d['tempC']} °C)"];
        }
    }
    foreach ($nas['fans'] ?? [] as $f) {
        if ($f['rpm'] === 0) $out[] = ['nas_health', "fan {$f['name']}", 'warning', "$label: {$f['name']} has stopped (0 RPM)"];
    }
    $t = $nas['systemTempC'] ?? null;
    if ($t !== null && $t >= NAS_SYSTEM_TEMP_WARN) {
        $out[] = ['nas_health', 'system temperature', $t >= NAS_SYSTEM_TEMP_CRIT ? 'critical' : 'warning',
            "$label: system temperature is $t °C"];
    }
    return $out;
}

/** History points from a NAS snapshot (see includes/history.php). */
function nas_history_points(array $n): array {
    $p = [
        ['cpu', '', '%', $n['cpuPct'] ?? null],
        ['mem', '', '%', !empty($n['memory']['total']) ? round($n['memory']['used'] / $n['memory']['total'] * 100, 1) : null],
        ['temp_system', '', '°C', $n['systemTempC'] ?? null],
    ];
    foreach ($n['volumes'] ?? [] as $v) $p[] = ['disk', "volume {$v['name']}", '%', $v['usedPct']];
    foreach ($n['disks'] ?? [] as $d) $p[] = ['temp_disk', $d['slot'], '°C', $d['tempC']];
    foreach ($n['fans'] ?? [] as $f) $p[] = ['fan', $f['name'], 'RPM', $f['rpm']];
    return $p;
}
