mkdir -p "$(dirname "$APP_DIR/includes/netcheck.php")"
cat > "$APP_DIR/includes/netcheck.php" <<'WEBMON_FILE_EOF'
<?php
/**
 * TCP-based reachability checks. No raw ICMP sockets are used — a plain
 * TCP connect (or even a fast refusal/RST) proves a host is alive without
 * needing root, setuid, capabilities, or any SELinux policy changes.
 */

const NETCHECK_PORTS = [80, 443, 22, 445, 3389];

/**
 * Guesses an OS family from which port answered, when SNMP text isn't
 * available to do better. Best-effort only.
 */
function guess_os_from_port(?int $port, bool $open): string {
    if ($port === null) return 'other';
    if (!$open) return 'other'; // a bare refusal doesn't tell us much about the OS
    if ($port === 445 || $port === 3389) return 'windows';
    if ($port === 22) return 'linux';
    return 'other';
}

/**
 * Attempts a non-blocking TCP connect to every (ip, port) pair and returns,
 * per ip, the first port that responded within $timeoutSec. A completed
 * connection ('open' => true) and a fast refusal ('open' => false, still
 * 'up' => true) both prove the host is alive; only silence counts as down.
 *
 * @param string[] $ips
 * @param int[] $ports
 * @return array<string, array{up: bool, port: ?int, open: bool, ms: ?int}>
 */
function tcp_probe_hosts(array $ips, array $ports, float $timeoutSec): array {
    $results = [];
    foreach ($ips as $ip) $results[$ip] = ['up' => false, 'port' => null, 'open' => false, 'ms' => null];
    if (!$ips || !$ports) return $results;

    $start = microtime(true);
    $sockets = [];
    foreach ($ips as $ip) {
        foreach ($ports as $port) {
            $fp = @stream_socket_client(
                "tcp://$ip:$port", $errno, $errstr, $timeoutSec,
                STREAM_CLIENT_CONNECT | STREAM_CLIENT_ASYNC_CONNECT
            );
            if ($fp !== false) {
                $sockets[(int) $fp] = ['ip' => $ip, 'port' => $port, 'fp' => $fp];
            }
        }
    }

    while ($sockets) {
        $remaining = $timeoutSec - (microtime(true) - $start);
        if ($remaining <= 0) break;

        $write = array_column($sockets, 'fp');
        $read = [];
        $except = $write;
        $sec = (int) $remaining;
        $usec = (int) (($remaining - $sec) * 1_000_000);
        $n = @stream_select($read, $write, $except, $sec, $usec);
        if ($n === false || $n === 0) break;

        foreach (array_merge($write, $except) as $fp) {
            $id = (int) $fp;
            if (!isset($sockets[$id])) continue;
            $ip = $sockets[$id]['ip'];
            $port = $sockets[$id]['port'];
            $open = @stream_socket_get_name($fp, true) !== false;

            if (!$results[$ip]['up']) {
                $results[$ip] = [
                    'up' => true,
                    'port' => $port,
                    'open' => $open,
                    'ms' => (int) round((microtime(true) - $start) * 1000),
                ];
            }
            fclose($fp);
            unset($sockets[$id]);
        }
    }

    foreach ($sockets as $s) fclose($s['fp']);

    return $results;
}

/** Convenience wrapper for a single host. */
function tcp_probe_host(string $ip, array $ports, float $timeoutSec): array {
    return tcp_probe_hosts([$ip], $ports, $timeoutSec)[$ip];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/netlive.php")"
cat > "$APP_DIR/includes/netlive.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/switchinfo.php';
require_once __DIR__ . '/history.php';

/**
 * Live port traffic of the switches and routers (Network tab).
 *
 * Each physical device's interface counters (IF-MIB ifHCInOctets /
 * ifHCOutOctets, or the 32-bit ifInOctets / ifOutOctets on older gear) are
 * read over SNMP; the rate of each port is the difference between two
 * samples. The dashboard asks for fresh rates every few seconds while the
 * Network tab is open (samples are shared: a device is read at most once per
 * NETLIVE_MIN_GAP_MS, whoever is watching), and cron reads every device once
 * a minute for the per-port history (metrics port_in / port_out, bit/s).
 *
 * Several cards for one switch (one per VLAN address) are read once: see
 * network_device_ids().
 */

const NETLIVE_MIN_GAP_MS = 2500;      // shared sample: reread a device at most this often
const NETLIVE_ERROR_BACKOFF_MS = 300000; // a device that didn't answer is retried after this (each try can take seconds)
const NETLIVE_TIMEOUT_SEC = 1.0;

const OID_IF_HC_IN = '.1.3.6.1.2.1.31.1.1.1.6';
const OID_IF_HC_OUT = '.1.3.6.1.2.1.31.1.1.1.10';
const OID_IF_IN_OCTETS = '.1.3.6.1.2.1.2.2.1.10';
const OID_IF_OUT_OCTETS = '.1.3.6.1.2.1.2.2.1.16';

/**
 * [hostId => [hostIds of the same device]]: one entry per physical switch or
 * router that has a port map. A device is identified by its ports' MAC
 * addresses; the card with a configuration backup (else the oldest) leads.
 */
function network_device_groups(): array {
    $pdo = db();
    $withBackup = array_flip(array_map('intval', $pdo->query('SELECT host_id FROM config_backup_settings')->fetchAll(PDO::FETCH_COLUMN)));
    $groups = [];
    foreach ($pdo->query('SELECT m.host_id, m.data FROM port_maps m JOIN hosts h ON h.id = m.host_id') as $r) {
        $macs = array_values(array_unique(array_filter(array_column(json_decode($r['data'], true)['ports'] ?? [], 'mac'))));
        sort($macs);
        $groups[$macs ? md5(implode(',', $macs)) : 'host' . $r['host_id']][] = (int) $r['host_id'];
    }
    $out = [];
    foreach ($groups as $ids) {
        usort($ids, fn($a, $b) => [!isset($withBackup[$a]), $a] <=> [!isset($withBackup[$b]), $b]);
        $out[$ids[0]] = $ids;
    }
    return $out;
}

/** SNMPv2c walk that keeps Counter64 values (snmprealwalk is SNMPv1). [suffix => string]. */
function snmp2_walk_raw(string $ip, string $community, string $oid, float $timeoutSec): array {
    $prefix = ltrim($oid, '.') . '.';
    $out = [];
    if (function_exists('snmp2_real_walk')) {
        snmp_set_quick_print(true);
        snmp_set_valueretrieval(SNMP_VALUE_PLAIN);
        snmp_set_oid_output_format(SNMP_OID_OUTPUT_NUMERIC);
        $walk = @snmp2_real_walk($ip, $community, $oid, (int) round($timeoutSec * 1_000_000), 0);
        if (!is_array($walk)) return [];
        foreach ($walk as $k => $v) {
            $k = ltrim((string) $k, '.');
            if (str_starts_with($k, $prefix)) $out[substr($k, strlen($prefix))] = trim((string) $v, " \t\"");
        }
        return $out;
    }
    $bin = trim((string) shell_exec('command -v snmpbulkwalk 2>/dev/null'));
    if ($bin === '') return snmp_walk($ip, $community, $oid, $timeoutSec);
    exec(escapeshellarg($bin) . ' -Oqn -v2c -c ' . escapeshellarg($community) . ' -t ' . max(1, (int) round($timeoutSec))
        . ' -r 0 ' . escapeshellarg($ip) . ' ' . escapeshellarg($oid) . ' 2>/dev/null', $lines);
    foreach ($lines as $line) {
        if (preg_match('/^\.?(\S+)\s+(\S+)/', $line, $m) && str_starts_with($m[1], $prefix)) $out[substr($m[1], strlen($prefix))] = $m[2];
    }
    return $out;
}

/**
 * Octet counters of a device's ports: ['bits' => 64|32, 'c' => [ifIndex => [in, out]]].
 * Only the ports of its port map are kept (when it has one).
 */
function read_iface_counters(array $host, ?array $portIdx): array {
    $ip = $host['ip_address'];
    $c = $host['community'] !== '' ? $host['community'] : 'public';
    $bits = 64;
    $in = snmp2_walk_raw($ip, $c, OID_IF_HC_IN, NETLIVE_TIMEOUT_SEC);
    $out = $in ? snmp2_walk_raw($ip, $c, OID_IF_HC_OUT, NETLIVE_TIMEOUT_SEC) : [];
    if (!$in) {   // no 64-bit counters (or SNMPv1 only)
        $bits = 32;
        $in = snmp_walk($ip, $c, OID_IF_IN_OCTETS, NETLIVE_TIMEOUT_SEC);
        $out = $in ? snmp_walk($ip, $c, OID_IF_OUT_OCTETS, NETLIVE_TIMEOUT_SEC) : [];
    }
    if (!$in) throw new RuntimeException('no answer to SNMP');
    $counters = [];
    foreach ($in as $idx => $v) {
        $idx = (int) $idx;
        if ($portIdx !== null && !isset($portIdx[$idx])) continue;
        if (!is_numeric($v) || !isset($out[$idx]) || !is_numeric($out[$idx])) continue;
        $counters[$idx] = [(float) $v, (float) $out[$idx]];
    }
    return ['bits' => $bits, 'c' => $counters];
}

/** bit/s per port between two counter sets; a counter that went backwards (reset) gives no rate. */
function iface_rates(array $old, array $new, float $sec): array {
    if ($sec <= 0.5) return [];
    $wrap = ($new['bits'] ?? 64) === 32 ? 4294967296.0 : null;
    $rates = [];
    foreach ($new['c'] as $idx => [$i, $o]) {
        if (!isset($old['c'][$idx])) continue;
        $d = [];
        foreach ([[$i, $old['c'][$idx][0]], [$o, $old['c'][$idx][1]]] as [$now, $then]) {
            $delta = $now - $then;
            if ($delta < 0 && $wrap) $delta += $wrap;
            $d[] = $delta < 0 ? null : round($delta * 8 / $sec);
        }
        if ($d[0] !== null && $d[1] !== null) $rates[$idx] = $d;
    }
    return $rates;
}

/** [hostId => ifIndex set] of the stored port maps. */
function port_map_ifindexes(array $ids): array {
    if (!$ids) return [];
    $out = [];
    foreach (db()->query('SELECT host_id, data FROM port_maps WHERE host_id IN (' . implode(',', array_map('intval', $ids)) . ')') as $r) {
        $out[(int) $r['host_id']] = array_flip(array_map('intval', array_column(json_decode($r['data'], true)['ports'] ?? [], 'ifIndex')));
    }
    return $out;
}

/**
 * Fresh rates of one device (sampled now unless someone did in the last
 * NETLIVE_MIN_GAP_MS). Returns the iface_samples row as an array.
 */
function sample_device(array $host, ?array $portIdx): array {
    $pdo = db();
    $id = (int) $host['id'];
    $lock = "webmonitor_iface_$id";
    $st = $pdo->prepare('SELECT GET_LOCK(?, 5)');
    $st->execute([$lock]);
    $locked = (int) $st->fetchColumn();
    try {
        $sel = $pdo->prepare('SELECT * FROM iface_samples WHERE host_id = ?');
        $sel->execute([$id]);
        $row = $sel->fetch() ?: null;
        $now = (int) round(microtime(true) * 1000);
        if ($row && $now - (int) $row['live_at'] < ($row['error'] ? NETLIVE_ERROR_BACKOFF_MS : NETLIVE_MIN_GAP_MS)) return $row;
        try {
            $new = read_iface_counters($host, $portIdx);
        } catch (Throwable $e) {
            $pdo->prepare('INSERT INTO iface_samples (host_id, live_at, live_counters, rates, error) VALUES (?, ?, ?, NULL, ?)
                           ON DUPLICATE KEY UPDATE live_at = VALUES(live_at), error = VALUES(error), rates = NULL')
                ->execute([$id, $now, $row['live_counters'] ?? '{}', mb_substr($e->getMessage(), 0, 255)]);
            return ['host_id' => $id, 'live_at' => $now, 'rates' => null, 'error' => $e->getMessage()] + ($row ?? []);
        }
        $old = $row && !$row['error'] ? json_decode($row['live_counters'], true) : null;
        // Older than 2 minutes: too long ago to call it "live".
        $rates = $old && $now - (int) $row['live_at'] < 120000 ? iface_rates($old, $new, ($now - (int) $row['live_at']) / 1000) : null;
        $pdo->prepare('INSERT INTO iface_samples (host_id, live_at, live_counters, rates, error) VALUES (?, ?, ?, ?, NULL)
                       ON DUPLICATE KEY UPDATE live_at = VALUES(live_at), live_counters = VALUES(live_counters), rates = VALUES(rates), error = NULL')
            ->execute([$id, $now, json_encode($new), $rates === null ? null : json_encode((object) $rates)]);
        $sel->execute([$id]);
        return $sel->fetch();
    } finally {
        if ($locked) $pdo->prepare('SELECT RELEASE_LOCK(?)')->execute([$lock]);
    }
}

/**
 * Live rates of every network device (or the given ones):
 * [hostId => ['at' => ms, 'error' => ?string, 'rates' => {ifIndex: [in, out]} | null]].
 */
function live_network_rates(?array $only = null): array {
    $groups = network_device_groups();
    $ids = array_keys($groups);
    if ($only !== null) $ids = array_values(array_intersect($ids, $only));
    if (!$ids) return [];
    $hosts = db()->query('SELECT * FROM hosts WHERE id IN (' . implode(',', $ids) . ')')->fetchAll();
    $portIdx = port_map_ifindexes($ids);
    $out = [];
    foreach ($hosts as $h) {
        $r = sample_device($h, $portIdx[(int) $h['id']] ?? null);
        $out[(int) $h['id']] = [
            'at' => (int) $r['live_at'],
            'error' => $r['error'] ?: null,
            'rates' => $r['rates'] ? json_decode($r['rates'], true) : null,
        ];
    }
    return $out;
}

/**
 * Cron, every minute: samples every network device and records each port's
 * average rate since the previous minute (ports that are up only).
 */
function record_port_traffic(): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'iface_samples'")->fetchColumn()) return;
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_port_traffic', 0)")->fetchColumn()) return;
    try {
        $groups = network_device_groups();
        if (!$groups) return;
        $ids = implode(',', array_keys($groups));
        $hosts = $pdo->query("SELECT * FROM hosts WHERE id IN ($ids)")->fetchAll();
        $maps = [];
        foreach ($pdo->query("SELECT host_id, data FROM port_maps WHERE host_id IN ($ids)") as $r) {
            $maps[(int) $r['host_id']] = array_column(json_decode($r['data'], true)['ports'] ?? [], null, 'ifIndex');
        }
        foreach ($hosts as $h) {
            $id = (int) $h['id'];
            $ports = $maps[$id] ?? [];
            $row = sample_device($h, $ports ? array_fill_keys(array_keys($ports), true) : null);
            if (!empty($row['error'])) continue;
            $live = json_decode($row['live_counters'], true);
            $liveAt = (int) $row['live_at'];
            $prev = $row['minute_counters'] ? json_decode($row['minute_counters'], true) : null;
            $age = ($liveAt - (int) $row['minute_at']) / 1000;
            if ($prev && $age >= 30 && $age <= 600) {
                $points = [];
                foreach (iface_rates($prev, $live, $age) as $idx => [$in, $out]) {
                    $p = $ports[$idx] ?? null;
                    if ($ports && (!$p || $p['status'] !== 'up')) continue;
                    $name = $p['name'] ?? "if$idx";
                    $points[] = ['port_in', $name, 'bit/s', $in];
                    $points[] = ['port_out', $name, 'bit/s', $out];
                }
                record_points($id, $points, intdiv($liveAt, 1000));
            }
            if (!$prev || $age >= 30 || $age < 0) {
                $pdo->prepare('UPDATE iface_samples SET minute_at = ?, minute_counters = ? WHERE host_id = ?')
                    ->execute([$liveAt, $row['live_counters'], $id]);
            }
        }
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_port_traffic')");
    }
}

/** [hostId => [{i, name, speed, status, lag, desc, ips}]] of every network device, for matching rates to port names. */
function network_port_index(): array {
    $ids = array_keys(network_device_groups());
    if (!$ids) return [];
    $out = [];
    foreach (db()->query('SELECT host_id, data FROM port_maps WHERE host_id IN (' . implode(',', $ids) . ')') as $r) {
        foreach (json_decode($r['data'], true)['ports'] ?? [] as $p) {
            $out[(int) $r['host_id']][] = ['i' => (int) $p['ifIndex'], 'name' => $p['name'], 'speed' => $p['speedMbps'],
                'status' => $p['status'], 'lag' => $p['lag'] ?? null, 'desc' => $p['description'] ?? '', 'ips' => $p['ips'] ?? []];
        }
    }
    return $out;
}

/** History of one port: ['in' => [[ts, avg, min, max], ...], 'out' => [...]]. */
function port_history(int $hostId, string $port, string $range): array {
    [$span, $bucket, $source] = HISTORY_RANGES[$range] ?? HISTORY_RANGES['24h'];
    $pdo = db();
    $st = $pdo->prepare("SELECT id, metric FROM metric_series WHERE host_id = ? AND subject = ? AND metric IN ('port_in', 'port_out')");
    $st->execute([$hostId, $port]);
    $out = ['in' => [], 'out' => []];
    foreach ($st->fetchAll() as $s) {
        $sql = $source === 'raw'
            ? "SELECT ts - MOD(ts, $bucket) t, AVG(value), MIN(value), MAX(value) FROM metric_points WHERE series_id = ? AND ts >= ? GROUP BY t ORDER BY t"
            : "SELECT ts - MOD(ts, $bucket) t, SUM(avg_value * samples) / SUM(samples), MIN(min_value), MAX(max_value) FROM metric_hourly WHERE series_id = ? AND ts >= ? GROUP BY t ORDER BY t";
        $q = $pdo->prepare($sql);
        $q->execute([(int) $s['id'], time() - $span]);
        $out[$s['metric'] === 'port_in' ? 'in' : 'out'] = array_map(fn($r) => [(int) $r[0], round((float) $r[1]), round((float) $r[2]), round((float) $r[3])], $q->fetchAll(PDO::FETCH_NUM));
    }
    return $out;
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/notify.php")"
cat > "$APP_DIR/includes/notify.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';

/**
 * Notification channels: email (SMTP), ntfy, and webhooks (Discord, Slack,
 * or any endpoint that accepts JSON).
 *
 * Channel config (JSON in notification_channels.config):
 *   email:   host, port, security (starttls|ssl|none), username, password,
 *            from, to (comma-separated), verify_tls (bool)
 *   ntfy:    url (https://ntfy.sh/topic or self-hosted), token (optional)
 *   webhook: url
 */

const CHANNEL_TYPES = ['email', 'ntfy', 'webhook'];
const CHANNEL_SECRET_FIELDS = ['password', 'token'];

/** Sends to every enabled channel; returns how many succeeded. */
function notify_all(string $title, string $body, string $priority = 'warning', ?int $alertId = null): int {
    $ok = 0;
    foreach (db()->query('SELECT * FROM notification_channels WHERE enabled = 1')->fetchAll() as $ch) {
        $err = send_to_channel($ch, $title, $body, $priority);
        log_notification((int) $ch['id'], $alertId, $err === null, $err ?? 'sent');
        if ($err === null) $ok++;
    }
    return $ok;
}

function log_notification(?int $channelId, ?int $alertId, bool $ok, string $detail): void {
    db()->prepare('INSERT INTO notification_log (ts, channel_id, alert_id, ok, detail) VALUES (?, ?, ?, ?, ?)')
        ->execute([(int) round(microtime(true) * 1000), $channelId, $alertId, $ok ? 1 : 0, substr($detail, 0, 500)]);
}

/** Returns null on success or an error message. Never throws. */
function send_to_channel(array $ch, string $title, string $body, string $priority): ?string {
    $cfg = json_decode((string) $ch['config'], true) ?: [];
    try {
        switch ($ch['type']) {
            case 'email':
                return smtp_send($cfg, $title, $body . "\n\n-- \nSent by WebMonitor");
            case 'ntfy':
                $headers = [
                    'Title: ' . ntfy_header_value($title),
                    'Priority: ' . (['critical' => '5', 'warning' => '4'][$priority] ?? '3'),
                    'Tags: ' . (['critical' => 'rotating_light', 'warning' => 'warning'][$priority] ?? 'information_source'),
                    'Content-Type: text/plain; charset=utf-8',
                ];
                if (!empty($cfg['token'])) $headers[] = 'Authorization: Bearer ' . $cfg['token'];
                return http_post((string) ($cfg['url'] ?? ''), $body, $headers);
            case 'webhook':
                $url = (string) ($cfg['url'] ?? '');
                $text = "**$title**\n$body";
                if (preg_match('#^https://(discord|discordapp)\.com/api/webhooks/#', $url)) {
                    $payload = ['content' => mb_substr($text, 0, 1900)];
                } elseif (str_starts_with($url, 'https://hooks.slack.com/')) {
                    $payload = ['text' => str_replace('**', '*', $text)];
                } else {
                    $payload = ['title' => $title, 'text' => $text, 'content' => $text, 'priority' => $priority];
                }
                return http_post($url, json_encode($payload), ['Content-Type: application/json']);
        }
        return "unknown channel type '{$ch['type']}'";
    } catch (Throwable $e) {
        return $e->getMessage();
    }
}

/** HTTP header values must be ASCII; ntfy accepts RFC 2047 for the rest. */
function ntfy_header_value(string $s): string {
    return preg_match('/[^\x20-\x7E]/', $s) ? '=?UTF-8?B?' . base64_encode($s) . '?=' : $s;
}

function http_post(string $url, string $body, array $headers): ?string {
    if (!preg_match('#^https?://#i', $url)) return 'URL must start with http:// or https://';
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => $body,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 15,
        CURLOPT_CONNECTTIMEOUT => 8,
        CURLOPT_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS,
        CURLOPT_USERAGENT => 'WebMonitor',
    ]);
    $resp = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    $err = curl_error($ch);
    curl_close($ch);
    if ($resp === false) return "request failed: $err";
    if ($code < 200 || $code >= 300) return "HTTP $code: " . substr(trim((string) $resp), 0, 200);
    return null;
}

/**
 * Minimal SMTP client (no mail server is needed on this machine):
 * implicit TLS (465) or STARTTLS (587), AUTH LOGIN, UTF-8 plain text.
 */
function smtp_send(array $cfg, string $subject, string $body): ?string {
    $host = trim((string) ($cfg['host'] ?? ''));
    $port = (int) ($cfg['port'] ?? 587);
    $security = $cfg['security'] ?? 'starttls';
    $from = trim((string) ($cfg['from'] ?? ''));
    $to = array_values(array_filter(array_map('trim', explode(',', (string) ($cfg['to'] ?? '')))));
    if ($host === '' || !$from || !$to) return 'SMTP host, From and To are required';
    foreach (array_merge([$from], $to) as $addr) {
        if (!filter_var($addr, FILTER_VALIDATE_EMAIL)) return "invalid email address: $addr";
    }

    $verify = !array_key_exists('verify_tls', $cfg) || $cfg['verify_tls'];
    $ctx = stream_context_create(['ssl' => [
        'verify_peer' => $verify, 'verify_peer_name' => $verify, 'peer_name' => $host,
    ]]);
    $target = ($security === 'ssl' ? 'ssl://' : 'tcp://') . $host . ':' . $port;
    $fp = @stream_socket_client($target, $errno, $errstr, 15, STREAM_CLIENT_CONNECT, $ctx);
    if (!$fp) return "cannot connect to $host:$port: $errstr";
    stream_set_timeout($fp, 20);

    $read = function () use ($fp): array {
        $text = '';
        while (($line = fgets($fp, 2048)) !== false) {
            $text .= $line;
            if (strlen($line) < 4 || $line[3] !== '-') break;   // last line of a reply
        }
        return [(int) substr($text, 0, 3), trim($text)];
    };
    $cmd = function (string $line, array $expect) use ($fp, $read): void {
        fwrite($fp, $line . "\r\n");
        [$code, $text] = $read();
        if (!in_array($code, $expect, true)) {
            // Don't echo credentials or the message body into error messages.
            $shown = str_contains($line, "\r\n") ? 'message DATA'
                : (str_starts_with($line, 'AUTH') || strlen($line) > 60 ? 'AUTH' : $line);
            throw new RuntimeException("SMTP: '$shown' rejected: $text");
        }
    };

    try {
        [$code, $text] = $read();
        if ($code !== 220) throw new RuntimeException("SMTP greeting: $text");
        $me = gethostname() ?: 'webmonitor';
        $cmd("EHLO $me", [250]);
        if ($security === 'starttls') {
            $cmd('STARTTLS', [220]);
            if (!stream_socket_enable_crypto($fp, true, STREAM_CRYPTO_METHOD_TLSv1_2_CLIENT | STREAM_CRYPTO_METHOD_TLSv1_3_CLIENT)) {
                throw new RuntimeException('STARTTLS negotiation failed (certificate problem?)');
            }
            $cmd("EHLO $me", [250]);
        }
        if (!empty($cfg['username'])) {
            $cmd('AUTH LOGIN', [334]);
            $cmd(base64_encode((string) $cfg['username']), [334]);
            $cmd(base64_encode((string) ($cfg['password'] ?? '')), [235]);
        }
        $cmd("MAIL FROM:<$from>", [250]);
        foreach ($to as $rcpt) $cmd("RCPT TO:<$rcpt>", [250, 251]);
        $cmd('DATA', [354]);

        $headers = [
            'From: WebMonitor <' . $from . '>',
            'To: ' . implode(', ', $to),
            'Subject: =?UTF-8?B?' . base64_encode($subject) . '?=',
            'Date: ' . date('r'),
            'Message-ID: <' . bin2hex(random_bytes(12)) . '@' . $me . '>',
            'MIME-Version: 1.0',
            'Content-Type: text/plain; charset=UTF-8',
            'Content-Transfer-Encoding: base64',
        ];
        $data = implode("\r\n", $headers) . "\r\n\r\n" . chunk_split(base64_encode($body), 76, "\r\n");
        $cmd($data . '.', [250]);
        $cmd('QUIT', [221]);
        return null;
    } catch (RuntimeException $e) {
        return $e->getMessage();
    } finally {
        fclose($fp);
    }
}

/** Channel as shown to the browser: secrets replaced by "is it set". */
function channel_public(array $ch): array {
    $cfg = json_decode((string) $ch['config'], true) ?: [];
    foreach (CHANNEL_SECRET_FIELDS as $f) {
        $cfg[$f . '_set'] = !empty($cfg[$f]);
        unset($cfg[$f]);
    }
    return ['id' => (int) $ch['id'], 'type' => $ch['type'], 'name' => $ch['name'],
            'enabled' => (bool) $ch['enabled'], 'config' => $cfg];
}

/**
 * Validates and normalizes a channel config from the browser. Secret
 * fields left blank keep their previous value.
 */
function channel_config(string $type, array $in, array $previous = []): array {
    $str = fn($k, $max = 255) => substr(trim((string) ($in[$k] ?? '')), 0, $max);
    switch ($type) {
        case 'email':
            $cfg = [
                'host' => $str('host'), 'port' => (int) ($in['port'] ?? 587) ?: 587,
                'security' => in_array($in['security'] ?? '', ['starttls', 'ssl', 'none'], true) ? $in['security'] : 'starttls',
                'username' => $str('username'), 'password' => (string) ($in['password'] ?? ''),
                'from' => $str('from'), 'to' => $str('to', 1000),
                'verify_tls' => !array_key_exists('verify_tls', $in) || (bool) $in['verify_tls'],
            ];
            if ($cfg['host'] === '' || $cfg['from'] === '' || $cfg['to'] === '') throw new InvalidArgumentException('SMTP server, From and To are required.');
            break;
        case 'ntfy':
            $cfg = ['url' => $str('url', 500), 'token' => (string) ($in['token'] ?? '')];
            if (!preg_match('#^https?://[^/]+/[^/]+#', $cfg['url'])) throw new InvalidArgumentException('ntfy URL should look like https://ntfy.sh/your-topic');
            break;
        case 'webhook':
            $cfg = ['url' => $str('url', 1000)];
            if (!preg_match('#^https?://#', $cfg['url'])) throw new InvalidArgumentException('Webhook URL must start with https://');
            break;
        default:
            throw new InvalidArgumentException('Unknown channel type.');
    }
    foreach (CHANNEL_SECRET_FIELDS as $f) {
        if (array_key_exists($f, $cfg) && $cfg[$f] === '' && !empty($previous[$f])) $cfg[$f] = $previous[$f];
    }
    return $cfg;
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/portflows.php")"
cat > "$APP_DIR/includes/portflows.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/flows.php';
require_once __DIR__ . '/netlive.php';
require_once __DIR__ . '/portmap.php';

/**
 * What's using a switch port, from NetFlow (Network tab, port details).
 *
 * Two ways, picked per port:
 *   exact  the switch's flows name this port as their input interface (a
 *          Catalyst 3850 does even with the monitor on VLAN interfaces): what
 *          the port sends is exact; what it receives comes from matching by
 *          IP unless output interfaces are exported too.
 *   ip     otherwise: the flows of the devices the port map puts on this
 *          port (by IP), from whichever exporter saw them.
 * Either way, only traffic that passes a switch exporting NetFlow is seen.
 */

const PORTFLOW_RANGES = ['15m' => [900, 60], '1h' => [3600, 300], '6h' => [21600, 900], '24h' => [86400, 1800], '7d' => [604800, 3 * 3600]];

/** Addresses a device exports flows from: every card of it, plus its interface addresses. */
function device_exporter_ips(int $hostId): array {
    $ids = [$hostId];
    foreach (network_device_groups() as $main => $group) if (in_array($hostId, $group, true)) $ids = $group;
    $pdo = db();
    $ips = $pdo->query('SELECT ip_address FROM hosts WHERE id IN (' . implode(',', array_map('intval', $ids)) . ')')->fetchAll(PDO::FETCH_COLUMN);
    $st = $pdo->prepare('SELECT data FROM port_maps WHERE host_id = ?');
    $st->execute([$hostId]);
    foreach (json_decode((string) $st->fetchColumn(), true)['ports'] ?? [] as $p) {
        foreach (array_merge($p['ips'] ?? [], ...array_map(fn($x) => $x['ips'] ?? [], $p['subs'] ?? [])) as $cidr) $ips[] = explode('/', $cidr)[0];
    }
    return array_values(array_unique($ips));
}

/** [ifIndex => name] of a device: its port map, plus ifName over SNMP for the rest (VLAN interfaces), cached a day. */
function device_if_names(array $host): array {
    $pdo = db();
    $names = [];
    $st = $pdo->prepare('SELECT data FROM port_maps WHERE host_id = ?');
    $st->execute([(int) $host['id']]);
    foreach (json_decode((string) $st->fetchColumn(), true)['ports'] ?? [] as $p) $names[(int) $p['ifIndex']] = $p['name'];
    $key = 'ifnames:' . (int) $host['id'];
    $st = $pdo->prepare('SELECT v FROM settings WHERE k = ?');
    $st->execute([$key]);
    $cached = json_decode((string) $st->fetchColumn(), true);
    if (!$cached || ($cached['at'] ?? 0) < time() - 86400) {
        $walk = snmp_walk($host['ip_address'], $host['community'] !== '' ? $host['community'] : 'public', OID_IF_NAME, 2.0);
        if ($walk) {
            $cached = ['at' => time(), 'names' => array_map('strval', $walk)];
            $pdo->prepare('INSERT INTO settings (k, v) VALUES (?, ?) ON DUPLICATE KEY UPDATE v = VALUES(v)')->execute([$key, json_encode($cached)]);
        }
    }
    foreach ($cached['names'] ?? [] as $idx => $n) $names[(int) $idx] ??= $n;
    return $names;
}

/**
 * Where a device's flow monitors are, from its configuration backup: 'ports' (on physical
 * ports: everything entering them is seen), 'vlans' (only on VLAN interfaces: routed and
 * internet traffic only), or null when unknown.
 */
function flow_monitor_scope(int $hostId): ?string {
    static $cache = [];
    if (array_key_exists($hostId, $cache)) return $cache[$hostId];
    $st = db()->prepare('SELECT content FROM switch_configs WHERE host_id = ? ORDER BY fetched_at DESC LIMIT 1');
    $st->execute([$hostId]);
    $if = null;
    $ports = $vlans = false;
    foreach (explode("\n", (string) $st->fetchColumn()) as $line) {
        if (preg_match('/^interface (\S+)/', $line, $m)) $if = $m[1];
        elseif ($if !== null && preg_match('/^\s+(ip|ipv6) flow monitor /', $line)) {
            if (preg_match('/^(Vlan|BDI|Loopback)/i', $if)) $vlans = true; else $ports = true;
        } elseif ($line !== '' && $line[0] !== ' ') $if = null;
    }
    return $cache[$hostId] = $ports ? 'ports' : ($vlans ? 'vlans' : null);
}

function portflow_tables_ready(): bool {
    return (bool) db()->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'flow_iface_conv'")->fetchColumn();
}

// How long a report is reused (seconds): long ranges are slow to add up and change slowly.
const PORTFLOW_CACHE_SEC = ['15m' => 30, '1h' => 60, '6h' => 180, '24h' => 600, '7d' => 1800];

/** port_flow_report(), reused for a while (settings table, so every viewer shares it). */
function port_flow_report_cached(int $hostId, int $ifIndex, string $range): array {
    $pdo = db();
    $key = "pflow:$hostId:$ifIndex:$range";
    $st = $pdo->prepare('SELECT v FROM settings WHERE k = ?');
    $st->execute([$key]);
    $hit = json_decode((string) $st->fetchColumn(), true);
    if ($hit && ($hit['at'] ?? 0) > time() - (PORTFLOW_CACHE_SEC[$range] ?? 60)) return $hit['r'];
    $r = port_flow_report($hostId, $ifIndex, $range);
    $r['generatedAt'] = time();
    $pdo->prepare('INSERT INTO settings (k, v) VALUES (?, ?) ON DUPLICATE KEY UPDATE v = VALUES(v)')->execute([$key, json_encode(['at' => time(), 'r' => $r])]);
    if (random_int(1, 50) === 1) {   // now and then, drop old entries
        foreach ($pdo->query("SELECT k, v FROM settings WHERE k LIKE 'pflow:%'")->fetchAll() as $row) {
            if ((json_decode($row['v'], true)['at'] ?? 0) < time() - 3600) $pdo->prepare('DELETE FROM settings WHERE k = ?')->execute([$row['k']]);
        }
    }
    return $r;
}

/** The NetFlow breakdown of one port. */
function port_flow_report(int $hostId, int $ifIndex, string $range): array {
    [$span, $bucket] = PORTFLOW_RANGES[$range] ?? PORTFLOW_RANGES['1h'];
    $pdo = db();
    $from = intdiv(time() - $span, 60) * 60;
    $convFrom = max($from, time() - FLOW_CONV_KEEP_DAYS * 86400);
    $view = port_map_view($hostId);
    $port = null;
    foreach ($view['ports'] ?? [] as $p) if ((int) $p['ifIndex'] === $ifIndex) $port = $p;
    if (!$port) throw new RuntimeException('That port is not in the port map.');
    [$who, $names] = flow_name_resolver();
    $base = ['range' => $range, 'bucket' => $bucket, 'from' => $from, 'port' => $port['name'], 'role' => $port['role']];

    // --- Exact: flows that came in on this very port (their input interface). Most exporters
    // send only that, so it's the "sent from this port" side; what the port received comes
    // from matching by IP below, unless output interfaces are reported too.
    $exact = null;
    if (portflow_tables_ready()) {
        $exp = device_exporter_ips($hostId);
        $in = implode(',', array_fill(0, count($exp), '?'));
        $q = $pdo->prepare("SELECT ts - MOD(ts, $bucket) t, SUM(CASE WHEN dir = 'i' THEN bytes ELSE 0 END) bi, SUM(CASE WHEN dir = 'o' THEN bytes ELSE 0 END) bo
                            FROM flow_ifaces WHERE exporter IN ($in) AND if_index = ? AND ts >= ? GROUP BY t ORDER BY t");
        $q->execute([...$exp, $ifIndex, $from]);
        $rows = $q->fetchAll();
        if ($rows) {
            // [t, to the device(s) (out of the switch on this port), from them (into the switch)], bit/s.
            $series = array_map(fn($r) => [(int) $r['t'], round($r['bo'] * 8 / $bucket), round($r['bi'] * 8 / $bucket)], $rows);
            $q = $pdo->prepare("SELECT src_ip, dst_ip, proto, port, SUM(bytes) b FROM flow_iface_conv WHERE exporter IN ($in) AND if_index = ? AND ts >= ?
                                GROUP BY src_ip, dst_ip, proto, port ORDER BY b DESC LIMIT 500");
            $q->execute([...$exp, $ifIndex, $convFrom]);
            $exactConv = [];
            foreach ($q->fetchAll() as $r) {
                // Entering the switch on this port: sent by the device(s) behind it.
                $exactConv[] = ['local' => $r['src_ip'], 'remote' => $r['dst_ip'], 'proto' => (int) $r['proto'], 'port' => (int) $r['port'], 'in' => 0, 'out' => (int) $r['b']];
            }
            $exact = ['series' => $series, 'conv' => $exactConv, 'sent' => array_sum(array_column($rows, 'bi')), 'received' => array_sum(array_column($rows, 'bo'))];
        }
    }
    $base['scope'] = flow_monitor_scope($hostId);

    // --- By IP: the devices the port map puts on this port.
    $ips = [];
    foreach ($port['devices'] as $d) if ($d['ip']) $ips[$d['ip']] = true;
    if ($port['role'] !== 'uplink') foreach ($port['neighbors'] as $n) if (!empty($n['ip'])) $ips[$n['ip']] = true;
    $ips = array_keys($ips);
    if (!$ips) {
        if ($exact) {
            return $base + ['mode' => 'exact', 'received' => $exact['received'] ? 'exact' : null, 'series' => $exact['series'],
                'totals' => ['in' => $exact['received'], 'out' => $exact['sent'], 'inetIn' => null, 'inetOut' => null]]
                + portflow_breakdown($exact['conv'], $who, $names, []);
        }
        return $base + ['mode' => 'none', 'reason' => $port['status'] !== 'up' ? 'The port is down.' : 'No device with a known IP address is seen on this port.'];
    }

    $in = implode(',', array_fill(0, count($ips), '?'));
    $q = $pdo->prepare("SELECT ts - MOD(ts, $bucket) t, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_hosts WHERE ip IN ($in) AND ts >= ? GROUP BY t ORDER BY t");
    $q->execute([...$ips, $from]);
    $series = array_map(fn($r) => [(int) $r['t'], round($r['i'] * 8 / $bucket), round($r['o'] * 8 / $bucket)], $q->fetchAll());
    $q = $pdo->prepare("SELECT ip, SUM(bytes_in) i, SUM(bytes_out) o, SUM(inet_in) ii, SUM(inet_out) io FROM flow_hosts WHERE ip IN ($in) AND ts >= ? GROUP BY ip");
    $q->execute([...$ips, $from]);
    $perIp = $q->fetchAll();
    $totals = ['in' => 0, 'out' => 0, 'inetIn' => 0, 'inetOut' => 0];
    $devices = [];
    foreach ($perIp as $r) {
        $totals['in'] += $r['i']; $totals['out'] += $r['o']; $totals['inetIn'] += $r['ii']; $totals['inetOut'] += $r['io'];
        $devices[] = $who($r['ip']) + ['in' => (int) $r['i'], 'out' => (int) $r['o']];
    }
    usort($devices, fn($a, $b) => ($b['in'] + $b['out']) <=> ($a['in'] + $a['out']));

    // A port towards the router carries the internet traffic of everything (NAT hides it behind the router's address).
    $isRouter = fn($h) => ($h['device'] ?? '') === 'router';
    $toRouter = (bool) array_filter($port['devices'], fn($d) => $isRouter($d['host'] ?? null))
        || (bool) array_filter($port['neighbors'], fn($n) => $isRouter($n['host'] ?? null))
        || (bool) array_filter($port['towards'] ?? [], $isRouter);
    if ($toRouter) {
        $q = $pdo->prepare("SELECT ts - MOD(ts, $bucket) t, SUM(down_bytes) d, SUM(up_bytes) u FROM flow_totals WHERE ts >= ? GROUP BY t");
        $q->execute([$from]);
        $byT = [];
        foreach ($series as $pt) $byT[$pt[0]] = $pt;
        foreach ($q->fetchAll() as $r) {
            $t = (int) $r['t'];
            $byT[$t] = [$t, ($byT[$t][1] ?? 0) + round($r['d'] * 8 / $bucket), ($byT[$t][2] ?? 0) + round($r['u'] * 8 / $bucket)];
            $totals['in'] += $r['d']; $totals['out'] += $r['u']; $totals['inetIn'] += $r['d']; $totals['inetOut'] += $r['u'];
        }
        ksort($byT);
        $series = array_values($byT);
    }

    // Conversations: the device as the local end, or as the far end of internal traffic.
    $conv = [];
    $q = $pdo->prepare("SELECT local_ip, remote_ip, proto, port, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_conv
                        WHERE local_ip IN ($in) AND ts >= ? GROUP BY local_ip, remote_ip, proto, port ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 500");
    $q->execute([...$ips, $convFrom]);
    foreach ($q->fetchAll() as $r) $conv[] = ['local' => $r['local_ip'], 'remote' => $r['remote_ip'], 'proto' => (int) $r['proto'], 'port' => (int) $r['port'], 'in' => (int) $r['i'], 'out' => (int) $r['o']];
    $q = $pdo->prepare("SELECT local_ip, remote_ip, proto, port, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_conv
                        WHERE remote_ip IN ($in) AND local_ip NOT IN ($in) AND ts >= ? GROUP BY local_ip, remote_ip, proto, port ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 500");
    $q->execute([...$ips, ...$ips, $convFrom]);
    // Seen from the other end: its "in" is what this device sent.
    foreach ($q->fetchAll() as $r) $conv[] = ['local' => $r['remote_ip'], 'remote' => $r['local_ip'], 'proto' => (int) $r['proto'], 'port' => (int) $r['port'], 'in' => (int) $r['o'], 'out' => (int) $r['i']];
    if ($toRouter) {
        $q = $pdo->prepare("SELECT local_ip, remote_ip, proto, port, SUM(bytes_in) i, SUM(bytes_out) o FROM flow_conv WHERE ts >= ?
                            AND remote_ip NOT LIKE '10.%' AND remote_ip NOT LIKE '192.168.%' AND remote_ip NOT REGEXP '^172\\.(1[6-9]|2[0-9]|3[01])\\.'
                            AND remote_ip NOT REGEXP '^(22[4-9]|23[0-9])\\.' AND remote_ip NOT LIKE 'f%' AND remote_ip <> '255.255.255.255'
                            GROUP BY local_ip, remote_ip, proto, port ORDER BY SUM(bytes_in) + SUM(bytes_out) DESC LIMIT 800");
        $q->execute([$convFrom]);
        $inetByIp = [];
        foreach ($q->fetchAll() as $r) {
            if (in_array($r['local_ip'], $ips, true)) continue;   // already counted above
            $conv[] = ['local' => $r['local_ip'], 'remote' => $r['remote_ip'], 'proto' => (int) $r['proto'], 'port' => (int) $r['port'], 'in' => (int) $r['i'], 'out' => (int) $r['o']];
            $inetByIp[$r['local_ip']] ??= ['in' => 0, 'out' => 0];
            $inetByIp[$r['local_ip']]['in'] += $r['i'];
            $inetByIp[$r['local_ip']]['out'] += $r['o'];
        }
        foreach ($inetByIp as $ip => $t) $devices[] = $who((string) $ip) + $t;
        usort($devices, fn($a, $b) => ($b['in'] + $b['out']) <=> ($a['in'] + $a['out']));
    }

    if ($exact) {
        // Sent: exact. Received: exact too when the exporter reports output interfaces, else by IP.
        $both = $exact['received'] > 0;
        $byT = [];
        foreach ($series as $pt) $byT[$pt[0]] = [$pt[0], $both ? 0 : $pt[1], 0];
        foreach ($exact['series'] as [$t, $rcv, $sent]) $byT[$t] = [$t, $both ? $rcv : ($byT[$t][1] ?? 0), $sent];
        ksort($byT);
        $totals['out'] = $exact['sent'];
        if ($both) $totals['in'] = $exact['received'];
        $conv = $both ? [] : array_values(array_filter(array_map(fn($c) => array_merge($c, ['out' => 0]), $conv), fn($c) => $c['in'] > 0));
        return $base + ['mode' => 'exact', 'received' => $both ? 'exact' : 'ip', 'ips' => count($ips), 'internetPath' => $toRouter,
                        'series' => array_values($byT), 'totals' => $totals]
            + portflow_breakdown(array_merge($conv, $exact['conv']), $who, $names, []);
    }
    return $base + ['mode' => 'ip', 'ips' => count($ips), 'internetPath' => $toRouter, 'series' => $series, 'totals' => $totals]
        + portflow_breakdown($conv, $who, $names, $devices);
}

/** Top services, far ends and conversations from a list of {local, remote, proto, port, in, out}. */
function portflow_breakdown(array $conv, callable $who, array $names, array $devices): array {
    $isLocal = fn(string $ip) => (bool) preg_match('/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|f[cd]|fe80)/i', $ip);
    $isNoise = fn(string $ip) => (bool) preg_match('/^(22[4-9]|23\d)\.|^255\.255\.255\.255$|^ff/i', $ip);
    $services = [];
    $remotes = [];
    $byLocal = [];
    foreach ($conv as $c) {
        $svc = flow_service_name($c['proto'], $c['port']);
        $services[$svc] ??= ['name' => $svc, 'in' => 0, 'out' => 0];
        $services[$svc]['in'] += $c['in'];
        $services[$svc]['out'] += $c['out'];
        if (!$isNoise($c['remote'])) {
            $remotes[$c['remote']] ??= ['ip' => $c['remote'], 'local' => $isLocal($c['remote']), 'name' => $names[$c['remote']]['name'] ?? null,
                                        'hostId' => $names[$c['remote']]['hostId'] ?? null, 'in' => 0, 'out' => 0, 'services' => []];
            $remotes[$c['remote']]['in'] += $c['in'];
            $remotes[$c['remote']]['out'] += $c['out'];
            $remotes[$c['remote']]['services'][$svc] = ($remotes[$c['remote']]['services'][$svc] ?? 0) + $c['in'] + $c['out'];
        }
        if (!$devices) {
            $byLocal[$c['local']] ??= ['in' => 0, 'out' => 0];
            $byLocal[$c['local']]['in'] += $c['in'];
            $byLocal[$c['local']]['out'] += $c['out'];
        }
    }
    if (!$devices) foreach ($byLocal as $ip => $t) $devices[] = $who((string) $ip) + $t;
    $sortTotal = fn($a, $b) => ($b['in'] + $b['out']) <=> ($a['in'] + $a['out']);
    usort($devices, $sortTotal);
    $services = array_values($services);
    usort($services, $sortTotal);
    $remotes = array_values($remotes);
    usort($remotes, $sortTotal);
    foreach ($remotes as &$r) { arsort($r['services']); $r['services'] = array_slice(array_keys($r['services']), 0, 3); }
    unset($r);
    usort($conv, $sortTotal);
    $conv = array_map(fn($c) => ['local' => $who($c['local']), 'remote' => $c['remote'], 'remoteLocal' => $isLocal($c['remote']),
        'remoteName' => $names[$c['remote']]['name'] ?? null, 'remoteHostId' => $names[$c['remote']]['hostId'] ?? null,
        'service' => flow_service_name($c['proto'], $c['port']), 'in' => $c['in'], 'out' => $c['out']],
        array_values(array_filter(array_slice($conv, 0, 60), fn($c) => !$isNoise($c['remote']))));
    return ['devices' => array_slice($devices, 0, 15), 'services' => array_slice($services, 0, 10), 'remotes' => array_slice($remotes, 0, 12),
            'conversations' => array_slice($conv, 0, 20)];
}

/**
 * NetFlow a device exports, per interface: [{ifIndex, name, physical, in, out, flows}], plus
 * whether its flow monitors are on physical ports (exact per-port data) or only on VLAN interfaces.
 */
function device_flow_interfaces(int $hostId, string $range): array {
    [$span] = PORTFLOW_RANGES[$range] ?? PORTFLOW_RANGES['1h'];
    if (!portflow_tables_ready()) return ['exporter' => false, 'interfaces' => []];
    $pdo = db();
    $exp = device_exporter_ips($hostId);
    $in = implode(',', array_fill(0, count($exp), '?'));
    $q = $pdo->prepare("SELECT if_index, SUM(CASE WHEN dir = 'i' THEN bytes ELSE 0 END) bi, SUM(CASE WHEN dir = 'o' THEN bytes ELSE 0 END) bo, SUM(flows) f
                        FROM flow_ifaces WHERE exporter IN ($in) AND ts >= ? GROUP BY if_index ORDER BY SUM(bytes) DESC");
    $q->execute([...$exp, time() - $span]);
    $rows = $q->fetchAll();
    // Not exporting (yet): is it one of the collector's exporters at all?
    $status = json_decode((string) $pdo->query("SELECT v FROM settings WHERE k = 'flow_status'")->fetchColumn(), true);
    $isExporter = (bool) array_intersect($exp, array_keys($status['exporters'] ?? []));
    if (!$rows) return ['exporter' => $isExporter, 'interfaces' => [], 'physical' => false];
    $st = $pdo->prepare('SELECT * FROM hosts WHERE id = ?');
    $st->execute([$hostId]);
    $names = device_if_names($st->fetch());
    $phys = port_map_ifindexes([$hostId])[$hostId] ?? [];
    // The suggested change, from its configuration backup: the flow monitor in use, applied to its port ranges.
    $st = $pdo->prepare('SELECT content FROM switch_configs WHERE host_id = ? ORDER BY fetched_at DESC LIMIT 1');
    $st->execute([$hostId]);
    $cfg = (string) $st->fetchColumn();
    $monitor = preg_match('/^\s*ip flow monitor (\S+) input/m', $cfg, $m) ? $m[1] : (preg_match('/^flow monitor (\S+)/m', $cfg, $m) ? $m[1] : null);
    $ranges = [];
    $st = $pdo->prepare('SELECT data FROM port_maps WHERE host_id = ?');
    $st->execute([$hostId]);
    foreach (json_decode((string) $st->fetchColumn(), true)['ports'] ?? [] as $p) {
        if (preg_match('#^(.*/)(\d+)$#', $p['name'], $m)) $ranges[$m[1]][] = (int) $m[2];
    }
    $suggest = [];
    foreach ($ranges as $prefix => $nums) $suggest[] = 'interface range ' . $prefix . min($nums) . ' - ' . max($nums) . "\n ip flow monitor " . ($monitor ?? '<monitor name>') . ' input';
    $out = array_map(fn($r) => ['ifIndex' => (int) $r['if_index'], 'name' => $names[(int) $r['if_index']] ?? 'if' . $r['if_index'],
        'physical' => isset($phys[(int) $r['if_index']]), 'in' => (int) $r['bi'], 'out' => (int) $r['bo'], 'flows' => (int) $r['f']], $rows);
    return ['exporter' => true, 'interfaces' => $out, 'physical' => (bool) array_filter($out, fn($i) => $i['physical']),
            'monitor' => $monitor, 'scope' => flow_monitor_scope($hostId), 'suggest' => implode("\n", $suggest)];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/portmap.php")"
cat > "$APP_DIR/includes/portmap.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/switchinfo.php';   // snmp_walk(), Cisco VLAN OIDs

/**
 * Switch port map: every physical port with its state, speed, VLAN, and
 * what's plugged into it.
 *
 *   - Neighbours (other switches, APs, phones) from CDP and LLDP.
 *   - Devices from the MAC address table (BRIDGE-MIB; per VLAN on Cisco,
 *     where each VLAN is its own SNMP context, "community@vlan").
 *   - MAC -> IP from the ARP tables of every switch that routes (stored
 *     with each map), this server's ARP cache and agent-reported MACs; IP
 *     -> the WebMonitor card.
 *
 * A port with a switch neighbour, trunking, or many MACs is an uplink: its
 * MACs are counted, not listed (they're devices further away).
 */

const PORTMAP_MAX_AGE_SEC = 900;      // background refresh
const PORTMAP_UPLINK_MACS = 20;       // more MACs than this on a port with no neighbour info: probably another switch

const OID_IF_TYPE = '.1.3.6.1.2.1.2.2.1.3';
const OID_IF_ADMIN = '.1.3.6.1.2.1.2.2.1.7';
const OID_IF_ALIAS = '.1.3.6.1.2.1.31.1.1.1.18';
const OID_IF_HIGH_SPEED = '.1.3.6.1.2.1.31.1.1.1.15';
const OID_BRIDGE_PORT_IFINDEX = '.1.3.6.1.2.1.17.1.4.1.2';
const OID_FDB_ADDRESS = '.1.3.6.1.2.1.17.4.3.1.1';
const OID_FDB_PORT = '.1.3.6.1.2.1.17.4.3.1.2';
const OID_LAG_MEMBER = '.1.2.840.10006.300.43.1.2.1.1.13';      // dot3adAggPortAttachedAggID: member ifIndex -> port-channel ifIndex
const OID_FDB_STATUS = '.1.3.6.1.2.1.17.4.3.1.3';
const OID_Q_PVID = '.1.3.6.1.2.1.17.7.1.4.5.1.1';
const OID_ARP = '.1.3.6.1.2.1.4.22.1.2';
const OID_IF_PHYS = '.1.3.6.1.2.1.2.2.1.6';
const OID_IP_ADDR_IF = '.1.3.6.1.2.1.4.20.1.2';
const OID_IP_ADDR_MASK = '.1.3.6.1.2.1.4.20.1.3';
const OID_CISCO_TRUNK = '.1.3.6.1.4.1.9.9.46.1.6.1.1.14';      // vlanTrunkPortDynamicStatus: 1 trunking
const OID_CISCO_VTP_STATE = '.1.3.6.1.4.1.9.9.46.1.3.1.1.2';    // vtpVlanState: 1 operational
const OID_CDP = '.1.3.6.1.4.1.9.9.23.1.2.1.1';                   // .4 address .6 device id .7 port .8 platform
const OID_LLDP_REM = '.1.0.8802.1.1.2.1.4.1.1';                  // .5 chassis .7 port id .8 port desc .9 sys name
const OID_LLDP_LOC_PORT_ID = '.1.0.8802.1.1.2.1.3.7.1.3';

/** "aa:bb:cc:dd:ee:ff" from raw bytes, hex strings or dotted decimals. */
function normalize_mac(string $v): ?string {
    if (strlen($v) === 6 && !ctype_print($v)) return implode(':', str_split(bin2hex($v), 2));
    if (preg_match('/^([0-9a-f]{1,2}[:-]){5}[0-9a-f]{1,2}$/i', trim($v))) {   // "0:10:f3:87:7c:cb"
        return strtolower(implode(':', array_map(fn($o) => str_pad($o, 2, '0', STR_PAD_LEFT), preg_split('/[:-]/', trim($v)))));
    }
    $hex = strtolower(preg_replace('/[^0-9a-fA-F]/', '', preg_replace('/^(Hex-)?STRING:\s*/i', '', $v)));
    if (strlen($hex) === 12) return implode(':', str_split($hex, 2));
    $parts = explode('.', $v);
    if (count($parts) === 6 && array_filter($parts, 'ctype_digit') === $parts) {
        return implode(':', array_map(fn($n) => sprintf('%02x', (int) $n), $parts));
    }
    return null;
}

/** IPv4 from raw 4 bytes or a hex string ("0A 0D 5A 0B"). */
function snmp_ipv4(string $v): ?string {
    if (strlen($v) === 4 && !ctype_print($v)) return inet_ntop($v);
    if (filter_var($v, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) return $v;
    $hex = preg_replace('/[^0-9a-fA-F]/', '', preg_replace('/^(Hex-)?STRING:\s*/i', '', $v));
    return strlen($hex) === 8 ? long2ip((int) hexdec($hex)) : null;
}

/** [suffix => [col => value]] for a table walked at TABLE.entry. */
function snmp_columns(string $ip, string $community, string $entry, array $cols, float $t): array {
    $rows = [];
    foreach ($cols as $c) {
        foreach (snmp_walk($ip, $community, "$entry.$c", $t) as $suffix => $v) $rows[$suffix][$c] = (string) $v;
    }
    return $rows;
}

/** Is this interface a front-panel port (not a VLAN interface, loopback, tunnel, stack port, ...)? */
function is_physical_port(int $type, string $name): bool {
    if ($type !== 6 && $type !== 117 && $type !== 62) return false;   // ethernetCsmacd, gigabitEthernet, fastEther
    return !preg_match('/^(Vl|Vlan|Lo|Nu|Tu|Ap|Gi0\/0$|Bluetooth|StackPort|StackSub|mgmt|internal|NVE)/i', $name);
}

/**
 * Collects the raw port map of a switch over SNMP (a few seconds; the MAC
 * table is walked once per VLAN on Cisco).
 */
function collect_port_map(array $host): array {
    $ip = $host['ip_address'];
    $c = $host['community'] !== '' ? $host['community'] : 'public';
    $t = 3.0;

    $names = snmp_walk($ip, $c, OID_IF_NAME, $t) ?: snmp_walk($ip, $c, OID_IF_DESCR, $t);
    if (!$names) throw new RuntimeException('the switch did not answer SNMP (check the community in Edit)');
    $types = snmp_walk($ip, $c, OID_IF_TYPE, $t);
    $oper = snmp_walk($ip, $c, OID_IF_OPER_STATUS, $t);
    $admin = snmp_walk($ip, $c, OID_IF_ADMIN, $t);
    $alias = snmp_walk($ip, $c, OID_IF_ALIAS, $t);
    $speed = snmp_walk($ip, $c, OID_IF_HIGH_SPEED, $t);
    $vmVlan = snmp_walk($ip, $c, OID_CISCO_VLAN_PORT, $t);
    $physAddr = snmp_walk($ip, $c, OID_IF_PHYS, $t);
    $trunk = snmp_walk($ip, $c, OID_CISCO_TRUNK, $t);
    $isCisco = (bool) $vmVlan || (bool) $trunk;

    $ports = [];
    foreach ($names as $idx => $name) {
        $name = (string) $name;
        if (!is_physical_port((int) ($types[$idx] ?? 0), $name)) continue;
        $o = (string) ($oper[$idx] ?? '');
        $ports[(int) $idx] = [
            'ifIndex' => (int) $idx, 'name' => $name,
            'description' => trim((string) ($alias[$idx] ?? '')),
            'status' => (string) ($admin[$idx] ?? '') === '2' ? 'disabled' : ($o === '1' ? 'up' : ($o === '2' || $o === '7' ? 'down' : 'other')),
            'speedMbps' => isset($speed[$idx]) && (int) $speed[$idx] > 0 ? (int) $speed[$idx] : null,
            'vlan' => isset($vmVlan[$idx]) && is_numeric($vmVlan[$idx]) ? (int) $vmVlan[$idx] : null,
            'trunk' => (string) ($trunk[$idx] ?? '') === '1',
            'lag' => null, 'macs' => [], 'neighbors' => [],
            'mac' => normalize_mac((string) ($physAddr[$idx] ?? '')), 'ips' => [], 'subs' => [],
        ];
    }

    // Routers and firewalls: VLAN sub-interfaces ("ix0.10", "Gi0/1.20") belong to their port.
    $parentOf = [];
    $nameToIdx = array_flip(array_map(fn($p) => $p['name'], $ports));
    foreach ($names as $idx => $name) {
        if (isset($ports[(int) $idx]) || !preg_match('/^(.+)\.(\d{1,4})$/', (string) $name, $m) || !isset($nameToIdx[$m[1]])) continue;
        $parentOf[(int) $idx] = [$nameToIdx[$m[1]], (int) $m[2]];
        $ports[$nameToIdx[$m[1]]]['subs'][(int) $idx] = ['name' => (string) $name, 'vlan' => (int) $m[2], 'ips' => []];
    }
    // Interface addresses ("192.168.10.254/24"), on the port or its sub-interface.
    $masks = snmp_walk($ip, $c, OID_IP_ADDR_MASK, $t);
    foreach (snmp_walk($ip, $c, OID_IP_ADDR_IF, $t) as $addr => $ifi) {
        $addr = (string) $addr;
        if (!filter_var($addr, FILTER_VALIDATE_IP) || str_starts_with($addr, '127.') || $addr === '0.0.0.0') continue;
        $mask = (string) ($masks[$addr] ?? '');
        $cidr = $addr . (filter_var($mask, FILTER_VALIDATE_IP) ? '/' . substr_count(decbin(ip2long($mask)), '1') : '');
        $ifi = (int) $ifi;
        if (isset($ports[$ifi])) $ports[$ifi]['ips'][] = $cidr;
        elseif (isset($parentOf[$ifi])) $ports[$parentOf[$ifi][0]]['subs'][$ifi]['ips'][] = $cidr;
    }

    // Port-channels: MACs are learned on the channel, so show them on its member ports.
    $lagMembers = [];
    foreach (snmp_walk($ip, $c, OID_LAG_MEMBER, $t) as $member => $agg) {
        if ((int) $agg > 0 && isset($ports[(int) $member])) {
            $lagMembers[(int) $agg][] = (int) $member;
            $ports[(int) $member]['lag'] = (string) ($names[(int) $agg] ?? "LAG $agg");
        }
    }

    // MAC address table, per VLAN context on Cisco.
    $contexts = [''];
    if ($isCisco) {
        $contexts = [];
        foreach (snmp_walk($ip, $c, OID_CISCO_VTP_STATE, $t) as $suffix => $state) {
            $vlan = (int) substr((string) $suffix, strrpos((string) $suffix, '.') + 1);
            if ((string) $state === '1' && $vlan >= 1 && ($vlan < 1002 || $vlan > 1005)) $contexts[] = (string) $vlan;
        }
    }
    $pvidByBridgePort = snmp_walk($ip, $c, OID_Q_PVID, $t);
    foreach ($contexts as $vlan) {
        $comm = $vlan === '' ? $c : "$c@$vlan";
        $bpIf = snmp_walk($ip, $comm, OID_BRIDGE_PORT_IFINDEX, $t);
        if ($vlan === '') {
            foreach ($pvidByBridgePort as $bp => $pvid) {
                $if = (int) ($bpIf[$bp] ?? 0);
                if (isset($ports[$if]) && $ports[$if]['vlan'] === null && is_numeric($pvid)) $ports[$if]['vlan'] = (int) $pvid;
            }
        }
        $status = snmp_walk($ip, $comm, OID_FDB_STATUS, $t);
        // The table is normally indexed by the MAC itself; some switches (FortiSwitch)
        // number the rows instead, so the address column is read too.
        $addr = snmp_walk($ip, $comm, OID_FDB_ADDRESS, $t);
        foreach (snmp_walk($ip, $comm, OID_FDB_PORT, $t) as $key => $bp) {
            if (isset($status[$key]) && (string) $status[$key] !== '3') continue;   // only learned entries
            $if = (int) ($bpIf[(string) $bp] ?? $bp);
            $mac = isset($addr[$key]) ? normalize_mac((string) $addr[$key]) : null;
            $mac ??= normalize_mac((string) $key);
            if (!$mac) continue;
            $v = $vlan !== '' ? (int) $vlan : null;
            foreach (isset($lagMembers[$if]) ? $lagMembers[$if] : [$if] as $pif) {
                if (isset($ports[$pif])) $ports[$pif]['macs'][$mac] = $v ?? $ports[$pif]['vlan'];
            }
        }
    }

    // Neighbours: CDP (Cisco) and LLDP.
    foreach (snmp_columns($ip, $c, OID_CDP, [4, 6, 7, 8], $t) as $suffix => $r) {
        $if = (int) explode('.', (string) $suffix)[0];
        if (!isset($ports[$if]) || empty($r[6])) continue;
        $ports[$if]['neighbors'][] = ['via' => 'CDP', 'name' => $r[6], 'port' => short_port_name($r[7] ?? ''), 'platform' => $r[8] ?? '',
                                     'ip' => isset($r[4]) ? snmp_ipv4($r[4]) : null];
    }
    $locPort = snmp_walk($ip, $c, OID_LLDP_LOC_PORT_ID, $t);
    $nameToIf = array_flip(array_map(fn($p) => $p['name'], $ports));
    foreach (snmp_columns($ip, $c, OID_LLDP_REM, [5, 7, 8, 9], $t) as $suffix => $r) {
        $parts = explode('.', (string) $suffix);   // timeMark.localPortNum.index
        $local = (int) ($parts[1] ?? 0);
        $locId = (string) ($locPort[$local] ?? '');
        $if = $nameToIf[$locId] ?? (isset($ports[$local]) ? $local : null);
        if ($if === null) continue;
        $sys = trim($r[9] ?? '');
        $chassis = normalize_mac($r[5] ?? '');
        if ($sys === '' && !$chassis) continue;
        $ports[$if]['neighbors'][] = ['via' => 'LLDP', 'name' => $sys !== '' ? $sys : $chassis, 'port' => trim($r[8] ?? '') ?: trim($r[7] ?? ''),
                                     'platform' => '', 'ip' => null, 'mac' => $chassis];
    }

    // ARP table: MAC -> IP for every map (the switch may route for other VLANs). On a port
    // or sub-interface (routers, firewalls) it's also what's connected there.
    $arp = [];
    foreach (snmp_walk($ip, $c, OID_ARP, $t) as $suffix => $v) {
        $parts = explode('.', (string) $suffix);
        $addr = implode('.', array_slice($parts, -4));
        $mac = normalize_mac((string) $v);
        if (!$mac || !filter_var($addr, FILTER_VALIDATE_IP)) continue;
        $arp[$mac] = $addr;
        $ifi = (int) $parts[0];
        [$pif, $vlan] = isset($ports[$ifi]) ? [$ifi, $ports[$ifi]['vlan']] : ($parentOf[$ifi] ?? [null, null]);
        if ($pif !== null && !isset($ports[$pif]['macs'][$mac])) $ports[$pif]['macs'][$mac] = $vlan;
    }

    foreach ($ports as &$p) {
        $p['subs'] = array_values($p['subs']);
        ksort($p['macs']);
        $p['macs'] = array_map(fn($m, $v) => ['mac' => $m, 'vlan' => $v], array_keys($p['macs']), $p['macs']);
    }
    unset($p);
    return ['ports' => array_values($ports), 'arp' => $arp, 'vlans' => get_switch_vlans($ip, $c, $t)];
}

/** "TenGigabitEthernet1/0/1" -> "Te1/0/1", like the switch's own ifName. */
function short_port_name(string $name): string {
    return preg_replace(['/^HundredGigE/i', '/^FortyGigabitEthernet/i', '/^TwentyFiveGigE/i', '/^TenGigabitEthernet/i',
        '/^GigabitEthernet/i', '/^FastEthernet/i', '/^Port-channel/i'], ['Hu', 'Fo', 'Twe', 'Te', 'Gi', 'Fa', 'Po'], $name);
}

function save_port_map(int $hostId, array $map): void {
    db()->prepare('INSERT INTO port_maps (host_id, collected_at, data) VALUES (?, ?, ?)
                   ON DUPLICATE KEY UPDATE collected_at = VALUES(collected_at), data = VALUES(data)')
        ->execute([$hostId, (int) round(microtime(true) * 1000), json_encode($map)]);
}

/** MAC -> IP from every stored switch ARP table, this server's ARP cache and agents. */
function known_mac_ips(): array {
    $pdo = db();
    // Switch ARP tables, oldest first, so the newest answer wins; and an IP that a newer table
    // gives to a different MAC is no longer that old MAC's (e.g. after fixing an IP conflict).
    $map = [];
    $ipOwner = [];
    foreach ($pdo->query('SELECT data FROM port_maps ORDER BY collected_at') as $r) {
        foreach ((json_decode($r['data'], true)['arp'] ?? []) as $mac => $ip) {
            $map[$mac] = $ip;
            $ipOwner[$ip] = $mac;
        }
    }
    foreach ($map as $mac => $ip) if ($ipOwner[$ip] !== $mac) unset($map[$mac]);
    foreach (json_decode((string) $pdo->query("SELECT v FROM settings WHERE k = 'arp_cache'")->fetchColumn(), true) ?: [] as $mac => $ip) {
        $map[strtolower($mac)] = $ip;
    }
    foreach ($pdo->query('SELECT a.metrics, h.ip_address FROM agents a JOIN hosts h ON h.id = a.host_id WHERE a.metrics IS NOT NULL') as $r) {
        foreach ((json_decode($r['metrics'], true)['network'] ?? []) as $if) {
            $mac = normalize_mac((string) ($if['mac'] ?? ''));
            if ($mac && !isset($map[$mac])) $map[$mac] = $r['ip_address'];
        }
    }
    return $map;
}

/**
 * The stored map with names filled in: each MAC gets its IP and WebMonitor
 * card, each neighbour its card, and each port a role (uplink/device/empty).
 */
function port_map_view(int $hostId): ?array {
    $pdo = db();
    $stmt = $pdo->prepare('SELECT collected_at, data FROM port_maps WHERE host_id = ?');
    $stmt->execute([$hostId]);
    $row = $stmt->fetch();
    if (!$row) return null;
    $map = json_decode($row['data'], true);

    $macIp = known_mac_ips();
    $hostsByIp = [];
    $hostsByName = [];
    foreach ($pdo->query('SELECT id, name, ip_address, device FROM hosts') as $h) {
        $hostsByIp[$h['ip_address']] = $h;
        $hostsByName[strtolower(explode('.', $h['name'])[0])] ??= $h;
    }
    $card = fn(?array $h) => $h ? ['id' => (int) $h['id'], 'name' => $h['name'], 'ip' => $h['ip_address'], 'device' => $h['device']] : null;

    // APs' real MACs (from the Wi-Fi controller): another MAC answering on an AP's IP is a
    // different device using the same address, not the AP.
    $apMacByIp = [];
    foreach ($pdo->query('SELECT data FROM wlan_maps') as $w) {
        foreach (json_decode($w['data'], true)['aps'] ?? [] as $a) if ($a['ip']) $apMacByIp[$a['ip']] = $a['mac'];
    }

    // This device's own addresses (its ARP table lists them too).
    $ownIps = [];
    foreach ($map['ports'] as $op) foreach (array_merge($op['ips'] ?? [], ...array_map(fn($x) => $x['ips'], $op['subs'] ?? [])) as $cidr) {
        $ownIps[explode('/', $cidr)[0]] = true;
    }
    $self = $pdo->prepare('SELECT ip_address FROM hosts WHERE id = ?');
    $self->execute([$hostId]);
    $ownIps[(string) $self->fetchColumn()] = true;

    // Where each of this device's own ports is plugged in: a port on another switch that
    // learned the port's MAC directly (not through an uplink full of other devices).
    $pluggedInto = [];
    $seesMe = [];   // other devices with any of this device's MACs on one of their ports
    $allOwn = array_flip(array_filter(array_column($map['ports'], 'mac')));
    $ownMacs = array_count_values(array_filter(array_column(array_filter($map['ports'], fn($p) => $p['status'] === 'up'), 'mac')));
    if ($allOwn) {
        $others = $pdo->prepare('SELECT m.host_id, m.data, h.name, h.ip_address, h.device FROM port_maps m JOIN hosts h ON h.id = m.host_id WHERE m.host_id <> ?');
        $others->execute([$hostId]);
        foreach ($others as $o) {
            foreach (json_decode($o['data'], true)['ports'] ?? [] as $op) {
                foreach ($op['macs'] as $m) if (isset($allOwn[$m['mac']])) $seesMe[(int) $o['host_id']] = true;
                if (count($op['macs']) > 3 || ($op['trunk'] ?? false) && count($op['macs']) > 1) continue;
                foreach ($op['macs'] as $m) {
                    if (($ownMacs[$m['mac']] ?? 0) !== 1) continue;   // shared by several ports: can't tell which
                    $key = strtolower(explode('.', $o['name'])[0]) . '|' . $op['name'];   // one switch, several addresses
                    $pluggedInto[$m['mac']][$key] = ['host' => $card(['id' => $o['host_id'], 'name' => $o['name'], 'ip_address' => $o['ip_address'], 'device' => $o['device']]),
                                                     'port' => $op['name'], 'description' => $op['description']];
                }
            }
        }
    }

    foreach ($map['ports'] as &$p) {
        foreach ($p['neighbors'] as &$n) {
            $n['port'] = short_port_name((string) $n['port']);
            $h = ($n['ip'] ?? null) ? ($hostsByIp[$n['ip']] ?? null) : null;
            $h ??= $hostsByName[strtolower(explode('.', (string) $n['name'])[0])] ?? null;
            $n['host'] = $card($h);
        }
        unset($n);
        $p['pluggedInto'] = $p['mac'] && $p['status'] === 'up' ? array_values($pluggedInto[$p['mac']] ?? []) : [];
        $p['macCount'] = count($p['macs']);
        // Uplink: a switch on the other end (CDP/LLDP), or so many MACs it must be one.
        $switchNeighbor = array_filter($p['neighbors'], fn($n) => in_array($n['host']['device'] ?? '', ['switch', 'router'], true)
            || preg_match('/switch|catalyst|fortiswitch|C2960|C3850|C9[23]00|WS-C|FS-\d/i', $n['platform'] . ' ' . $n['name']));
        $intoSwitch = array_filter($p['pluggedInto'], fn($x) => in_array($x['host']['device'], ['switch', 'router'], true));
        $uplink = $switchNeighbor || $intoSwitch || ($p['macCount'] > PORTMAP_UPLINK_MACS && !$p['neighbors']);
        $p['role'] = $p['status'] !== 'up' ? 'empty' : ($uplink ? 'uplink' : ($p['macCount'] || $p['neighbors'] ? 'device' : 'unknown'));
        $devices = [];
        foreach ($p['macs'] as $m) {
            $ip = $macIp[$m['mac']] ?? null;
            if ($m['mac'] === $p['mac'] || ($ip !== null && isset($ownIps[$ip]))) continue;   // the device itself
            $conflict = $ip !== null && isset($apMacByIp[$ip]) && $apMacByIp[$ip] !== $m['mac'];
            $devices[] = ['mac' => $m['mac'], 'vlan' => $m['vlan'], 'ip' => $ip, 'host' => $conflict ? null : $card($ip ? ($hostsByIp[$ip] ?? null) : null),
                          'note' => $conflict ? 'IP conflict: ' . ($hostsByIp[$ip]['name'] ?? 'an AP') . ' also uses ' . $ip : null];
        }
        // Known cards first, then by IP.
        usort($devices, fn($a, $b) => [$a['host'] === null, $a['ip'] === null, ip2long($a['ip'] ?? '0.0.0.0')]
                                   <=> [$b['host'] === null, $b['ip'] === null, ip2long($b['ip'] ?? '0.0.0.0')]);
        $p['devices'] = $devices;
        if ($p['role'] === 'device' && !$devices && !$p['neighbors'] && !$p['pluggedInto']) $p['role'] = 'unknown';
        // A port that leads to another monitored switch is an uplink to it, even when
        // CDP/LLDP doesn't say so (e.g. Cisco to FortiSwitch).
        if ($p['status'] === 'up' && !$switchNeighbor) {
            $sw = array_values(array_filter($devices, fn($d) => in_array($d['host']['device'] ?? '', ['switch', 'router'], true)
                && $d['host']['id'] !== $hostId));
            if ($sw) {
                // Several switches can sit beyond one port: the next one is the one that also
                // sees this device on one of its ports.
                $next = array_values(array_filter($sw, fn($d) => isset($seesMe[$d['host']['id']])));
                $p['role'] = 'uplink';
                $p['towards'] = array_map(fn($d) => $d['host'], $next ?: [$sw[0]]);
            }
        }
        unset($p['macs']);
    }
    unset($p);
    return ['collectedAt' => (int) $row['collected_at'], 'ports' => $map['ports'], 'vlans' => (object) ($map['vlans'] ?? [])];
}

/** Background refresh of switch port maps (cli/poll-snmp.php). */
function refresh_port_maps(): void {
    $pdo = db();
    $due = $pdo->prepare("SELECT h.* FROM hosts h LEFT JOIN port_maps m ON m.host_id = h.id
                          WHERE h.device IN ('switch', 'router') AND (m.collected_at IS NULL OR m.collected_at < ?)");
    $due->execute([(int) round(microtime(true) * 1000) - PORTMAP_MAX_AGE_SEC * 1000]);
    $any = false;
    foreach ($due->fetchAll() as $h) {
        try {
            save_port_map((int) $h['id'], collect_port_map($h));
            $any = true;
        } catch (Throwable $e) {
            // Unreachable or no SNMP: try again next time.
        }
    }
    if ($any) update_port_summaries();
}

// ---- Card strip ----

/** Role codes for the card strip: d device, n link up/nothing seen, u uplink, e free, x disabled. */
const PORT_ROLE_CODES = ['device' => 'd', 'unknown' => 'n', 'uplink' => 'u', 'empty' => 'e'];

/**
 * Recomputes the compact port strips shown on switch cards. Roles depend on
 * the other switches' maps (uplinks, "plugged into"), so all are redone
 * together after a refresh.
 */
function update_port_summaries(): void {
    $pdo = db();
    $save = $pdo->prepare('UPDATE port_maps SET summary = ? WHERE host_id = ?');
    foreach ($pdo->query('SELECT host_id FROM port_maps')->fetchAll(PDO::FETCH_COLUMN) as $id) {
        $v = port_map_view((int) $id);
        if (!$v) continue;
        $strip = [];
        foreach ($v['ports'] as $p) {
            $code = $p['status'] === 'disabled' ? 'x' : (PORT_ROLE_CODES[$p['role']] ?? 'e');
            $strip[] = [$p['name'], $code, count($p['devices'])];
        }
        $save->execute([json_encode(['at' => $v['collectedAt'], 'ports' => $strip]), $id]);
    }
}

/** [hostId => strip] for host summaries. */
function port_summaries(): array {
    $out = [];
    foreach (db()->query('SELECT host_id, summary FROM port_maps WHERE summary IS NOT NULL') as $r) {
        $out[(int) $r['host_id']] = json_decode($r['summary'], true);
    }
    return $out;
}

// ---- Network topology report ----

/**
 * The whole network as a tree: network devices (switches, routers) joined
 * by the links their port maps show, and under each one what's plugged into
 * its ports, with Proxmox guests under their host.
 *
 * Several cards for one switch (e.g. one per VLAN address) are merged: a
 * switch is identified by its ports' MAC addresses.
 */
function network_topology(): array {
    require_once __DIR__ . '/topology.php';
    $pdo = db();
    $hosts = [];
    foreach ($pdo->query('SELECT id, name, ip_address, device FROM hosts') as $h) $hosts[(int) $h['id']] = $h;
    $withBackup = array_flip(array_map('intval', $pdo->query('SELECT host_id FROM config_backup_settings')->fetchAll(PDO::FETCH_COLUMN)));
    $vendors = function_exists('vendor_summaries') ? vendor_summaries() : [];

    // One entry per physical device.
    $views = [];
    $groups = [];
    foreach ($pdo->query('SELECT host_id FROM port_maps')->fetchAll(PDO::FETCH_COLUMN) as $id) {
        $id = (int) $id;
        if (!isset($hosts[$id]) || !($v = port_map_view($id))) continue;
        $views[$id] = $v;
        $macs = array_values(array_unique(array_filter(array_column($v['ports'], 'mac'))));
        sort($macs);
        $groups[$macs ? md5(implode(',', $macs)) : "host$id"][] = $id;
    }
    $canon = [];
    $nodes = [];
    foreach ($groups as $ids) {
        // The card with a configuration backup, else the oldest card.
        usort($ids, fn($a, $b) => [!isset($withBackup[$a]), $a] <=> [!isset($withBackup[$b]), $b]);
        $main = $ids[0];
        foreach ($ids as $id) $canon[$id] = $main;
        $h = $hosts[$main];
        $ports = $views[$main]['ports'];
        $nodes[$main] = [
            'id' => $main, 'name' => $h['name'], 'ip' => $h['ip_address'], 'device' => $h['device'], 'vendor' => $vendors[$main] ?? null,
            'model' => null, 'aliases' => array_values(array_map(fn($i) => $hosts[$i]['ip_address'], array_slice($ids, 1))),
            'portsTotal' => count($ports), 'portsUp' => count(array_filter($ports, fn($p) => $p['status'] === 'up')),
            'collectedAt' => $views[$main]['collectedAt'], 'ports' => [],
        ];
    }

    // Links between network devices, with the port at each end when known.
    $links = [];
    $addLink = function (int $a, ?string $pa, int $b, ?string $pb) use (&$links) {
        if ($a === $b) return;
        $key = min($a, $b) . '-' . max($a, $b);
        $links[$key] ??= ['a' => min($a, $b), 'b' => max($a, $b), 'ports' => []];
        if ($pa !== null) $links[$key]['ports'][$a] ??= $pa;
        if ($pb !== null) $links[$key]['ports'][$b] ??= $pb;
    };
    foreach ($nodes as $nid => &$node) {
        foreach ($views[$nid]['ports'] as $p) {
            if ($p['status'] !== 'up') continue;
            $local = $p['lag'] ? "{$p['lag']}" : $p['name'];
            foreach ($p['neighbors'] as $n) {
                if (($hid = $n['host']['id'] ?? null) && isset($canon[$hid])) {
                    $addLink($nid, $local, $canon[$hid], $n['port'] ?: null);
                    if ($n['platform'] !== '') $nodes[$canon[$hid]]['model'] ??= $n['platform'];
                }
            }
            foreach ($p['pluggedInto'] as $x) {
                if (isset($canon[$x['host']['id']])) $addLink($nid, $local, $canon[$x['host']['id']], $x['port']);
            }
            foreach ($p['towards'] ?? [] as $t) {
                if (isset($canon[$t['id']])) $addLink($nid, $local, $canon[$t['id']], null);
            }
        }
    }
    unset($node);

    // What's plugged into each device's ports (uplinks excluded: those devices are further away).
    $topo = build_topology();
    $placed = [];   // host id -> true, so a device shows once
    require_once __DIR__ . '/wireless.php';
    $wifi = wireless_overview();
    $wifiClientMacs = array_flip(array_column($wifi['clients'], 'mac'));
    $clientsByAp = [];
    foreach ($wifi['clients'] as $cl) if ($cl['ap']) $clientsByAp[$cl['ap']][] = $cl;
    // APs with a card whose switch port is known get their own box under that switch.
    $apNodes = [];
    foreach ($wifi['aps'] as $mac => $ap) {
        if ($ap['card'] && $ap['uplink'] && isset($canon[$ap['uplink']['switch']['id']]) && !isset($nodes[$ap['card']['id']])) $apNodes[$mac] = $ap;
    }
    $isGuest = fn(?int $id) => $id !== null && isset($topo['parents'][$id]);
    foreach ($nodes as $nid => &$node) {
        $byPort = [];
        foreach ($views[$nid]['ports'] as $p) {
            if ($p['status'] !== 'up' || $p['role'] === 'uplink') continue;
            $portName = $p['lag'] ?: $p['name'];
            foreach ($p['devices'] as $d) {
                $hid = $d['host']['id'] ?? null;
                if (isset($wifiClientMacs[$d['mac']]) || isset($apNodes[$d['mac']])) continue;   // shown under / as its AP
                if ($hid !== null && (isset($canon[$hid]) || isset($placed[$hid]) || $isGuest($hid))) continue;
                if ($hid !== null) $placed[$hid] = true;
                $key = $hid !== null ? "h$hid" : $d['mac'];
                $byPort[$portName]['port'] = $portName;
                $byPort[$portName]['members'] = $p['lag'] ? array_values(array_unique(array_merge($byPort[$portName]['members'] ?? [], [$p['name']]))) : [$p['name']];
                $byPort[$portName]['description'] = $p['description'] !== $p['name'] ? $p['description'] : '';
                $byPort[$portName]['vlan'] = $p['trunk'] ? 'trunk' : $p['vlan'];
                $entry = ['host' => $d['host'], 'ip' => $d['ip'], 'mac' => $d['mac'], 'vlan' => $d['vlan'], 'note' => $d['note'] ?? null];
                if ($hid !== null && isset($topo['hypervisors'][$hid])) {
                    $entry['guests'] = array_map(fn($g) => ['name' => $g['name'], 'type' => $g['type'], 'vmid' => $g['vmid'],
                        'status' => $g['status'], 'hostId' => $g['hostId'], 'ip' => $g['ips'][0] ?? null], $topo['hypervisors'][$hid]['guests']);
                }
                if ($hid !== null && isset($topo['docker'][$hid])) $entry['containers'] = count($topo['docker'][$hid]['containers']);
                if (isset($wifi['aps'][$d['mac']])) {
                    $ap = $wifi['aps'][$d['mac']];
                    $entry['ap'] = ['name' => $ap['name'], 'radios' => array_map(fn($r) => "{$r['band']} ch{$r['channel']}", $ap['radios'])];
                    $entry['wifiClients'] = array_map(fn($c) => ['name' => (isset($c['card']['name']) && $c['card']['name'] !== $c['ip'] ? $c['card']['name'] : null) ?? $c['name'] ?? $c['ip'] ?? $c['mac'],
                        'hostId' => $c['card']['id'] ?? null, 'ip' => $c['ip'], 'mac' => $c['mac'], 'ssid' => $c['ssid'], 'band' => $c['band']],
                        $clientsByAp[$d['mac']] ?? []);
                    if ($entry['host'] === null) $entry['ip'] ??= $ap['ip'];
                    foreach ($clientsByAp[$d['mac']] ?? [] as $c) if ($c['card']) $placed[$c['card']['id']] = true;
                }
                $byPort[$portName]['devices'][$key] = $entry;
            }
        }
        foreach ($byPort as &$bp) $bp['devices'] = array_values($bp['devices']);
        unset($bp);
        uksort($byPort, 'strnatcasecmp');
        $node['ports'] = array_values($byPort);
    }
    unset($node);

    // Access points: a box each, linked to their switch port, with their clients by SSID.
    foreach ($apNodes as $mac => $ap) {
        $id = $ap['card']['id'];
        $placed[$id] = true;
        $bySsid = [];
        foreach ($clientsByAp[$mac] ?? [] as $c) {
            $ssid = $c['ssid'] ?? '(unknown SSID)';
            $bySsid[$ssid]['port'] = $ssid;
            $bySsid[$ssid]['members'] = [$ssid];
            $bySsid[$ssid]['description'] = '';
            $bySsid[$ssid]['vlan'] = null;
            $bySsid[$ssid]['ssid'] = true;
            $bySsid[$ssid]['devices'][] = ['host' => $c['card'], 'ip' => $c['ip'], 'mac' => $c['mac'], 'vlan' => null,
                                           'name' => $c['name'], 'band' => $c['band']];
            if ($c['card']) $placed[$c['card']['id']] = true;
        }
        uksort($bySsid, 'strnatcasecmp');
        $nodes[$id] = [
            'id' => $id, 'name' => $ap['card']['name'], 'ip' => $ap['ip'], 'mac' => $mac, 'device' => 'ap', 'vendor' => 'aruba',
            'model' => $ap['model'] ? "Aruba {$ap['model']}" . ($ap['role'] ? " · {$ap['role']}" : '') : null, 'aliases' => [],
            'portsTotal' => 1, 'portsUp' => 1, 'collectedAt' => $wifi['collectedAt'], 'ports' => array_values($bySsid),
            'radios' => array_map(fn($r) => ['band' => $r['band'], 'channel' => $r['channel'], 'clients' => $r['clients'], 'utilization' => $r['utilization']], $ap['radios']),
            'wifiClients' => count($clientsByAp[$mac] ?? []),
        ];
        $canon[$id] = $id;
        $addLink($canon[$ap['uplink']['switch']['id']], $ap['uplink']['port'], $id, 'eth0');
    }

    // Tree: from the router if it's linked, else the best-connected switch.
    $adj = [];
    foreach ($links as $l) { $adj[$l['a']][] = $l['b']; $adj[$l['b']][] = $l['a']; }
    $candidates = array_keys($nodes);
    // A card typed Router that CDP/LLDP says is a switch model (e.g. WS-C2960X) isn't the edge router.
    $isRouter = fn($n) => $n['device'] === 'router' && !preg_match('/WS-C|C9[23]\d{2}|catalyst|FS-\d|switch/i', (string) $n['model']);
    usort($candidates, fn($a, $b) => [!$isRouter($nodes[$a]) || empty($adj[$a]), -count($adj[$a] ?? []), $a]
                                   <=> [!$isRouter($nodes[$b]) || empty($adj[$b]), -count($adj[$b] ?? []), $b]);
    $seen = [];
    $build = function (int $id, ?int $from) use (&$build, &$seen, $adj, $links, $nodes) {
        $seen[$id] = true;
        $children = [];
        foreach ($adj[$id] ?? [] as $next) {
            if (isset($seen[$next])) continue;
            $seen[$next] = true;
            $l = $links[min($id, $next) . '-' . max($id, $next)];
            $child = $build($next, $id);
            $child['link'] = ['parentPort' => $l['ports'][$id] ?? null, 'childPort' => $l['ports'][$next] ?? null];
            $children[] = $child;
        }
        return ['id' => $id, 'children' => $children];
    };
    $roots = [];
    foreach ($candidates as $id) if (!isset($seen[$id])) $roots[] = $build($id, null);

    // Monitored hosts that aren't on any port we can see (VPN, other sites, quiet devices).
    $unplaced = [];
    foreach ($hosts as $id => $h) {
        if (isset($canon[$id]) || isset($placed[$id]) || $isGuest($id)) continue;
        if (in_array($id, $wifi['controllers'], true)) continue;   // a virtual controller's address moves with its conductor AP
        $unplaced[] = ['id' => $id, 'name' => $h['name'], 'ip' => $h['ip_address'], 'device' => $h['device']];
    }
    usort($unplaced, fn($a, $b) => ip2long($a['ip']) <=> ip2long($b['ip']));

    return ['nodes' => (object) $nodes, 'links' => array_values($links), 'roots' => $roots, 'unplaced' => $unplaced, 'wifiClients' => count($wifi['clients']),
            'generatedAt' => (int) round(microtime(true) * 1000)];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/scanner.php")"
cat > "$APP_DIR/includes/scanner.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/netcheck.php';

const SCAN_MIN_PREFIX = 22;   // smallest allowed network per CIDR token (1024 addresses)
const SCAN_MAX_TOTAL_IPS = 1024;

const OID_SYS_DESCR = '.1.3.6.1.2.1.1.1.0';
const OID_SYS_OBJECT_ID = '.1.3.6.1.2.1.1.2.0';
const OID_SYS_NAME = '.1.3.6.1.2.1.1.5.0';
const OID_SYS_SERVICES = '.1.3.6.1.2.1.1.7.0';

/**
 * Expands a comma/newline-separated list of IPv4 addresses and/or CIDR
 * ranges (e.g. "192.168.1.0/24, 10.0.0.5") into a flat, deduped IP list.
 * Network/broadcast addresses are skipped for prefixes < 31.
 */
function parse_networks(string $input): array {
    $ips = [];
    $tokens = preg_split('/[\s,]+/', trim($input), -1, PREG_SPLIT_NO_EMPTY);

    foreach ($tokens as $token) {
        if (!str_contains($token, '/')) {
            if (!filter_var($token, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
                throw new InvalidArgumentException("Invalid address: $token");
            }
            $ips[] = $token;
            continue;
        }

        [$base, $prefixStr] = explode('/', $token, 2);
        if (!filter_var($base, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) || !ctype_digit($prefixStr)) {
            throw new InvalidArgumentException("Invalid network: $token");
        }
        $prefix = (int) $prefixStr;
        if ($prefix < SCAN_MIN_PREFIX || $prefix > 32) {
            throw new InvalidArgumentException(
                "Network $token is too large — smallest allowed prefix is /" . SCAN_MIN_PREFIX
            );
        }

        $hostBits = 32 - $prefix;
        $baseLong = ip2long($base);
        $mask = $hostBits === 0 ? 0xFFFFFFFF : ((~0 << $hostBits) & 0xFFFFFFFF);
        $network = $baseLong & $mask;
        $broadcast = $network | (~$mask & 0xFFFFFFFF);

        $start = $prefix >= 31 ? $network : $network + 1;
        $end = $prefix >= 31 ? $broadcast : $broadcast - 1;

        for ($i = $start; $i <= $end; $i++) {
            $ips[] = long2ip($i);
            if (count($ips) > SCAN_MAX_TOTAL_IPS) {
                throw new InvalidArgumentException(
                    'Too many addresses requested — max ' . SCAN_MAX_TOTAL_IPS . ' per scan. Narrow your ranges.'
                );
            }
        }
    }

    return array_values(array_unique($ips));
}

const SCAN_BATCH_SIZE = 200; // caps concurrent sockets per round, well under typical fd limits

/**
 * Sweeps every address for liveness via TCP connect (see netcheck.php) —
 * no raw ICMP, so no root/setuid/capabilities/SELinux policy needed.
 * Addresses are checked in batches to keep concurrent socket counts sane;
 * returns ip => ['up' => bool, 'port' => ?int, 'open' => bool, 'ms' => ?int].
 */
function network_sweep(array $ips, array $ports = NETCHECK_PORTS, float $timeoutSec = 1.0): array {
    $results = [];
    foreach (array_chunk($ips, SCAN_BATCH_SIZE) as $batch) {
        $results += tcp_probe_hosts($batch, $ports, $timeoutSec);
    }
    return $results;
}

function snmp_cli_path(): ?string {
    static $path = false;
    if ($path === false) {
        $found = trim((string) shell_exec('command -v snmpget 2>/dev/null'));
        $path = $found !== '' ? $found : null;
    }
    return $path;
}

function snmp_available(): bool {
    return function_exists('snmpget') || snmp_cli_path() !== null;
}

/**
 * Queries sysDescr/sysObjectID/sysName/sysServices over SNMP v2c.
 * Returns null if the host didn't respond (SNMP not enabled on it, wrong
 * community string, or blocked by a firewall).
 */
function snmp_probe(string $ip, string $community, float $timeoutSec = 1.0): ?array {
    if (function_exists('snmpget')) {
        snmp_set_quick_print(true);
        snmp_set_valueretrieval(SNMP_VALUE_PLAIN);
        $timeoutMicro = (int) round($timeoutSec * 1_000_000);

        $descr = @snmpget($ip, $community, OID_SYS_DESCR, $timeoutMicro, 1);
        if ($descr === false) return null;

        $objId = @snmpget($ip, $community, OID_SYS_OBJECT_ID, $timeoutMicro, 1);
        $name = @snmpget($ip, $community, OID_SYS_NAME, $timeoutMicro, 1);
        $services = @snmpget($ip, $community, OID_SYS_SERVICES, $timeoutMicro, 1);

        return [
            'sysDescr' => is_string($descr) ? trim($descr, " \t\"") : null,
            'sysObjectID' => is_string($objId) ? trim($objId, " \t\"") : null,
            'sysName' => is_string($name) ? trim($name, " \t\"") : null,
            'sysServices' => is_numeric($services) ? (int) $services : null,
        ];
    }

    $bin = snmp_cli_path();
    if ($bin === null) return null;

    $timeoutArg = max(1, (int) round($timeoutSec));
    $cmd = escapeshellarg($bin) .
        ' -O nq -v2c -c ' . escapeshellarg($community) .
        ' -t ' . $timeoutArg . ' -r 1 ' . escapeshellarg($ip) . ' ' .
        OID_SYS_DESCR . ' ' . OID_SYS_OBJECT_ID . ' ' . OID_SYS_NAME . ' ' . OID_SYS_SERVICES .
        ' 2>/dev/null';
    exec($cmd, $lines, $exit);
    if ($exit !== 0 || !$lines) return null;

    $values = [];
    foreach ($lines as $line) {
        if (preg_match('/^\S+\s+(.*)$/', $line, $m)) {
            $values[] = trim($m[1], " \t\"");
        }
    }
    if (!$values) return null;

    return [
        'sysDescr' => $values[0] ?? null,
        'sysObjectID' => $values[1] ?? null,
        'sysName' => $values[2] ?? null,
        'sysServices' => isset($values[3]) && is_numeric($values[3]) ? (int) $values[3] : null,
    ];
}

/**
 * Guesses os/device from which TCP port responded and (if available) SNMP
 * sysDescr text. device is one of: server, desktop, laptop, mobile, router,
 * switch, ap, printer, camera, nas, ups.
 */
function classify_device(?int $respondingPort, bool $portOpen, ?array $snmp): array {
    $os = guess_os_from_port($respondingPort, $portOpen);

    if ($snmp === null) {
        return ['os' => $os, 'device' => 'server', 'label' => 'No SNMP response', 'confidence' => 'low'];
    }

    $descr = strtolower((string) ($snmp['sysDescr'] ?? ''));

    if (str_contains($descr, 'windows')) $os = 'windows';
    elseif (str_contains($descr, 'darwin') || str_contains($descr, 'mac os')) $os = 'macos';
    elseif (str_contains($descr, 'linux')) $os = 'linux';

    // Order matters: more specific categories are checked before generic ones.
    $devicePatterns = [
        'ap'      => ['access point', 'unifi ap', 'aironet', 'wireless ap'],
        'printer' => ['printer', 'jetdirect', 'laserjet', 'officejet', 'deskjet'],
        'camera'  => ['camera', 'ipcam', 'dvr', 'nvr', 'hikvision', 'dahua'],
        'nas'     => ['synology', 'qnap', 'freenas', 'truenas', 'nas4free'],
        'ups'     => ['ups', 'smart-ups', 'apc web/snmp'],
        'switch'  => ['switch', 'catalyst', 'procurve'],
        'router'  => ['router', 'routeros', 'mikrotik', 'juniper', 'fortigate', 'pfsense', 'edgerouter', 'firewall', 'ubiquiti', 'cisco ios'],
    ];

    foreach ($devicePatterns as $device => $needles) {
        foreach ($needles as $needle) {
            if (str_contains($descr, $needle)) {
                return [
                    'os' => $os,
                    'device' => $device,
                    'label' => $snmp['sysDescr'] ?: ucfirst($device),
                    'confidence' => 'high',
                ];
            }
        }
    }

    return [
        'os' => $os,
        'device' => 'server',
        'label' => $snmp['sysDescr'] ?: 'SNMP host (unclassified)',
        'confidence' => 'medium',
    ];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/scanqueue.php")"
cat > "$APP_DIR/includes/scanqueue.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';

function next_scan_priority(): int {
    if (db()->exec('UPDATE scan_queue_order SET sequence = LAST_INSERT_ID(sequence + 1) WHERE id = 1') !== 1) {
        throw new RuntimeException('Scan queue priority counter is missing');
    }
    return (int) db()->query('SELECT LAST_INSERT_ID()')->fetchColumn();
}

function scan_activity_start(string $lock, string $kind, string $target): void {
    db()->exec('DELETE FROM scan_activity WHERE IS_USED_LOCK(lock_name) IS NULL OR IS_USED_LOCK(lock_name) <> connection_id');
    db()->prepare('INSERT INTO scan_activity (lock_name, connection_id, kind, target, started_at)
                   VALUES (?, CONNECTION_ID(), ?, ?, ?)
                   ON DUPLICATE KEY UPDATE connection_id = VALUES(connection_id), kind = VALUES(kind),
                     target = VALUES(target), started_at = VALUES(started_at)')
        ->execute([$lock, $kind, $target, (int) round(microtime(true) * 1000)]);
}

function scan_activity_end(string $lock): void {
    db()->prepare('DELETE FROM scan_activity WHERE lock_name = ? AND connection_id = CONNECTION_ID()')->execute([$lock]);
}

function active_scans(): array {
    $rows = db()->query('SELECT kind, target, started_at FROM scan_activity
                         WHERE IS_USED_LOCK(lock_name) = connection_id ORDER BY started_at')->fetchAll();
    return array_map(fn($r) => ['kind' => $r['kind'], 'target' => $r['target'], 'startedAt' => (int) $r['started_at']], $rows);
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/schedules.php")"
cat > "$APP_DIR/includes/schedules.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/jobs.php';
require_once __DIR__ . '/notify.php';

/**
 * Update windows: recurring jobs (e.g. security updates every Sunday at
 * 03:00, server time). cli/cron.php calls process_schedules() every minute.
 *
 * A schedule fires at most once per occurrence (last_run_key). If the
 * server was down at that moment it still fires up to SCHEDULE_GRACE_MIN
 * late; later than that the occurrence is skipped rather than running
 * updates at an unexpected hour. When every job of a run has finished, one
 * summary notification is sent.
 */

const SCHEDULE_JOB_TYPES = ['updates', 'refresh', 'reboot'];
const SCHEDULE_TARGETS = ['all', 'linux', 'windows', 'hosts'];
const SCHEDULE_GRACE_MIN = 30;
const DAY_NAMES = [1 => 'Mon', 2 => 'Tue', 3 => 'Wed', 4 => 'Thu', 5 => 'Fri', 6 => 'Sat', 7 => 'Sun'];

function day_bit(int $isoDay): int {
    return 1 << ($isoDay - 1);   // Mon=1 ... Sun=64
}

function describe_days(int $days): string {
    if ($days === 127) return 'Every day';
    if ($days === 31) return 'Weekdays';
    if ($days === 96) return 'Weekends';
    $names = [];
    foreach (DAY_NAMES as $n => $name) if ($days & day_bit($n)) $names[] = $name;
    return implode(', ', $names);
}

/** Occurrence of $sched at $day (DateTimeImmutable, any time that day), as DateTimeImmutable. */
function occurrence_on(array $sched, DateTimeImmutable $day): DateTimeImmutable {
    [$h, $m] = array_map('intval', explode(':', $sched['at_time']));
    return $day->setTime($h, $m);
}

/** Next occurrence after now, or null if no days are set. */
function schedule_next_run(array $sched, ?DateTimeImmutable $now = null): ?DateTimeImmutable {
    $now = $now ?? new DateTimeImmutable();
    for ($d = 0; $d <= 7; $d++) {
        $day = $now->modify("+$d day");
        $occ = occurrence_on($sched, $day);
        if (($sched['days'] & day_bit((int) $day->format('N'))) && $occ > $now) return $occ;
    }
    return null;
}

/** The most recent occurrence at or before now (within the last week), or null. */
function schedule_last_occurrence(array $sched, DateTimeImmutable $now): ?DateTimeImmutable {
    for ($d = 0; $d <= 7; $d++) {
        $day = $now->modify("-$d day");
        $occ = occurrence_on($sched, $day);
        if (($sched['days'] & day_bit((int) $day->format('N'))) && $occ <= $now) return $occ;
    }
    return null;
}

/** Host ids a schedule targets right now (target groups are evaluated at run time). */
function schedule_host_ids(array $sched): array {
    if ($sched['targets'] === 'hosts') {
        return array_values(array_filter(array_map('intval', json_decode($sched['host_ids'], true) ?: [])));
    }
    $ids = [];
    foreach (agent_summaries() as $hid => $a) {
        if ($sched['targets'] === 'all' || $a['platform'] === $sched['targets']) $ids[] = $hid;
    }
    return $ids;
}

function schedule_row(array $s): array {
    $params = json_decode($s['params'], true) ?: [];
    $next = $s['enabled'] ? schedule_next_run($s) : null;
    $run = db()->prepare('SELECT * FROM schedule_runs WHERE schedule_id = ? ORDER BY id DESC LIMIT 1');
    $run->execute([$s['id']]);
    $last = $run->fetch();
    return [
        'id' => (int) $s['id'],
        'name' => $s['name'],
        'enabled' => (bool) $s['enabled'],
        'jobType' => $s['job_type'],
        'params' => $params,
        'label' => job_label($s['job_type'], $params),
        'days' => (int) $s['days'],
        'daysLabel' => describe_days((int) $s['days']),
        'atTime' => $s['at_time'],
        'targets' => $s['targets'],
        'hostIds' => array_map('intval', json_decode($s['host_ids'], true) ?: []),
        'nextRun' => $next ? $next->getTimestamp() * 1000 : null,
        'lastRun' => $last ? [
            'startedAt' => (int) $last['started_at'],
            'manual' => (bool) $last['manual'],
            'finishedAt' => $last['finished_at'] !== null ? (int) $last['finished_at'] : null,
            'summary' => $last['summary'],
            'jobs' => count(json_decode($last['job_ids'], true) ?: []),
            'skipped' => json_decode($last['skipped'], true) ?: [],
        ] : null,
    ];
}

/** Validates schedule fields from the browser; throws InvalidArgumentException. */
function schedule_fields(array $in): array {
    $name = trim((string) ($in['name'] ?? ''));
    if ($name === '' || mb_strlen($name) > 60) throw new InvalidArgumentException('Give the schedule a name (up to 60 characters).');
    $type = (string) ($in['jobType'] ?? '');
    if (!in_array($type, SCHEDULE_JOB_TYPES, true)) throw new InvalidArgumentException('Choose what the schedule should do.');
    $days = (int) ($in['days'] ?? 0);
    if ($days < 1 || $days > 127) throw new InvalidArgumentException('Pick at least one day.');
    $time = (string) ($in['atTime'] ?? '');
    if (!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $time)) throw new InvalidArgumentException('Time must be HH:MM (24-hour).');
    $targets = (string) ($in['targets'] ?? 'hosts');
    if (!in_array($targets, SCHEDULE_TARGETS, true)) throw new InvalidArgumentException('Unknown target.');
    $hostIds = array_values(array_unique(array_filter(array_map('intval', (array) ($in['hostIds'] ?? [])))));
    if ($targets === 'hosts' && !$hostIds) throw new InvalidArgumentException('Pick at least one host.');
    return [
        'name' => $name, 'job_type' => $type, 'params' => json_encode(job_params($type, (array) ($in['params'] ?? []))),
        'days' => $days, 'at_time' => $time, 'targets' => $targets,
        'host_ids' => json_encode($targets === 'hosts' ? $hostIds : []),
        'enabled' => array_key_exists('enabled', $in) ? (int) (bool) $in['enabled'] : 1,
    ];
}

/** Queues the schedule's jobs now and records the run. */
function run_schedule(array $sched, bool $manual = false): array {
    $params = json_decode($sched['params'], true) ?: [];
    $res = create_jobs(schedule_host_ids($sched), $sched['job_type'], $params,
                       $sched['created_by'] !== null ? (int) $sched['created_by'] : null, (int) $sched['id']);
    $now = now_ms();
    $summary = null;
    $finished = null;
    if (!$res['created']) {   // nothing to wait for
        $finished = $now;
        $summary = $res['skipped'] ? 'Nothing ran: every host was skipped' : 'Nothing ran: no matching hosts';
    }
    db()->prepare('INSERT INTO schedule_runs (schedule_id, started_at, manual, job_ids, skipped, finished_at, summary) VALUES (?, ?, ?, ?, ?, ?, ?)')
        ->execute([$sched['id'], $now, $manual ? 1 : 0, json_encode($res['created']), json_encode($res['skipped']), $finished, $summary]);
    if ($finished !== null && !$manual) {
        notify_all("WebMonitor: scheduled \"{$sched['name']}\" didn't run", $summary . "\n" . skipped_lines($res['skipped']), 'warning');
    }
    return $res;
}

function skipped_lines(array $skipped): string {
    return implode("\n", array_map(fn($s) => "⏭ {$s['host']}: {$s['reason']}", $skipped));
}

/** Fires due schedules and reports finished runs. Called every minute by cron. */
function process_schedules(): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_schedules', 0)")->fetchColumn()) return;
    try {
        $now = new DateTimeImmutable();
        foreach ($pdo->query('SELECT * FROM update_schedules WHERE enabled = 1')->fetchAll() as $s) {
            $occ = schedule_last_occurrence($s, $now);
            if ($occ === null) continue;
            $key = $occ->format('Y-m-d H:i');
            if ($s['last_run_key'] === $key) continue;
            // Record the occurrence first so a slow run can't fire twice.
            $pdo->prepare('UPDATE update_schedules SET last_run_key = ? WHERE id = ?')->execute([$key, $s['id']]);
            $lateMin = ($now->getTimestamp() - $occ->getTimestamp()) / 60;
            if ($lateMin > SCHEDULE_GRACE_MIN) continue;   // missed (server down); wait for the next one
            run_schedule($s);
        }
        report_finished_runs();
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_schedules')");
    }
}

/** Sends one summary per schedule run once all its jobs are done. */
function report_finished_runs(): void {
    $pdo = db();
    $runs = $pdo->query('SELECT r.*, s.name FROM schedule_runs r JOIN update_schedules s ON s.id = r.schedule_id
                         WHERE r.finished_at IS NULL')->fetchAll();
    foreach ($runs as $r) {
        $ids = array_map('intval', json_decode($r['job_ids'], true) ?: []);
        if (!$ids) continue;
        $jobs = $pdo->query(JOB_SELECT . ' WHERE j.id IN (' . implode(',', $ids) . ')')->fetchAll();
        if (array_filter($jobs, fn($j) => in_array($j['status'], ['queued', 'running'], true))) continue;

        $counts = array_count_values(array_column($jobs, 'status'));
        $ok = $counts['succeeded'] ?? 0;
        $bad = count($jobs) - $ok;
        $summary = "$ok succeeded" . ($bad ? ", $bad failed or didn't run" : '');
        $skipped = json_decode($r['skipped'], true) ?: [];
        if ($skipped) $summary .= ', ' . count($skipped) . ' skipped';
        $pdo->prepare('UPDATE schedule_runs SET finished_at = ?, summary = ? WHERE id = ?')->execute([now_ms(), $summary, $r['id']]);

        $lines = [];
        foreach ($jobs as $j) {
            $host = $j['host_name'] === $j['ip_address'] ? $j['ip_address'] : $j['host_name'];
            $icon = $j['status'] === 'succeeded' ? '✅' : '❌';
            $lines[] = "$icon $host: " . ($j['summary'] ?: $j['status']);
        }
        if ($skipped) $lines[] = skipped_lines($skipped);
        notify_all("WebMonitor: \"{$r['name']}\" finished — $summary", implode("\n", $lines), $bad ? 'critical' : 'info');
    }
}

// ---------------------------------------------------------------- conflicts

const SCHEDULE_OVERLAP_MIN = 120;   // runs closer than this may still be going
const WEEK_MIN = 7 * 1440;

/** Minute-of-week (Mon 00:00 = 0) of each occurrence. */
function schedule_week_minutes(array $s): array {
    [$h, $m] = array_map('intval', explode(':', $s['at_time']));
    $out = [];
    foreach (DAY_NAMES as $n => $_) if ((int) $s['days'] & day_bit($n)) $out[] = ($n - 1) * 1440 + $h * 60 + $m;
    return $out;
}

function fmt_week_minute(int $m): string {
    return DAY_NAMES[intdiv($m, 1440) + 1] . ' ' . sprintf('%02d:%02d', intdiv($m % 1440, 60), $m % 60);
}

/** Closest pair of occurrences less than SCHEDULE_OVERLAP_MIN apart (wrapping the week), or null. */
function schedules_overlap(array $a, array $b): ?array {
    $best = null;
    foreach (schedule_week_minutes($a) as $ma) {
        foreach (schedule_week_minutes($b) as $mb) {
            $d = abs($ma - $mb);
            $d = min($d, WEEK_MIN - $d);
            if ($d < SCHEDULE_OVERLAP_MIN && ($best === null || $d < $best[2])) $best = [$ma, $mb, $d];
        }
    }
    return $best;
}

function schedule_may_reboot(array $s): bool {
    if ($s['job_type'] === 'reboot') return true;
    return $s['job_type'] === 'updates' && !empty((json_decode($s['params'], true) ?: [])['reboot']);
}

/**
 * Problems between enabled schedules:
 *   error   - the same host is in two schedules that run within 2 hours
 *             (one job per host at a time, so the later one skips it)
 *   warning - a Proxmox host may reboot while KVM guests (possibly its VMs)
 *             are being updated, or WebMonitor's own server may reboot
 *             while other hosts' jobs run
 * Each item: [level, scheduleIds, message].
 */
function schedule_conflicts(array $schedules, ?string $serverIp = null): array {
    $agents = agent_summaries();
    $hosts = [];
    foreach (db()->query('SELECT id, name, ip_address FROM hosts')->fetchAll() as $h) {
        $hosts[(int) $h['id']] = $h['name'] === $h['ip_address'] ? $h['ip_address'] : $h['name'];
        if ($serverIp !== null && $h['ip_address'] === $serverIp) $serverHost = (int) $h['id'];
    }
    $serverHost = $serverHost ?? null;
    $name = fn(int $id) => $hosts[$id] ?? "#$id";
    $list = fn(array $ids) => implode(', ', array_map($name, $ids));

    $active = array_values(array_filter($schedules, fn($s) => (int) $s['enabled'] === 1));
    $targets = [];
    foreach ($active as $s) $targets[(int) $s['id']] = schedule_host_ids($s);
    $pick = fn(array $ids, string $flag) => array_values(array_filter($ids, fn($id) => !empty($agents[$id][$flag])));

    $out = [];
    // Within one schedule: a Proxmox host rebooting alongside KVM guests.
    foreach ($active as $s) {
        $ids = $targets[(int) $s['id']];
        $hv = $pick($ids, 'hypervisor');
        $vms = array_values(array_diff($pick($ids, 'vm'), $hv));
        if ($hv && $vms && schedule_may_reboot($s)) {
            $out[] = ['warning', [(int) $s['id']], "\"{$s['name']}\" may reboot the Proxmox host {$list($hv)} while it also updates "
                . "{$list($vms)} (VMs, possibly on that host). Give the Proxmox host its own schedule, run after its VMs."];
        }
    }
    // Between schedules.
    for ($i = 0; $i < count($active); $i++) {
        for ($j = $i + 1; $j < count($active); $j++) {
            [$a, $b] = [$active[$i], $active[$j]];
            $ov = schedules_overlap($a, $b);
            if ($ov === null) continue;
            $ta = $targets[(int) $a['id']];
            $tb = $targets[(int) $b['id']];
            $whenA = fmt_week_minute($ov[0]);
            $whenB = fmt_week_minute($ov[1]);
            $ids = [(int) $a['id'], (int) $b['id']];

            $shared = array_values(array_intersect($ta, $tb));
            if ($shared) {
                [$first, $second] = $ov[0] <= $ov[1] ? [$a, $b] : [$b, $a];
                $out[] = ['error', $ids, "{$list($shared)} " . (count($shared) === 1 ? 'is' : 'are')
                    . " in both \"{$a['name']}\" ($whenA) and \"{$b['name']}\" ($whenB). A host runs one job at a time, so "
                    . "\"{$second['name']}\" will skip " . (count($shared) === 1 ? 'it' : 'them') . " if \"{$first['name']}\" is still running."];
            }
            foreach ([[$a, $ta, $b, $tb, $whenA, $whenB], [$b, $tb, $a, $ta, $whenB, $whenA]] as [$x, $tx, $y, $ty, $wx, $wy]) {
                if (!schedule_may_reboot($x)) continue;
                $hv = $pick($tx, 'hypervisor');
                $vms = array_values(array_diff($pick($ty, 'vm'), $hv, $tx));
                if ($hv && $vms) {
                    $out[] = ['warning', $ids, "\"{$x['name']}\" may reboot the Proxmox host {$list($hv)} ($wx) while \"{$y['name']}\" "
                        . "updates {$list($vms)} ($wy) — VMs, possibly on that host. Space them more than 2 hours apart."];
                }
                $others = array_values(array_diff($ty, $tx));
                if ($serverHost !== null && in_array($serverHost, $tx, true) && $others) {
                    $out[] = ['warning', $ids, "\"{$x['name']}\" may reboot WebMonitor's own server {$name($serverHost)} ($wx) while "
                        . "\"{$y['name']}\" runs ($wy). Jobs keep going, but progress and the dashboard pause until it's back."];
                }
            }
        }
    }
    return array_map(fn($c) => ['level' => $c[0], 'scheduleIds' => $c[1], 'message' => $c[2]], $out);
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/services.php")"
cat > "$APP_DIR/includes/services.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';
require_once __DIR__ . '/agents.php';
require_once __DIR__ . '/devicescan.php';   // dns_wire_name(), dns_read_name()

/**
 * Service monitoring (Services tab).
 *
 * Network checks need no agent and run from this server every interval:
 *   http   the page answers with an expected status (and keyword), how fast,
 *          and when its TLS certificate expires
 *   tcp    a port accepts connections
 *   dns    a name resolves (optionally on a given server, to an expected value)
 * Agent services are services on an agent host that must be running. The
 * server tells each agent which to watch (in its report replies) and the agent
 * reports their state with its metrics, every minute.
 *
 * Status: up, warn (slow, or certificate expiring soon), down, pending (not
 * checked yet), unknown (the agent isn't reporting).
 */

const SERVICE_KINDS = ['http', 'tcp', 'dns', 'agent'];
const SERVICE_INTERVALS = [30, 60, 120, 300, 600, 900, 1800, 3600];
const SERVICE_HTTP_TIMEOUT_SEC = 10;
const SERVICE_TCP_TIMEOUT_SEC = 5;
const SERVICE_DNS_TIMEOUT_SEC = 3;
const SERVICE_BODY_MAX = 1024 * 1024;          // read at most 1 MB of a page for the keyword
const SERVICE_RESULTS_KEEP_DAYS = 7;
const SERVICE_DOWN_AFTER = 2;                  // network checks: failures in a row before an alert
const SERVICE_CERT_WARN_DAYS = 14;
const SERVICE_NAME_RE = '/^[A-Za-z0-9@._:\-+ ]{1,120}$/';   // systemd units and Windows service names
const SERVICE_RESTART_MIN_AGENT = ['linux' => '0.6.0', 'windows' => '0.5.0'];
const SERVICE_WATCH_MIN_AGENT = SERVICE_RESTART_MIN_AGENT;

function service_options(?string $json): array {
    $o = $json ? json_decode($json, true) : null;
    return is_array($o) ? $o : [];
}

// ---------------------------------------------------------------- validation

/**
 * Cleans a create/update request. Returns [row, error]: row has host_id, kind,
 * name, target, options (array), interval_sec, enabled, alert.
 */
function service_validate(array $in, ?array $existing = null): array {
    $kind = (string) ($in['kind'] ?? ($existing['kind'] ?? ''));
    if (!in_array($kind, SERVICE_KINDS, true)) return [null, 'Pick a check type.'];
    $hostId = array_key_exists('hostId', $in) ? ($in['hostId'] !== null && $in['hostId'] !== '' ? (int) $in['hostId'] : null)
        : ($existing ? ($existing['host_id'] !== null ? (int) $existing['host_id'] : null) : null);
    $host = null;
    if ($hostId !== null) {
        $st = db()->prepare('SELECT id, name, ip_address FROM hosts WHERE id = ?');
        $st->execute([$hostId]);
        $host = $st->fetch() ?: null;
        if (!$host) return [null, 'That host no longer exists.'];
    }
    $target = trim((string) ($in['target'] ?? ($existing['target'] ?? '')));
    $opt = is_array($in['options'] ?? null) ? $in['options'] : ($existing ? service_options($existing['options']) : []);
    $clean = [];

    if ($kind === 'http') {
        if (preg_match('#^[a-z][a-z0-9+.\-]*://#i', $target) && !preg_match('#^https?://#i', $target)) return [null, 'Only http:// and https:// addresses can be checked.'];
        if ($target !== '' && !preg_match('#^https?://#i', $target)) $target = 'http://' . $target;
        $u = parse_url($target);
        if (!$u || empty($u['host']) || !in_array(strtolower($u['scheme'] ?? ''), ['http', 'https'], true)) {
            return [null, 'Enter a web address, e.g. https://nas.local:5001/ or http://192.168.1.53/admin.'];
        }
        $clean['method'] = ($opt['method'] ?? 'GET') === 'HEAD' ? 'HEAD' : 'GET';
        $expect = trim((string) ($opt['expect'] ?? ''));
        if ($expect !== '' && !preg_match('/^\d{3}(-\d{3})?(\s*,\s*\d{3}(-\d{3})?)*$/', $expect)) {
            return [null, 'Expected status: codes or ranges like 200 or 200-299, 301.'];
        }
        $clean['expect'] = $expect;
        $clean['keyword'] = mb_substr(trim((string) ($opt['keyword'] ?? '')), 0, 200);
        $clean['verify_tls'] = !array_key_exists('verify_tls', $opt) || !empty($opt['verify_tls']);
        $clean['warn_ms'] = max(0, min(60000, (int) ($opt['warn_ms'] ?? 0)));
        $clean['cert_warn_days'] = max(0, min(365, (int) ($opt['cert_warn_days'] ?? SERVICE_CERT_WARN_DAYS)));
    } elseif ($kind === 'tcp') {
        if (preg_match('/^\d{1,5}$/', $target) && $host) $target = $host['ip_address'] . ':' . $target;
        if (!preg_match('/^(\[[0-9a-f:]+\]|[A-Za-z0-9.\-]+):(\d{1,5})$/i', $target, $m) || (int) $m[2] < 1 || (int) $m[2] > 65535) {
            return [null, 'Enter host:port, e.g. 192.168.1.50:445, or just the port when a host is picked.'];
        }
        $clean['warn_ms'] = max(0, min(60000, (int) ($opt['warn_ms'] ?? 0)));
    } elseif ($kind === 'dns') {
        if (!preg_match('/^[A-Za-z0-9_.\-]{1,253}$/', $target) || !str_contains($target, '.')) {
            return [null, 'Enter the name to look up, e.g. nas.home.arpa or google.com.'];
        }
        $server = trim((string) ($opt['server'] ?? ''));
        if ($server === '' && $host) $server = $host['ip_address'];
        if ($server !== '' && !filter_var($server, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) return [null, 'DNS server: an IPv4 address, or blank for this server\'s resolver.'];
        $clean['server'] = $server;
        $type = (string) ($opt['type'] ?? 'A');
        $clean['type'] = in_array($type, ['A', 'AAAA', 'CNAME', 'MX'], true) ? $type : 'A';
        $clean['expect'] = mb_substr(trim((string) ($opt['expect'] ?? '')), 0, 200);
    } else {   // agent
        if (!$host) return [null, 'Pick the host the service runs on.'];
        if (!preg_match(SERVICE_NAME_RE, $target)) return [null, 'Pick a service, or type its name (e.g. nginx.service or Spooler).'];
        $st = db()->prepare("SELECT agent_version, JSON_UNQUOTE(JSON_EXTRACT(inventory, '$.os.id')) AS os_id FROM agents WHERE host_id = ?");
        $st->execute([$hostId]);
        $a = $st->fetch();
        if (!$a) return [null, 'That host has no agent. Install one from its Details window first.'];
        $platform = $a['os_id'] === 'windows' ? 'windows' : 'linux';
        if ($platform === 'linux' && !str_contains($target, '.')) $target .= '.service';
        if (!$a['agent_version'] || version_compare($a['agent_version'], SERVICE_WATCH_MIN_AGENT[$platform], '<')) {
            return [null, "Watching services needs agent " . SERVICE_WATCH_MIN_AGENT[$platform] . " or newer (this host has {$a['agent_version']}). Upgrade it from the Updates tab first."];
        }
    }

    $name = trim((string) ($in['name'] ?? ($existing['name'] ?? '')));
    if ($name === '') $name = service_default_name($kind, $target, $clean, $host);
    $interval = (int) ($in['interval'] ?? ($existing['interval_sec'] ?? 60));
    if (!in_array($interval, SERVICE_INTERVALS, true)) $interval = 60;

    $dup = db()->prepare('SELECT id FROM services WHERE kind = ? AND target = ? AND host_id <=> ? AND id <> ?');
    $dup->execute([$kind, $target, $hostId, $existing ? (int) $existing['id'] : 0]);
    if ($dup->fetchColumn()) return [null, 'That check already exists.'];

    return [[
        'host_id' => $hostId, 'kind' => $kind, 'name' => mb_substr($name, 0, 120), 'target' => mb_substr($target, 0, 500),
        'options' => $clean, 'interval_sec' => $kind === 'agent' ? 60 : $interval,
        'enabled' => array_key_exists('enabled', $in) ? (bool) $in['enabled'] : ($existing ? (bool) $existing['enabled'] : true),
        'alert' => array_key_exists('alert', $in) ? (bool) $in['alert'] : ($existing ? (bool) $existing['alert'] : true),
    ], null];
}

function service_default_name(string $kind, string $target, array $opt, ?array $host): string {
    if ($kind === 'http') {
        $u = parse_url($target);
        return ($u['host'] ?? $target) . (isset($u['port']) ? ':' . $u['port'] : '') . (($u['path'] ?? '/') !== '/' ? $u['path'] : '');
    }
    if ($kind === 'tcp') {
        $port = (int) substr($target, strrpos($target, ':') + 1);
        $known = [21 => 'FTP', 22 => 'SSH', 25 => 'SMTP', 53 => 'DNS', 80 => 'HTTP', 110 => 'POP3', 143 => 'IMAP', 443 => 'HTTPS',
                  445 => 'SMB', 993 => 'IMAPS', 1433 => 'SQL Server', 1883 => 'MQTT', 3306 => 'MySQL', 3389 => 'Remote Desktop',
                  5432 => 'PostgreSQL', 5900 => 'VNC', 6379 => 'Redis', 8006 => 'Proxmox', 8123 => 'Home Assistant', 9100 => 'Printer'];
        return ($known[$port] ?? "Port $port") . ($host ? '' : ' · ' . substr($target, 0, strrpos($target, ':')));
    }
    if ($kind === 'dns') return "DNS $target";
    return preg_replace('/\.service$/', '', $target);
}

// ---------------------------------------------------------------- network checks

/** Whether an HTTP status matches "200-299, 301" ('' = 200-399). */
function http_status_ok(int $code, string $expect): bool {
    if ($expect === '') return $code >= 200 && $code < 400;
    foreach (preg_split('/\s*,\s*/', trim($expect)) as $part) {
        [$lo, $hi] = array_pad(explode('-', $part), 2, null);
        if ($code >= (int) $lo && $code <= (int) ($hi ?? $lo)) return true;
    }
    return false;
}

/**
 * Runs HTTP checks in parallel. $checks: [id => [url, options]].
 * Returns [id => [up(bool), ms, message, cert_expires_at(ms|null), warn(bool)]].
 */
function http_checks(array $checks): array {
    $mh = curl_multi_init();
    $handles = [];
    $bodies = [];
    foreach ($checks as $id => [$url, $o]) {
        $ch = curl_init($url);
        $bodies[$id] = '';
        curl_setopt_array($ch, [
            CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 5,
            CURLOPT_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS, CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS,
            CURLOPT_CONNECTTIMEOUT => SERVICE_HTTP_TIMEOUT_SEC, CURLOPT_TIMEOUT => SERVICE_HTTP_TIMEOUT_SEC,
            CURLOPT_SSL_VERIFYPEER => !empty($o['verify_tls']), CURLOPT_SSL_VERIFYHOST => !empty($o['verify_tls']) ? 2 : 0,
            CURLOPT_CERTINFO => true, CURLOPT_NOBODY => ($o['method'] ?? 'GET') === 'HEAD',
            CURLOPT_USERAGENT => 'WebMonitor service check', CURLOPT_ENCODING => '',
            CURLOPT_HTTPHEADER => ['Accept: */*'],
            CURLOPT_WRITEFUNCTION => function ($ch, $data) use ($id, &$bodies, $o) {
                if (($o['keyword'] ?? '') === '') return strlen($data);   // not needed: discard
                if (strlen($bodies[$id]) < SERVICE_BODY_MAX) $bodies[$id] .= substr($data, 0, SERVICE_BODY_MAX - strlen($bodies[$id]));
                return strlen($data);
            },
        ]);
        curl_multi_add_handle($mh, $ch);
        $handles[$id] = $ch;
    }
    do {
        $status = curl_multi_exec($mh, $running);
        if ($running) curl_multi_select($mh, 1.0);
    } while ($running && $status === CURLM_OK);
    // Per-transfer results: curl_error() is empty for transfers run by curl_multi.
    $codes = [];
    while ($info = curl_multi_info_read($mh)) $codes[spl_object_id($info['handle'])] = (int) $info['result'];

    $out = [];
    foreach ($handles as $id => $ch) {
        [$url, $o] = $checks[$id];
        $code = $codes[spl_object_id($ch)] ?? 0;
        $err = curl_error($ch) ?: ($code ? curl_strerror($code) : '');
        $code = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        $ms = (int) round(curl_getinfo($ch, CURLINFO_TOTAL_TIME) * 1000);
        $cert = null;
        foreach ((array) curl_getinfo($ch, CURLINFO_CERTINFO) as $c) {
            if (!empty($c['Expire date']) && ($t = strtotime($c['Expire date']))) { $cert = $t * 1000; break; }
        }
        curl_multi_remove_handle($mh, $ch);
        curl_close($ch);

        if ($err !== '' && $code === 0) {
            $out[$id] = [false, null, service_curl_message($err), $cert, false];
            continue;
        }
        if (!http_status_ok($code, (string) ($o['expect'] ?? ''))) {
            $out[$id] = [false, $ms, "HTTP $code" . (($o['expect'] ?? '') !== '' ? " (expected {$o['expect']})" : ''), $cert, false];
            continue;
        }
        if (($o['keyword'] ?? '') !== '' && mb_stripos($bodies[$id], $o['keyword']) === false) {
            $out[$id] = [false, $ms, "HTTP $code, but \"{$o['keyword']}\" is not on the page", $cert, false];
            continue;
        }
        $msg = "HTTP $code";
        $warn = false;
        $days = $cert !== null ? (int) floor(($cert - now_ms()) / 86400000) : null;
        if ($days !== null && $days < 0) {
            $out[$id] = [false, $ms, "HTTP $code, but the certificate expired " . date('Y-m-d', intdiv($cert, 1000)), $cert, false];
            continue;
        }
        if ($days !== null && !empty($o['cert_warn_days']) && $days <= (int) $o['cert_warn_days']) {
            $warn = true;
            $msg .= " · certificate expires in $days day" . ($days === 1 ? '' : 's');
        }
        if (!empty($o['warn_ms']) && $ms > (int) $o['warn_ms']) {
            $warn = true;
            $msg .= " · slow ({$ms} ms, limit {$o['warn_ms']} ms)";
        }
        $out[$id] = [true, $ms, $msg, $cert, $warn];
    }
    curl_multi_close($mh);
    return $out;
}

/** curl's error in plain words. */
function service_curl_message(string $err): string {
    $map = [
        '/Could not resolve host|resolve host name/i' => 'Name does not resolve',
        '/Connection refused|Failed to connect.*refused|Couldn\'t connect to server|Could not connect to server/i' => 'Connection refused',
        '/timed out/i' => 'No answer (timed out)',
        '/SSL certificate problem: self.signed|unable to get local issuer|certificate verify failed/i' =>
            'Certificate not trusted (untick "Check the certificate" for self-signed devices)',
        '/certificate has expired/i' => 'Certificate expired',
        '/No route to host/i' => 'No route to host',
        '/SSL|TLS/i' => 'TLS error: ' . $err,
    ];
    foreach ($map as $re => $msg) if (preg_match($re, $err)) return $msg;
    return $err;
}

/** TCP connects in parallel. $checks: [id => [host, port]]. Returns [id => [up, ms, message]]. */
function tcp_checks(array $checks): array {
    $out = [];
    $socks = [];
    $start = microtime(true);
    foreach ($checks as $id => [$host, $port]) {
        $ip = filter_var(trim($host, '[]'), FILTER_VALIDATE_IP) ? trim($host, '[]') : gethostbyname($host);
        if (!filter_var($ip, FILTER_VALIDATE_IP)) { $out[$id] = [false, null, 'Name does not resolve']; continue; }
        $addr = str_contains($ip, ':') ? "[$ip]" : $ip;
        $fp = @stream_socket_client("tcp://$addr:$port", $errno, $errstr, SERVICE_TCP_TIMEOUT_SEC,
            STREAM_CLIENT_CONNECT | STREAM_CLIENT_ASYNC_CONNECT);
        if ($fp === false) { $out[$id] = [false, null, $errstr ?: 'Cannot connect']; continue; }
        $socks[(int) $fp] = [$id, $fp];
    }
    while ($socks) {
        $left = SERVICE_TCP_TIMEOUT_SEC - (microtime(true) - $start);
        if ($left <= 0) break;
        $w = array_column($socks, 1);
        $e = $w;
        $r = [];
        $n = @stream_select($r, $w, $e, (int) $left, (int) (($left - (int) $left) * 1e6));
        if (!$n) break;
        foreach (array_merge($w, $e) as $fp) {
            if (!isset($socks[(int) $fp])) continue;
            $id = $socks[(int) $fp][0];
            $ms = (int) round((microtime(true) - $start) * 1000);
            $out[$id] = @stream_socket_get_name($fp, true) !== false ? [true, $ms, 'Port open'] : [false, null, 'Connection refused'];
            fclose($fp);
            unset($socks[(int) $fp]);
        }
    }
    foreach ($socks as [$id, $fp]) { fclose($fp); $out[$id] = [false, null, 'No answer (timed out)']; }
    return $out;
}

/**
 * One DNS lookup. Returns [up, ms, message]. With a server, asks it directly
 * over UDP; without, uses this server's resolver.
 */
function dns_check(string $name, array $o, int $port = 53): array {
    $types = ['A' => 1, 'CNAME' => 5, 'MX' => 15, 'AAAA' => 28];
    $type = $o['type'] ?? 'A';
    $start = microtime(true);
    $answers = [];
    if (($o['server'] ?? '') === '') {
        $recs = @dns_get_record($name, ['A' => DNS_A, 'AAAA' => DNS_AAAA, 'CNAME' => DNS_CNAME, 'MX' => DNS_MX][$type]);
        foreach ((array) $recs as $r) $answers[] = $r['ip'] ?? $r['ipv6'] ?? $r['target'] ?? '';
    } else {
        $s = @stream_socket_client("udp://{$o['server']}:$port", $errno, $err, SERVICE_DNS_TIMEOUT_SEC);
        if (!$s) return [false, null, "Cannot reach DNS server {$o['server']}"];
        $qid = random_int(1, 65535);
        fwrite($s, pack('nnnnnn', $qid, 0x0100, 1, 0, 0, 0) . dns_wire_name($name) . pack('nn', $types[$type], 1));
        stream_set_timeout($s, SERVICE_DNS_TIMEOUT_SEC);
        $r = (string) fread($s, 4096);
        fclose($s);
        if (strlen($r) < 12) return [false, null, "No answer from DNS server {$o['server']}"];
        $h = unpack('nid/nflags/nqd/nan/nns/nar', $r);
        $rcode = $h['flags'] & 0xF;
        if ($rcode === 3) return [false, (int) round((microtime(true) - $start) * 1000), "$name does not exist (NXDOMAIN)"];
        if ($rcode !== 0) return [false, null, "DNS server error (code $rcode)"];
        $off = 12;
        for ($i = 0; $i < $h['qd']; $i++) { dns_read_name($r, $off); $off += 4; }
        for ($i = 0; $i < $h['an'] && $off + 10 <= strlen($r); $i++) {
            dns_read_name($r, $off);
            $t = unpack('ntype/nclass/Nttl/nlen', substr($r, $off, 10));
            $off += 10;
            $data = substr($r, $off, $t['len']);
            $o2 = $off;
            $off += $t['len'];
            if ($t['type'] === 1 && $t['len'] === 4) $answers[] = inet_ntop($data);
            elseif ($t['type'] === 28 && $t['len'] === 16) $answers[] = inet_ntop($data);
            elseif ($t['type'] === 5) $answers[] = dns_read_name($r, $o2);
            elseif ($t['type'] === 15) { $o2 += 2; $answers[] = dns_read_name($r, $o2); }
        }
    }
    $ms = (int) round((microtime(true) - $start) * 1000);
    $answers = array_values(array_filter($answers));
    if (!$answers) return [false, $ms, "No $type record for $name"];
    $shown = implode(', ', array_slice($answers, 0, 4));
    if (($o['expect'] ?? '') !== '' && !array_filter($answers, fn($a) => stripos($a, $o['expect']) !== false)) {
        return [false, $ms, "Resolves to $shown, expected {$o['expect']}"];
    }
    return [true, $ms, $shown];
}

// ---------------------------------------------------------------- recording

/**
 * Stores a result: [up, ms, message, certExpires?, warn?]. Status changes set
 * changed_at; network checks only show down after SERVICE_DOWN_AFTER failures.
 */
function record_service_result(array $svc, array $res, ?array $detail = null): void {
    [$up, $ms, $msg] = $res;
    $cert = $res[3] ?? null;
    $warn = $res[4] ?? false;
    $now = now_ms();
    $fails = $up ? 0 : (int) $svc['fail_count'] + 1;
    $needed = $svc['kind'] === 'agent' ? 1 : SERVICE_DOWN_AFTER;
    if ($up) $status = $warn ? 'warn' : 'up';
    elseif ($fails >= $needed || in_array($svc['status'], ['down', 'pending'], true)) $status = 'down';
    else $status = $svc['status'];   // one failure: keep the old status until it's confirmed
    $pdo = db();
    $pdo->prepare('UPDATE services SET status = ?, message = ?, last_check_at = ?, last_ms = ?, fail_count = ?,
                   changed_at = IF(status <> ?, ?, COALESCE(changed_at, ?)), cert_expires_at = COALESCE(?, cert_expires_at),
                   detail = COALESCE(?, detail) WHERE id = ?')
        ->execute([$status, $msg !== null ? mb_substr($msg, 0, 500) : null, $now, $ms, $fails, $status, $now, $now,
                   $cert, $detail !== null ? json_encode($detail) : null, $svc['id']]);
    $pdo->prepare('INSERT IGNORE INTO service_results (service_id, ts, up, ms) VALUES (?, ?, ?, ?)')
        ->execute([$svc['id'], $now, $up ? 1 : 0, $ms]);
}

/** Runs the given network checks (rows from services) now. */
function run_service_checks(array $rows): void {
    $http = $tcp = [];
    $byId = [];
    foreach ($rows as $s) {
        $byId[(int) $s['id']] = $s;
        $o = service_options($s['options']);
        if ($s['kind'] === 'http') $http[(int) $s['id']] = [$s['target'], $o];
        elseif ($s['kind'] === 'tcp') {
            $i = strrpos($s['target'], ':');
            $tcp[(int) $s['id']] = [substr($s['target'], 0, $i), (int) substr($s['target'], $i + 1)];
        }
    }
    $results = [];
    foreach (array_chunk($http, 25, true) as $batch) $results += http_checks($batch);
    foreach (array_chunk($tcp, 100, true) as $batch) {
        foreach (tcp_checks($batch) as $id => $r) {
            $o = service_options($byId[$id]['options']);
            if ($r[0] && !empty($o['warn_ms']) && $r[1] > $o['warn_ms']) $r = [true, $r[1], "Port open · slow ({$r[1]} ms)", null, true];
            $results[$id] = $r;
        }
    }
    foreach ($byId as $id => $s) {
        if ($s['kind'] === 'dns') $results[$id] = dns_check($s['target'], service_options($s['options']));
    }
    foreach ($results as $id => $r) record_service_result($byId[$id], $r);
}

/**
 * Cron: runs network checks that are due, marks agent services unknown when
 * their agent stops reporting, and trims old results. One process at a time.
 */
function run_due_services(): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT GET_LOCK('webmonitor_services', 0)")->fetchColumn()) return;
    try {
        $now = now_ms();
        // 5 s of slack so a 60 s check run by a once-a-minute timer isn't skipped every other run.
        $st = $pdo->prepare("SELECT * FROM services WHERE enabled = 1 AND kind <> 'agent'
                             AND (last_check_at IS NULL OR last_check_at + interval_sec * 1000 - 5000 <= ?)");
        $st->execute([$now]);
        $due = $st->fetchAll();
        if ($due) run_service_checks($due);

        $pdo->prepare("UPDATE services SET status = 'unknown', message = 'The agent is not reporting', changed_at = ?
                       WHERE kind = 'agent' AND status NOT IN ('unknown', 'pending') AND (last_check_at IS NULL OR last_check_at < ?)")
            ->execute([$now, $now - AGENT_OFFLINE_AFTER_SEC * 1000]);
        if (random_int(1, 30) === 1) {
            $pdo->prepare('DELETE FROM service_results WHERE ts < ?')->execute([$now - SERVICE_RESULTS_KEEP_DAYS * 86400000]);
        }
    } finally {
        $pdo->query("SELECT RELEASE_LOCK('webmonitor_services')");
    }
}

/** Service names an agent should report on (sent in its report replies). */
function services_watch_list(int $hostId): array {
    $st = db()->prepare("SELECT target FROM services WHERE host_id = ? AND kind = 'agent' AND enabled = 1 ORDER BY target");
    $st->execute([$hostId]);
    return $st->fetchAll(PDO::FETCH_COLUMN);
}

/**
 * From an agent's metrics: [{name, display, state, sub, since, restarts, start_type}]
 * for the services it was asked to watch. Running = up; anything else = down.
 */
function store_agent_services(int $hostId, $list): void {
    if (!is_array($list)) return;
    $byName = [];
    foreach ($list as $s) {
        if (is_array($s) && is_string($s['name'] ?? null)) $byName[strtolower($s['name'])] = $s;
    }
    $st = db()->prepare("SELECT * FROM services WHERE host_id = ? AND kind = 'agent' AND enabled = 1");
    $st->execute([$hostId]);
    foreach ($st->fetchAll() as $svc) {
        $r = $byName[strtolower($svc['target'])] ?? null;
        if ($r === null) continue;   // not in this report (the agent may not have the new list yet)
        $detail = [
            'display' => is_string($r['display'] ?? null) ? mb_substr($r['display'], 0, 200) : null,
            'state' => is_string($r['state'] ?? null) ? mb_substr($r['state'], 0, 40) : null,
            'sub' => is_string($r['sub'] ?? null) ? mb_substr($r['sub'], 0, 40) : null,
            'since' => num_or_null($r['since'] ?? null),
            'restarts' => num_or_null($r['restarts'] ?? null),
            'startType' => is_string($r['start_type'] ?? null) ? mb_substr($r['start_type'], 0, 40) : null,
            'pid' => num_or_null($r['pid'] ?? null),
        ];
        if (!empty($r['missing'])) {
            record_service_result($svc, [false, null, 'Not installed on this host'], $detail);
            continue;
        }
        $up = in_array($detail['state'], ['active', 'running', 'Running'], true);
        $msg = trim(($detail['state'] ?? '?') . ($detail['sub'] && $detail['sub'] !== $detail['state'] ? " ({$detail['sub']})" : ''));
        record_service_result($svc, [$up, null, $msg], $detail);
    }
}

// ---------------------------------------------------------------- reading

/** JSON-ready row. $history: [[ts, up, ms]...] oldest first. */
function service_row(array $s, array $history = [], ?float $uptime = null): array {
    return [
        'id' => (int) $s['id'],
        'hostId' => $s['host_id'] !== null ? (int) $s['host_id'] : null,
        'hostName' => $s['host_name'] ?? null,
        'hostIp' => $s['ip_address'] ?? null,
        'kind' => $s['kind'],
        'name' => $s['name'],
        'target' => $s['target'],
        'options' => service_options($s['options']),
        'interval' => (int) $s['interval_sec'],
        'enabled' => (bool) $s['enabled'],
        'alert' => (bool) $s['alert'],
        'status' => $s['enabled'] ? $s['status'] : 'paused',
        'message' => $s['message'],
        'lastCheck' => $s['last_check_at'] !== null ? (int) $s['last_check_at'] : null,
        'lastMs' => $s['last_ms'] !== null ? (int) $s['last_ms'] : null,
        'changedAt' => $s['changed_at'] !== null ? (int) $s['changed_at'] : null,
        'certExpiresAt' => $s['cert_expires_at'] !== null ? (int) $s['cert_expires_at'] : null,
        'detail' => $s['detail'] ? json_decode($s['detail'], true) : null,
        'uptime' => $uptime,
        'history' => $history,
    ];
}

/** Every service with its last 30 results and 24-hour uptime. $hostId limits it to one host. */
function service_list(?int $hostId = null): array {
    $pdo = db();
    $sql = 'SELECT s.*, h.name AS host_name, h.ip_address FROM services s LEFT JOIN hosts h ON h.id = s.host_id';
    $st = $pdo->prepare($sql . ($hostId !== null ? ' WHERE s.host_id = ?' : '') . ' ORDER BY h.name IS NULL, h.name, s.name');
    $st->execute($hostId !== null ? [$hostId] : []);
    $rows = $st->fetchAll();
    if (!$rows) return [];
    $ids = array_map(fn($r) => (int) $r['id'], $rows);
    $in = implode(',', $ids);
    $since = now_ms() - 86400000;
    $uptime = [];
    foreach ($pdo->query("SELECT service_id, AVG(up) AS u FROM service_results WHERE service_id IN ($in) AND ts >= $since GROUP BY service_id") as $r) {
        $uptime[(int) $r['service_id']] = round((float) $r['u'] * 100, 2);
    }
    $hist = array_fill_keys($ids, []);
    $recent = $pdo->query("SELECT service_id, ts, up, ms FROM (
            SELECT service_id, ts, up, ms, ROW_NUMBER() OVER (PARTITION BY service_id ORDER BY ts DESC) AS rn
            FROM service_results WHERE service_id IN ($in) AND ts >= $since) x WHERE rn <= 30 ORDER BY ts");
    foreach ($recent as $r) $hist[(int) $r['service_id']][] = [(int) $r['ts'], (bool) $r['up'], $r['ms'] !== null ? (int) $r['ms'] : null];
    return array_map(fn($r) => service_row($r, $hist[(int) $r['id']], $uptime[(int) $r['id']] ?? null), $rows);
}

/** For the host cards: [hostId => {total, up, warn, down, unknown, down_names}]. */
function service_card_summaries(): array {
    $out = [];
    foreach (db()->query('SELECT host_id, name, status, enabled FROM services WHERE host_id IS NOT NULL ORDER BY name') as $r) {
        $h = (int) $r['host_id'];
        $out[$h] ??= ['total' => 0, 'up' => 0, 'warn' => 0, 'down' => 0, 'other' => 0, 'downNames' => []];
        if (!$r['enabled']) continue;
        $out[$h]['total']++;
        $k = in_array($r['status'], ['up', 'warn', 'down'], true) ? $r['status'] : 'other';
        $out[$h][$k]++;
        if ($k === 'down') $out[$h]['downNames'][] = $r['name'];
    }
    return array_filter($out, fn($s) => $s['total'] > 0);
}

/**
 * Services an agent host has (from its inventory) for the "watch a service"
 * picker: {platform, version, canWatch, canRestart, services: [{name, display, state}]}.
 */
function agent_available_services(int $hostId): ?array {
    $st = db()->prepare("SELECT agent_version, JSON_UNQUOTE(JSON_EXTRACT(inventory, '$.os.id')) AS os_id,
                                JSON_EXTRACT(inventory, '$.services') AS services FROM agents WHERE host_id = ?");
    $st->execute([$hostId]);
    $a = $st->fetch();
    if (!$a) return null;
    $platform = $a['os_id'] === 'windows' ? 'windows' : 'linux';
    $ok = $a['agent_version'] && version_compare($a['agent_version'], SERVICE_WATCH_MIN_AGENT[$platform], '>=');
    $list = [];
    foreach ((array) json_decode((string) $a['services'], true) as $s) {
        if (!is_array($s) || !is_string($s['name'] ?? null) || !preg_match(SERVICE_NAME_RE, $s['name'])) continue;
        $list[] = ['name' => $s['name'], 'display' => is_string($s['display'] ?? null) ? $s['display'] : null,
                   'state' => is_string($s['state'] ?? null) ? $s['state'] : null];
    }
    usort($list, fn($x, $y) => strcasecmp($x['display'] ?? $x['name'], $y['display'] ?? $y['name']));
    return ['platform' => $platform, 'version' => $a['agent_version'], 'canWatch' => (bool) $ok,
            'minVersion' => SERVICE_WATCH_MIN_AGENT[$platform], 'services' => $list];
}
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/includes/speedtest.php")"
cat > "$APP_DIR/includes/speedtest.php" <<'WEBMON_FILE_EOF'
<?php
require_once __DIR__ . '/db.php';

/**
 * Internet speed tests from the server (Network tab).
 *
 * Engines:
 *   cloudflare  built in: download, upload and latency against
 *               speed.cloudflare.com over HTTPS, using PHP's curl. Nothing to install.
 *   ookla       the official Speedtest CLI ("speedtest", speedtest.net servers),
 *               when an admin has installed it on the server.
 *
 * Tests run on the schedule set by an admin (every N minutes, or off) or on
 * demand. Its own timer (webmonitor-speedtest.timer, cli/speedtest.php
 * --if-due) starts them, since a test takes 20-40 seconds and must not hold
 * up cli/cron.php; the lock below keeps it to one at a time.
 */

const SPEEDTEST_LOCK = 'webmonitor_speedtest';
const SPEEDTEST_INTERVALS = [0, 15, 30, 60, 120, 180, 240, 360, 720, 1440];   // minutes; 0 = off
const SPEEDTEST_DEFAULTS = [
    'interval_min' => 180,
    'engine' => 'cloudflare',
    'streams' => 6,            // parallel connections (cloudflare)
    'seconds' => 8,            // per direction (cloudflare)
    'min_down_mbps' => 0,      // alert when two tests in a row are slower than this (0 = off)
    'min_up_mbps' => 0,
    'keep_days' => 400,
];
const SPEEDTEST_CF = 'https://speed.cloudflare.com';
const SPEEDTEST_CHUNK = 25000000;   // bytes per download request / upload body

function speedtest_settings(): array {
    $saved = json_decode((string) db()->query("SELECT v FROM settings WHERE k = 'speedtest'")->fetchColumn(), true) ?: [];
    $out = SPEEDTEST_DEFAULTS;
    foreach ($saved as $k => $v) if (array_key_exists($k, $out)) $out[$k] = is_string(SPEEDTEST_DEFAULTS[$k]) ? (string) $v : (int) $v;
    return $out;
}

function save_speedtest_settings(array $in): array {
    $s = speedtest_settings();
    if (isset($in['interval_min'])) {
        $s['interval_min'] = (int) $in['interval_min'];
        if (!in_array($s['interval_min'], SPEEDTEST_INTERVALS, true)) throw new InvalidArgumentException('Pick one of the offered intervals.');
    }
    if (isset($in['engine'])) {
        if (!array_key_exists($in['engine'], speedtest_engines())) throw new InvalidArgumentException('Unknown engine.');
        if ($in['engine'] === 'ookla' && !speedtest_engines()['ookla']) throw new InvalidArgumentException('The Speedtest CLI is not installed on the server.');
        $s['engine'] = $in['engine'];
    }
    foreach (['streams' => [1, 16], 'seconds' => [4, 20], 'min_down_mbps' => [0, 100000], 'min_up_mbps' => [0, 100000], 'keep_days' => [7, 3650]] as $k => [$lo, $hi]) {
        if (isset($in[$k])) $s[$k] = max($lo, min($hi, (int) $in[$k]));
    }
    db()->prepare("INSERT INTO settings (k, v) VALUES ('speedtest', ?) ON DUPLICATE KEY UPDATE v = VALUES(v)")->execute([json_encode($s)]);
    return $s;
}

/** Path of the Ookla Speedtest CLI, or null. */
function ookla_cli_path(): ?string {
    foreach (['/usr/bin/speedtest', '/usr/local/bin/speedtest'] as $p) {
        if (is_executable($p)) {
            // speedtest-cli (the unofficial Python one) also installs as "speedtest" on some systems; it lacks --accept-license.
            $v = (string) shell_exec(escapeshellarg($p) . ' --version 2>&1');
            if (stripos($v, 'Ookla') !== false) return $p;
        }
    }
    return null;
}

/** ['cloudflare' => true, 'ookla' => bool]. */
function speedtest_engines(): array {
    return ['cloudflare' => function_exists('curl_multi_init'), 'ookla' => ookla_cli_path() !== null];
}

function speedtest_running(): bool {
    $st = db()->prepare('SELECT IS_USED_LOCK(?)');
    $st->execute([SPEEDTEST_LOCK]);
    return $st->fetchColumn() !== null;
}

function speedtest_requested(): bool {
    return (bool) db()->query("SELECT v FROM settings WHERE k = 'speedtest_requested'")->fetchColumn();
}

function request_speedtest(): void {
    db()->exec("INSERT INTO settings (k, v) VALUES ('speedtest_requested', '1') ON DUPLICATE KEY UPDATE v = '1'");
}

/** When the next scheduled test is due (ms), or null when scheduling is off. */
function speedtest_next_due(array $s): ?int {
    if ($s['interval_min'] <= 0) return null;
    $last = (int) db()->query('SELECT MAX(ts) FROM speedtests WHERE manual = 0')->fetchColumn();
    return $last ? $last + $s['interval_min'] * 60000 : (int) round(microtime(true) * 1000);
}

/**
 * What should run now: 'manual' (someone pressed Run now), 'scheduled' (the
 * next scheduled test is due) or null. Checked every minute by
 * webmonitor-speedtest.timer (cli/speedtest.php --if-due).
 */
function speedtest_due_now(): ?string {
    $pdo = db();
    if (!(int) $pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'speedtests'")->fetchColumn()) return null;
    if (speedtest_running()) return null;
    if (speedtest_requested()) return 'manual';
    $due = speedtest_next_due(speedtest_settings());
    return $due !== null && $due <= microtime(true) * 1000 ? 'scheduled' : null;
}

/** Runs one test now with the configured engine and stores it. Returns the stored row. */
function run_speedtest(bool $manual): array {
    $pdo = db();
    $st = $pdo->prepare('SELECT GET_LOCK(?, 0)');
    $st->execute([SPEEDTEST_LOCK]);
    if (!(int) $st->fetchColumn()) throw new RuntimeException('a speed test is already running');
    try {
        if ($manual) $pdo->exec("DELETE FROM settings WHERE k = 'speedtest_requested'");
        $s = speedtest_settings();
        $engine = $s['engine'] === 'ookla' && ookla_cli_path() ? 'ookla' : 'cloudflare';
        $start = (int) round(microtime(true) * 1000);
        try {
            $r = $engine === 'ookla' ? speedtest_ookla() : speedtest_cloudflare($s['streams'], $s['seconds']);
            $r['error'] = null;
        } catch (Throwable $e) {
            $r = ['error' => mb_substr($e->getMessage(), 0, 500)];
        }
        $cols = ['down_mbps', 'up_mbps', 'ping_ms', 'jitter_ms', 'loss_pct', 'bytes_used', 'server', 'isp', 'public_ip', 'result_url', 'error'];
        $vals = array_map(fn($c) => $r[$c] ?? null, $cols);
        $pdo->prepare('INSERT INTO speedtests (ts, engine, manual, duration_ms, ' . implode(', ', $cols) . ') VALUES (?, ?, ?, ?, '
            . implode(', ', array_fill(0, count($cols), '?')) . ')')
            ->execute(array_merge([$start, $engine, $manual ? 1 : 0, (int) round(microtime(true) * 1000) - $start], $vals));
        $id = (int) $pdo->lastInsertId();
        $pdo->prepare('DELETE FROM speedtests WHERE ts < ?')->execute([$start - $s['keep_days'] * 86400000]);
        $row = $pdo->query("SELECT * FROM speedtests WHERE id = $id")->fetch();
        return $row;
    } finally {
        $pdo->prepare('SELECT RELEASE_LOCK(?)')->execute([SPEEDTEST_LOCK]);
    }
}

// ---- Ookla Speedtest CLI ----

function speedtest_ookla(): array {
    $bin = ookla_cli_path();
    if (!$bin) throw new RuntimeException('the Speedtest CLI is not installed');
    // HOME must be writable: the CLI stores its licence acceptance there.
    $home = sys_get_temp_dir() . '/webmonitor-speedtest';
    @mkdir($home, 0700, true);
    $cmd = 'HOME=' . escapeshellarg($home) . ' timeout 120 ' . escapeshellarg($bin) . ' --accept-license --accept-gdpr -f json -p no 2>&1';
    $raw = (string) shell_exec($cmd);
    $j = null;
    foreach (array_reverse(preg_split('/\R/', trim($raw))) as $line) {
        if (($d = json_decode($line, true)) && ($d['type'] ?? '') === 'result') { $j = $d; break; }
    }
    if (!$j) {
        $msg = '';
        foreach (preg_split('/\R/', trim($raw)) as $line) if (($d = json_decode($line, true)) && isset($d['message'])) $msg = $d['message'];
        throw new RuntimeException('Speedtest CLI: ' . ($msg ?: mb_substr(trim($raw), 0, 200) ?: 'no result'));
    }
    return [
        'down_mbps' => round(($j['download']['bandwidth'] ?? 0) * 8 / 1e6, 2),
        'up_mbps' => round(($j['upload']['bandwidth'] ?? 0) * 8 / 1e6, 2),
        'ping_ms' => isset($j['ping']['latency']) ? round($j['ping']['latency'], 1) : null,
        'jitter_ms' => isset($j['ping']['jitter']) ? round($j['ping']['jitter'], 1) : null,
        'loss_pct' => isset($j['packetLoss']) ? round($j['packetLoss'], 1) : null,
        'bytes_used' => (int) (($j['download']['bytes'] ?? 0) + ($j['upload']['bytes'] ?? 0)),
        'server' => mb_substr(trim(($j['server']['name'] ?? '') . ' · ' . ($j['server']['location'] ?? ''), ' ·'), 0, 160),
        'isp' => mb_substr((string) ($j['isp'] ?? ''), 0, 160) ?: null,
        'public_ip' => $j['interface']['externalIp'] ?? null,
        'result_url' => $j['result']['url'] ?? null,
    ];
}

// ---- Built-in test against speed.cloudflare.com ----

function speedtest_curl(string $url): CurlHandle {
    $h = curl_init($url);
    curl_setopt_array($h, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => 5,
        CURLOPT_TIMEOUT => 30,
        CURLOPT_USERAGENT => 'WebMonitor speed test',
        CURLOPT_HTTPHEADER => ['Referer: ' . SPEEDTEST_CF . '/'],
        CURLOPT_ENCODING => 'identity',
    ]);
    return $h;
}

function speedtest_cloudflare(int $streams, int $seconds): array {
    // Who and where.
    $h = speedtest_curl(SPEEDTEST_CF . '/meta');
    $meta = json_decode((string) curl_exec($h), true) ?: [];
    if (curl_errno($h)) throw new RuntimeException('cannot reach speed.cloudflare.com: ' . curl_error($h));

    // Latency: TCP connect time of fresh connections (one round trip each).
    $rtts = [];
    $fails = 0;
    for ($i = 0; $i < 12; $i++) {
        $h = speedtest_curl(SPEEDTEST_CF . '/__down?bytes=0');
        curl_setopt_array($h, [CURLOPT_FRESH_CONNECT => true, CURLOPT_FORBID_REUSE => true, CURLOPT_TIMEOUT => 5]);
        curl_exec($h);
        if (curl_errno($h)) { $fails++; continue; }
        $connect = curl_getinfo($h, CURLINFO_CONNECT_TIME_T) - curl_getinfo($h, CURLINFO_NAMELOOKUP_TIME_T);
        if ($connect > 0) $rtts[] = $connect / 1000;
    }
    if (!$rtts) throw new RuntimeException('no answer from speed.cloudflare.com');
    $sorted = $rtts;
    sort($sorted);
    $ping = $sorted[intdiv(count($sorted), 2)];
    $jitter = 0.0;
    for ($i = 1; $i < count($rtts); $i++) $jitter += abs($rtts[$i] - $rtts[$i - 1]);
    $jitter = count($rtts) > 1 ? $jitter / (count($rtts) - 1) : 0.0;

    [$down, $bytesDown] = speedtest_transfer('down', $streams, $seconds);
    [$up, $bytesUp] = speedtest_transfer('up', $streams, $seconds);

    $colo = $meta['colo'] ?? null;
    return [
        'down_mbps' => round($down, 2),
        'up_mbps' => round($up, 2),
        'ping_ms' => round($ping, 1),
        'jitter_ms' => round($jitter, 1),
        'loss_pct' => round($fails / 12 * 100, 1),
        'bytes_used' => $bytesDown + $bytesUp,
        'server' => 'Cloudflare' . (is_array($colo) ? ' ' . trim(($colo['iata'] ?? '') . ' ' . ($colo['city'] ?? '')) : (is_string($colo) ? " $colo" : '')),
        'isp' => isset($meta['asOrganization']) ? mb_substr($meta['asOrganization'], 0, 160) : null,
        'public_ip' => $meta['clientIp'] ?? null,
        'result_url' => null,
    ];
}

/**
 * Saturates the line with $streams parallel transfers for $seconds and
 * returns [Mbit/s, bytes moved]. The first second and a half (TCP ramp-up)
 * is left out of the rate.
 */
function speedtest_transfer(string $dir, int $streams, int $seconds): array {
    $moved = 0;
    $payload = $dir === 'up' ? random_bytes(1 << 20) : '';
    $mh = curl_multi_init();
    $handles = [];
    $make = function () use ($dir, &$moved, $payload): CurlHandle {
        if ($dir === 'down') {
            $h = speedtest_curl(SPEEDTEST_CF . '/__down?bytes=' . SPEEDTEST_CHUNK);
            curl_setopt($h, CURLOPT_RETURNTRANSFER, false);
            curl_setopt($h, CURLOPT_WRITEFUNCTION, function ($ch, $data) use (&$moved) { $len = strlen($data); $moved += $len; return $len; });
        } else {
            $h = speedtest_curl(SPEEDTEST_CF . '/__up');
            $sent = 0;
            curl_setopt_array($h, [
                CURLOPT_UPLOAD => true, CURLOPT_CUSTOMREQUEST => 'POST', CURLOPT_INFILESIZE => SPEEDTEST_CHUNK,
                CURLOPT_HTTPHEADER => ['Referer: ' . SPEEDTEST_CF . '/', 'Content-Type: application/octet-stream'],
                CURLOPT_READFUNCTION => function ($ch, $fd, $len) use (&$sent, &$moved, $payload) {
                    $n = min($len, SPEEDTEST_CHUNK - $sent);
                    if ($n <= 0) return '';
                    $off = $sent % strlen($payload);
                    $chunk = substr($payload, $off, min($n, strlen($payload) - $off));
                    $sent += strlen($chunk);
                    $moved += strlen($chunk);
                    return $chunk;
                },
            ]);
        }
        curl_setopt($h, CURLOPT_TIMEOUT, 60);
        return $h;
    };
    for ($i = 0; $i < $streams; $i++) {
        $h = $make();
        curl_multi_add_handle($mh, $h);
        $handles[] = $h;
    }
    $t0 = microtime(true);
    $warm = 1.5;
    $markBytes = null;
    $markAt = null;
    $errors = [];
    do {
        curl_multi_exec($mh, $running);
        curl_multi_select($mh, 0.1);
        while ($info = curl_multi_info_read($mh)) {
            $h = $info['handle'];
            if ($info['result'] !== CURLE_OK) $errors[] = curl_error($h);
            curl_multi_remove_handle($mh, $h);
            // Keep the line busy: start another transfer in its place.
            if (microtime(true) - $t0 < $seconds && count($errors) < $streams * 3) {
                $n = $make();
                curl_multi_add_handle($mh, $n);
                $handles[] = $n;
            }
        }
        $elapsed = microtime(true) - $t0;
        if ($markAt === null && $elapsed >= $warm) { $markAt = microtime(true); $markBytes = $moved; }
    } while ($elapsed < $seconds && ($running > 0 || count($errors) < $streams * 3));
    $end = microtime(true);
    foreach ($handles as $h) { @curl_multi_remove_handle($mh, $h); }
    curl_multi_close($mh);
    if ($markAt === null || $end - $markAt < 0.5) throw new RuntimeException("$dir test failed" . ($errors ? ': ' . $errors[0] : ''));
    $mbps = ($moved - $markBytes) * 8 / ($end - $markAt) / 1e6;
    if ($mbps <= 0) throw new RuntimeException("$dir test moved no data" . ($errors ? ': ' . $errors[0] : ''));
    return [$mbps, $moved];
}

// ---- Dashboard ----

function speedtest_row(array $r): array {
    $f = fn($v) => $v === null ? null : (float) $v;
    return [
        'id' => (int) $r['id'], 'ts' => (int) $r['ts'], 'engine' => $r['engine'], 'manual' => (bool) $r['manual'],
        'down' => $f($r['down_mbps']), 'up' => $f($r['up_mbps']), 'ping' => $f($r['ping_ms']), 'jitter' => $f($r['jitter_ms']),
        'loss' => $f($r['loss_pct']), 'bytes' => $r['bytes_used'] === null ? null : (int) $r['bytes_used'],
        'durationMs' => (int) $r['duration_ms'], 'server' => $r['server'], 'isp' => $r['isp'], 'ip' => $r['public_ip'],
        'url' => $r['result_url'], 'error' => $r['error'],
    ];
}

/** Results for the Network tab: settings, state and the tests within $days. */
function speedtest_overview(int $days): array {
    $s = speedtest_settings();
    $st = db()->prepare('SELECT * FROM speedtests WHERE ts >= ? ORDER BY ts');
    $st->execute([(int) round(microtime(true) * 1000) - $days * 86400000]);
    $rows = array_map('speedtest_row', $st->fetchAll());
    $last = db()->query('SELECT * FROM speedtests ORDER BY ts DESC LIMIT 1')->fetch();
    return [
        'settings' => $s, 'intervals' => SPEEDTEST_INTERVALS, 'engines' => speedtest_engines(),
        'running' => speedtest_running(), 'requested' => speedtest_requested(), 'nextDue' => speedtest_next_due($s),
        'latest' => $last ? speedtest_row($last) : null, 'results' => $rows,
    ];
}

/** Alerts: the last two scheduled tests were both slower than the set minimum. */
function speedtest_problems(callable $add, array &$frozenHosts): void {
    $pdo = db();
    if (!(int) $pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'speedtests'")->fetchColumn()) return;
    $s = speedtest_settings();
    if ($s['min_down_mbps'] <= 0 && $s['min_up_mbps'] <= 0) return;
    $last = $pdo->query('SELECT down_mbps, up_mbps, ts FROM speedtests WHERE error IS NULL ORDER BY ts DESC LIMIT 2')->fetchAll();
    $maxAge = max(2, $s['interval_min'] * 3) * 60000;
    if (count($last) < 2 || microtime(true) * 1000 - (int) $last[0]['ts'] > max($maxAge, 6 * 3600000)) {
        $frozenHosts[0]['speedtest'] = true;   // not enough fresh results: leave as is
        return;
    }
    foreach (['down' => ['min_down_mbps', 'Download'], 'up' => ['min_up_mbps', 'Upload']] as $dir => [$key, $label]) {
        $min = $s[$key];
        if ($min <= 0) continue;
        $vals = array_map(fn($r) => (float) $r["{$dir}_mbps"], $last);
        if (max($vals) < $min) {
            $add(null, 'speedtest', $dir, 'warning', sprintf('Internet %s speed is low: %.1f and %.1f Mbit/s in the last two tests (minimum %d)',
                strtolower($label), $vals[0], $vals[1], $min));
        }
    }
}
