mkdir -p "$(dirname "$APP_DIR/migrations/010_history.sql")"
cat > "$APP_DIR/migrations/010_history.sql" <<'WEBMON_FILE_EOF'
-- Time series for history graphs. A series is one metric of one host
-- (subject distinguishes e.g. disks or interfaces). Points are per minute
-- (kept 8 days); cron rolls them into hourly avg/min/max (kept 400 days).
CREATE TABLE IF NOT EXISTS metric_series (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  host_id INT UNSIGNED NOT NULL,
  metric VARCHAR(32) NOT NULL,
  subject VARCHAR(120) NOT NULL DEFAULT '',
  unit VARCHAR(8) NOT NULL DEFAULT '',
  UNIQUE KEY uk_series (host_id, metric, subject),
  FOREIGN KEY (host_id) REFERENCES hosts(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS metric_points (
  series_id INT UNSIGNED NOT NULL,
  ts INT UNSIGNED NOT NULL,
  value FLOAT NOT NULL,
  PRIMARY KEY (series_id, ts),
  FOREIGN KEY (series_id) REFERENCES metric_series(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS metric_hourly (
  series_id INT UNSIGNED NOT NULL,
  ts INT UNSIGNED NOT NULL,
  avg_value FLOAT NOT NULL,
  min_value FLOAT NOT NULL,
  max_value FLOAT NOT NULL,
  samples SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (series_id, ts),
  FOREIGN KEY (series_id) REFERENCES metric_series(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Carry over the per-minute agent history collected so far.
INSERT IGNORE INTO metric_series (host_id, metric, subject, unit)
  SELECT DISTINCT host_id, 'cpu', '', '%' FROM agent_metrics WHERE cpu_pct IS NOT NULL;
INSERT IGNORE INTO metric_series (host_id, metric, subject, unit)
  SELECT DISTINCT host_id, 'mem', '', '%' FROM agent_metrics WHERE mem_pct IS NOT NULL;
INSERT IGNORE INTO metric_series (host_id, metric, subject, unit)
  SELECT DISTINCT host_id, 'load1', '', '' FROM agent_metrics WHERE load1 IS NOT NULL;
INSERT IGNORE INTO metric_points (series_id, ts, value)
  SELECT s.id, FLOOR(m.ts / 60000) * 60, m.cpu_pct FROM agent_metrics m
  JOIN metric_series s ON s.host_id = m.host_id AND s.metric = 'cpu' AND s.subject = '' WHERE m.cpu_pct IS NOT NULL;
INSERT IGNORE INTO metric_points (series_id, ts, value)
  SELECT s.id, FLOOR(m.ts / 60000) * 60, m.mem_pct FROM agent_metrics m
  JOIN metric_series s ON s.host_id = m.host_id AND s.metric = 'mem' AND s.subject = '' WHERE m.mem_pct IS NOT NULL;
INSERT IGNORE INTO metric_points (series_id, ts, value)
  SELECT s.id, FLOOR(m.ts / 60000) * 60, m.load1 FROM agent_metrics m
  JOIN metric_series s ON s.host_id = m.host_id AND s.metric = 'load1' AND s.subject = '' WHERE m.load1 IS NOT NULL;
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/migrations/011_discovery.sql")"
cat > "$APP_DIR/migrations/011_discovery.sql" <<'WEBMON_FILE_EOF'
-- Subnet discovery: scheduled scans that add new devices and remove cards
-- that haven't been seen for a while (see includes/discovery.php).

-- When the host was last seen: a successful check, an ARP entry or a scan.
ALTER TABLE hosts ADD COLUMN IF NOT EXISTS last_seen_at BIGINT UNSIGNED NULL;
-- 'manual' (added by a person) or 'scan' (added by subnet discovery).
ALTER TABLE hosts ADD COLUMN IF NOT EXISTS added_by VARCHAR(16) NOT NULL DEFAULT 'manual';

-- Backfill: the last successful check still on record...
UPDATE hosts h JOIN (SELECT host_id, MAX(ts) t FROM checks WHERE up = 1 GROUP BY host_id) c ON c.host_id = h.id
  SET h.last_seen_at = c.t WHERE h.last_seen_at IS NULL;
-- ...then availability history...
UPDATE hosts h JOIN (SELECT s.host_id, MAX(p.ts) t FROM metric_series s JOIN metric_points p ON p.series_id = s.id
                     WHERE s.metric = 'up' AND p.value > 0 GROUP BY s.host_id) m ON m.host_id = h.id
  SET h.last_seen_at = m.t * 1000 WHERE h.last_seen_at IS NULL;
-- ...and everything else starts its "not seen" clock now, so nothing is removed right away.
UPDATE hosts SET last_seen_at = UNIX_TIMESTAMP() * 1000 WHERE last_seen_at IS NULL;

CREATE TABLE IF NOT EXISTS subnet_scans (
  subnet VARCHAR(18) NOT NULL PRIMARY KEY,
  enabled TINYINT(1) NOT NULL DEFAULT 0,
  every_min INT UNSIGNED NOT NULL DEFAULT 60,
  auto_add TINYINT(1) NOT NULL DEFAULT 0,
  remove_after_days INT UNSIGNED NULL,
  remove_scan_only TINYINT(1) NOT NULL DEFAULT 1,
  last_scan_at BIGINT UNSIGNED NULL,
  last_result TEXT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS discovery_log (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ts BIGINT UNSIGNED NOT NULL,
  subnet VARCHAR(18) NOT NULL,
  action VARCHAR(16) NOT NULL,
  ip VARCHAR(45) NOT NULL,
  name VARCHAR(60) NOT NULL,
  detail VARCHAR(255) NULL,
  INDEX idx_ts (ts)
) ENGINE=InnoDB;
WEBMON_FILE_EOF

