  kind VARCHAR(16) NOT NULL,
  target VARCHAR(255) NOT NULL,
  started_at BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/migrations/025_vulns.sql")"
cat > "$APP_DIR/migrations/025_vulns.sql" <<'WEBMON_FILE_EOF'
-- Vulnerability scans (Security tab). source says which engine found a
-- finding ('builtin' now; 'openvas' when a Greenbone engine feeds results).
CREATE TABLE IF NOT EXISTS vuln_scans (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  scope VARCHAR(64) NOT NULL,             -- 'all', 'subnet:192.168.60.0/24' or 'host:12'
  status VARCHAR(16) NOT NULL DEFAULT 'queued',   -- queued, running, done, failed, cancelled
  requested_by INT UNSIGNED NULL,
  created_at BIGINT UNSIGNED NOT NULL,
  started_at BIGINT UNSIGNED NULL,
  finished_at BIGINT UNSIGNED NULL,
  total_hosts INT UNSIGNED NOT NULL DEFAULT 0,
  done_hosts INT UNSIGNED NOT NULL DEFAULT 0,
  current VARCHAR(255) NULL,
  error VARCHAR(500) NULL,
  KEY status_idx (status)
) ENGINE=InnoDB;

-- One row per host per scan: the newest row per address is that host's current result.
CREATE TABLE IF NOT EXISTS vuln_hosts (
  scan_id INT UNSIGNED NOT NULL,
  ip VARCHAR(45) NOT NULL,
  host_id INT UNSIGNED NULL,
  scanned_at BIGINT UNSIGNED NOT NULL,
  open_ports VARCHAR(1000) NULL,
  os_guess VARCHAR(120) NULL,
  error VARCHAR(500) NULL,
  PRIMARY KEY (scan_id, ip),
  KEY ip_idx (ip, scanned_at),
  CONSTRAINT vuln_hosts_scan FOREIGN KEY (scan_id) REFERENCES vuln_scans (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS vuln_findings (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  scan_id INT UNSIGNED NOT NULL,
  ip VARCHAR(45) NOT NULL,
  port INT UNSIGNED NULL,
  service VARCHAR(120) NULL,
  check_id VARCHAR(64) NOT NULL,
  severity VARCHAR(8) NOT NULL,           -- critical, high, medium, low, info
  cvss DECIMAL(3,1) NULL,
  title VARCHAR(255) NOT NULL,
  detail TEXT NULL,
  solution VARCHAR(1000) NULL,
  refs VARCHAR(2000) NULL,                -- JSON list of CVE ids / URLs
  confidence VARCHAR(8) NOT NULL DEFAULT 'high',   -- high: confirmed; medium: version-based
  source VARCHAR(16) NOT NULL DEFAULT 'builtin',
  KEY scan_ip (scan_id, ip),
  CONSTRAINT vuln_findings_scan FOREIGN KEY (scan_id) REFERENCES vuln_scans (id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- NVD / OSV answers, so each product version is looked up rarely.
CREATE TABLE IF NOT EXISTS vuln_cache (
  k VARCHAR(190) NOT NULL PRIMARY KEY,
  fetched_at BIGINT UNSIGNED NOT NULL,
  data MEDIUMTEXT NOT NULL
) ENGINE=InnoDB;
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/migrations/026_services.sql")"
cat > "$APP_DIR/migrations/026_services.sql" <<'WEBMON_FILE_EOF'
-- Service monitoring (Services tab). One row per check:
--   http   target = URL; options: method, expect (status codes), keyword, verify_tls, cert_warn_days, warn_ms
--   tcp    target = host:port
--   dns    target = name to resolve; options: server, type (A, AAAA, CNAME, MX), expect
--   agent  target = service name on the host (systemd unit / Windows service), reported by its agent
CREATE TABLE IF NOT EXISTS services (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  host_id INT UNSIGNED NULL,               -- the card it belongs to (required for agent services)
  kind VARCHAR(8) NOT NULL,
  name VARCHAR(120) NOT NULL,
  target VARCHAR(500) NOT NULL,
  options TEXT NULL,                       -- JSON
  interval_sec INT UNSIGNED NOT NULL DEFAULT 60,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  alert TINYINT(1) NOT NULL DEFAULT 1,     -- send alerts when it's down
  status VARCHAR(8) NOT NULL DEFAULT 'pending',   -- up, warn, down, pending, unknown
  message VARCHAR(500) NULL,               -- why it's down / what was seen
  last_check_at BIGINT UNSIGNED NULL,
  last_ms INT UNSIGNED NULL,
  fail_count INT UNSIGNED NOT NULL DEFAULT 0,
  changed_at BIGINT UNSIGNED NULL,         -- when status last changed
  cert_expires_at BIGINT UNSIGNED NULL,
  detail TEXT NULL,                        -- JSON: agent service state, start time, restarts
  created_by INT UNSIGNED NULL,
  created_at BIGINT UNSIGNED NOT NULL,
  KEY host_idx (host_id),
  KEY due_idx (enabled, kind, last_check_at),
  CONSTRAINT services_host FOREIGN KEY (host_id) REFERENCES hosts (id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Check results for the uptime bar and percentage (kept 7 days).
CREATE TABLE IF NOT EXISTS service_results (
  service_id INT UNSIGNED NOT NULL,
  ts BIGINT UNSIGNED NOT NULL,
  up TINYINT(1) NOT NULL,
  ms INT UNSIGNED NULL,
  PRIMARY KEY (service_id, ts),
  KEY ts_idx (ts),
  CONSTRAINT service_results_service FOREIGN KEY (service_id) REFERENCES services (id) ON DELETE CASCADE
) ENGINE=InnoDB;
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/migrations/027_network.sql")"
cat > "$APP_DIR/migrations/027_network.sql" <<'WEBMON_FILE_EOF'
-- Network tab (includes/netlive.php, includes/speedtest.php).

-- Interface counters of each switch/router, for live port traffic. "live" is
-- the latest sample (the dashboard polls every few seconds while the Network
-- tab is open); "minute" is the baseline cron uses for per-minute history.
CREATE TABLE IF NOT EXISTS iface_samples (
  host_id INT UNSIGNED NOT NULL PRIMARY KEY,
  live_at BIGINT UNSIGNED NOT NULL,          -- ms
  live_counters MEDIUMTEXT NOT NULL,         -- JSON {ifIndex: [in, out]} octets
  rates MEDIUMTEXT NULL,                     -- JSON {ifIndex: [in, out]} bit/s, from the last two live samples
  minute_at BIGINT UNSIGNED NULL,
  minute_counters MEDIUMTEXT NULL,
  error VARCHAR(255) NULL,
  FOREIGN KEY (host_id) REFERENCES hosts(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Internet speed tests, scheduled (Network tab -> Speed test settings) or run on demand.
CREATE TABLE IF NOT EXISTS speedtests (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  ts BIGINT UNSIGNED NOT NULL,               -- ms, when it started
  engine VARCHAR(16) NOT NULL,               -- cloudflare, ookla
  manual TINYINT(1) NOT NULL DEFAULT 0,
  down_mbps FLOAT NULL,
  up_mbps FLOAT NULL,
  ping_ms FLOAT NULL,
  jitter_ms FLOAT NULL,
  loss_pct FLOAT NULL,
  bytes_used BIGINT UNSIGNED NULL,
  duration_ms INT UNSIGNED NULL,
  server VARCHAR(160) NULL,
  isp VARCHAR(160) NULL,
  public_ip VARCHAR(45) NULL,
  result_url VARCHAR(255) NULL,
  error VARCHAR(500) NULL,
  KEY ts_idx (ts)
) ENGINE=InnoDB;
WEBMON_FILE_EOF

mkdir -p "$(dirname "$APP_DIR/migrations/028_flow_ifaces.sql")"
cat > "$APP_DIR/migrations/028_flow_ifaces.sql" <<'WEBMON_FILE_EOF'
-- NetFlow per exporter interface (cli/flow-collector.py -> includes/flows.php), for
-- the Network tab's per-port traffic breakdown (includes/portflows.php).
--   dir 'i': the flow came in on this interface (the flow record's input ifIndex)
--   dir 'o': it went out of it (output ifIndex, when the exporter sends one)
CREATE TABLE IF NOT EXISTS flow_ifaces (
  ts INT UNSIGNED NOT NULL,
  exporter VARCHAR(45) NOT NULL,
  if_index INT UNSIGNED NOT NULL,
  dir CHAR(1) NOT NULL,
  bytes BIGINT UNSIGNED NOT NULL,
  packets BIGINT UNSIGNED NOT NULL,
  flows INT UNSIGNED NOT NULL,
  PRIMARY KEY (exporter, if_index, dir, ts),
  KEY ts_idx (ts)
) ENGINE=InnoDB;

-- Top conversations per exporter and input interface, per minute (kept 3 days).
CREATE TABLE IF NOT EXISTS flow_iface_conv (
  ts INT UNSIGNED NOT NULL,
  exporter VARCHAR(45) NOT NULL,
  if_index INT UNSIGNED NOT NULL,
  src_ip VARCHAR(45) NOT NULL,
  dst_ip VARCHAR(45) NOT NULL,
  proto TINYINT UNSIGNED NOT NULL,
  port SMALLINT UNSIGNED NOT NULL,
  bytes BIGINT UNSIGNED NOT NULL,
  KEY iface_ts (exporter, if_index, ts),
  KEY ts_idx (ts)
) ENGINE=InnoDB;

-- Port matching looks flows up by the far end too (internal traffic).
ALTER TABLE flow_conv ADD INDEX IF NOT EXISTS idx_remote_ts (remote_ip, ts);
WEBMON_FILE_EOF

sed -i "s/__WEBMON_DB_PASS__/${DB_PASS}/" "$APP_DIR/config.php"

# Files from older versions that must not linger (index.html would bypass
# the login page, which is now index.php).
rm -f "$APP_DIR/index.html" "$APP_DIR/db.sql"

echo "    Applying database migrations"
php "$APP_DIR/cli/migrate.php" | sed 's/^/    /'

ADMIN_PASS=""
if [ -z "$(mysql_root -N "${DB_NAME}" -e 'SELECT 1 FROM users LIMIT 1')" ]; then
    ADMIN_PASS="$(openssl rand -base64 18 | tr -d '/+=' | cut -c1-20)"
    WEBMON_PASSWORD="$ADMIN_PASS" php "$APP_DIR/cli/create-user.php" admin | sed 's/^/    /'
fi

echo "==> [5/6] Setting ownership, permissions, SELinux context, and firewall"
chown -R apache:apache "$APP_DIR"
find "$APP_DIR" -type d -exec chmod 755 {} \;
find "$APP_DIR" -type f -exec chmod 644 {} \;

if command -v semanage >/dev/null 2>&1; then
    semanage fcontext -a -t httpd_sys_content_t "${APP_DIR}(/.*)?" 2>/dev/null || \
    semanage fcontext -m -t httpd_sys_content_t "${APP_DIR}(/.*)?" 2>/dev/null || true
    restorecon -Rv "$APP_DIR" >/dev/null
fi

setsebool -P httpd_can_network_connect_db 1 2>/dev/null || true

cat > /etc/httpd/conf.d/webmonitor.conf <<EOF
<Directory "${APP_DIR}">
    AllowOverride All
    Require all granted
    Options -Indexes
</Directory>
EOF

# --- BEGIN https setup ---
# Self-signed certificate for this server's hostname and IPs, created once
# and kept on re-runs (agents will pin it). mod_ssl's default HTTPS site is
# pointed at it: requests made to an IP address don't send SNI, so the
# default site is the one browsers and agents actually get.
WEBMON_CERT=/etc/pki/tls/certs/webmonitor.crt
WEBMON_KEY=/etc/pki/tls/private/webmonitor.key
if [ ! -s "$WEBMON_CERT" ] || [ ! -s "$WEBMON_KEY" ]; then
    # `hostname -f` can resolve to "localhost" via /etc/hosts; prefer the
    # configured name when it is already fully qualified.
    HOST_FQDN="$(hostname)"
    case "$HOST_FQDN" in *.*) ;; *) HOST_FQDN="$(hostname -f 2>/dev/null || hostname)" ;; esac
    SAN="DNS:${HOST_FQDN},DNS:$(hostname -s),DNS:localhost,IP:127.0.0.1"
    for ip in $(hostname -I); do SAN="${SAN},IP:${ip}"; done
    openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes -days 3650 \
        -subj "/CN=${HOST_FQDN}/O=WebMonitor" -addext "subjectAltName=${SAN}" \
        -keyout "$WEBMON_KEY" -out "$WEBMON_CERT" 2>/dev/null
    chmod 600 "$WEBMON_KEY"
    chmod 644 "$WEBMON_CERT"
    restorecon "$WEBMON_CERT" "$WEBMON_KEY" 2>/dev/null || true
    echo "    Created self-signed certificate ${WEBMON_CERT}"
fi
sed -i -E "s|^([[:space:]]*SSLCertificateFile[[:space:]]+).*|\\1${WEBMON_CERT}|; s|^([[:space:]]*SSLCertificateKeyFile[[:space:]]+).*|\\1${WEBMON_KEY}|" \
    /etc/httpd/conf.d/ssl.conf
# --- END https setup ---

apachectl configtest
systemctl restart php-fpm
systemctl restart httpd

# --- BEGIN cron setup ---
# WebMonitor's own SSH key and known_hosts for switch configuration backups.
install -d -o apache -g apache -m 700 /var/lib/webmonitor /var/lib/webmonitor/ssh
# NetFlow/IPFIX collector (Reports -> Traffic): switches send flows to UDP 2055.
cat > /etc/systemd/system/webmonitor-flow.service <<UNIT_EOF
[Unit]
Description=WebMonitor NetFlow/IPFIX collector
After=network-online.target

[Service]
User=apache
Group=apache
ExecStart=/usr/bin/python3 -I ${APP_DIR}/cli/flow-collector.py
Restart=always
RestartSec=5
NoNewPrivileges=yes

[Install]
WantedBy=multi-user.target
UNIT_EOF
systemctl daemon-reload
systemctl enable --now webmonitor-flow.service
if systemctl is-active --quiet firewalld; then
  firewall-cmd -q --permanent --add-port=2055/udp && firewall-cmd -q --reload
fi
# Host checks and alert evaluation every minute, so monitoring and
# notifications don't depend on anyone having the dashboard open.
cat > /etc/systemd/system/webmonitor-cron.service <<UNIT_EOF
[Unit]
Description=WebMonitor background checks and alerts
After=mariadb.service network-online.target

[Service]
Type=oneshot
User=apache
Group=apache
ExecStart=/usr/bin/php ${APP_DIR}/cli/cron.php
TimeoutStartSec=55
UNIT_EOF
cat > /etc/systemd/system/webmonitor-cron.timer <<'UNIT_EOF'
[Unit]
Description=Run WebMonitor background checks and alerts every minute

[Timer]
OnCalendar=*-*-* *:*:00
AccuracySec=1s

[Install]
WantedBy=timers.target
UNIT_EOF
# NAS health over SNMP every 5 minutes; separate because QNAP SNMP agents
# can take 20-40 s to answer.
cat > /etc/systemd/system/webmonitor-snmp.service <<UNIT_EOF
[Unit]
Description=WebMonitor background polls (NAS health, subnet discovery)
After=mariadb.service network-online.target

[Service]
Type=oneshot
User=apache
Group=apache
ExecStart=/usr/bin/php ${APP_DIR}/cli/poll-snmp.php
TimeoutStartSec=240
UNIT_EOF
cat > /etc/systemd/system/webmonitor-snmp.timer <<'UNIT_EOF'
[Unit]
Description=Poll WebMonitor SNMP devices every 5 minutes

[Timer]
OnCalendar=*-*-* *:00/5:30
AccuracySec=1s

[Install]
WantedBy=timers.target
UNIT_EOF
# Vulnerability scans (Security tab): the worker runs queued scans and exits;
# separate so a long scan never delays the checks above.
cat > /etc/systemd/system/webmonitor-vuln.service <<UNIT_EOF
[Unit]
Description=WebMonitor vulnerability scans
After=mariadb.service network-online.target

[Service]
Type=oneshot
User=apache
Group=apache
Nice=10
ExecStart=/usr/bin/php ${APP_DIR}/cli/vulnscan.php
TimeoutStartSec=12h
UNIT_EOF
cat > /etc/systemd/system/webmonitor-vuln.timer <<'UNIT_EOF'
[Unit]
Description=Start queued WebMonitor vulnerability scans

[Timer]
OnCalendar=*-*-* *:*:15
AccuracySec=1s

[Install]
WantedBy=timers.target
UNIT_EOF
# Internet speed tests (Network tab): checks each minute whether one is due; a test takes ~30 s.
cat > /etc/systemd/system/webmonitor-speedtest.service <<UNIT_EOF
[Unit]
Description=WebMonitor internet speed test
After=mariadb.service network-online.target

[Service]
Type=oneshot
User=apache
Group=apache
ExecStart=/usr/bin/php ${APP_DIR}/cli/speedtest.php --if-due
TimeoutStartSec=5min
UNIT_EOF
cat > /etc/systemd/system/webmonitor-speedtest.timer <<'UNIT_EOF'
[Unit]
Description=Run due WebMonitor internet speed tests

[Timer]
OnCalendar=*-*-* *:*:30
AccuracySec=1s

[Install]
WantedBy=timers.target
UNIT_EOF
systemctl daemon-reload
systemctl enable --now webmonitor-cron.timer webmonitor-snmp.timer webmonitor-vuln.timer webmonitor-speedtest.timer >/dev/null 2>&1
echo "    Background checks/alerts timer: $(systemctl is-active webmonitor-cron.timer); SNMP poll timer: $(systemctl is-active webmonitor-snmp.timer)"
# --- END cron setup ---

if systemctl is-active --quiet firewalld; then
    firewall-cmd --permanent --add-service=http --add-service=https >/dev/null
    firewall-cmd --reload >/dev/null
fi

echo
echo "==> [6/6] Self-test"
LOGIN_CODE="$(curl -sk -o /dev/null -w '%{http_code}' https://localhost/webmonitor/login.php)"
API_CODE="$(curl -sk -o /dev/null -w '%{http_code}' https://localhost/webmonitor/api/hosts.php)"
if [ "$LOGIN_CODE" = 200 ] && [ "$API_CODE" = 401 ]; then
    echo "    HTTPS login page OK; API correctly requires a login."
else
    echo "    WARNING: login page returned ${LOGIN_CODE}, API returned ${API_CODE} (expected 200/401) — check /var/log/httpd/ssl_error_log and php-fpm logs."
fi

echo
echo "Done. Open: https://$(hostname -I | awk '{print $1}')/webmonitor/"
echo "(The certificate is self-signed, so your browser will ask you to accept it once.)"
echo "DB user '${DB_USER}' password (also saved in ${APP_DIR}/config.php): ${DB_PASS}"
if [ -n "$ADMIN_PASS" ]; then
    echo "Dashboard login: admin / ${ADMIN_PASS}"
    echo "Change it with: php ${APP_DIR}/cli/create-user.php admin"
fi
